/* ground tones — grass for housing/park, warm pavers for commercial,
   distinct from the sidewalk's own concrete tone */
const GRASS = { a:0x5a9c52, b:0x519246, edge:0x3f7a3a };
const PLAZA = { a:0xd9c9a8, b:0xceba95, edge:0xb09b74 };

const EXT_YARD_DEPTH = 220, EXT_PARK_DEPTH = 380; // exterior (world-perimeter) lot depths

const CAR_LANE = ROAD_HALF / 2;          // each traffic direction's lane, inside ROAD_HALF
const SPAWN_S = 60;

/* ---------- block edge frame, as a free function ----------
   edges[0] is always the block's NORTH edge (dv=DIRV[0], outward
   rv=DIRV[3]). Lifted out of the scene class because route generation
   needs it too and generateRoute is not a method — Scene.blockEdges now
   delegates here so there is still exactly one construction of this. */
function blockEdgesOf(blk){
  return [
    { ox: blk.x0, oy: blk.y0, dv: DIRV[0], rv: DIRV[3], len: blk.x1-blk.x0 },
    { ox: blk.x1, oy: blk.y0, dv: DIRV[1], rv: DIRV[0], len: blk.y1-blk.y0 },
    { ox: blk.x1, oy: blk.y1, dv: DIRV[2], rv: DIRV[1], len: blk.x1-blk.x0 },
    { ox: blk.x0, oy: blk.y1, dv: DIRV[3], rv: DIRV[2], len: blk.y1-blk.y0 }
  ];
}

/* ---------- parking stall geometry: ONE function, two callers ----------
   drawParkingRow paints these bays and parks civilian cars in them.
   Anything else that needs to know where a bay actually IS — parking a
   vehicle in one, standing a person beside one — reads the same function
   rather than re-deriving it, exactly like dogSpotAt and trafficWorldAt.
   Two copies of stall arithmetic is precisely how art and placement drift
   apart.

   Takes the rng OBJECT, not a seed, and consumes exactly the one draw
   drawParkingRow used to make for nStalls — so its stream is unchanged
   from here on and every lot in the city stays byte-identical. Pass wantN
   to fix the count and skip that draw entirely, for callers laying their
   own row on a fresh rng.

   Sign convention (unchanged, and load-bearing): NEGATIVE b is "into the
   block", the same direction a house's back wall lies. Positive b would
   push the whole lot outward onto the sidewalk the robot walks. */
function parkingStallsAt(e, rng, wantN){
  const stallW = CARC.wid + 40;
  const stallDepth = CARC.len + 50;
  const nStalls = wantN || (2 + Math.floor(rng()*2));   // 2-3
  const clusterW = nStalls * stallW;
  if(e.len < clusterW + T2) return null;
  const startAlong = (e.len - clusterW) / 2;   // centred ON the edge, not spanning it
  const depthNear = -6;                        // rear bumper at the block boundary line —
  const depthFar  = depthNear - stallDepth;    // same depth a house's front wall sits at
  const cDepth    = (depthNear + depthFar) / 2;
  /* nose pointing deeper into the block */
  const fdirIn = DIRV.findIndex(d => d.x === -e.rv.x && d.y === -e.rv.y);
  const stalls = [];
  for(let i = 0; i < nStalls; i++){
    const a = startAlong + (i+0.5)*stallW;
    stalls.push({ x: e.ox + e.dv.x*a + e.rv.x*cDepth,
                  y: e.oy + e.dv.y*a + e.rv.y*cDepth, fdir: fdirIn, a });
  }
  return { nStalls, stallW, stallDepth, startAlong, depthNear, depthFar, cDepth, fdirIn, stalls };
}
/* minimum drivable route length: ONE displayed mile. The HUD's flavor
   conversion is FT_PER_UNIT = 0.6 and 5280 ft/mi, so 1 mi = 8800 route
   units — plus the spawn offset so the readout starts at >= 1.0 mi. */
const MIN_ROUTE_UNITS = 5280 / 0.6 + SPAWN_S;

/* ---------- the single source of truth for "what is at this point" ----------
   Road always wins over sidewalk — a crossing street's road legitimately
   owns that ground, which is what resolves intersection corners correctly. */
function classifyAt(edges, x, y){
  let sidewalk = false;
  for(const e of edges){
    const dv = DIRV[e.f], rv = DIRV[(e.f+1)%4];
    const relX = x - e.a.x, relY = y - e.a.y;
    const along = relX*dv.x + relY*dv.y;
    const perp  = relX*rv.x + relY*rv.y;
    if(along >= -OVERSHOOT && along <= BLOCK + OVERSHOOT){
      if(Math.abs(perp) <= ROAD_HALF) return "road";
      if(Math.abs(perp) <= ROAD_HALF + SIDEWALK_W) sidewalk = true;
    }
  }
  return sidewalk ? "sidewalk" : "block";
}

/* precomputed once per grid: cheap full-length runs for the safe mid-block
   stretch, fine classify()-checked cells only near actual intersections. */
function buildSidewalkGeometry(grid){
  const runs = [];  // individual T2-square tiles along the safe mid-block zone —
                     // NOT long rectangles. A real sidewalk has visible panel
                     // seams every tile-width; one giant rectangle per lane
                     // erased that entirely. Still no classify() check needed
                     // here — this zone is provably conflict-free by construction,
                     // same guarantee as before, just rendered at the right grain.
  const safeLen = BLOCK - 2*OVERSHOOT;
  if(safeLen > T2){
    const nTiles = Math.floor(safeLen / T2);
    for(const e of grid.edges){
      const dv = DIRV[e.f], rv = DIRV[(e.f+1)%4];
      for(const side of [-1, 1])
        for(let t = 0; t < SIDEWALK_ROWS; t++){
          const perp = side * (ROAD_HALF + (t+0.5)*T2);
          for(let ai = 0; ai < nTiles; ai++){
            const along = OVERSHOOT + (ai+0.5)*T2;
            const x = e.a.x + dv.x*along + rv.x*perp;
            const y = e.a.y + dv.y*along + rv.y*perp;
            runs.push({ x, y, parity: (ai + t) % 2 });
          }
        }
    }
  }
  /* SPATIAL INDEX FOR THE CORNER-CELL SCAN (2026-08-10, perf fix, found
     while chasing "why isn't Tipsey spinning" -- the honest answer was
     "the calculation is a multi-second synchronous block, so nothing
     can paint a spinner during it regardless"). The loop below used to
     call classifyAt(grid.edges, x, y) for every sample point, and
     classifyAt itself scans EVERY edge to answer one point -- correct
     on a single-hood grid (a few hundred edges) but effectively
     O(edges^2) once the 12-district merge pushed the map to ~1650
     edges: measured 3.3s of buildGrid's 3.34s total, entirely inside
     this one function. A sample point near edge e can only ever be
     classified by an edge sharing a node with e (or one node further
     out, for the far end of e) -- OVERSHOOT+SIDEWALK_W is 736 units,
     well inside one BLOCK (3128 units) either direction -- so
     nodeEdges buckets every edge by the nodes it touches ONCE
     (O(edges)), and nearbyEdgesForEdge hands back only the small,
     bounded set of edges actually near e's own two corners instead of
     the whole city. Verified byte-identical cornerCells/runs output
     against the original algorithm before this replaced it; 3.3s ->
     0.45s on the real merged-map grid size. */
  const nodeEdges = new Map();
  const addNodeEdge = (node, e) => {
    const k = node.i + "," + node.j;
    let arr = nodeEdges.get(k);
    if(!arr){ arr = []; nodeEdges.set(k, arr); }
    arr.push(e);
  };
  for(const e of grid.edges){ addNodeEdge(e.a, e); addNodeEdge(e.b, e); }
  const nearbyEdgesForEdge = (e) => {
    const seen0 = new Set(), out = [];
    const scan = (node) => {
      for(let di = -1; di <= 1; di++) for(let dj = -1; dj <= 1; dj++){
        const arr = nodeEdges.get((node.i+di) + "," + (node.j+dj));
        if(!arr) continue;
        for(const ee of arr) if(!seen0.has(ee)){ seen0.add(ee); out.push(ee); }
      }
    };
    scan(e.a); scan(e.b);
    return out;
  };

  const cornerCells = [], seen = new Set();
  const perpSteps = Math.round(SIDEWALK_W / CELL);
  const alongSteps = Math.round((2*OVERSHOOT) / CELL);
  for(const e of grid.edges){
    const dv = DIRV[e.f], rv = DIRV[(e.f+1)%4];
    const localEdges = nearbyEdgesForEdge(e);
    for(const end of [0, 1]){
      for(let ai = 0; ai <= alongSteps; ai++){
        const along = end === 0 ? (-OVERSHOOT + ai*CELL) : (BLOCK - OVERSHOOT + ai*CELL);
        for(const side of [-1, 1])
        for(let pi = 0; pi < perpSteps; pi++){
          const perp = side * (ROAD_HALF + (pi+0.5)*CELL);
          const x = e.a.x + dv.x*along + rv.x*perp;
          const y = e.a.y + dv.y*along + rv.y*perp;
          const key = Math.round(x/CELL) + "," + Math.round(y/CELL);
          if(seen.has(key)) continue;
          seen.add(key);
          if(classifyAt(localEdges, x, y) === "sidewalk"){
            cornerCells.push({ x, y, parity: (Math.round(x/CELL) + Math.round(y/CELL)) % 2 });
          }
        }
      }
    }
  }
  return { runs, cornerCells };
}

/* ---------- world curb ramps ----------
   The route's own ramps are PHYSICS: they hang off crossings[], which is
   derived from segs[], and they feed crossingGroundAt so the robot
   actually rides them. That is why they only ever existed on the route --
   six of them in a whole city. From a wide view every other intersection
   read as sidewalk running into the street with no transition at all.

   This is the decorative twin, built from grid.edges (the full lattice)
   instead of the route, and it is VISUAL ONLY: no hazard entry, no
   collision, no ground height. Nothing off-route needs physics because
   the robot is never off-route, and giving these a hazard entry would put
   1,200 no-op objects through the collision loop every frame for nothing.

   Geometry mirrors the route's straight crossings exactly, so the two
   sets are indistinguishable where they meet: centred (ROAD_HALF + T2)
   out from the node -- the ramp's 2-tile depth then spans ROAD_HALF to
   ROAD_HALF + 2*T2, abutting the crossing roadway -- and cross-centred at
   ROAD_HALF + 2.5*T2 (the 2026-08-01 on-device dial; this text used to
   claim 1.5*T2, stale since that dial), the same rows 1-3 of the 4-row
   band that laneOffset(CROSSING_RAMP_ROW) gives the route ramps since
   the 2026-08-07 strip shift brought them into line.

   All 'sidewalkend': f points TOWARD the node, and the art descends along
   +f (sidewalk high behind, street-level pad ahead). Every ramp at an
   intersection descends into it, whichever way you approach -- 'begin' is
   the same ramp seen from the other side, not a different object.

   PERIMETER TRIM: a boundary street's outward band sits in the off-grid
   void, so a ramp there faces nothing. Rejected by block index rather
   than by special-casing i/j, which is orientation-independent and lands
   on the same answer findGoodS's facesInterior probe already uses. */
/* BOTH STREETS PER CORNER, or one.

   true  -- 8 ramps per interior node, one for each street at each of the
            four corners. What a modern intersection actually has. The
            two ramps sharing a corner DO overlap: each is 184 deep by
            276 wide and both hug the same curb point, so their
            footprints cross in a 184x184 square and their ADA pads in a
            92x92 one. Coplanar and identically coloured, so it may well
            read as one continuous corner treatment -- but a slope
            crossing a flat pad is drawn, not blended, and whichever
            sorts later wins that square.
   false -- 4 ramps per node, one per corner, alternating which street
            they serve by node parity so the city does not read as
            uniformly oriented. Older intersections look like this.
            Zero overlap by construction.

   No way to have eight and no overlap without reshaping the ramp art
   itself, which is lab-approved and shared with the route's own ramps. */
/* Tunables live on a MUTABLE object, not as separate `const`s, so
   labs/_bench.html can drive them live: the bench compiles inside the
   game's realm, where a const BINDING cannot be reassigned but an
   object's properties can. Paste labs/corner-ramp-tune.js into the
   bench console to get sliders on all of these; porting the result is
   then literally writing the approved numbers in here.

   SLOPE OVERLAP, the thing being tuned: each ramp's slope runs from
   `along` to `along + 2*TILE` and is 2*TILE wide, centred on `cross`.
   The neighbouring street's ramp at the same corner is the same shape
   with the axes swapped, so the two slopes intersect exactly when
       along < cross + TILE   AND   cross < along + 3*TILE
   Both held at the first-shipped 460/506, which is why every corner had
   two slopes drawn through the same 92x92 square. cross >= along + 3*TILE
   makes them abut instead, and 598 is that boundary exactly -- slope gap
   0, patch on the band's outer three rows (460..736), pad still on the
   kerb. Approved on device 2026-08-01 together with outline 1; at 2 the
   two patches crossing at a corner read as crossed rectangles. The pads never overlapped -- that part of my
   first reading was wrong; only the slopes and the base patches do. */
const WORLD_RAMP = {
  along:       ROAD_HALF + T2,        // 460 -- centre out from the node; puts the pad on the kerb
  cross:       ROAD_HALF + 2.5*T2,    // 598 -- dialled on device 2026-08-01; see below
  bothStreets: true,                  // false = one ramp per corner, alternating by node parity
  baseCross:   1.5*(TILE*2),          // 138 -- half-width of the repainted patch under the ramp
  baseOutline: 1                      // 1 -- dialled on device; 2 read as crossed rectangles at a corner
};

/* ---------- TRAFFIC SIGNALS ----------
   Mast-arm signals on the apex tile the curb ramps leave free. With
   WORLD_RAMP.cross at 598 the two ramps at a corner occupy u,v in
   [368,552] on their own axis but start at 460 on the other, so
   u,v in [368,460] is empty -- one 92x92 tile, centre 414/414.

   Checked against the robot's whole route (4,666 samples): its path never
   enters that tile and comes no closer than 91 to the centre. So these are
   scenery plus traffic logic, with no collision, exactly like the ramps.

   Mutable object for the same reason WORLD_RAMP is one -- labs/_bench.html
   compiles inside this realm, where a const binding cannot be reassigned but
   an object's properties can. */
const SIGNAL = {
  /* dialled on device 2026-08-02 via labs/_bench.html?lab=corner-light */
  cycle:    20000,  // full both-axes cycle, ms
  amber:     2600,  // amber at the tail of each green
  allRed:     700,  // both red between phases (not exposed in the tuner)
  poleH:      330,
  armLen:     120,  // arm reach from pole toward the node
  headR:        8,
  stopBand:   180,  // how far back from the line a car will hold
  arm:       true,  // false = pole-mounted head, no mast
  aware:     true,  // false = lights cycle but traffic ignores them
  readable:  true   // see the facing note on drawProp's signalhead branch
};

/* Pure and node-seeded off world time, so the lamp and the car read the
   same light with no shared state to drift. */
function signalPhaseAt(node, t){
  const off = (((node.i*73856093) ^ (node.j*19349663)) >>> 0) % SIGNAL.cycle;
  const half = SIGNAL.cycle/2;
  const u = (t + off) % SIGNAL.cycle;
  const axis = u < half ? 0 : 1;              // the axis holding green
  const inHalf = u % half;
  const g = half - SIGNAL.amber - SIGNAL.allRed;
  return { axis, state: inHalf < g ? "green" : (inHalf < g + SIGNAL.amber ? "amber" : "red") };
}
const signalAxisGo    = (node, t, axis) => { const p = signalPhaseAt(node, t);
                                             return p.axis === axis && p.state !== "red"; };
const signalAxisState = (node, t, axis) => { const p = signalPhaseAt(node, t);
                                             return p.axis === axis ? p.state : "red"; };

/* One signal per corner, arm reaching ACROSS the road it serves. A pole at
   414/414 is outside the roadway (ROAD_HALF 368), so an arm parallel to a
   street would hang over pavement rather than tarmac -- it has to point at
   the node. Corners are assigned diagonally, (-,-) and (+,+) to the x
   street, (-,+) and (+,-) to the y street, which covers all four
   approaches. The head aims back down the served street at the cars it is
   stopping, derived from the corner's own outward direction, so no lane-side
   arithmetic is involved and it holds however the route laid that street out.
   Perimeter trimmed by block index, same probe the ramps use. */
const SIGNAL_APEX = 414;
function buildWorldSignals(grid){
  const out = [];
  for(const n of grid.nodes){
    for(const su of [-1, 1]) for(const sv of [-1, 1]){
      const x = n.x + su*SIGNAL_APEX, y = n.y + sv*SIGNAL_APEX;
      const bi = Math.floor(x/BLOCK), bj = Math.floor(y/BLOCK);
      if(bi < 0 || bi > grid.cols-2 || bj < 0 || bj > grid.rows-2) continue;
      const axis = (su === sv) ? 0 : 1;
      const armF  = axis === 0 ? (sv < 0 ? 1 : 3) : (su < 0 ? 0 : 2);
      const headF = axis === 0 ? (su < 0 ? 2 : 0) : (sv < 0 ? 3 : 1);
      out.push({ x, y, node:{ i:n.i, j:n.j }, axis, armF, headF });
    }
  }
  return out;
}

function buildWorldCurbRamps(grid){
  const ramps = [];
  const along = WORLD_RAMP.along;
  const perpMag = WORLD_RAMP.cross;
  const interior = (x, y) => {
    const bi = Math.floor(x / BLOCK), bj = Math.floor(y / BLOCK);
    return bi >= 0 && bi <= grid.cols-2 && bj >= 0 && bj <= grid.rows-2;
  };
  /* each corner belongs to exactly ONE node -- the one its ramp points
     at -- so parity on that node picks a single street per corner with
     no double-counting across the shared edge. */
  const serves = (n, f) => WORLD_RAMP.bothStreets || (f % 2) === ((n.i + n.j) & 1);
  for(const e of grid.edges){
    const dv = DIRV[e.f], rv = DIRV[(e.f+1)%4];
    for(const side of [-1, 1]){
      const perp = side * perpMag;
      /* the a-end ramp faces BACK down the edge (f+2), the b-end ramp
         faces forward (f) -- both pointing at their own node. */
      if(serves(e.a, e.f)){
        const ax = e.a.x + dv.x*along + rv.x*perp, ay = e.a.y + dv.y*along + rv.y*perp;
        if(interior(ax, ay)) ramps.push({ x: ax, y: ay, f: (e.f + 2) % 4 });
      }
      if(serves(e.b, e.f)){
        const bx = e.b.x - dv.x*along + rv.x*perp, by = e.b.y - dv.y*along + rv.y*perp;
        if(interior(bx, by)) ramps.push({ x: bx, y: by, f: e.f });
      }
    }
  }
  return ramps;
}

/* ---------- the street grid: a real planar graph ---------- */
function nodeShape(n){
  const c = n.conn, count = c.filter(Boolean).length;
  if(count === 4) return "cross";
  if(count === 3) return "t";
  if(count === 2) return (c[0]&&c[2]) || (c[1]&&c[3]) ? "straight" : "corner";
  if(count === 1) return "end";
  return "isolated";
}
/* ---------- block-wrap layout: houses/storefronts packed along each
   block's inner (sidewalk-facing) edge, ported from the block-wrap lab.
   Position-seeded (same convention as palm/planter instance variety
   elsewhere), XORed with the route's own seed so layout varies day to
   day like everything else, while staying deterministic. ---------- */
function packEdge(edgeLen, rng){
  const minGap = T2*0.5, maxGap = T2*1.1;
  const minW = T2*2.4, maxW = T2*4.2; // wide enough that DOOR_W reads as ~25-40% of the facade
  /* corner clearance: a house is HOUSE_DEPTH deep, not just wide — the
     old margin (a fraction of minGap) only kept units from touching
     ALONG the same edge, but said nothing about the PERPENDICULAR
     edge sharing that same corner. Two houses each just inside their
     own edge's old small margin still had their full depth-boxes
     overlapping in the shared corner square. Clearing a full
     HOUSE_DEPTH from each end guarantees the perpendicular edge's own
     depth-box (which clears the same amount from its end) can't reach
     into this edge's corner region either. */
  const cornerMargin = HOUSE_DEPTH + T2*0.3;
  const units = [];
  let cursor = cornerMargin + rng()*(maxGap-minGap)*0.5;
  while(true){
    const w = minW + rng()*(maxW-minW);
    if(cursor + w > edgeLen - cornerMargin) break;
    units.push({ start: cursor, w });
    cursor += w + (minGap + rng()*(maxGap-minGap));
  }
  return units;
}
function packEdgeNoGap(edgeLen, rng){
  const avgW = T2*2.2;
  /* same corner-clearance reasoning as packEdge — storefronts are
     STORE_DEPTH deep, so the "no gap" run needs its own inset from
     each corner even though units within the run stay edge-to-edge. */
  const cornerMargin = STORE_DEPTH + T2*0.3;
  const usableLen = Math.max(avgW, edgeLen - 2*cornerMargin);
  const n = Math.max(1, Math.round(usableLen/avgW));
  const raw = [];
  for(let i=0;i<n;i++) raw.push(0.8 + rng()*0.4);
  const sum = raw.reduce((a,b)=>a+b, 0);
  const units = []; let cursor = cornerMargin;
  for(let i=0;i<n;i++){
    const w = usableLen * raw[i]/sum;
    units.push({ start: cursor, w });
    cursor += w;
  }
  return units;
}
function gapsFromUnits(units, edgeLen){
  const gaps = []; let cursor = 0;
  for(const u of units){
    if(u.start > cursor + 2) gaps.push({ start:cursor, w:u.start-cursor });
    cursor = u.start + u.w;
  }
  if(edgeLen > cursor + 2) gaps.push({ start:cursor, w:edgeLen-cursor });
  return gaps;
}

/* ---------- corner lots (2026-08-06, "corner lots in commercial and
   housing districts not drawing") ----------
   packEdge/packEdgeNoGap clear cornerMargin (= unit depth + T2*0.3) from
   every edge end so perpendicular edges' depth-boxes can't overlap in the
   shared corner square -- correct, but it left a ~3.3-tile square at all
   four corners of every housing/commercial block that nothing ever drew
   in. One dedicated unit per corner fills exactly that square: its width
   runs the cornerMargin along a seeded pick of the corner's two streets,
   its depth is the standard unit depth -- so by the same containment
   argument that created the margin, it cannot overlap either edge's
   packed units (their spans begin exactly where this one ends).
   CORNER_LOT_INSET nudges the unit off the perpendicular block line so a
   housing side fence (which stays: a yard fence along the side street is
   what a real corner lot has) is never coplanar with the flank wall.
   Corner c is the START of edge c and the END of edge (c+3)%4 -- read
   straight off blockEdgesOf's construction order. Position-seeded off the
   corner's own world point, the same discipline as every packed unit. */
const CORNER_LOT_INSET = 8;
function cornerUnitsOf(blk){
  const edges = blockEdgesOf(blk);
  const M = HOUSE_DEPTH + T2*0.3;   // === packEdge/packEdgeNoGap cornerMargin (HOUSE_DEPTH === STORE_DEPTH)
  const out = [];
  for(let c = 0; c < 4; c++){
    const eS = edges[c], eE = edges[(c+3)%4];
    const rng = mulberry32(((Math.round(eS.ox)*7919) ^ (Math.round(eS.oy)*104729) ^ 0x3c17) >>> 0);
    const atStart = rng() < 0.5;               // which of the corner's two streets it faces
    const e = atStart ? eS : eE;
    const start = atStart ? CORNER_LOT_INSET : e.len - M;
    const w = M - CORNER_LOT_INSET;
    const ux = e.ox + e.dv.x*start, uy = e.oy + e.dv.y*start;
    out.push({ edgeIdx: atStart ? c : (c+3)%4, adjEdges: [c, (c+3)%4], e, ux, uy, w, atStart, kind: "cornerStore",
               hx: ux + e.dv.x*w/2, hy: uy + e.dv.y*w/2 });
  }
  return out;
}

function buildBlockLayout(grid, seed){
  const { cols, rows } = grid;
  const inset = ROAD_HALF + SIDEWALK_W;
  const blocks = [];
  for(let j = 0; j < rows-1; j++){
    for(let i = 0; i < cols-1; i++){
      const x0 = i*BLOCK, y0 = j*BLOCK;
      const cx = x0 + BLOCK/2, cy = y0 + BLOCK/2;
      const s = ((Math.round(cx)*7919) ^ (Math.round(cy)*104729) ^ seed) >>> 0;
      const r = mulberry32(s)();
      const type = r < 1/3 ? "housing" : r < 2/3 ? "park" : "commercial";
      blocks.push({
        i, j, cx, cy,
        x0: x0+inset, x1: x0+BLOCK-inset,
        y0: y0+inset, y1: y0+BLOCK-inset,
        type
      });
    }
  }
  return blocks;
}

function lotRect(ox, oy, dv, rv, len, depth){
  const corners = [
    { x:ox, y:oy },
    { x:ox+dv.x*len, y:oy+dv.y*len },
    { x:ox+dv.x*len+rv.x*depth, y:oy+dv.y*len+rv.y*depth },
    { x:ox+rv.x*depth, y:oy+rv.y*depth }
  ];
  const xs = corners.map(c=>c.x), ys = corners.map(c=>c.y);
  return { x0:Math.min(...xs), x1:Math.max(...xs), y0:Math.min(...ys), y1:Math.max(...ys) };
}

function buildExteriorLots(grid, seed){
  const { cols, rows, edges } = grid;
  const inset = ROAD_HALF + SIDEWALK_W;
  const lots = [];
  for(const e of edges){
    let outward = null;
    if(e.f === 0){
      if(e.a.j === 0) outward = DIRV[3];
      else if(e.a.j === rows-1) outward = DIRV[1];
    } else {
      if(e.a.i === 0) outward = DIRV[2];
      else if(e.a.i === cols-1) outward = DIRV[0];
    }
    if(!outward) continue;
    const dv = DIRV[e.f];
    const ox = e.a.x + outward.x*inset, oy = e.a.y + outward.y*inset;
    const cx = (e.a.x+e.b.x)/2 + outward.x*(inset+80), cy = (e.a.y+e.b.y)/2 + outward.y*(inset+80);
    const s = ((Math.round(cx)*7919) ^ (Math.round(cy)*104729) ^ seed ^ 0x3c11) >>> 0;
    const r = mulberry32(s)();
    const type = r < 1/3 ? "housing" : r < 2/3 ? "park" : "commercial";
    lots.push({ ox, oy, dv, rv:outward, len:BLOCK, cx, cy, type });
  }
  return lots;
}

function buildGrid(cols, rows, seed=0, opts){
  /* classic: skip the coast-era swallow pass entirely for this grid,
     regardless of the global WORLDGEN_COAST default. Exists so a FROZEN
     seed (HJ_SEED_DATE, the atlas) always rebuilds the exact block
     layout it was tuned/tagged against, immune to worldgen features
     that ship after the freeze — see HJ drift note, 2026-08-10. */
  const classic = !!(opts && opts.classic);
  const nodes = [];
  for(let j=0; j<rows; j++) for(let i=0; i<cols; i++)
    nodes.push({ i, j, x:i*BLOCK, y:j*BLOCK, conn:[false,false,false,false] });
  const nodeAt = (i,j) => (i<0||i>=cols||j<0||j>=rows) ? null : nodes[j*cols+i];
  const edges = [];
  for(let j=0; j<rows; j++) for(let i=0; i<cols-1; i++){
    const a = nodeAt(i,j), b = nodeAt(i+1,j);
    a.conn[0] = true; b.conn[2] = true;
    edges.push({ a, b, f:0 });
  }
  for(let j=0; j<rows-1; j++) for(let i=0; i<cols; i++){
    const a = nodeAt(i,j), b = nodeAt(i,j+1);
    a.conn[1] = true; b.conn[3] = true;
    edges.push({ a, b, f:1 });
  }
  for(const n of nodes) n.shape = nodeShape(n);
  const grid = { cols, rows, nodes, edges, nodeAt, classic };
  /* zoning before pavement (2026-08-06, city survey): block types must
     exist before the swallow pass decides which streets survive, and
     everything pavement-shaped derives AFTER, so the whole city reacts
     to the final street set through the one lattice it already reads.
     buildBlockLayout only consumes cols/rows/seed, so hoisting it above
     the geometry builders changes nothing else. */
  grid.blocks = buildBlockLayout(grid, seed);
  grid.blockByIJ = new Map(grid.blocks.map(b => [b.i + "," + b.j, b]));
  if(WORLDGEN_COAST && !classic){
    /* MERGED PARKS SWALLOW THEIR STREETS. A street edge separates two
       block cells; when both are parks they are one park by adjacency,
       and the street between them stops existing — here, in the
       lattice, before anything derives from it. Roads, sidewalks, curb
       ramps, signals, classify, the walk, traffic and the GPS map all
       read grid.edges or conn, so removing the edge removes the street
       everywhere at once through the real call path. conn is cleared
       on both nodes so buildWalk and buildTraffic can never route
       through the grass; node shapes are rebuilt because a swallowed
       edge changes what kind of intersection its endpoints are. */
    const isPark = (i, j) => { const b = grid.blockByIJ.get(i + "," + j); return !!b && b.type === "park"; };
    const keep = [];
    for(const e of edges){
      const gone = e.f === 0 ? (isPark(e.a.i, e.a.j - 1) && isPark(e.a.i, e.a.j))
                             : (isPark(e.a.i - 1, e.a.j) && isPark(e.a.i, e.a.j));
      if(gone){
        if(e.f === 0){ e.a.conn[0] = false; e.b.conn[2] = false; }
        else         { e.a.conn[1] = false; e.b.conn[3] = false; }
      } else keep.push(e);
    }
    grid._allEdges = edges;
    if(keep.length !== edges.length){
      grid.edges = keep;
      for(const n of nodes) n.shape = nodeShape(n);
    }
  }
  grid.classify = (x, y) => classifyAt(grid.edges, x, y);
  const sw = buildSidewalkGeometry(grid);
  grid.sidewalkRuns = sw.runs;
  grid.sidewalkCornerCells = sw.cornerCells;
  grid.curbRamps = buildWorldCurbRamps(grid);
  grid.signals   = buildWorldSignals(grid);
  grid.extLots = buildExteriorLots(grid, seed);
  return grid;
}

/* ---------- the walked route: a random walk THROUGH the graph ----------
   Two stages: graph traversal (only ever follows real edges — this is
   what guarantees every turn is a real intersection), then the exact
   fillet-arc construction the game already used, now fed by the graph
   walk instead of arbitrary legs. The street grid stays perfectly
   rectilinear; only the walked line curves through it. */
/* ---------- the seg builder, shared ----------
   A route is a list of legs — direction + length from a start node —
   turned into tangent line+arc segments. buildWalk has always done this
   inline at its tail; hoisted here UNCHANGED so free-drive can build a
   rolling chain through the SAME function instead of a parallel copy of
   the corner math. One builder, every rail. */
function buildSegsFromLegs(startNode, legDescs, turnR){
  const cornerSign = [];
  for(let c = 0; c < legDescs.length - 1; c++){
    const f0 = legDescs[c].f, f1 = legDescs[c+1].f;
    cornerSign.push(((f1 - f0 + 4) % 4 === 1) ? 1 : -1);
  }
  const cornerRadius = cornerSign.map(sg => sg === -ROBOT_SIDE ? turnR : CORNER_R);

  const segs = [];
  let s = 0, p = { x:startNode.x, y:startNode.y };
  for(let i = 0; i < legDescs.length; i++){
    const f = legDescs[i].f, d = DIRV[f], rv = DIRV[(f+1)%4];
    const legLen = legDescs[i].blocks * BLOCK;
    const trimS = i > 0 ? cornerRadius[i-1] : 0;
    const trimE = i < legDescs.length-1 ? cornerRadius[i] : 0;
    const lineLen = legLen - trimS - trimE;
    segs.push({ type:"line", s0:s, s1:s+lineLen, f, hA:f*Math.PI/2,
                start:{ x:p.x + d.x*trimS, y:p.y + d.y*trimS } });
    s += lineLen;
    const cornerP = { x:p.x + d.x*legLen, y:p.y + d.y*legLen };
    if(i < legDescs.length-1){
      const sign = cornerSign[i];
      const R = cornerRadius[i];
      const center = {
        x: cornerP.x - d.x*R + sign*rv.x*R,
        y: cornerP.y - d.y*R + sign*rv.y*R };
      const startPt = { x:cornerP.x - d.x*R, y:cornerP.y - d.y*R };
      const a0 = Math.atan2(startPt.y - center.y, startPt.x - center.x);
      const arcLen = Math.PI/2 * R;
      segs.push({ type:"arc", s0:s, s1:s+arcLen, center, a0, sign,
                  R, hA:f*Math.PI/2, f });
      s += arcLen;
    }
    p = cornerP;
  }
  return { segs, totalLen: s, endP: p };
}

function buildWalk(grid, rng, startOverride, turnsRange, turnR = CORNER_R){
  const { cols, rows, nodeAt } = grid;
  let ci = startOverride ? startOverride.i : 1 + Math.floor(rng()*(cols-2 || 1));
  let cj = startOverride ? startOverride.j : 1 + Math.floor(rng()*(rows-2 || 1));
  let cur = nodeAt(ci, cj) || grid.nodes[Math.floor(rng()*grid.nodes.length)];
  let dir = Math.floor(rng()*4);
  while(!cur.conn[dir]) dir = (dir+1)%4;
  let turnSign = rng() < 0.5 ? 1 : -1;
  /* the turn loop below alternates between exactly two headings (dir
     and dir+turnSign) for the whole route unless a grid boundary
     forces a fallback — so if BOTH of those two headings land in
     {1,2} (south/west), the entire route can end up with zero f===0
     or f===3 legs. findGoodS then has nothing to find and falls back
     to an unguarded position, which is what caused occasional
     wrong-heading (f===1/f===2) starts. Bias the first turn's sign
     away from that trap so the alternating pair always includes at
     least one good heading — this only affects the coin-flip default,
     the per-turn connectivity fallback further down is untouched. */
  const isGoodF = f => f === 0 || f === 3;
  const firstAlt = ((dir + turnSign) % 4 + 4) % 4;
  if(!isGoodF(dir) && !isGoodF(firstAlt)) turnSign = -turnSign;
  /* player-route default raised from 2-3 turns to 4-6: the 1-mile
     route minimum (MIN_ROUTE_UNITS) needs a good-heading leg past the
     mile mark to exist, and 3-4-leg walks frequently had none —
     traffic keeps its own explicit {2,3} range. */
  const tMin = turnsRange ? turnsRange.min : 4, tSpan = turnsRange ? (turnsRange.max - turnsRange.min + 1) : 3;
  const nTurns = tMin + Math.floor(rng()*tSpan);

  const startNode = cur;
  const visited = [startNode];   // every real grid node this walk passes through --
                                  // exposed so traffic can seed its own walks from
                                  // points actually along the player's route instead
                                  // of a uniformly random spot anywhere on the map.
  const legDescs = [];
  for(let leg = 0; leg <= nTurns; leg++){
    const maxBlocks = 1 + Math.floor(rng()*2);   // 1-2 blocks/leg — narrowed further (was 1-3, originally 3-6) to bring the worst case under a 3mi max, same turn character
    let blocks = 0;
    for(let b=0; b<maxBlocks; b++){
      if(!cur.conn[dir]) break;
      const d = DIRV[dir];
      const nxt = nodeAt(cur.i + d.x, cur.j + d.y);
      if(!nxt) break;
      cur = nxt; blocks++;
      visited.push(cur);
    }
    if(blocks > 0){
      legDescs.push({ f:dir, blocks });
    } else if(legDescs.length === 0){
      let alt = 0; while(alt<4 && !cur.conn[alt]) alt++;
      if(alt === 4) break;
      dir = alt; leg--; continue;
    }
    if(leg < nTurns){
      let attemptSign = turnSign;
      let nd = ((dir + attemptSign) % 4 + 4) % 4;
      if(!cur.conn[nd]){ attemptSign = -attemptSign; nd = ((dir + attemptSign) % 4 + 4) % 4; }
      if(!cur.conn[nd]) break;
      dir = nd;
      turnSign = -attemptSign;   // alternate from the sign ACTUALLY used, not the original
                                  // intended one — the old code flipped once for the fallback
                                  // then flipped again unconditionally, canceling out and
                                  // silently permitting two same-direction turns in a row
                                  // whenever a boundary block triggered the fallback.
    }
  }

  /* per-corner radius: only OUTSIDE turns (sign === -ROBOT_SIDE) get the
     smaller turnR — those are the only ones that cross the street via
     ramps and need their tangent points aligned to them. INSIDE turns
     (walk stays on continuous sidewalk, no ramps at all — see the
     "outside-turn crossings" block below) keep CORNER_R exactly as
     before; they were never part of the ramp-alignment problem and
     shrinking their radius too is what broke them just now — CORNER_R's
     own comment explains why it can't safely go smaller for a lane that
     has no ramp-crossing reason to. Precomputed per corner (not inline
     in the loop) because trimS on leg i+1 has to match the SAME radius
     used for trimE on leg i — both sides of one corner must agree or
     the fillet stops being tangent. */
  const built = buildSegsFromLegs(startNode, legDescs, turnR);
  return { segs: built.segs, totalLen: built.totalLen || 1, nodes: visited };
}

/* ---------- traffic: reuses buildWalk verbatim for each route, two
   cars per route (one each direction, opposite lane) ---------- */
function buildTraffic(grid, rng, nRoutes, pathNodes){
  const cars = [];
  for(let r = 0; r < nRoutes; r++){
    const routeRng = mulberry32(Math.floor(rng()*4294967296));
    /* seed from a random point ALONG the player's own route path (if
       given) instead of a uniformly random grid node. Also: a SHORT
       turn range (2-3 vs the player's 5-10) so each loop's own
       footprint stays small and local to that seed point instead of
       wandering off across the map -- otherwise "starts near the
       player" didn't mean "stays anywhere near the player", since the
       loop keeps re-tracing whatever path it wandered into. */
    const seedNode = pathNodes && pathNodes.length ? pathNodes[Math.floor(rng()*pathNodes.length)] : null;
    const walk = buildWalk(grid, routeRng, seedNode, {min:2, max:3});
    if(!walk.segs.length) continue;
    /* 0.055-0.085 units/ms — roughly 3x the original crawl. The robot
       clamps at 0.15, cruises ~0.10; city traffic should read faster
       than a delivery robot, and at the old 0.02-0.034 it never did.
       (On-device report: "the speed of the cars/truck doesn't seem
       fast enough.") */
    const speed = 0.055 + rng()*0.03;
    const sBase = rng()*walk.totalLen;
    cars.push({ walk, sBase, speed, dir:1, laneOffset:CAR_LANE, kind: rng()<0.6?"car":"truck", colorSeed: Math.floor(rng()*0xffffffff) >>> 0 });
    cars.push({ walk, sBase:(sBase + walk.totalLen*0.5) % walk.totalLen,
                speed: speed*(0.85+rng()*0.3), dir:-1, laneOffset:-CAR_LANE,
                kind: rng()<0.6?"car":"truck", colorSeed: Math.floor(rng()*0xffffffff) >>> 0 });
    /* third car on the same loop, staggered a third of the way around
       and running the opposite direction to the first -- same loop,
       same lane geometry, just another phase so the loop reads as busy
       instead of empty most of the time. */
    cars.push({ walk, sBase:(sBase + walk.totalLen*0.33) % walk.totalLen,
                speed: speed*(0.9+rng()*0.25), dir:1, laneOffset:CAR_LANE,
                kind: rng()<0.6?"car":"truck", colorSeed: Math.floor(rng()*0xffffffff) >>> 0 });
  }
  return cars;

}

/* standalone path helpers for generateRoute (a plain function, no `this`) —
   mirror the scene's own segAt/posAt/headingAt exactly so hazard placement
   lines up with wherever the robot's own position code says it should. */
function segsSegAt(segs, s){
  for(const sg of segs) if(s <= sg.s1) return sg;
  return segs[segs.length-1];
}
function segsPosAt(segs, s){
  const sg = segsSegAt(segs, s);
  const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
  if(sg.type === "line"){
    const d = DIRV[sg.f], u = clamp(s, sg.s0, sg.s1) - sg.s0;
    return { x: sg.start.x + d.x*u, y: sg.start.y + d.y*u };
  }
  const a = sg.a0 + sg.sign * (clamp(s, sg.s0, sg.s1) - sg.s0) / sg.R;
  return { x: sg.center.x + Math.cos(a)*sg.R, y: sg.center.y + Math.sin(a)*sg.R };
}
function segsHeadingAt(segs, s){
  const sg = segsSegAt(segs, s);
  const clamp = (v,a,b) => Math.max(a, Math.min(b, v));
  if(sg.type === "line") return sg.hA;
  return sg.hA + sg.sign * (clamp(s, sg.s0, sg.s1) - sg.s0) / sg.R;
}
function segsWorldOf(segs, s, offsetUnits){
  const hdg = segsHeadingAt(segs, s), p = segsPosAt(segs, s);
  const rvx = -Math.sin(hdg), rvy = Math.cos(hdg);
  return { x: p.x + rvx*offsetUnits, y: p.y + rvy*offsetUnits };
}
/* pure, shared by both the renderer and the collision check (drawRobot)
   so a car's hitbox always matches exactly where it's drawn -- same
   principle as dogSpotAt/dogFleeAt already use for the dog. */
function trafficWorldAt(tr, t){
  const trTotal = tr.walk.totalLen;
  /* tr.hold is ACCUMULATED STOPPED TIME, and it is subtracted here —
     inside the one function the renderer and the collision check both
     call. A stop implemented anywhere else (a flag consulted only by
     the draw pass, a shadow position kept in the sim's own bookkeeping)
     leaves this function returning the car's unstopped position, so the
     car keeps driving and its hitbox keeps moving while the test that
     "proved" it stopped passes happily. Measure the thing the game
     actually reads. */
  const te = t - (tr.hold || 0);
  const trS = ((tr.sBase + te*tr.speed*tr.dir) % trTotal + trTotal) % trTotal;
  const hdg = segsHeadingAt(tr.walk.segs, trS) + (tr.dir < 0 ? Math.PI : 0);
  const fi = Math.round(hdg / (Math.PI/2));
  const trF = ((fi % 4) + 4) % 4;

  /* Straddle past the blocking cruiser. The cruiser sits in the near
     lane, so the only way past is on the CENTRELINE side — pushing
     "away from the cruiser" instead sends the car over the kerb onto
     the sidewalk. Cars shift out to sit against the centreline and stop
     there: at CRIME_STRADDLE they end 16 short of it, overlapping it by
     half a body, while the oncoming lane centre is a further 184 away.
     Opposing traffic therefore cannot overlap no matter how the phase
     timings drift — separation by geometry, not by tuning. */
  let lane = tr.laneOffset, straddle = 0;
  const P = tr.pinch;
  if(P){
    const base = segsWorldOf(tr.walk.segs, trS, tr.laneOffset);
    const d = Math.hypot(base.x - P.x, base.y - P.y);
    const lat = (base.x - P.x)*P.lx + (base.y - P.y)*P.ly;
    if(d < CRIME_PINCH_R && lat < CAR_LANE){      // only the blocked lane
      const u = 1 - d/CRIME_PINCH_R, ease = u*u*(3-2*u);
      /* segsWorldOf applies laneOffset in the UNDIRECTED segment frame —
         it never sees tr.dir. Deriving this from `hdg` (which carries
         the dir flip) inverts the shift for every reversed car, sending
         it over the kerb instead of onto the centreline. Same frame as
         the call being corrected, or the correction is backwards. */
      const h0 = segsHeadingAt(tr.walk.segs, trS);
      const proj = P.lx*(-Math.sin(h0)) + P.ly*Math.cos(h0);
      if(Math.abs(proj) > 1e-6){
        straddle = CRIME_STRADDLE * ease;
        lane += Math.sign(proj) * straddle;
      }
    }
  }
  const wp = segsWorldOf(tr.walk.segs, trS, lane);
  wp.z = 0;
  /* straddle is returned, not recomputed by the caller: the phase
     interlock has to ask "is this car still out of its lane" of the
     same call that decides where the car IS. */
  /* f is the QUANTIZED facing (0-3) -- the phase machine's DIRV lookups
     and anything else that needs an axis still use it. fc is the SAME
     heading unquantized, in quarter-turn units, for the renderer and
     the hitbox: through a corner arc the quantized value is up to 45
     degrees off the direction the car is actually travelling, which is
     what made every turn read as a sideways slide. */
  return { wp, f: trF, fc: hdg / (Math.PI/2), trS, straddle };
}

/* the address (and, later, the pickup) needs to sit on a straight leg
   whose heading is f===0 or f===3 — the two directions the block-wrap
   cutaway never touches. f===1/f===2 are exactly the headings where a
   nearby block's near wall gets cut away, so a door placed on one of
   those legs could have its own house wall vanish out from under it
   the moment the robot arrives. Search outward from the natural
   position (still totalLen-90 / SPAWN_S+90 — this does NOT change
   route length or leg count, just which existing point along the
   already-generated route gets used) for the nearest usable leg. */
function findGoodS(segs, totalLen, preferredS, scanFromEnd, grid, avoidBlock, minS = 0, relaxed = false){
  const isGood = sg => sg.type === "line" && GOOD_LEG_HEADING[sg.f];
  /* PERIMETER GUARD: a good leg can still run along the grid's outer edge
     with the robot's lane facing OUTWARD, off the grid. There, the address
     forcing (findAdjacentBlock -> .type="housing") clamps to a far interior
     block that the robot never reaches, while the building actually rendered
     at the robot's side is an exterior lot (buildExteriorLots) whose type is
     never forced -- so the route can end in front of a park or a business
     instead of a house. Reject any candidate whose near-side probe leaves the
     interior grid. Probe MUST match findAdjacentBlock's (same nearOff) so the
     leg we accept is the leg whose interior block is the one that gets forced.
     AVOID_BLOCK: the pickup must not land on the address's own block — a single
     block is forced to ONE type, so a shared block means the pickup silently
     renders as the address house instead of a shop. Passing the address block
     here keeps dropoff and pickup on distinct blocks so each gets its own type. */
  const nearOff = ROBOT_SIDE * (ROAD_HALF + SIDEWALK_W + T2*2);
  const facesInterior = (s) => {
    if(!grid) return true; // no grid supplied -> legacy behaviour (never reject)
    const p = segsWorldOf(segs, s, nearOff);
    const bi = Math.floor(p.x / BLOCK), bj = Math.floor(p.y / BLOCK);
    return bi >= 0 && bi <= grid.cols-2 && bj >= 0 && bj <= grid.rows-2;
  };
  const order = scanFromEnd ? [...segs].reverse() : segs;
  let interiorFallback = null; // interior-facing, but on the avoided block
  let anyFallback = null;      // any usable good leg (even facing outward)
  for(const sg of order){
    if(!isGood(sg)) continue;
    const len = sg.s1 - sg.s0;
    /* relaxed pass (see the fallback chain at the bottom): accept
       placement much closer to a corner rather than fall off the
       good-heading legs entirely — a door 24 units from an arc beats
       a door on an f=1 leg with no house behind it. */
    const inset = relaxed ? Math.min(24, len*0.1) : Math.min(90, len*0.3);
    /* minS floor (used by the door search to guarantee a >= 1 mile
       route): any candidate below it is skipped entirely — legs wholly
       under the floor never qualify, straddling legs clamp up to it. */
    const lo = Math.max(sg.s0 + inset, minS), hi = sg.s1 - inset;
    if(hi < lo) continue; // leg too short (or wholly under minS) — skip
    const s = Math.max(lo, Math.min(hi, preferredS));
    if(anyFallback === null) anyFallback = s;
    if(!facesInterior(s)) continue;                 // perimeter — reject (guard)
    if(interiorFallback === null) interiorFallback = s;
    if(avoidBlock && grid){
      const blk = findAdjacentBlock(segs, s, grid);
      if(blk === avoidBlock) continue;              // same block as the address — keep looking
    }
    return s; // interior-facing, distinct-block good leg — the ideal case
  }
  // graceful degradation on tight routes: prefer an interior-facing leg (correct
  // building type) even if it shares the address block, over an outward leg.
  if(interiorFallback !== null) return interiorFallback;
  if(anyFallback !== null) return anyFallback;
  /* no good leg found at the standard inset (2026-07-27, "still
     getting f=1"): this raw fall-through was the ONLY way gate mode
     ever triggered, and it came with no guards at all — no heading
     check, no perimeter check, not even a straight-leg check (the
     door could land mid-arc, where the address-edge math is
     meaningless, and findAdjacentBlock would clamp a perimeter probe
     into the wrong interior block). Chain of last resorts instead:
     1) rescan the same legs accepting near-corner placement — the
        usual reason to be here is every good leg being too short for
        the 90-unit inset, so this rescues most of them with all the
        interior/avoid-block guards intact;
     2) failing that, snap to the nearest STRAIGHT leg to preferredS
        regardless of heading — gate mode, but at least on a real leg
        with a well-defined edge;
     3) the old raw clamp, only if the route somehow has no line
        segments at all. */
  if(!relaxed) return findGoodS(segs, totalLen, preferredS, scanFromEnd, grid, avoidBlock, minS, true);
  /* 2) NO floor-dropping here: an earlier version searched below the
     minS mile floor at this point, which traded route length for
     heading (worst case a 0.22-mile delivery) — rejected. The walk
     generator now guarantees a good leg past the mile mark instead
     (see the hasGoodDoorLeg retry in generateRoute), so reaching this
     line means something upstream broke; the straight-leg snap below
     is purely a crash-proof net. */
  let lineBest = null, lineBd = Infinity;
  for(const sg of segs){
    if(sg.type !== "line") continue;
    const s = Math.max(sg.s0 + 12, Math.min(sg.s1 - 12, preferredS));
    if(s < sg.s0 + 12) continue;   // degenerate leg
    const d = Math.abs(s - preferredS);
    if(d < lineBd){ lineBd = d; lineBest = s; }
  }
  if(lineBest !== null) return lineBest;
  return Math.max(0, Math.min(totalLen, preferredS)); // no straight leg anywhere (should be impossible)
}

/* which real block sits next to a given route position — only valid
   for a "line" segment with f===0 or f===3 (guaranteed by findGoodS's
   search), same restriction the block-wrap cutaway already relies on.
   The robot's fixed sidewalk lane means the near block edge is always
   (f+2)%4 — for f===0 (east) that's the block one row NORTH of the
   street; for f===3 (north), one column WEST of it. Same derivation
   already verified for the cutaway system, just read in the other
   direction (position -> block, not heading -> edge-to-cut). */
function findAdjacentBlock(segs, s, grid){
  /* previously: a distinct, correct formula for f===0 only, with f===1/2/3
     all lumped into one shared "else" branch — wrong for at least f===2
     (confirmed: picked a block over 1300 units from where the route
     segment actually reaches, on west-heading final legs). Replaced with
     a single formula that works for all 4 headings by construction: probe
     the world point the robot's own lane offset actually sits at (same
     segsWorldOf convention used everywhere else — traffic, hazards, the
     robot's own position), then floor it directly into a grid cell. No
     per-direction sign table to get wrong. Validated 0 offset across 400
     test routes spanning all headings and grid-boundary cases. */
  const off = ROBOT_SIDE * (ROAD_HALF + SIDEWALK_W + T2*2);
  const probe = segsWorldOf(segs, s, off);
  let bi = Math.floor(probe.x / BLOCK);
  let bj = Math.floor(probe.y / BLOCK);
  bi = Math.max(0, Math.min(grid.cols-2, bi));
  bj = Math.max(0, Math.min(grid.rows-2, bj));
  return grid.blocks.find(b => b.i === bi && b.j === bj) || null;
}

/* which packed unit (house/store) on an edge is actually closest to
   where a route position crosses that edge — NOT always the first
   one. On a long edge (a full block face can be 1600+ units) the
   route can cross anywhere along it, while packEdge/packEdgeNoGap's
   units[0] always sits near one fixed end; picking units[0]
   unconditionally could put the address/pickup unit over a thousand
   units from where the route actually is. */
function closestUnitIndex(units, targetAlong){
  let best = 0, bestDist = Infinity;
  units.forEach((u, idx) => {
    const mid = u.start + u.w/2;
    const d = Math.abs(mid - targetAlong);
    if(d < bestDist){ bestDist = d; best = idx; }
  });
  return best;
}

/* ================= WEEKLY POLICE CRIME SCENE =================
   An occasional set-piece: on ONE day per week, a commercial block's
   parking lot is a taped-off crime scene with three cruisers and four
   officers.

   THE ROLL IS DELIBERATELY OFF THE ROUTE'S RNG STREAM. generateRoute's
   `rng` is consumed in a fixed order by the grid, the walk and every
   prop after it. Drawing even one value from it to decide the scene
   would shift everything downstream, so the entire city would come out
   a different shape on the days the scene does NOT appear. These roll
   from their own salted hashes of the date and touch nothing else. */
const CRIME_STALLS = 4;          // 2 occupied + 2 clear bays between them
const CRIME_LANE_OFFSET = 118;   // 2nd officer's step down the road from the lane car

/* ---- phased traffic control ----
   TWO tolerances, deliberately separate, because they answer two
   different questions. Collapsing them into one is what made the lab's
   officer wave cars through without ever looking: at a shared value of
   300 the "has the pinch cleared" test was true unconditionally, since
   any car within 300 of the cruiser also counted as *outside* it.
     ONROAD  — "is this car on the crime scene's road at all?"  Wide.
     CLEAR   — "is the pinch itself empty right now?"           Tight. */
const CRIME_ONROAD_TOL = 300;
const CRIME_CLEAR_TOL  = 90;
const CRIME_PHASE_MS    = 5200;  // one direction's green
const CRIME_ALLSTOP_MS  = 900;   // both held while the pinch drains
const CRIME_STOP_R      = 620;   // how far back a held car starts waiting
const CRIME_STOP_LINE   = 210;   // where it actually stops, short of the cruiser
const CRIME_PINCH_R     = 460;   // straddle ramp radius
const CRIME_STRADDLE    = 168;   // lateral shift onto the centreline
/* Clearance interlock, ported back from the bench, which was stricter
   than the first in-game version. Waiting only for the pinch to empty
   released the other direction while a car was still out of its lane
   getting round the cruiser. maxHold stops one stuck car deadlocking
   the junction forever. */
const CRIME_CLEARED_BY  = 45;    // "back in its own lane" threshold
const CRIME_MAX_HOLD    = 5000;  // cap on holding a phase open

/* ---- cordon ----
   PURELY COSMETIC. The robot walks through it: no jostle, no speed
   scrub, and it is never registered as a hazard. It is also the one
   prop in this file that carries MUTABLE STATE — a broken span has to
   stay broken for the rest of the route, which no pure function of
   (position, t) can express. Deliberate exception, not drift; the
   geometry itself stays pure and shared. */
const TAPE = {
  z: 60, half: 6, sag: 9, segs: 14,
  inset: 10,        // pull the stakes in off the kerb and the wall
  halfLen: 330,     // how far up and down the walk the cordon reaches
  snapMs: 520, hang: 0.46,
  yellow: 0xf0c53a, band: 0x23252b,
  stake: 0x585d66, stakeDk: 0x3c414a, stakeH: 74, stakeR: 3.5
};

/* The cordon, derived from the ROUTE — not from the block edge. The
   spans cross the sidewalk band, whose lateral frame is laneOffset()'s
   ROBOT_SIDE*(ROAD_HALF + ...): larger magnitude is further from the
   road, so the kerb is the small offset and the building the large one.
   Anchoring these off the block edge instead would put them in a
   different frame from the walk they are supposed to close off. */
function crimeTapeSpans(segs, s){
  const kerb = ROBOT_SIDE*(ROAD_HALF + TAPE.inset);
  const bldg = ROBOT_SIDE*(ROAD_HALF + SIDEWALK_W - TAPE.inset);
  const at = (ss, off) => segsWorldOf(segs, ss, off);
  const s0 = s - TAPE.halfLen, s1 = s + TAPE.halfLen;
  const P0 = at(s0, bldg), P1 = at(s0, kerb);
  const P2 = at(s1, kerb),  P3 = at(s1, bldg);
  return [
    { a:P0, b:P1, post:[true,true] },    // across the walk, upstream
    { a:P1, b:P2, post:[false,true] },   // the long run along the kerb
    { a:P2, b:P3, post:[false,true] }    // across the walk, downstream
  ];
}

/* Segment-vs-segment, NOT a box around the tape. The ribbon is a thin
   line and the robot is fast enough to step clean over a box between
   frames; testing the robot's previous-to-current travel segment
   against the span cannot tunnel at any frame rate. */
function segCross(p1, p2, p3, p4){
  const d = (p2.x-p1.x)*(p4.y-p3.y) - (p2.y-p1.y)*(p4.x-p3.x);
  if(Math.abs(d) < 1e-9) return false;
  const u = ((p3.x-p1.x)*(p4.y-p3.y) - (p3.y-p1.y)*(p4.x-p3.x)) / d;
  const v = ((p3.x-p1.x)*(p2.y-p1.y) - (p3.y-p1.y)*(p2.x-p1.x)) / d;
  return u >= 0 && u <= 1 && v >= 0 && v <= 1;
}

/* days since epoch; 1970-01-01 was a Thursday, so +3 makes 0 = Monday */
function crimeDayIndex(dateStr){
  const d = Date.parse(dateStr + "T00:00:00Z");
  return Math.floor(d / 86400000);
}
/* exactly one day per Mon-Sun week, by construction: the week key picks
   a weekday, and the date matches iff it IS that weekday. No per-day
   probability that could give a week two scenes or none. */
function crimeSceneOnDate(dateStr){
  const day = crimeDayIndex(dateStr);
  if(!isFinite(day)) return false;
  const week = Math.floor((day + 3) / 7);
  const chosen = Math.floor(mulberry32((hashStr("crime|" + week) ^ 0x5eed) >>> 0)() * 7);
  return (((day + 3) % 7) + 7) % 7 === chosen;
}

/* drawPersonHull's forward axis is bDir = (-sin th, cos th) — NOT aDir.
   Facing a direction D therefore means th = atan2(-Dx, Dy). */
function crimeFacing(D){ return Math.atan2(-D.x, D.y); }

/* Picks the lot and lays out every vehicle and officer ONCE, at route
   generation, from the same parkingStallsAt the renderer uses — so the
   cruisers sit in the bays that actually get painted rather than in a
   second, drifting copy of the stall maths. */
function findCrimeSite(grid, cutEdges, dateStr, segs, totalLen, avoid){
  const rng = mulberry32((hashStr("crimesite|" + dateStr) ^ 0xa71c) >>> 0);
  const blocked = (blk) => (avoid || []).some(b => b && b.i === blk.i && b.j === blk.j);
  const fits = (blk, idx) => parkingStallsAt(blockEdgesOf(blk)[idx], null, CRIME_STALLS);
  const collect = () => {
    const out = [];
    for(const blk of grid.blocks){
      if(blk.type !== "commercial") continue;
      const cuts = cutEdges[blk.i + "," + blk.j];
      if(!cuts) continue;
      for(const idx of cuts){
        const row = fits(blk, idx);
        if(row) out.push({ blk, idx, e: blockEdgesOf(blk)[idx], row });
      }
    }
    return out;
  };

  let cands = collect();
  /* FALLBACK. Cut edges only exist where an f=1/f=2 leg runs — about
     five blocks a route — and only a third of blocks are commercial, so
     roughly a quarter of scene days had no qualifying lot anywhere and
     the scene silently no-showed on its own day. Rather than shrink the
     row (stall width was never the constraint: edges are 1656 and a
     4-bay row needs 612), retype one cut block commercial, exactly as
     the route already does for the pickup shop. Only ever runs on a
     scene day that would otherwise produce nothing, so non-scene days
     are untouched. The address and pickup blocks are excluded — their
     types are forced on purpose and the door must stay housing. */
  if(!cands.length){
    const swaps = [];
    for(const blk of grid.blocks){
      if(blk.type === "commercial" || blocked(blk)) continue;
      const cuts = cutEdges[blk.i + "," + blk.j];
      if(!cuts) continue;
      for(const idx of cuts) if(fits(blk, idx)){ swaps.push(blk); break; }
    }
    if(swaps.length){
      swaps[Math.floor(rng()*swaps.length)].type = "commercial";
      cands = collect();
    }
  }

  /* LAST RESORT — and the reason the delivery sometimes lands on the
     crime scene's own block. Some routes have exactly one cut block and
     it IS the address block, which must never be retyped: the customer's
     house would turn into a storefront under the door. But addCut
     already excludes the address's OWN edge from cutEdges, so any cut
     edge on that block is a DIFFERENT side of it — safe to use, and the
     lot goes there without the block changing type at all. The renderer
     lays the crime row on a cut edge whatever the block is zoned. */
  if(!cands.length){
    for(const blk of grid.blocks){
      const cuts = cutEdges[blk.i + "," + blk.j];
      if(!cuts) continue;
      for(const idx of cuts){
        const row = fits(blk, idx);
        if(row) cands.push({ blk, idx, e: blockEdgesOf(blk)[idx], row });
      }
    }
  }
  if(!cands.length) return null;
  const pick = cands[Math.floor(rng() * cands.length)];
  const { blk, idx, e, row } = pick;
  const at = (a, b) => ({ x: e.ox + e.dv.x*a + e.rv.x*b, y: e.oy + e.dv.y*a + e.rv.y*b });

  /* rv points OUT of the block: sidewalk first, then the road, with the
     centreline exactly inset away (blocks are inset by ROAD_HALF +
     SIDEWALK_W from the grid line). The blocking cruiser sits IN the
     near traffic lane, not on the centreline — on the centreline its
     90-wide body spans only +-45 and the lanes at +-CAR_LANE (184)
     drive past untouched, so it would not have blocked anything. */
  const centreB = SIDEWALK_W + ROAD_HALF;
  const laneB = centreB - CAR_LANE;
  const gapA  = row.startAlong + row.stallW*2;      // middle of the two clear bays
  const fAlong = DIRV.findIndex(d => d.x === e.dv.x && d.y === e.dv.y);

  const s0 = row.stalls[0], s3 = row.stalls[CRIME_STALLS-1];
  const laneCar = at(gapA, laneB);
  const cars = [
    { x: s0.x, y: s0.y, fdir: s0.fdir, seed: (hashStr(dateStr+"|c0")>>>0), strobe: 0.0 },
    { x: s3.x, y: s3.y, fdir: s3.fdir, seed: (hashStr(dateStr+"|c1")>>>0), strobe: 0.37 },
    { x: laneCar.x, y: laneCar.y, fdir: fAlong, seed: (hashStr(dateStr+"|c2")>>>0), strobe: 0.71 }
  ];

  const into = { x:-e.rv.x, y:-e.rv.y }, out = e.rv, along = e.dv;
  const offP = [
    { a: row.startAlong + row.stallW*1.05, b: 26,  role:"tape",    D: along },
    { a: row.startAlong + row.stallW*2.0,  b: -70, role:"search",  D: into  },
    { a: row.startAlong + row.stallW*3.5,  b: 14,  role:"post",    D: out   },
    { a: gapA + CRIME_LANE_OFFSET,         b: SIDEWALK_W + ROAD_HALF*0.55, role:"traffic", D: along }
  ];
  const officers = offP.map((o, k) => {
    const p = at(o.a, o.b);
    return { x:p.x, y:p.y, thW: crimeFacing(o.D), role:o.role, seed:(hashStr(dateStr+"|o"+k)>>>0) };
  });

  /* the cordon closes off a stretch of the WALK, so it needs the route
     arclength beside the lot — found by sampling the robot's own lane
     line, the same line the tape spans will be measured from */
  let siteS = null;
  if(segs && totalLen){
    let best = Infinity;
    const lotX = (s0.x + s3.x)/2, lotY = (s0.y + s3.y)/2;
    for(let ss = 0; ss < totalLen; ss += TILE){
      const wp = segsWorldOf(segs, ss, laneOffset(1));
      const d = (wp.x-lotX)*(wp.x-lotX) + (wp.y-lotY)*(wp.y-lotY);
      if(d < best){ best = d; siteS = ss; }
    }
  }
  const tape = (siteS != null) ? crimeTapeSpans(segs, siteS) : null;

  return { blockKey: blk.i + "," + blk.j, edgeIdx: idx, cars, officers,
           laneB, gapA, fAlong, edge: { ox:e.ox, oy:e.oy, dv:e.dv, rv:e.rv, len:e.len },
           siteS, tape,
           /* mutable per-run break state — see TAPE's note */
           tapeBroken: tape ? tape.map(() => false) : null,
           tapeBrokeAt: tape ? tape.map(() => 0) : null,
           /* the pinch: where the road narrows past the blocking cruiser.
              ax/ay is along the road, lx/ly across it. */
           pinch: { x: laneCar.x, y: laneCar.y,
                    ax: e.dv.x, ay: e.dv.y, lx: e.rv.x, ly: e.rv.y } };
}


/* ---------- worldgen reconcile (coast) ----------
   The swallow pass runs inside buildGrid, before the walk, because conn
   is what steers buildWalk away from the grass. But generateRoute
   retypes blocks AFTER that — address to housing, pickup to commercial,
   the crime swap — and a retyped ex-park can leave its streets
   swallowed with no park left to justify it (found as three missing
   streets around a commercial pickup block: rule said 59, world had
   62). So the lattice gets one reconcile against FINAL zoning: any
   removed edge the retypes un-justified is restored, conn is rebuilt
   from scratch off the final edge set, and the pavement (sidewalks,
   curb ramps, signals) is re-derived through the same builders
   buildGrid used. Retypes never create parks, so reconcile only ever
   restores — the walk simply never needed the streets it gives back. */
function worldgenReconcile(grid){
  if(!WORLDGEN_COAST || grid.classic || !grid._allEdges) return;
  const isPark = (i, j) => { const b = grid.blockByIJ.get(i + "," + j); return !!b && b.type === "park"; };
  const keep = grid._allEdges.filter(e =>
    !(e.f === 0 ? (isPark(e.a.i, e.a.j - 1) && isPark(e.a.i, e.a.j))
                : (isPark(e.a.i - 1, e.a.j) && isPark(e.a.i, e.a.j))));
  if(keep.length === grid.edges.length) return;
  grid.edges = keep;
  for(const n of grid.nodes) n.conn = [false, false, false, false];
  for(const e of keep){
    if(e.f === 0){ e.a.conn[0] = true; e.b.conn[2] = true; }
    else         { e.a.conn[1] = true; e.b.conn[3] = true; }
  }
  for(const n of grid.nodes) n.shape = nodeShape(n);
  const sw = buildSidewalkGeometry(grid);
  grid.sidewalkRuns = sw.runs;
  grid.sidewalkCornerCells = sw.cornerCells;
  grid.curbRamps = buildWorldCurbRamps(grid);
  grid.signals   = buildWorldSignals(grid);
  delete grid.swRunHash; delete grid.swCornerHash; delete grid.curbRampHash;
}

/* ROUTE GENERATION CACHE (2026-08-10, "it needs to cache"): generateRoute
   is a genuinely expensive, PURE function of (dateStr, hoodIndex, classic,
   challenge) -- confirmed by direct measurement, ~1.6-3.5s on the merged
   12-district map, and confirmed byte-deterministic (same inputs, same
   output, every time -- see the earlier Cone Slalom pin-vs-route fix,
   which relied on exactly that property). Every frozen course
   (HJ_SEED_DATE, SL_SEED_DATE) was getting rebuilt from scratch on EVERY
   visit -- selecting Cone Slalom from the map, then pressing GO, was two
   full rebuilds of the identical street grid and gate corridor seconds
   apart, and that block is long enough that nothing can visibly animate
   through it regardless of what the loading spinner does (see
   ROUTE_LOADING_MIN_IDLE_MS above) -- the only real fix is not paying for
   the rebuild twice.

   The risk is everything gameplay bolts onto the result afterward and
   mutates in place: hz.hit/burst/kst/phi/angVel/... extensively (see the
   collision/physics code), route.hazards/props get PUSHED onto directly at
   runtime (course hydrants/ramps added when a challenge starts) as well as
   reassigned (stale-hazard cleanup filters), and route.pickupSpot/doorS/
   crime get reassigned live during a session. Sharing the cached object
   directly would leak one session's mutations into the next replay of the
   identical course -- exactly the class of bug "Fix slalom cone stacking"
   already had to patch once for stale hazards specifically.

   So the cache stores the PRISTINE result from _generateRouteFresh, and
   every retrieval -- hit or miss -- hands back a fresh top-level clone
   with hazards individually shallow-cloned too (the only field with deep
   in-place field mutation; a reassignment or .push() on a caller's own
   .map()-derived array can never touch the cached original either way).
   grid/segs/tiles/props/pal/etc. are never mutated after generation
   (checked: no assignment to any of their fields anywhere outside
   construction) and stay shared by reference -- that's where the actual
   saving comes from. The clone itself costs microseconds; the expensive
   part (buildGrid/buildWalk/course search) never reruns for inputs it's
   already built. */
const _routeGenCache = new Map();
function generateRoute(dateStr, opts){
  const key = dateStr + "|" + (opts && opts.hoodIndex != null ? opts.hoodIndex : "")
            + "|" + !!(opts && opts.classic) + "|" + !!(opts && opts.challenge);
  let cached = _routeGenCache.get(key);
  if(!cached){
    cached = _generateRouteFresh(dateStr, opts);
    _routeGenCache.set(key, cached);
  }
  return { ...cached, hazards: cached.hazards.map(h => ({...h})) };
}
function _generateRouteFresh(dateStr, opts){
  const seed = hashStr(dateStr);
  const rng = mulberry32(seed);
  /* THE CITY IS PERMANENT NOW (2026-08-10, Sir's call). cols/rows/grid
     used to come off the SAME daily `seed` as everything else in this
     function, which is exactly why the street layout used to be a new
     city every day. That's the one thing this freezes: cols, rows, and
     buildGrid all read off CITY_SEED -- a fixed structural seed derived
     from SL_SEED_DATE, the same frozen date the slalom course already
     builds its own city from -- so the daily route, Cone Slalom, and
     Hydrant Challenge are all standing on the literal same streets and
     blocks, forever. `classic:true` is forced unconditionally too --
     the whole reason that flag exists is "a frozen seed always rebuilds
     the exact block layout it was tuned against, immune to worldgen
     features that ship after the freeze" (see buildGrid's own comment),
     which is precisely the guarantee a permanent city needs.

     ALL 12 HOODS, ONE MAP (2026-08-10, Sir's call, same day): the city
     used to be one hood's grid, picked by seed. It's now ALL twelve,
     tiled into a fixed 4x3 grid of districts -- HOODS[0] ("The Flats")
     at district (0,0) through HOODS[11] ("Palm Gardens") at (3,2),
     row-major. The street MESH itself (buildGrid's nodes/edges/blocks)
     is one uniform algorithm regardless of hood -- it never took a hood
     parameter before this and still doesn't -- so districts connect
     seamlessly at their borders for free; nothing about intersections,
     turns, or block placement needed to change. hoodAt(i,j) is the one
     new piece: given a block position, which district's hood owns it.
     Every place below that used to read the single `hood` for something
     tied to a SPECIFIC position (a street name, a park name, a shop
     name) now looks it up through hoodAt at that position instead, so
     a Warehouse Dist. block still gets a Warehouse Dist. street name
     even though it's one corner of a much bigger map.

     NOT regionalized this pass, deliberately: elevation (HILL_AMP) and
     the world's colour palette are each a single value for the WHOLE
     map still, sourced from BLEND (the average of all 12 hoods' knobs)
     rather than any one hood's. Making terrain and palette vary by
     district too means blending across district borders so a Flats/
     Bluffs seam doesn't read as a cliff -- a real change, just not
     THIS one. BLEND is a principled placeholder for that, not a bug:
     the whole map reads as one moderate, consistent city today, and
     region-specific terrain/palette is the natural next pass. */
  const CITY_SEED = hashStr(SL_SEED_DATE);
  const cols = DISTRICT_COLS * DISTRICT_W;
  const rows = DISTRICT_ROWS * DISTRICT_H;
  /* hoodAt/hoodAtWorld/BLEND are global now -- one definition, shared with
     mapParkName and the map's own street-label drawing. See their own
     comment where they're declared, right after HOODS. */
  /* opts.hoodIndex still forces which DISTRICT the Hydrant Challenge's
     own course search happens in (The Flats, index 0) -- terrain isn't
     regionalized this pass (see above), so the flat-grade reasoning
     doesn't bind yet, but the address text ("The Flats") and the
     course's own visible surroundings (street/park names) should still
     agree with each other, so the search stays scoped to that district. */
  const hood = HOODS[(opts && opts.hoodIndex != null ? opts.hoodIndex : CITY_SEED) % HOODS.length];

  /* real street grid, generated independently of the walked route —
     this is what makes actual intersections possible. */
  /* classic:false NOW (2026-08-10, reverted the same day it was added):
     forcing classic:true here was meant to protect the permanent city
     from future worldgen drift, the same reasoning HJ_SEED_DATE always
     used it for. It had a side effect nobody wanted: classic SKIPS the
     park-merge swallow pass entirely (see buildGrid's own "MERGED PARKS
     SWALLOW THEIR STREETS" comment) -- adjacent park blocks stopped
     fusing into one contiguous green space and started rendering as
     separate lots with a street still cutting through them, which is
     NOT how the daily route ever looked before tonight. Both the daily
     route and Cone Slalom's own original generateRoute(SL_SEED_DATE)
     call were ALWAYS non-classic (only Hydrant Challenge's call ever
     passed classic:true, for its own precision-jump-course reasons) --
     forcing it everywhere overcorrected. Reverted to match what the two
     more common cases actually want; Hydrant Challenge's course search
     (district-scoped, see findCourseLeg) gets re-verified against the
     swallow pass being active rather than being carved out as a special
     case, since every caller sharing one real grid is the whole point
     of the permanent map. */
  /* HJ DRIFT REDUX (reported 2026-08-10, same day as the revert above):
     the revert fixed park-merging for the daily route and Cone Slalom,
     but it hardcoded classic:false for EVERY caller instead of reading
     opts.classic -- silently dropping the Hydrant Challenge's own
     classic:true request (still passed by loadRoute, see HJ_SEED_DATE's
     own note above). The course's curb ramps and hazard rows are placed
     against the classic lattice they were tuned on; building the grid
     itself on the swallow-pass lattice instead reintroduced exactly the
     misalignment (curb ramps off by a row) and prop-density drift
     (extra people) HJ_SEED_DATE existed to prevent. Reading opts.classic
     restores the original per-caller intent: HJ opts in, the daily
     route and Cone Slalom (which never pass classic) are untouched. */
  const grid = buildGrid(cols, rows, CITY_SEED, { classic: !!(opts && opts.classic) });
  /* good-heading guarantee (2026-07-27, "that is unacceptable"): the
     door needs an f===0/f===3 straight leg past the 1-mile mark with
     room for findGoodS's standard 90-unit inset. buildWalk's turnSign
     bias makes such a leg LIKELY but not certain (census: 9/120 daily
     routes had none, and the only alternatives were a gate address on
     a cut heading or a sub-mile door — both rejected). Deterministic
     retry instead: same date-seeded rng stream, so re-rolling is
     reproducible per date; 92% per-attempt success makes 8 attempts
     astronomically safe, and the door search below keeps its own
     fallback chain as the final net regardless. Route length is
     untouched — every accepted walk satisfies the full mile floor. */
  /* HYDRANT CHALLENGE COURSE. Needs one straight leg long enough to hold
     the run-up, the kicker, ten hydrants and the catch ramp, on a heading
     the block-wrap cutaway never touches (same GOOD_LEG_HEADING rule the
     address uses, for the same reason: an f===1/f===2 leg can have a wall
     cut away out from under it). Measured in the lab, level 10 spans
     s=0 to LAND.s+1 = 12.7 tile-pairs, so the leg must be at least that
     plus the run-up. */
  const findCourseLeg = (segs) => {
    /* run-up + kicker tile + the level-10 course + the catch ramp tile */
    const NEED = HJ_GEOM.runup + TILE + (2.25 + 9*0.55)*T2 + 2*TILE;
    /* DISTRICT-SCOPED NOW (2026-08-10): before the merge, "the whole grid"
       and "The Flats" were the same thing -- HJ built its own small,
       single-hood city, so any long-enough leg anywhere in it WAS in The
       Flats by construction. Now every route shares one 12-district map,
       and this search has to say so explicitly or the hydrant course can
       land in any of the twelve, unrelated to its own "1200 Palmline Ave,
       The Flats" address. Only filters when the caller actually asked for
       a hood (opts.hoodIndex != null) -- the daily route's own door-leg
       search reuses this same file's GOOD_LEG_HEADING rule elsewhere and
       was never hood-scoped, so it stays exactly as unconstrained as it
       always was. */
    const wantHood = (opts && opts.hoodIndex != null) ? HOODS[opts.hoodIndex] : null;
    let best = null;
    for(const sg of segs){
      if(sg.type !== "line" || !GOOD_LEG_HEADING[sg.f]) continue;
      const len = sg.s1 - sg.s0;
      if(len < NEED) continue;
      if(wantHood){
        const mid = segsPosAt(segs, (sg.s0+sg.s1)/2);
        if(hoodAtWorld(mid.x, mid.y) !== wantHood) continue;
      }
      if(best === null || sg.s0 < best.s0) best = sg;
    }
    return best;
  };

  const hasGoodDoorLeg = w => w.segs.some(sg => {
    if(sg.type !== "line" || !GOOD_LEG_HEADING[sg.f]) return false;
    const inset = Math.min(90, (sg.s1 - sg.s0)*0.3);
    return sg.s1 - inset >= Math.max(sg.s0 + inset, MIN_ROUTE_UNITS);
  });
  /* walk starts inside the requested district now, not wherever the rng
     happens to land in a map twelve times the size it used to be. Only
     matters when opts.hoodIndex is set (Hydrant Challenge); the daily
     route's own start stays exactly as unconstrained/random as before. */
  const districtStart = (opts && opts.hoodIndex != null)
    ? { i: (opts.hoodIndex % DISTRICT_COLS)*DISTRICT_W + Math.floor(DISTRICT_W/2),
        j: Math.floor(opts.hoodIndex/DISTRICT_COLS)*DISTRICT_H + Math.floor(DISTRICT_H/2) }
    : undefined;
  let walk = buildWalk(grid, rng, districtStart, undefined, TURN_R);
  for(let att = 0; att < 8 && !hasGoodDoorLeg(walk); att++)
    walk = buildWalk(grid, rng, districtStart, undefined, TURN_R);
  const segs = walk.segs, totalLen = walk.totalLen;

  const inCorner = sv => segs.some(sg => sg.type === "arc" && sv > sg.s0 - CORNER_HAZARD_CLEAR && sv < sg.s1 + CORNER_HAZARD_CLEAR);
  const facingAt = sv => {
    for(const sg of segs) if(sv >= sg.s0 && sv <= sg.s1) return sg.f;
    return segs[segs.length-1].f;
  };
  /* verifies a candidate placement against the grid directly instead of
     predicting conflicts via s-distance heuristics — a long route can
     pass near its own earlier path, which no local margin can see. */
  const onSidewalk = (s, offsetUnits) => {
    const wp = segsWorldOf(segs, s, offsetUnits);
    return grid.classify(wp.x, wp.y) === "sidewalk";
  };
  const onRoad = (s, offsetUnits) => {
    const wp = segsWorldOf(segs, s, offsetUnits);
    return grid.classify(wp.x, wp.y) === "road";
  };

  /* snap a candidate along-path s to the nearest REAL sidewalk tile
     center (grid.sidewalkRuns, the same T2 grid buildSidewalkGeometry
     draws) — for tile-sized props like the slab, an unsnapped s can
     land anywhere within a tile, so the panel straddles a seam or
     bleeds toward the road edge instead of sitting on one panel.
     Only the along-path component needs correcting: laneOffset(row)
     already lands exactly on the tile's row center by construction
     (same ROAD_HALF+(t+0.5)*T2 formula the tile grid itself uses). */
  const snapToSidewalkTile = (sv, row) => {
    const wp = segsWorldOf(segs, sv, laneOffset(row));
    let best = null, bestD = Infinity;
    for(const tl of grid.sidewalkRuns){
      const d = (tl.x-wp.x)*(tl.x-wp.x) + (tl.y-wp.y)*(tl.y-wp.y);
      if(d < bestD){ bestD = d; best = tl; }
    }
    if(!best || bestD > (T2*1.5)*(T2*1.5)) return null; // no real tile nearby (corner mesh) — don't place one
    const d = DIRV[facingAt(sv)];
    const ds = (best.x-wp.x)*d.x + (best.y-wp.y)*d.y;
    return Math.round(sv + ds);
  };

  /* ---------- straight-through street crossings ----------
     The only places on a route where the robot's sidewalk genuinely
     BREAKS. Corners never do it — they're filleted arcs on continuous
     sidewalk (the robot never leaves its own walk going around one,
     which is exactly why the original "curb ramps at every corner"
     plan for prop.sidewalkend/sidewalkbegin never fit; see
     docs/DESIGN.md "Sidewalkend curb ramps", open placement question).
     But a 2-block leg passes straight THROUGH an interior grid node,
     and classifyAt gives the crossing street's road priority over our
     sidewalk band — so the walk really does end at sN-ROAD_HALF and
     begin again at sN+ROAD_HALF. Both boundaries land exactly on tile
     seams by construction (ROAD_HALF = 4*T2, nodes at multiples of
     BLOCK = 34*T2), which is the whole-tile snap the ramp spec asks
     for, with zero snapping needed.
     A node only cuts OUR band if a road edge extends toward the
     robot's own side: ROBOT_SIDE = -1 puts the walk along
     -DIRV[(f+1)%4] = DIRV[(f+3)%4], so the test is conn[(f+3)%4] —
     a T-intersection whose stem points the other way leaves our
     sidewalk unbroken (classifyAt's OVERSHOOT window confirms this:
     the band sits entirely outside that stem's along-extent). */
  const crossings = [];
  for(const sg of segs){
    if(sg.type !== "line") continue;
    const d = DIRV[sg.f], rv = DIRV[(sg.f+1)%4];
    for(const n of grid.nodes){
      if(!n.conn[(sg.f+3)%4]) continue;                    // no road on the robot's side
      const relX = n.x - sg.start.x, relY = n.y - sg.start.y;
      if(Math.abs(relX*rv.x + relY*rv.y) > 1) continue;    // node not on this leg's centerline
      const sN = sg.s0 + (relX*d.x + relY*d.y);
      /* both 2-tile-deep ramps must fit fully inside this straight leg —
         this also cleanly rejects the leg's own endpoint/corner nodes
         (they sit at or beyond s0/s1) and route start/end crossings,
         where a lone half-pair would read as broken. */
      if(sN - ROAD_HALF - 2*T2 < sg.s0 || sN + ROAD_HALF + 2*T2 > sg.s1) continue;
      /* crossings are stored as SPANS of route-s where the walk is
         genuinely gone — [sA, sB] — so straight crossings and turn
         crossings (below) share one geometry model everywhere
         downstream: ramps at the span's ends, street level between. */
      crossings.push({ sA: sN - ROAD_HALF, sB: sN + ROAD_HALF, fIn: sg.f, fOut: sg.f });
    }
  }

  /* ---------- outside-turn crossings ----------
     The earlier "corners never break the walk" note is only true of
     INSIDE turns (sidewalk on the inside of the bend, robot radius
     CORNER_R - |laneOff|, sweep stays on the corner sidewalk patch).
     On an OUTSIDE turn the robot's radius is CORNER_R + |laneOff| and
     its real arc cuts diagonally across the intersection corner —
     over its own curb and/or the side street's, past the corner point,
     back up onto the new street's walk (traced numerically: row 0 dips
     ~46 units past its own curb, row 3 crosses the side street's curb
     ~270 units out). Which side is "outside" falls out of the arc's
     own sign: sign=+1 turns toward +rv, and ROBOT_SIDE=-1 puts the
     walk at -rv, so outside ⟺ sign === -ROBOT_SIDE.
     The junction model is the lab-approved sidewalkendturn shape,
     built ONLY from the two existing straight ramps per Sir's spec
     (no sidewalkbeginTurn): ramp down on the last two tiles of the
     straight before the arc (old heading), the whole sweep at street
     level, ramp up on the first two tiles after it (new heading).
     Arc endpoints sit TURN_R = 5*T2 from the node (player route only —
     see TURN_R's own comment) — tile-aligned by construction, same free
     alignment the straight crossings got, and now the SAME 5*T2 the
     ramps themselves sit at, so the turn+tip mechanic (gated on
     seg.type==="arc" elsewhere) starts and ends on the ramps instead of
     several tiles early/late. */
  for(let i = 0; i < segs.length; i++){
    const sg = segs[i];
    if(sg.type !== "arc") continue;
    if(sg.sign !== -ROBOT_SIDE) continue;                  // inside turn: walk never breaks
    const prev = segs[i-1], next = segs[i+1];
    if(!prev || !next || prev.type !== "line" || next.type !== "line") continue;
    /* ramps must fit on the adjacent straights (always true for
       >=1-block legs: lineLen >= BLOCK - 2*TURN_R = 24*T2 on the player
       route (was 18*T2 at the old CORNER_R trim), but the guard keeps
       route-shape assumptions out of the invariant) */
    if(sg.s0 - 2*T2 < prev.s0 + T2 || sg.s1 + 2*T2 > next.s1 - T2) continue;
    /* the corner NODE's world position, recovered from the arc's own
       stored geometry (center = cornerP - d*sg.R + sign*rv*sg.R,
       inverted — uses sg.R, not the CORNER_R constant, since the
       player route now builds this arc at TURN_R). Still WORLD-anchored
       rather than route-s anchored for the lateral (cross-axis) offset,
       since laneOff still shifts a diagonal-crossing robot off the
       centerline the same way it always did — but now that the arc's
       own endpoints sit at TURN_R (== the ramps' own ROAD_HALF+T2), the
       along-axis component lines up with the true curb by construction
       instead of needing the 8-tiles-out correction this used to. */
    const dA = DIRV[sg.f], rvA = DIRV[(sg.f+1)%4];
    const nx = sg.center.x + dA.x*sg.R - sg.sign*rvA.x*sg.R;
    const ny = sg.center.y + dA.y*sg.R - sg.sign*rvA.y*sg.R;
    crossings.push({ kind:"turn", sA: sg.s0, sB: sg.s1, nx, ny,
                     fIn: sg.f, fOut: (sg.f + sg.sign + 4) % 4 });
  }
  /* keep every other spawn out of any crossing span: the gap itself
     plus one ramp (2 tiles) each side, small margin on top. Checked
     inside spawnBlocked so every spawn loop below inherits it —
     MIN_GAP_S/MIN_GAP_OFFSET alone can't protect a 2x3-tile decal
     (60 < the ramp's own 92-unit half-depth, and the row-offset gate
     only sees the anchor row, not the full 3-row span). */
  const CROSSING_CLEAR = 2*T2 + 30;
  const inCrossing = sv => crossings.some(cx => sv > cx.sA - CROSSING_CLEAR && sv < cx.sB + CROSSING_CLEAR);

  /* RULE: no two props/hazards stack at the same spot. Every spawn loop
     below checks a candidate placement against everything already
     placed this route (both hazards[] and props[], since either array
     can hold something at a given lane) before pushing — same-lane
     items within MIN_GAP_S of each other are rejected. offsetOf()
     normalizes the two placement conventions in use (row = sidewalk
     lane index, roadOffset = raw lateral offset) to one comparable
     number. This is a placement-time check, not a runtime one: once
     the route is built, item positions don't move (flee/wander only
     animate the art, not the spawn point), so checking once here is
     sufficient — nothing needs to re-check at draw time. */
  const MIN_GAP_S = 60, MIN_GAP_OFFSET = T2*0.6;
  const offsetOf = item => item.row !== undefined ? laneOffset(item.row) : item.roadOffset;
  const spawnBlocked = (s, offsetUnits) => {
    if(inCrossing(s)) return true;   // nothing spawns in an intersection crossing or on its curb ramps
    for(const list of [hazards, props]){
      for(const it of list){
        if(Math.abs(it.s - s) < MIN_GAP_S && Math.abs(offsetOf(it) - offsetUnits) < MIN_GAP_OFFSET) return true;
      }
    }
    return false;
  };

  /* ---------- virtual grade profile ----------
     Grades are FEEL, not geometry: this profile is consumed as SLOPE
     only (pitch, hill gravity, speed strain — the physics ramp-lab and
     the sidewalkend lab already dialed, live in the sim since). groundZ
     stays hard-zero, so the flat-drawn world and every z consumer
     (props, doors, robot, camera) remain in exact agreement — the
     "robot floats above his own street" failure of literal 1D heights
     can't happen. True drawn elevation stays the deferred "real 2D
     system across the grid" this comment block used to punt on.
     The model is spatially consistent: two octaves of node-lattice
     value noise over WORLD position (wavelengths two blocks and one
     block), scaled by the hood's hill knob — so a crossing sampled
     twice by the route gets one answer, The Flats (hill 0) stays
     perfectly flat, and The Bluffs (hill 1) becomes a leg-burner. */
  const lerp = (a, b, t) => a + (b - a)*t;
  const HILL_AMP = 73 * BLEND.hill;   // retuned so hill:1 (The Bluffs) tops out
                                      // around a 5% grade — see MAX_GRADE clamp
                                      // on the pitch calc below for the hard cap
  /* directional bias: real slope should agree with the isometric
     camera's own depth cue instead of being pure coin-flip noise. W()'s
     screen-y is (x+y)*0.5 - z, so +x/+y (f=0/f=1) increases screen-y —
     lower on screen, which reads as coming toward the viewer/downhill —
     and -x/-y (f=2/f=3) reads the opposite, uphill. Before this,
     elevAtWorld was symmetric noise with no relationship to that reading
     at all. GRADE_BIAS is sized to roughly match the noise octaves' own
     typical per-block slope (see oct() below) so it reliably sets the
     overall trend direction per leg without flattening out the local
     texture/bumps the noise still provides. Scales with HILL_AMP like
     everything else here, so The Flats (hill 0) stays exactly flat —
     no bias either. Tune GRADE_BIAS's multiplier on HILL_AMP/BLOCK if
     playtesting wants the trend stronger/weaker relative to the bumps. */
  const GRADE_BIAS = HILL_AMP / BLOCK;
  const elevLattice = (i, j) =>
    mulberry32(((i*73856093) ^ (j*19349663) ^ (seed ^ 0x9e37)) >>> 0)() - 0.5;
  const smoothT = v => v*v*(3 - 2*v);
  const elevAtWorld = (x, y) => {
    if(HILL_AMP === 0) return 0;
    const oct = (wl, w) => {
      const u = x/(BLOCK*wl), v = y/(BLOCK*wl);
      const i0 = Math.floor(u), j0 = Math.floor(v);
      const fu = smoothT(u - i0), fv = smoothT(v - j0);
      return w * lerp(lerp(elevLattice(i0, j0),   elevLattice(i0+1, j0),   fu),
                      lerp(elevLattice(i0, j0+1), elevLattice(i0+1, j0+1), fu), fv);
    };
    return HILL_AMP * (oct(2, 1) + oct(1, 0.5)) - GRADE_BIAS * (x + y);
  };
  const tiles = [];
  const nT = Math.ceil(totalLen / (TILE*2)) + 3;
  for(let i = 0; i < nT; i++){
    const p = segsPosAt(segs, Math.min(i*T2, totalLen));
    tiles.push(elevAtWorld(p.x, p.y));
  }
  /* two passes of light smoothing so grades ease at block seams
     instead of kinking the pitch */
  for(let pass = 0; pass < 2; pass++)
    for(let i = 1; i < nT-1; i++) tiles[i] = (tiles[i-1] + 2*tiles[i] + tiles[i+1]) / 4;


  /* hazards along the route; corners stay clear (the corner IS the hazard
     there), and classify() is the final word on every placement.
     props[] is declared here too (not down by the palm loop where it
     used to be) — spawnBlocked() closes over both arrays and its first
     call site is inside this loop, so props has to exist before this
     loop runs, not after it. */
  const hazards = [];
  const props = [];

  /* ADA curb ramps at both ends of every crossing SPAN — straight
     crossings and outside turns alike (see crossings[] above).
     Down-ramp owns the LAST two walk tiles before the span (anchor at
     sA - T2, prop spans anchor±T2 along-travel), up-ramp mirrors it on
     the far side, each oriented to its own end's heading (fIn/fOut —
     identical for straights, perpendicular for turns). Pad tile
     touching the street in both, per the ADA spec the lab settled on.
     Cross axis: the prop is 3 tiles wide but the game sidewalk is 4
     rows; the CROSSING_RAMP_ROW anchor centers it on rows 1-3 on tile
     seams (laneOffset(2) ± 1.5*T2 = ROAD_HALF+T2 .. ROAD_HALF+4*T2),
     leaving row 0 (street side) as plain flat walk — shifted one lane
     off the kerb (2026-08-07) so the route ramps sit exactly where the
     world corner ramps do (WORLD_RAMP.cross = 598 = laneOffset(2), the
     2026-08-01 on-device dial). */
  for(const cx of crossings){
    if(cx.kind !== "turn"){
      hazards.push({ type:"sidewalkend",   s: cx.sA - T2, row: CROSSING_RAMP_ROW, f: cx.fIn,  hit:true });
      hazards.push({ type:"sidewalkbegin", s: cx.sB + T2, row: CROSSING_RAMP_ROW, f: cx.fOut, hit:true });
      continue;
    }
    /* turn crossings: world-anchored at the TRUE curb lines (see the
       detection note above). Down-ramp: (ROAD_HALF + T2) before the
       node along the OLD heading — exactly where a straight crossing's
       near ramp would sit — cross-centered on rows 1-3 via
       laneOffset(CROSSING_RAMP_ROW), tile-aligned by construction. Up-ramp mirrored
       along the NEW heading. hz.s carries the arc span midpointish
       value purely for the near()-culling and sorting paths that
       expect one; position comes from wx/wy. */
    const dI = DIRV[cx.fIn],  rI = DIRV[(cx.fIn+1)%4];
    const dO = DIRV[cx.fOut], rO = DIRV[(cx.fOut+1)%4];
    const offR = laneOffset(CROSSING_RAMP_ROW);
    hazards.push({ type:"sidewalkend", row: CROSSING_RAMP_ROW, f: cx.fIn, hit:true, s: cx.sA,
      wx: cx.nx - dI.x*(ROAD_HALF + T2) + rI.x*offR,
      wy: cx.ny - dI.y*(ROAD_HALF + T2) + rI.y*offR, wz: 0 });
    hazards.push({ type:"sidewalkbegin", row: CROSSING_RAMP_ROW, f: cx.fOut, hit:true, s: cx.sB,
      wx: cx.nx + dO.x*(ROAD_HALF + T2) + rO.x*offR,
      wy: cx.ny + dO.y*(ROAD_HALF + T2) + rO.y*offR, wz: 0 });
  }
  /* pigeon flocks: living set dressing. Density follows the crumbs
     (hood.litter); middle rows only so a milling flock's ±30-unit
     wander stays on the walk; line legs only, never in a crossing.
     hz.fledAt starts null — the sim stamps it when the robot drives in
     and the whole flock bursts skyward (see the pigeons sim branch). */
  {
    const nFlocks = 2 + Math.floor(rng() * (2 + BLEND.litter * 3));
    let placedF = 0;
    for(let i = 0; i < nFlocks*8 && placedF < nFlocks; i++){
      const s = snapToSidewalkTile(SPAWN_S + 400 + rng()*(totalLen - 800), 1);
      const srow = 1 + Math.floor(rng()*2);
      const sg2 = segs.find(g => s >= g.s0 && s <= g.s1);
      if(!sg2 || sg2.type !== "line") continue;
      if(inCorner(s) || inCrossing(s)) continue;
      if(!onSidewalk(s, laneOffset(srow))) continue;
      if(spawnBlocked(s, laneOffset(srow))) continue;
      hazards.push({ type:"pigeons", s, row: srow, f: sg2.f, hit:false, fledAt: null });
      placedF++;
    }
  }

  /* grade chevrons: DISABLED per Sir's request (2026-07-17) — the yellow
     slope-indicator chevrons are gone from the walk. The underlying hill
     physics (pitch, hill gravity, speed strain — driven by the `tiles`
     elevation profile via groundSlope/elevAt, not by these hazard
     markers) are completely untouched; this only stops the paint from
     spawning. Re-enable by restoring the loop body below if wanted back. */

  const density = 0.45 + BLEND.litter*0.35 + (1 - BLEND.pave)*0.3;
  /* ---------- hazard spawning, as a RANGE ----------
     Was a bare while-loop over the whole walk. It is a function now for
     one reason: the GPS reroute lap is welded on AFTER every spawn pass
     has already run, so the lap was never offered to any of them. The
     weld deletes the old tail's placements (they were anchored to
     geometry that no longer exists) and nothing ever repopulated it --
     measured at 0 props and ~1 hazard per 1000 units against 12-14 on
     the main route, i.e. a bare corridor you could drive the whole way
     round without touching anything.

     Taking a range and an rng makes the lap a second call instead of a
     rewrite. It MUST take the rng as a parameter rather than closing
     over the builder's: spending extra draws from that stream would
     reshuffle everything generated after the weld (William, the crime
     site, the challenge), moving them on dates that are otherwise
     unchanged. The lap gets its own stream, so the rest of the world
     stays byte-identical.

     Every helper this uses -- inCorner, onSidewalk, spawnBlocked,
     facingAt -- closes over `segs`, and the weld mutates `segs` IN
     PLACE (segs.length = n, then push). So called after the weld they
     read the final geometry with no changes of their own. That is what
     makes this cheap rather than a reordering of the whole builder. */
  const spawnHazardRange = (from, to, R) => {
    let hs = from;
    while(hs < to){
      /* halved step = DOUBLED obstacle count (requested). spawnBlocked's
         60-unit floor still guarantees breathing room between props, and
         crossing/corner exclusions are unchanged — the course just gets
         twice as busy. Cracks and slabs keep their own dedicated passes
         and levers. */
      hs += ((330 - density*176) + R()*198) * 0.25;
      const hsR = Math.round(hs);
      if(inCorner(hsR)) continue;
      const lane = Math.floor(R()*4);
      if(!onSidewalk(hsR, laneOffset(lane))) continue;
      if(spawnBlocked(hsR, laneOffset(lane))) continue;
      const r2 = R();
      let type;
      /* crack used to be a branch here (r2 < (1-hood.pave)*0.45), but
         moved to its own dedicated spawn pass below -- same reason
         slabs already have their own loop instead of sharing this
         roll: a 3x density target needs a spacing lever, and cracks
         can't get one while sharing a single probability budget with
         scooter/trash/cone/dog/people/bin/planter. Removing the branch
         here doesn't rebalance the rest -- litter/cone/dog+ranges are
         unchanged, cone's effective share just widens to cover what
         used to be crack's slice of r2. */
      if(r2 < BLEND.litter*0.35)          type = R() < 0.6 ? "scooter" : "trash";
      else if(r2 < 0.75){
        /* cone-density fix (2026-08-10, requested: route felt too cone-
           cluttered). Cone's slice widened when the crack branch moved to
           its own dedicated pass above -- crack's old share of r2 just
           fell open to cone instead of coming back to it. A coin-flip
           miss here roughly halves cone's actual placement rate without
           touching scooter/trash/dog/people/bin/planter's shares or the
           overall roll frequency (that doubling was separately requested
           and stays). A miss just leaves the spot empty, same as any
           other rejected roll. */
        if(R() < 0.5) continue;
        type = "cone";
      }
      else { const r3 = R(); type = r3 < 0.25 ? "dog" : r3 < 0.48 ? "people" : r3 < 0.73 ? "bin" : "planter"; }
      const hzObj = { type, s: hsR, row: lane, f: facingAt(hsR), hit:false };
      if(type === "dog"){
        hzObj.dogSeed = (R()*4294967296) >>> 0;  // coat + scar + waypoints
        /* 50/50 free-roaming vs the original pace/sit behavior (requested
           2026-07-24, same sidewalk-block system as prop.people above).
           The free-roaming half never sits -- walking and sitting are
           mutually exclusive, so sit only gets rolled for the half that
           ISN'T getting a walk range, leaving their ~40% sitter rate
           exactly as it always was. */
        if(R() < 0.5){
          const dSeg = segs.find(g => hsR >= g.s0 && hsR <= g.s1 && g.type === "line");
          if(dSeg){
            const w0 = dSeg.s0 + CROSSING_CLEAR, w1 = dSeg.s1 - CROSSING_CLEAR;
            if(w1 - w0 >= T2){ hzObj.walkS0 = w0; hzObj.walkS1 = w1; }
          }
          hzObj.sit = false;
        } else {
          hzObj.sit = R() < 0.4;                 // ~40% sitters, same as always
        }
      }
      if(type === "people"){
        hzObj.peopleSeed = (R()*4294967296) >>> 0;  // body/skin/shirt/pants/hair/shoe
        /* sidewalk-walking range (requested 2026-07-24): confined to the
           straight run they spawned on -- same "line"-segment-only
           restriction the pigeon flocks already use above, so nobody
           gets routed through a corner's arc geometry. Margin (same
           CROSSING_CLEAR the route generator already uses) keeps the
           walk off the curb cut at each end. If the block's too short
           after margins, walkS0/walkS1 collapse to a point and
           peopleSpotAt's own fallback leaves them on the old idle
           wander -- nobody regresses, they just don't get a route. */
        const pSeg = segs.find(g => hsR >= g.s0 && hsR <= g.s1 && g.type === "line");
        if(pSeg){
          const w0 = pSeg.s0 + CROSSING_CLEAR, w1 = pSeg.s1 - CROSSING_CLEAR;
          if(w1 - w0 >= T2){ hzObj.walkS0 = w0; hzObj.walkS1 = w1; }
        }
      }
      if(type === "cone"){
        const preKnocked = R() < 0.4;
        hzObj.phi = preKnocked ? CONE_HIT.phiRest : 0;
        hzObj.phase = preKnocked ? 2 : 1;
        hzObj.angVel = 0; hzObj.moving = false;
        hzObj.pose = preKnocked ? "knocked" : "standing";
        hzObj.slide = 0; hzObj.slideVel = 0;
        if(preKnocked) hzObj.fallPsi = R()*Math.PI*2;
      }
      if(type === "bin"){
        const preKnocked = R() < 0.4;
        hzObj.phi = preKnocked ? BIN_HIT.phiRest : 0;
        hzObj.angVel = 0; hzObj.moving = false;
        hzObj.pose = preKnocked ? "knocked" : "standing";
        hzObj.slide = 0; hzObj.slideVel = 0;
        hzObj.bonked = false;
        hzObj.items = []; hzObj.spilled = false;
        hzObj.thetaF = 0;
        if(preKnocked) hzObj.fallPsi = R()*Math.PI*2;
      }
      if(type === "planter"){
        hzObj.scale = 1.0 + R()*1.2;                 // 1.0-2.2x, straddles PLANTER_HIT.thresh (1.4) and largeMin (1.8)
        hzObj.variantIdx = Math.floor(R()*PLANTER_VARIANTS.length);
        /* large planters are immovable street furniture (2026-07-26) --
           they never fall, so they can't spawn already-fallen either;
           a pre-knocked LARGE would contradict the contract on sight. */
        const preKnocked = R() < 0.25 && hzObj.scale < PLANTER_HIT.largeMin;   // rarer than bin's 0.4 — a bigger visual event
        hzObj.phi = preKnocked ? PLANTER_HIT.phiRest : 0;
        hzObj.angVel = 0; hzObj.moving = false;
        hzObj.pose = preKnocked ? "knocked" : "standing";
        hzObj.bonked = false;
        hzObj.items = []; hzObj.spilled = false;
        if(preKnocked) hzObj.fallPsi = (R()*2 - 1) * 0.4;   // small fall-direction jitter, same idea as bin's
      }
      if(type === "scooter"){
        /* 0.8 -> 0.5: at 80% dumped, routes with a few scooters routinely
           showed EVERY one down (reported once fallen/standing both read
           correctly). Half and half keeps the dockless-litter flavor with
           standing ones actually visible. Same single draw — layout
           stream unchanged; only the 0.5-0.8 band flips to standing. */
        const preKnocked = R() < 0.5;
        /* ALONG the walk, nose either way, slop — the spawn's thetaF is
           what the draw actually uses (it overrides the draw branch's own
           seed, which is why the v32 constraint there was dead code for
           spawned scooters). The old free ±162° roll aimed dumped stems
           up-screen in iso, where a flat squashed scooter masquerades as
           standing with pancake wheels (on-device report). Parked AND
           fallen both read right lying on the street's own axis. */
        const uTh = R();   // ONE draw for direction AND slop — keeps the
                             // spawn stream length identical, so the same
                             // date keeps the same world layout it had
                             // before this fix (two draws reshuffled every
                             // downstream roll: standing scooters re-rolled
                             // fallen, reported on-device)
        hzObj.thetaF = (uTh < 0.5 ? 0 : Math.PI) + (((uTh * 977) % 1) - 0.5) * 0.3;
        hzObj.brand = BRANDS[Math.floor(R()*BRANDS.length)];
        hzObj.phi = preKnocked ? SCOOT_HIT.phiRest : 0;
        hzObj.angVel = 0; hzObj.moving = false;
        hzObj.pose = preKnocked ? "knocked" : "standing";
        hzObj.slide = 0; hzObj.slideVel = 0;
        if(preKnocked) hzObj.fallPsi = hzObj.thetaF;
      }
      hazards.push(hzObj);
    }
  };
  spawnHazardRange(SPAWN_S + 120, totalLen - 220, rng);

  /* palms: lane 3, farthest from the road — nearest the buildings, same
     "building-side" flavor the game already used. Real palms grow in
     clumps, not perfectly isolated — clusterExtras are small along/
     lateral offsets from the main (collidable) hazard, each with its
     own independently-rolled kind, purely decorative (never pushed
     into hazards[], so spawnBlocked/collision spacing is completely
     untouched — only the ONE real hazard per spawn point still counts
     for gameplay). Different offset = different position = drawProp's
     own position-seeded rng naturally varies lean/height/sway per
     companion without any extra seeding work needed. */
  /* palms: same range treatment, same reason -- see spawnHazardRange. */
  const spawnPalmRange = (from, to, R) => {
    for(let ps = from; ps < to; ps += (286 + R()*264) * 0.25){
      const psR = Math.round(ps);
      if(inCorner(psR)) continue;
      if(!onSidewalk(psR, laneOffset(3))) continue;
      if(spawnBlocked(psR, laneOffset(3))) continue;
      if(R() < BLEND.palms){
        const sizeRoll = R();
        const clusterSize = sizeRoll < 0.6 ? 1 : sizeRoll < 0.85 ? 2 : 3;
        const clusterExtras = [];
        for(let c=1; c<clusterSize; c++){
          clusterExtras.push({
            ds: (R()-0.5)*70,
            dOff: (R()-0.5)*T2*0.9,
            kind: R() < 0.25 ? "palmDwarf" : "palm"
          });
        }
        hazards.push({
          type: R() < 0.25 ? "palmDwarf" : "palm",
          s: psR, row:3, f: facingAt(psR), hit:false, clusterExtras });
      }
    }
  };
  spawnPalmRange(SPAWN_S + 140, totalLen - 220, rng);
  /* storefront dressing (prop.planter / prop.bin): the FAR sidewalk —
     the opposite side of the street from the robot's own lane. Pure
     decoration, never a hazard, never reachable (the robot's walk
     never puts it on that side of the road). */
  for(let fs = SPAWN_S + 160; fs < totalLen - 240; fs += 150 + rng()*160){
    const fsR = Math.round(fs);
    if(inCorner(fsR)) continue;
    const farLane = Math.floor(rng()*4);
    const off = farLaneOffset(farLane);
    if(!onSidewalk(fsR, off)) continue;
    if(spawnBlocked(fsR, off)) continue;
    if(rng() < 0.6) props.push({
      kind: rng() < 0.55 ? "planter" : "bin",
      s: fsR, roadOffset: off, f: facingAt(fsR) });
  }
  /* decorative road cracks: asphalt-tone spall out on the road itself,
     pure texture, zero physics (the impact check requires row===botRow,
     and these never get a `row` field at all, so they can never match). */
  for(let rs = SPAWN_S + 200; rs < totalLen - 260; rs += 380 + rng()*400){
    const rsR = Math.round(rs);
    if(inCorner(rsR)) continue;
    if(rng() > (1 - BLEND.pave)*0.8 + 0.1) continue;
    const off = (rng()<0.5?-1:1) * (T2 + rng()*T2*1.5);
    if(!onRoad(rsR, off)) continue;
    if(spawnBlocked(rsR, off)) continue;
    hazards.push({ type:"crack", s: rsR, roadOffset: off, surface: "road",
                   len: 24 + Math.floor(rng()*49), f: facingAt(rsR), hit:false });
  }

  /* other robots (requested 2026-07-24): parked, lane 3 -- the inside/
     building lane, confirmed geometrically via laneOffset (increasing
     lane index moves further from the road), same lane palms already
     use. Facing is rotated 90 degrees from the normal sidewalk-forward
     convention in the render code (see drawProp) so the face looks
     OUT across the lane band toward the road -- toward Tipsey as he
     drives past -- rather than along the sidewalk like every other
     prop. Moderate spacing: these read as a much bigger visual event
     than a cone or hydrant, shouldn't crowd the route. */
  for(let rb = SPAWN_S + 260; rb < totalLen - 320; rb += 900 + rng()*700){
    const rbR = Math.round(rb);
    if(inCorner(rbR)) continue;
    if(!onSidewalk(rbR, laneOffset(3))) continue;
    if(spawnBlocked(rbR, laneOffset(3))) continue;
    if(rng() < 0.5){
      hazards.push({ type:"robot", s: rbR, row: 3, f: facingAt(rbR),
                     hit:false, robotSeed: (rng()*4294967296) >>> 0,
                     knocked:false, fallPsi: (rng()*2-1)*0.4, items:[] });
    }
  }

  /* other robots, roving (requested 2026-07-24, phase 2): other
     delivery bots out on their own routes -- same sidewalk-block walk
     system as people/dogs (line segments only, CROSSING_CLEAR margin
     at each end), placed at any lane rather than fixed to lane 3 like
     the parked ones above. roving:true switches the render code's
     axis mapping so the face points along the direction of travel
     (like a vehicle actually driving somewhere) instead of across the
     lane band toward the road. Lower density than parked -- these are
     a genuinely dynamic, catchable-and-collidable hazard, shouldn't
     flood the route. */
  for(let rr = SPAWN_S + 300; rr < totalLen - 360; rr += 1400 + rng()*1000){
    const rrR = Math.round(rr);
    if(inCorner(rrR)) continue;
    const rLane = Math.floor(rng()*4);
    if(!onSidewalk(rrR, laneOffset(rLane))) continue;
    if(spawnBlocked(rrR, laneOffset(rLane))) continue;
    const rSeg = segs.find(g => rrR >= g.s0 && rrR <= g.s1 && g.type === "line");
    if(!rSeg) continue;
    const rw0 = rSeg.s0 + CROSSING_CLEAR, rw1 = rSeg.s1 - CROSSING_CLEAR;
    if(rw1 - rw0 < T2) continue;   // block too short after margins -- skip, don't spawn stationary
    hazards.push({ type:"robot", s: rrR, row: rLane, f: facingAt(rrR),
                   hit:false, robotSeed: (rng()*4294967296) >>> 0,
                   knocked:false, fallPsi: (rng()*2-1)*0.4,
                   roving:true, walkS0: rw0, walkS1: rw1, items:[] });
  }

  /* hydrants: lane 0, closest to the road — the real curb side. */
  for(let ys = SPAWN_S + 220; ys < totalLen - 280; ys += (1056 + rng()*1144) * 0.25){
    const ysR = Math.round(ys);
    if(inCorner(ysR)) continue;
    if(!onSidewalk(ysR, laneOffset(0))) continue;
    if(spawnBlocked(ysR, laneOffset(0))) continue;
    if(rng() < 0.55){
      /* ~35% of spawned hydrants start already-burst (was 15% — too
         rare to ever meet, on-device). burstT far in the past so the
         hit-burst's own grow math clamps to 1 immediately.
         PRE-burst floods live ONE TILE OVER (pudDir · T2 along the
         walk) instead of pooling at the base like a fresh hit: old
         water has had time to RUN — and it runs DOWNHILL when the
         grade profile has an opinion, seeded coin on the flats. The
         slick zone moves with it (see the sim), so art and physics
         agree, and dodging the hydrant no longer means you dodged
         the water. */
      const startsBurst = rng() < 0.35;
      let pudDir;
      if(startsBurst){
        const ti = Math.round(ysR / T2);
        const sl = (tiles[Math.min(tiles.length-1, ti+1)] - tiles[Math.max(0, ti-1)]) / (2*T2);
        pudDir = sl > 0.02 ? -1 : sl < -0.02 ? 1 : (rng() < 0.5 ? -1 : 1);
      }
      hazards.push({ type:"hydrant", s: ysR, row: 0, f: facingAt(ysR),
                     hit:false, burst:startsBurst,
                     burstT: startsBurst ? -1e9 : undefined,
                     pudDir });
    }
  }

  /* heaved slabs (prop.slab): runs of bad sidewalk across the full
     4-lane band now, same drifting-run logic as before.
     3x density: spacing cut to a third (was 660+rng()*924) rather
     than scaling the 0.18+(1-pave)*0.75 success probability, since
     that already reaches ~0.78 in low-pave hoods -- tripling it
     would exceed 1.0 there. Spacing has no such ceiling. */
  let ss = SPAWN_S + 260;
  while(ss < totalLen - 320){
    ss += (200 + rng()*277) * 0.5;
    if(inCorner(ss)) continue;
    if(rng() > 0.18 + (1 - BLEND.pave)*0.75) continue;
    const runN = 1 + Math.floor(rng()*3);
    let srow = Math.floor(rng()*4);
    for(let k=0; k<runN; k++){
      const skR0 = Math.round(ss + k*TILE*2);
      if(inCorner(skR0)) break;
      if(!onSidewalk(skR0, laneOffset(srow))){ srow = Math.floor(rng()*4); continue; }
      const skR = snapToSidewalkTile(skR0, srow);
      if(skR === null || inCorner(skR) || !onSidewalk(skR, laneOffset(srow))){ srow = Math.floor(rng()*4); continue; }
      if(spawnBlocked(skR, laneOffset(srow))){ srow = Math.floor(rng()*4); continue; }
      hazards.push({ type:"slab", s: skR, row: srow,
                     lift: 3 + Math.floor(rng()*6),
                     side: rng() < 0.5 ? 1 : -1,
                     root: rng() < 0.55,
                     f: facingAt(skR), hit:false, lipHit:false });
      if(rng() < 0.6) srow = Math.max(0, Math.min(3, srow + (rng() < 0.5 ? -1 : 1)));
    }
    ss += runN*TILE*2;
  }

  /* sidewalk cracks (prop.crack): own pass now instead of a shared-roll
     branch, same reasoning as the slab loop above -- needs an
     independently tunable spacing to hit a 3x density target without
     touching scooter/trash/cone/dog/people/bin/planter's odds. */
  let cs = SPAWN_S + 180;
  while(cs < totalLen - 240){
    cs += (22 + rng()*110) * 0.5;
    if(inCorner(cs)) continue;
    if(rng() > (1 - BLEND.pave)*0.45) continue;
    const crow = Math.floor(rng()*4);
    if(!onSidewalk(cs, laneOffset(crow))) continue;
    const csR = snapToSidewalkTile(cs, crow);
    if(csR === null || inCorner(csR) || !onSidewalk(csR, laneOffset(crow))) continue;
    if(spawnBlocked(csR, laneOffset(crow))) continue;
    hazards.push({ type:"crack", s: csR, row: crow,
                   len: 24 + Math.floor(rng()*49), surface:"sidewalk",
                   f: facingAt(csR), hit:false });
  }

  /* walker detours (2026-07-26, v2 -- replaces the walk-range clamp
     shipped earlier the same day): a clamp shrinks the world every
     time a route gets dense and eventually traps everyone in slivers;
     a DETOUR keeps the full block alive. This post-pass runs after
     EVERY hazard spawn loop above (rovers spawn before hydrants/
     slabs/cracks, so anything earlier would miss late spawns). For
     each walker (roving robot / walking dog / walking person), every
     static same-row blocker inside its range becomes a sidestep
     interval in hz.detours: the walker eases one full lane over
     (whichever adjacent lane is actually clear across the whole
     group, checked here at build time), passes the prop, and eases
     back -- see detourBAt for the runtime half. Blockers closer
     together than a full ease-out/ease-in merge into one longer
     sidestep. Only if BOTH adjacent lanes are blocked at a group
     (boxed in) does the old trim behavior apply, at that group only
     -- the last-resort, not the default. Rover-vs-rover still splits
     the block at the midpoint: both parties MOVE, so no spawn-time
     sidestep can dodge one, and half a block each is honest.
     Dogs/people never treat moving robots as blockers (NPC-vs-NPC
     pass-through, pre-existing and accepted). A range that still
     collapses below T2 demotes exactly as before: rovers park,
     dogs/people fall back to their idle wander via their own
     spot-function guard. */
  {
    const DETOUR_CLEAR = { robot: 46, dog: 30, people: 30 };  // half-span of the sidestep around a blocker's s
    const DETOUR_BLOCKERS = { robot:1, planter:1, bin:1, cone:1, hydrant:1,
                              scooter:1, trash:1, palm:1, palmDwarf:1 };
    const staticOn = (row, s0, s1, self) => {
      const list = [];
      for(const ob of hazards){
        if(ob === self || !DETOUR_BLOCKERS[ob.type]) continue;
        if(ob.type === "robot" && ob.roving) continue;
        if(ob.row !== row || ob.s < s0 || ob.s > s1) continue;
        list.push(ob);
      }
      return list;
    };
    for(const rv of hazards){
      const clear = DETOUR_CLEAR[rv.type];
      if(clear === undefined) continue;
      if(rv.walkS0 === undefined || rv.walkS1 === undefined) continue;
      if(rv.type === "robot" && !rv.roving) continue;
      let lo = rv.walkS0, hi = rv.walkS1;
      if(rv.type === "robot") for(const ob of hazards){
        if(ob === rv || ob.type !== "robot" || !ob.roving || ob.row !== rv.row) continue;
        const mid = (rv.s + ob.s) / 2;
        if(ob.s > rv.s) hi = Math.min(hi, mid - 20);
        else if(ob.s < rv.s) lo = Math.max(lo, mid + 20);
      }
      /* group blockers: sorted, merged when two sidesteps would touch
         (gap < ease-out + ease-in = 2*DETOUR_RAMP) -- guarantees the
         intervals detourBAt sees are disjoint even with their ramps */
      const blocks = staticOn(rv.row, lo, hi, rv).sort((p,q) => p.s - q.s);
      const groups = [];
      for(const ob of blocks){
        const g0 = ob.s - clear, g1 = ob.s + clear;
        const last = groups[groups.length - 1];
        if(last && g0 <= last.s1 + DETOUR_RAMP*2) last.s1 = Math.max(last.s1, g1);
        else groups.push({ s0: g0, s1: g1 });
      }
      const detours = [];
      for(const gp of groups){
        let target = -1;
        for(const cand of [rv.row - 1, rv.row + 1]){
          if(cand < 0 || cand > 3) continue;
          /* window = group + ramps + the walker's OWN clearance: the
             walker occupies the candidate lane for the whole group
             span and is still partially displaced across each ramp,
             so a prop just past the ramp end must ALSO be `clear`
             away or the ease-back grazes it (caught by the sweep
             census: row-0 cone 2 units outside a ramp-only window). */
          if(staticOn(cand, gp.s0 - DETOUR_RAMP - clear, gp.s1 + DETOUR_RAMP + clear, rv).length) continue;
          target = cand; break;
        }
        if(target < 0){
          /* boxed in on both sides -- trim at THIS group only */
          if(gp.s0 > rv.s) hi = Math.min(hi, gp.s0);
          else if(gp.s1 < rv.s) lo = Math.max(lo, gp.s1);
          else { lo = hi = rv.s; }   // spawned inside a boxed group: collapse, demote below
          continue;
        }
        detours.push({ s0: gp.s0, s1: gp.s1, db: laneOffset(target) - laneOffset(rv.row) });
      }
      if(hi - lo < T2){
        if(rv.type === "robot") rv.roving = false;
        delete rv.walkS0; delete rv.walkS1; delete rv.detours;
      } else {
        rv.walkS0 = lo; rv.walkS1 = hi;
        rv.detours = detours.filter(d => d.s1 > lo && d.s0 < hi);
      }
    }
  }

  /* parked car: on the road, off to one side (never blocking either
     traffic lane's centerline). */
  if(rng() < 0.5){
    const cs = Math.round(SPAWN_S + 150 + rng()*(totalLen - 500));
    const off = -1*(T2*1.5);
    if(!inCorner(cs) && onRoad(cs, off) && !spawnBlocked(cs, off)) props.push({ kind: rng() < 0.65 ? "car" : "truck", s: cs, roadOffset: off, f: facingAt(cs) });
  }

  /* the address */
  const number = 100 + Math.floor(rng()*3800);
  let doorS = findGoodS(segs, totalLen, totalLen - 90, true, grid, null, MIN_ROUTE_UNITS);
  /* graceful degradation: if no interior good leg exists past the mile
     mark (short-walk day), take the best route the map offers rather
     than none — findGoodS's own final fallback returns preferredS-ish
     even with the floor, so re-run unfloored only if the floored pick
     itself landed short (it only can via that last-resort path). */
  if(doorS < MIN_ROUTE_UNITS) doorS = Math.max(doorS, findGoodS(segs, totalLen, totalLen - 90, true, grid));

  /* the address is always a real block, forced to housing (a park or
     shop can't be the delivery destination); the pickup is always a
     real block, forced to commercial. Same override the lab used with
     a hardcoded i,j — now driven by where the route actually put
     doorS/pickupS instead of a fixed test position. */
  const addressBlock = findAdjacentBlock(segs, doorS, grid);
  if(addressBlock) addressBlock.type = "housing";
  /* pickup chosen AFTER the address block is known, so it can steer clear of
     it (a shared block can only hold one type, which would make the pickup
     render as the address house instead of a shop). */
  let pickupS = findGoodS(segs, totalLen, SPAWN_S + 90, false, grid, addressBlock);
  const doorHeadingF = segsSegAt(segs, doorS).f;
  const addressEdgeIdx = (doorHeadingF + 2) % 4;
  /* f===1/f===2 addresses only happen via findGoodS's rare no-good-leg
     fallback (see GOOD_LEG_HEADING) — the cutaway system says a house
     wall isn't safe to render on that heading. Rather than keep
     force-protecting a house there, this address renders as a fence
     with a gate instead (see queueHousingEdgeAt / drawGateFence) —
     the same treatment every OTHER house on a cut heading already
     gets, just with an opening so the customer still has somewhere
     to stand. */
  const addressUsesGate = !GOOD_LEG_HEADING[doorHeadingF];
  let addressUnitIdx = 0, addressSpot = null;
  if(addressBlock){
    const abEdges = [
      { ox: addressBlock.x0, oy: addressBlock.y0, dv: DIRV[0], rv: DIRV[3], len: addressBlock.x1-addressBlock.x0 },
      { ox: addressBlock.x1, oy: addressBlock.y0, dv: DIRV[1], rv: DIRV[0], len: addressBlock.y1-addressBlock.y0 },
      { ox: addressBlock.x1, oy: addressBlock.y1, dv: DIRV[2], rv: DIRV[1], len: addressBlock.x1-addressBlock.x0 },
      { ox: addressBlock.x0, oy: addressBlock.y1, dv: DIRV[3], rv: DIRV[2], len: addressBlock.y1-addressBlock.y0 }
    ];
    const ae = abEdges[addressEdgeIdx];
    const aeseed = ((Math.round(ae.ox*3+ae.dv.x)*7919) ^ (Math.round(ae.oy*3+ae.dv.y)*104729) ^ 0x9e3779b9) >>> 0;
    const aunits = packEdge(ae.len, mulberry32(aeseed));
    if(aunits.length){
      const aPos = segsPosAt(segs, doorS);
      const aAlong = ae.dv.x*(aPos.x-ae.ox) + ae.dv.y*(aPos.y-ae.oy);
      addressUnitIdx = closestUnitIndex(aunits, aAlong);
      /* the house actually selected (closestUnitIndex) can sit anywhere
         along this edge — houses pack ~220-390 units wide with gaps, so
         its real center is frequently 300-1600+ units from the original
         doorS target. doorS was never updated to match, which meant the
         win check (remain = doorS - botS, a ~94-unit window) was being
         measured against a point nowhere near the actual rendered door —
         confirmed on 200/200 test routes. addressSpot captures the real
         world position of the selected house so doorS can be refined to
         match it below, same fix pickupS already had for the shop. */
      const au = aunits[addressUnitIdx];
      const aux = ae.ox + ae.dv.x*au.start, auy = ae.oy + ae.dv.y*au.start;
      addressSpot = { x: aux + ae.dv.x*(au.w/2), y: auy + ae.dv.y*(au.w/2) };
    }
  }
  /* street name comes from the address's own DISTRICT now, not a single
     city-wide hood -- moved here (was picked blind, before doorS even
     existed) specifically so it can read addressSpot's real position.
     addressSpot can be null on the rare block with no packed units;
     doorS's own position is the fallback, still real ground either way. */
  const addressHood = addressSpot ? hoodAtWorld(addressSpot.x, addressSpot.y)
                                   : hoodAtWorld(segsPosAt(segs, doorS).x, segsPosAt(segs, doorS).y);
  const street = addressHood.streets[Math.floor(rng()*addressHood.streets.length)];
  /* refine doorS to the address unit's actual on-route position. UNLIKE
     pickupS's refinement (which searches every good leg for the nearest
     match), this doesn't need to search at all: addressEdgeIdx was
     already derived from segsSegAt(segs, doorS) above, so the address
     unit is guaranteed to be on the block adjacent to THIS EXACT segment
     — no other leg is a candidate. Searching broadly (as first tried,
     copying pickupS's pattern verbatim) risked locking onto a
     geometrically-nearby PARALLEL street instead, since the building
     face sits ~736 units off centerline with nothing pulling the search
     toward the correct lane — confirmed on 11/200 test routes, with
     residuals up to 2738 units. Projecting onto the one segment we
     already know is correct removes that failure mode entirely. */
  if(addressSpot){
    const sg0 = segsSegAt(segs, doorS);
    const hdg0 = segsHeadingAt(segs, sg0.s0);
    const dirX0 = Math.cos(hdg0), dirY0 = Math.sin(hdg0);
    const p00 = segsPosAt(segs, sg0.s0);
    const segLen0 = sg0.s1 - sg0.s0;
    const inset0 = Math.min(90, segLen0*0.3);
    let k0 = (addressSpot.x-p00.x)*dirX0 + (addressSpot.y-p00.y)*dirY0;
    k0 = Math.max(inset0, Math.min(segLen0-inset0, k0));
    doorS = sg0.s0 + k0;
  }
  const pickupBlock = findAdjacentBlock(segs, pickupS, grid);
  if(pickupBlock && pickupBlock !== addressBlock) pickupBlock.type = "commercial";
  const pickupEdgeIdx = (segsSegAt(segs, pickupS).f + 2) % 4;

  /* the pickup spot is a real, sensible point (just outside the shop
     door) — the robot should spawn AT it, not the other way around.
     Since the robot's position is always route-driven (posAt(botS) +
     laneOffset), spawning it exactly at an independently-computed
     shop-relative point would either require breaking that (causing a
     jump the instant it starts moving) or finding the closest point
     ON the route that already lines up. Same edge-packing computation
     queueCommercialEdgeAt will independently do for rendering — kept
     in sync by storing the result once here rather than recomputing
     it twice and risking drift. */
  let pickupSpot = null, pickupUnitIdx = 0, pickupShopName = null;
  if(pickupBlock){
    const pbEdges = [
      { ox: pickupBlock.x0, oy: pickupBlock.y0, dv: DIRV[0], rv: DIRV[3], len: pickupBlock.x1-pickupBlock.x0 },
      { ox: pickupBlock.x1, oy: pickupBlock.y0, dv: DIRV[1], rv: DIRV[0], len: pickupBlock.y1-pickupBlock.y0 },
      { ox: pickupBlock.x1, oy: pickupBlock.y1, dv: DIRV[2], rv: DIRV[1], len: pickupBlock.x1-pickupBlock.x0 },
      { ox: pickupBlock.x0, oy: pickupBlock.y1, dv: DIRV[3], rv: DIRV[2], len: pickupBlock.y1-pickupBlock.y0 }
    ];
    const pe = pbEdges[pickupEdgeIdx];
    const peseed = ((Math.round(pe.ox*3+pe.dv.x)*7919) ^ (Math.round(pe.oy*3+pe.dv.y)*104729) ^ 0x51b3) >>> 0;
    const punits = packEdgeNoGap(pe.len, mulberry32(peseed));
    if(punits.length){
      const pPos = segsPosAt(segs, pickupS);
      const pAlong = pe.dv.x*(pPos.x-pe.ox) + pe.dv.y*(pPos.y-pe.oy);
      pickupUnitIdx = closestUnitIndex(punits, pAlong);
      const pu = punits[pickupUnitIdx];
      const pux = pe.ox + pe.dv.x*pu.start, puy = pe.oy + pe.dv.y*pu.start;
      const pDoorCenterX = pu.w/2, pRobotDy = T2*2.1;
      pickupSpot = {
        x: pux + pe.dv.x*pDoorCenterX + pe.rv.x*pRobotDy,
        y: puy + pe.dv.y*pDoorCenterX + pe.rv.y*pRobotDy
      };
      const pickupHood = hoodAtWorld(pux, puy);
      pickupShopName = pickupHood.shops[Math.abs(Math.round(pux)+Math.round(puy)) % pickupHood.shops.length];
    }
  }
  /* refine pickupS to the pickup unit's actual on-route position.
     PREVIOUSLY: searched every f===0/f===3 leg in the whole route for
     whichever point was closest to pickupSpot. That's the same
     broad-search pattern doorS's refinement tried first and rejected
     (see addressSpot's comment above: "copying pickupS's pattern
     verbatim ... confirmed on 11/200 test routes, with residuals up
     to 2738 units") — on a route that loops back near itself, a later
     unrelated leg can sit closer to pickupSpot in raw distance than
     the leg the shop was actually placed on, so pickupS would lock
     onto the WRONG leg. Since this.botS starts at route.pickupS and
     the robot's initial heading is headingAt(botS), that wrong leg
     meant an occasional wrong start-facing angle. Fixed the same way
     doorS was: no search at all. pickupEdgeIdx above was already
     derived from segsSegAt(segs, pickupS), so the pickup unit is
     guaranteed to be on the block adjacent to THIS EXACT segment —
     project onto it directly. */
  if(pickupSpot){
    const sg0 = segsSegAt(segs, pickupS);
    const hdg0 = segsHeadingAt(segs, sg0.s0);
    const dirX0 = Math.cos(hdg0), dirY0 = Math.sin(hdg0);
    const p00 = segsPosAt(segs, sg0.s0);
    const segLen0 = sg0.s1 - sg0.s0;
    const inset0 = Math.min(90, segLen0*0.3);
    let k0 = (pickupSpot.x-p00.x)*dirX0 + (pickupSpot.y-p00.y)*dirY0;
    k0 = Math.max(inset0, Math.min(segLen0-inset0, k0));
    pickupS = sg0.s0 + k0;
  }

  /* EXTERIOR-LOT BACKSTOP (degenerate routes only): findGoodS's perimeter
     guard keeps the door/pickup on an interior-facing leg whenever one
     exists. On a tiny route whose ONLY good legs all hug the grid edge
     facing outward (≈1% of days), it falls back to an outward leg — there
     the robot faces an exterior lot (buildExteriorLots), not an interior
     block, and that lot's random type is what forcing the interior block
     missed. Force the faced lot's type to match so the ending building is
     always the right kind: housing at the door, commercial at the pickup.
     (The full isAddress door/customer treatment on a lot is the shelved
     perimeter-delivery feature; this only guarantees the building TYPE.) */
  const forceFacedLot = (s, wantType) => {
    const off = ROBOT_SIDE * (ROAD_HALF + SIDEWALK_W + T2*2);
    const p = segsWorldOf(segs, s, off);
    const bi = Math.floor(p.x / BLOCK), bj = Math.floor(p.y / BLOCK);
    const interior = bi >= 0 && bi <= grid.cols-2 && bj >= 0 && bj <= grid.rows-2;
    if(interior) return; // faces a real interior block — already handled
    let best = null, bestD = Infinity;
    for(const l of grid.extLots){ const d = (l.cx-p.x)**2 + (l.cy-p.y)**2; if(d < bestD){ bestD = d; best = l; } }
    if(best) best.type = wantType;
  };
  forceFacedLot(doorS, "housing");
  forceFacedLot(pickupS, "commercial");

  const pal = BLEND.hill > 0.55
    ? { sky:0xf2c48d, pave:0xbdb6a8, paveB:0xb3ac9e, paveEdge:0x9c9588, road:0x45484f, roadLine:0xcfc9b9 }
    : BLEND.pave < 0.5
    ? { sky:0xc9b49b, pave:0xa19a8e, paveB:0x958e82, paveEdge:0x7d7669, road:0x3d4046, roadLine:0x8f897b }
    : { sky:0x9fd4e8, pave:0xc9c3b4, paveB:0xbfb9aa, paveEdge:0xa8a294, road:0x4a4d55, roadLine:0xd8d2c2 };

  /* ---------- the ORDER (replaces the tip multiplier) ----------
     Each delivery is a real seeded order with contents and a dollar
     value. The old tipMult difficulty score (hills + rough pavement +
     litter + turns) now scales the ORDER SIZE instead of floating over
     the payout as a bare multiplier — harder route, bigger order,
     bigger stakes, same economics delivered as fiction. Tips are a
     PERCENTAGE of this value: 20% baseline, deductions for damage /
     lateness / walk distance, small bonuses to a 22% ceiling (engine
     in showWin). */
  const difficulty = 1 + BLEND.hill*1.2 + (1-BLEND.pave)*1.0 + BLEND.litter*0.8 + (walk.segs.filter(s=>s.type==="arc").length-2)*0.15;
  const MENU = SHOP_MENUS[shopTypeOf(pickupShopName)] || SHOP_MENUS.tacos;
  const orderLines = [];
  let orderValue = 0;
  const nLineItems = 1 + Math.floor(rng()*3);
  for(let i = 0; i < nLineItems; i++){
    const [oname, oprice, ospill] = MENU[Math.floor(rng()*MENU.length)];
    const qty = 1 + (rng() < 0.3 ? 1 : 0);
    const ex = orderLines.find(l => l.name === oname);
    if(ex) ex.qty += qty; else orderLines.push({ name: oname, qty, spill: ospill });
    orderValue += oprice * qty;
  }
  /* softened from x0.45: typed menus brought genuinely pricey goods
     (retail parcels/parts), and the old multiplier double-dipped into
     ~$190 orders. Cap keeps the worst stacks honest. */
  orderValue = Math.min(99, Math.round(orderValue * (0.85 + difficulty*0.3) * 100) / 100);
  const order = { lines: orderLines, value: orderValue,
    text: orderLines.map(l => l.qty > 1 ? `${l.qty}× ${l.name}` : l.name).join(", ") };

  /* par time — TIGHTENED from the casual launch tuning (0.075 cruise,
     3s/turn, 15s grace): beatable clean, not beatable sightseeing.
     The HUD counts it down; the tip decays 1%/5s past it; the ORDER
     CANCELS at par + 60s (see the cancel check in the sim). */
  const nTurns = walk.segs.filter(s => s.type === "arc").length;
  const parMs = Math.round((doorS - SPAWN_S)/0.088 + nTurns*2000 + BLEND.hill*15000 + 8000);

  /* traffic: real road-aware two-way loops through the same grid,
     instead of a fixed row that never knew where the road was.
     Bumped up for heavier traffic (was 2-3 routes / 4-6 cars total) --
     each route is still cheap (one buildWalk at route-gen time, not
     per-frame), and per-frame cost only applies to cars actually within
     cullSpan of the camera via near(), so more independent routes just
     means denser coverage across the grid, not a flat per-frame cost
     increase. */
  const nTrafficRoutes = totalLen > 50000 ? 18 : totalLen > 30000 ? 15 : 12;
  const traffic = buildTraffic(grid, rng, nTrafficRoutes, walk.nodes);

  /* ---------- GPS reroute loop (miss-the-door fallback, built at spawn) ----------
     Sailing past the door no longer dead-ends into the clamp+tip: the
     route is built WITH a rectangular block lap welded on just past the
     address — continue to the next intersection, four same-direction
     turns around the address block(s), rejoin the street behind the
     door, pass it again. The lap is geometrically periodic (end point
     and heading === start point and heading, guaranteed by the node
     lattice), so the sim wraps botS by loop.len at loop.sEnd and the
     player circles forever until the order cancels; doorS is retargeted
     ONCE (+= len, its next-lap occurrence — F(s+len)===F(s) on the lap)
     the moment the first pass is missed. See the sim's loop block.
     Placement in this builder is load-bearing: AFTER difficulty/parMs
     (which must read the ORIGINAL walk's turns/first-pass length) and
     BEFORE the hazard clear / cutEdges / tiles rebuild below (which
     must see the FINAL segs). SIGMA=-1 first (all inside turns,
     R=CORNER_R, continuous sidewalk, zero turn crossings — circles the
     address side); SIGMA=+1 fallback (outside turns, R=TURN_R, ramped
     turn crossings same as any outside corner). If neither rectangle
     has road connectivity (grid corner days), loop stays null and the
     sim falls back to the clamp — minus its old auto-tip shove. */
  let loop = null;
  {
    const sgD = segsSegAt(segs, doorS);
    if(sgD && sgD.type === "line"){
      const f = sgD.f, d = DIRV[f];
      const pD = segsPosAt(segs, doorS);
      const aDoor = pD.x*d.x + pD.y*d.y;   // signed along-axis coordinate (nodes live at multiples of BLOCK on it)
      const cN = Math.round((d.x !== 0 ? pD.y : pD.x) / BLOCK) * BLOCK;
      const chainOK = (n0, fh, nB) => {
        let cur = n0; const dd = DIRV[fh];
        for(let k = 0; k < nB; k++){
          if(!cur || !cur.conn[fh]) return null;
          cur = grid.nodeAt(cur.i + dd.x, cur.j + dd.y);
        }
        return cur;
      };
      for(const SIGMA of [-1, 1]){
        const R = (SIGMA === -ROBOT_SIDE) ? TURN_R : CORNER_R;
        /* first street node far enough past the win window (+60) that
           the entry corner's fillet can't eat the stopping zone */
        const aN0 = (Math.floor((aDoor + 60 + R + 20) / BLOCK) + 1) * BLOCK;
        const Ax = d.x !== 0 ? aN0*d.x : cN, Ay = d.x !== 0 ? cN : aN0*d.y;
        const A = grid.nodeAt(Math.round(Ax/BLOCK), Math.round(Ay/BLOCK));
        if(!A) continue;
        /* street sides span L blocks so the door sits safely inside the
           lap's return straight, >= R+90 clear of the re-entry corner —
           that keeps the door reachable with the same approach room a
           first pass gets */
        const L = Math.max(1, Math.ceil((aN0 - aDoor + R + 90) / BLOCK));
        const f1 = ((f + SIGMA) % 4 + 4) % 4, f2 = (f + 2) % 4, f3 = ((f - SIGMA) % 4 + 4) % 4;
        const B = chainOK(A, f1, 1); if(!B) continue;
        const C = chainOK(B, f2, L); if(!C) continue;
        const D = chainOK(C, f3, 1); if(!D) continue;
        if(chainOK(D, f, L) !== A) continue;
        /* truncate: the door leg now ends R short of corner A. A line
           seg is start+f parametric, so pushing s1 OUT (A beyond the
           leg's original trimmed end) is as valid as pulling it in —
           both just re-window the same infinite line. */
        const sCut = sgD.s0 + (Ax - R*d.x - sgD.start.x)*d.x + (Ay - R*d.y - sgD.start.y)*d.y;
        if(sCut <= doorS + 60) continue;
        segs.length = segs.indexOf(sgD) + 1;
        sgD.s1 = sCut;
        /* weld the lap: corners at A/B/C/D, seg construction copied
           field-for-field from buildWalk so every downstream consumer
           (segsPosAt, heading ease, corner tilt, arc-gated crossings)
           sees ordinary route segs */
        let s = sCut;
        const corner = (node, fIn) => {
          const dI = DIRV[fIn], rv = DIRV[(fIn+1)%4];
          const center = { x: node.x - dI.x*R + SIGMA*rv.x*R, y: node.y - dI.y*R + SIGMA*rv.y*R };
          const startPt = { x: node.x - dI.x*R, y: node.y - dI.y*R };
          const a0 = Math.atan2(startPt.y - center.y, startPt.x - center.x);
          const arcLen = Math.PI/2 * R;
          segs.push({ type:"arc", s0:s, s1:s+arcLen, center, a0, sign:SIGMA, R, hA:fIn*Math.PI/2, f:fIn });
          s += arcLen;
        };
        const leg = (node, fh, nB) => {
          const dd = DIRV[fh], len = nB*BLOCK - 2*R;
          segs.push({ type:"line", s0:s, s1:s+len, f:fh, hA:fh*Math.PI/2,
                      start:{ x: node.x + dd.x*R, y: node.y + dd.y*R } });
          s += len;
        };
        corner(A, f);  leg(A, f1, 1);
        corner(B, f1); leg(B, f2, L);
        corner(C, f2); leg(C, f3, 1);
        corner(D, f3); leg(D, f, L);
        loop = { sCut, sEnd: s, len: s - sCut, doorS0: doorS, missed: false };
        break;
      }
    }
  }
  if(loop){
    /* everything s-anchored past the cut now maps onto LAP geometry —
       stale placements from the removed tail must go (their ramps
       included; ramp anchors sit within a tile of their crossing) */
    for(const list of [hazards, props])
      for(let i = list.length - 1; i >= 0; i--)
        if(list[i].s > loop.sCut - 100) list.splice(i, 1);
    for(let i = crossings.length - 1; i >= 0; i--)
      if(crossings[i].sB > loop.sCut) crossings.splice(i, 1);
    /* fresh crossings for the extended door leg + lap — the SAME two
       detection rules as the originals above (straight-through nodes on
       line legs, outside-turn arcs), each with its ADA ramp pair pushed
       here since the main ramp spawn already ran. Dedupe by sA against
       the surviving originals (the door leg keeps its pre-cut ones). */
    const lapSegs = segs.slice(segs.indexOf(segsSegAt(segs, doorS)));
    const newCx = [];
    for(const sg of lapSegs){
      if(sg.type !== "line") continue;
      const dL = DIRV[sg.f], rvL = DIRV[(sg.f+1)%4];
      for(const n of grid.nodes){
        if(!n.conn[(sg.f+3)%4]) continue;
        const relX = n.x - sg.start.x, relY = n.y - sg.start.y;
        if(Math.abs(relX*rvL.x + relY*rvL.y) > 1) continue;
        const sN = sg.s0 + (relX*dL.x + relY*dL.y);
        if(sN - ROAD_HALF - 2*T2 < sg.s0 || sN + ROAD_HALF + 2*T2 > sg.s1) continue;
        if(crossings.some(cx => Math.abs(cx.sA - (sN - ROAD_HALF)) < 1)) continue;
        newCx.push({ sA: sN - ROAD_HALF, sB: sN + ROAD_HALF, fIn: sg.f, fOut: sg.f });
      }
    }
    for(let i = 0; i < lapSegs.length; i++){
      const sg = lapSegs[i];
      if(sg.type !== "arc") continue;
      if(sg.sign !== -ROBOT_SIDE) continue;
      const prev = lapSegs[i-1], next = lapSegs[i+1];
      if(!prev || !next || prev.type !== "line" || next.type !== "line") continue;
      if(sg.s0 - 2*T2 < prev.s0 + T2 || sg.s1 + 2*T2 > next.s1 - T2) continue;
      const dA = DIRV[sg.f], rvA = DIRV[(sg.f+1)%4];
      const nx = sg.center.x + dA.x*sg.R - sg.sign*rvA.x*sg.R;
      const ny = sg.center.y + dA.y*sg.R - sg.sign*rvA.y*sg.R;
      newCx.push({ kind:"turn", sA: sg.s0, sB: sg.s1, nx, ny,
                   fIn: sg.f, fOut: (sg.f + sg.sign + 4) % 4 });
    }
    for(const cx of newCx){
      crossings.push(cx);
      if(cx.kind !== "turn"){
        hazards.push({ type:"sidewalkend",   s: cx.sA - T2, row: CROSSING_RAMP_ROW, f: cx.fIn,  hit:true });
        hazards.push({ type:"sidewalkbegin", s: cx.sB + T2, row: CROSSING_RAMP_ROW, f: cx.fOut, hit:true });
      } else {
        const dI = DIRV[cx.fIn],  rI = DIRV[(cx.fIn+1)%4];
        const dO = DIRV[cx.fOut], rO = DIRV[(cx.fOut+1)%4];
        const offR = laneOffset(CROSSING_RAMP_ROW);
        hazards.push({ type:"sidewalkend", row: CROSSING_RAMP_ROW, f: cx.fIn, hit:true, s: cx.sA,
          wx: cx.nx - dI.x*(ROAD_HALF + T2) + rI.x*offR,
          wy: cx.ny - dI.y*(ROAD_HALF + T2) + rI.y*offR, wz: 0 });
        hazards.push({ type:"sidewalkbegin", row: CROSSING_RAMP_ROW, f: cx.fOut, hit:true, s: cx.sB,
          wx: cx.nx + dO.x*(ROAD_HALF + T2) + rO.x*offR,
          wy: cx.ny + dO.y*(ROAD_HALF + T2) + rO.y*offR, wz: 0 });
      }
    }
    /* the virtual grade profile is a per-s array — rebuild it over the
       final segs (elevAtWorld is world-seeded, so shared stretches get
       identical values; only the welded portion is genuinely new) */
    tiles.length = 0;
    const nTL = Math.ceil(loop.sEnd / (TILE*2)) + 3;
    for(let i = 0; i < nTL; i++){
      const p = segsPosAt(segs, Math.min(i*T2, loop.sEnd));
      tiles.push(elevAtWorld(p.x, p.y));
    }
    for(let pass = 0; pass < 2; pass++)
      for(let i = 1; i < nTL-1; i++) tiles[i] = (tiles[i-1] + 2*tiles[i] + tiles[i+1]) / 4;

    /* THE WILLIAM — one per day, waiting on the wrap-around lap. Line
       legs only (s past sCut), clear of crossings and every other
       spawn (the no-stacking RULE), with a prop.people-style walk
       range so he paces his block until you show up. */
    {
      const lapLines = segs.filter(sg => sg.type === "line" && sg.s0 >= loop.sCut - 1);
      for(let att = 0; att < 24 && lapLines.length; att++){
        const sg = lapLines[Math.floor(rng()*lapLines.length)];
        const lo = sg.s0 + 2*T2, hi = sg.s1 - 2*T2;
        if(hi - lo < T2) continue;
        const ks = lo + rng()*(hi - lo);
        if(crossings.some(cx => ks > cx.sA - 2*T2 && ks < cx.sB + 2*T2)) continue;
        let kClear = true;
        for(const list of [hazards, props])
          for(const o of list) if(Math.abs(o.s - ks) < 2*T2){ kClear = false; break; }
        if(!kClear) continue;
        const kObj = { type:"william", s: ks, row: 0, f: facingAt(ks), hit:true,
                       williamSeed: (rng()*4294967296) >>> 0,
                       peopleSeed: (rng()*4294967296) >>> 0 };
        /* SHORT beat, not the whole (34-block-scaled) leg: his wall
           plants at hz.s + ka, so the spawn point's crossing/stacking
           clearances only mean something if he stays near his anchor */
        const kw0 = Math.max(sg.s0 + CROSSING_CLEAR, ks - 3*T2);
        const kw1 = Math.min(sg.s1 - CROSSING_CLEAR, ks + 3*T2);
        if(kw1 - kw0 >= T2){ kObj.walkS0 = kw0; kObj.walkS1 = kw1; }
        hazards.push(kObj);
        break;
      }
    }
  }

    /* ---------- FURNISH THE LAP ----------
       Everything s-anchored past the cut was deleted above, and until now
       nothing put anything back, so the lap ran bare: 0 props and ~1
       hazard per 1000 units against 12-14 on the main route. You could
       drive the entire way round the block without touching a thing.

       Placed HERE for two ordering reasons, both found by measurement.
       AFTER newCx: spawnBlocked() consults inCrossing(), so run any
       earlier and props spawn inside the lap's own intersections and on
       its curb ramps. AFTER the William block: he only gets 24 placement
       attempts and rejects any spot within 2*T2 of an existing item, so
       furnishing the lap first starved him out -- he failed to spawn on
       every single day tested. He picks his spot on the empty lap exactly
       as before, and these props then avoid HIM via spawnBlocked.

       Its own rng, seeded off the date and the cut, so the builder's
       stream is untouched and every other feature on a given date keeps
       the exact position it had before this existed. Margins match the
       main walk's (+120 / -220 from each end). */
    {
      const lapRng = mulberry32(((dateStr.length*2654435761) ^ (Math.round(loop.sCut)*40503)
                                 ^ (Math.round(loop.sEnd)*97) ^ 0x1a9d) >>> 0);
      spawnHazardRange(loop.sCut + 120, loop.sEnd - 220, lapRng);
      spawnPalmRange(loop.sCut + 140, loop.sEnd - 220, lapRng);
    }

  /* ---------- clear stage for the choreography ----------
     Volumetric hazards are swept out of a window around BOTH scene
     anchors (pickup shop, dropoff door). The three-canvas stacking
     draws the worker/customer with the building pass while hazards
     ride the depth layers, so a cone spawned at the shop door paints
     over the worker's face regardless of true depth (reported
     on-device). Runs post-spawn because pickupS/doorS are only chosen
     after the hazard passes. Ground paint (crack/slab/grade) and the
     curb ramps stay — they're pinned under everything and can't
     occlude anyone. */
  {
    /* slab REMOVED from the exemptions (it originally rode along as
       "ground paint"): slabs are RAISED terrain pinned to the mid
       layer, so one under the pickup worker painted over his legs —
       the worker draws with the building pass beneath it (on-device).
       Cracks and grade chevrons are truly flat and stay; the curb
       ramps are structural to crossings and stay. */
    const GROUNDY = { crack:1, grade:1, sidewalkend:1, sidewalkbegin:1 };
    const CLEAR = 240;
    /* WORLD-space test added (2026-08-06, "props drawing over the
       delivery carpet", on-device): the s-window above is blind to two
       lap holes. (1) The lap's closing leg runs the door's OWN street
       back to the weld, so lap-spawned props stand in front of the door
       with lap-s nowhere near doorS -- measured on a live route: a
       scooter 49 world-units from the mat centre with an s-gap of
       11266. (2) Main-pass hazards spawned past the cut (their range
       ends at a totalLen the weld then truncates) remap onto lap
       geometry the same way. Both resolve through the SAME segsWorldOf
       the renderer draws them with, so this sweep and the art cannot
       disagree. Anchors sit mid-sidewalk (lane 1.5): a 240 radius spans
       all four lanes at both scene anchors, mat included. */
    const pkPt = segsWorldOf(segs, pickupS, laneOffset(1.5));
    const drPt = segsWorldOf(segs, doorS, laneOffset(1.5));
    const nearAnchorWorld = hz => {
      if(hz.row === undefined) return false;   // road-anchored pieces keep their own lane
      const wp = segsWorldOf(segs, hz.s, laneOffset(hz.row));
      return (wp.x-pkPt.x)**2 + (wp.y-pkPt.y)**2 < CLEAR*CLEAR
          || (wp.x-drPt.x)**2 + (wp.y-drPt.y)**2 < CLEAR*CLEAR;
    };
    for(let i = hazards.length - 1; i >= 0; i--){
      const hz = hazards[i];
      if(GROUNDY[hz.type]) continue;
      if(Math.abs(hz.s - pickupS) < CLEAR || Math.abs(hz.s - doorS) < CLEAR
         || nearAnchorWorld(hz))
        hazards.splice(i, 1);
    }
  }

  /* ---------- precomputed cutaway edges ----------
     The north-wall cutaway (NORTH_WALL_CUT_EDGE: f=1 cuts a block's
     west edge, f=2 its north — the two headings where the fixed iso
     camera can push the near block's wall over the robot) used to be
     evaluated LIVE per frame against the current seg + the block the
     robot stood in. That made it snap three ways: houses vanished the
     instant the heading seg flipped, jumped block-to-block mid-leg,
     and popped back through every corner arc. The route is fully
     known here, so the whole thing is now computed ONCE: every block
     the robot's lane traverses on a cut-heading leg goes into a
     static map, block(i,j) -> [edges], permanent for the route —
     those edges show their fence/parking replacement from frame one
     and never change. Arcs contribute BOTH neighbor legs' cut edges
     to the blocks they sweep, so corners are covered without any
     transition. The address door's edge and the pickup shop's edge
     are never cut — the live version would happily vanish the
     customer's house if you approached it westbound. */
  const cutEdges = {};
  /* cutExt (2026-07-27, "still getting f=1"): world-space spans of
     every cut-heading leg portion whose near-side probe leaves the
     interior grid — i.e. the robot's side faces an EXTERIOR LOT.
     Exterior lots aren't in the block grid, so the cutEdges map above
     can't reach them; before this, a perimeter f=1/f=2 leg showed
     full, un-cut houses at the robot's side (queueExteriorLot never
     consulted the cutaway at all). The render side (queueExteriorLot)
     tests each lot unit against these spans and swaps house/store for
     the same solid fence row an interior cut edge gets. */
  const cutExt = [];
  const addCut = (bi, bj, edge) => {
    if(edge == null) return;
    if(addressBlock && bi === addressBlock.i && bj === addressBlock.j && edge === addressEdgeIdx) return;
    if(pickupBlock && bi === pickupBlock.i && bj === pickupBlock.j && edge === pickupEdgeIdx) return;
    const k = bi + "," + bj;
    if(!cutEdges[k]) cutEdges[k] = [];
    if(!cutEdges[k].includes(edge)) cutEdges[k].push(edge);
  };
  for(const sg of segs){
    const eIn = NORTH_WALL_CUT_EDGE[sg.f];
    const eOut = sg.type === "arc" ? NORTH_WALL_CUT_EDGE[(sg.f + sg.sign + 4) % 4] : null;
    if(eIn == null && eOut == null) continue;
    let prevWp = null;
    for(let s = sg.s0; ; s += T2){
      const sv = Math.min(s, sg.s1);
      const wp = segsWorldOf(segs, sv, laneOffset(1));   // any lane row lands in the same block
      const bi = Math.floor(wp.x/BLOCK), bj = Math.floor(wp.y/BLOCK);
      const offGrid = bi < 0 || bi > grid.cols-2 || bj < 0 || bj > grid.rows-2;
      if(offGrid){
        /* beside an exterior lot — record the step as a cut span
           (consecutive step points chain into a polyline; arcs come
           out as short chords, which is all the render test needs).
           addCut skipped: it used to file these under nonexistent
           block keys like "-1,3" that nothing ever read. */
        if(prevWp) cutExt.push({ x0: prevWp.x, y0: prevWp.y, x1: wp.x, y1: wp.y });
      } else {
        if(sg.type === "line") addCut(bi, bj, eIn);
        else { addCut(bi, bj, eIn); addCut(bi, bj, eOut); }
      }
      prevWp = wp;
      if(sv >= sg.s1) break;
    }
  }

  /* STREETLAMPS (approved lamp lab v2): the night feature's anchor
     prop. Spawned LAST — after the loop weld and the pickup/door
     stage sweep — so no later pass can prune them and the rhythm
     covers the wrap-around lap too (a night lap deserves its lights).
     Beats ALTERNATE between the two edges of the sidewalk band --
     row 3 (building side) and row 0 (curb side) -- so both sides are
     lit rather than one, staggered rather than paired so the lamp
     count and the blocking density stay where they were. Each lamp
     carries an armSign so its head always hangs INWARD over the
     walking band: +1 (toward the road) from row 3, -1 (away from the
     road) from row 0. No lamp ever throws its light over the road.
     Each beat retries one tile either way before gapping, and uses
     pole-scale clearance (a lamp post stands closer to things than a
     palm cluster ever could — spawnBlocked's palm-sized gap starved
     the row to 2 lamps in testing). ~10% are broken: they lean, and
     at night they flicker. All seeded from the route rng — the same
     lamp is the same broken lamp for everyone, all day. */
  {
    const effLen = loop ? loop.sEnd : totalLen;
    /* stage anchors in WORLD form for lampClear -- the same lap
       blindness the clear stage above just fixed: the lap's closing leg
       passes the door with lap-s values the s-window can't see. The
       live-route probe that found the clear-stage hole also caught one
       lamp surviving it, 193 world-units from the mat. */
    const stagePts = [segsWorldOf(segs, pickupS, laneOffset(1.5)),
                      segsWorldOf(segs, doorS, laneOffset(1.5))];
    const lampClear = (s, row) => {
      if(inCrossing(s)) return false;
      if(Math.abs(s - pickupS) < 260 || Math.abs(s - doorS) < 260) return false;  // the stage rule
      const off = laneOffset(row);
      const wp0 = segsWorldOf(segs, s, off);
      for(const ap of stagePts)
        if((wp0.x-ap.x)**2 + (wp0.y-ap.y)**2 < 260*260) return false;   // stage rule, world form
      for(const list of [hazards, props])
        for(const it of list)
          if(Math.abs(it.s - s) < 40 && Math.abs((it.row !== undefined ? laneOffset(it.row) : (it.roadOffset || 0)) - off) < T2*0.55) return false;
      return true;
    };
    let beat = 0;
    for(let ls = SPAWN_S + 120; ls < effLen - 160; ls += LAMP_ACT.spacing * T2){
      const lampRow = (beat++ % 2) ? 0 : 3;              // alternate building side / curb side
      const armSign = lampRow === 0 ? -1 : 1;            // always reach INWARD, over the sidewalk
      for(const nudge of [0, T2, -T2]){
        const lsR = Math.round(ls + nudge);
        if(lsR < SPAWN_S + 80 || lsR > effLen - 120) continue;
        if(inCorner(lsR)) continue;
        if(!onSidewalk(lsR, laneOffset(lampRow))) continue;
        if(!lampClear(lsR, lampRow)) continue;
        hazards.push({ type:"lamp", s: lsR, row: lampRow, armSign, f: facingAt(lsR), hit: false,
                       lampSeed: (rng()*4294967296) >>> 0,
                       mal: rng() < LAMP_ACT.malRate });
        break;
      }
    }
  }
  /* THE NIGHT ROLL — consumed LAST so every rng draw before it is
     untouched: existing daily layouts don't shift under this
     feature. ~1 day in 4 is a night route, same for everyone. */
  const night = rng() < NIGHT_RATE;
  /* the reserved course leg, if this route was generated for the
     challenge. null on every normal delivery route. */
  const courseLeg = (opts && opts.challenge) ? findCourseLeg(segs) : null;
  /* The course itself is NOT built here. Level n means n hydrants with
     the catch ramp moved out to match, so it is rebuilt every level by
     WorldScene.hjBuildCourse(). generateRoute only reserves the leg. */
  const challenge = courseLeg ? {
    lane: 1,
    /* The kicker sits a full RUN-UP past the start of the straight leg.
       It used to be legS0 + 60, and the robot spawned at kicker - 420 —
       which is legS0 - 360, i.e. BEFORE the leg even starts, out in the
       corner arc. That is why he began mid-turn. */
    kickerS: Math.round(courseLeg.s0 + HJ_GEOM.runup + TILE),
    hydS: [], catchS: 0,
    f: courseLeg.f,
    /* start the course a short way into the leg so the run-up has room
       and the robot is clear of the corner fillet */
    s0: courseLeg.s0 + 60,
    legS0: courseLeg.s0, legS1: courseLeg.s1,
    /* always the same address, so it is a real findable place rather
       than a different corner every run */
    street: HJ_ADDRESS.street
  } : null;

  /* weekly crime scene — rolled from its own salted date hashes, never
     from `rng`, so non-scene days generate a byte-identical city */
  const crime = crimeSceneOnDate(dateStr)
    ? findCrimeSite(grid, cutEdges, dateStr, segs, loop ? loop.sEnd : totalLen,
                    [addressBlock, pickupBlock]) : null;
  /* every car reads the same pinch — trafficWorldAt is pure, so the
     scene data has to reach it through the car it is called with */
  if(crime) for(const tr of traffic) tr.pinch = crime.pinch;

  /* ---------- routeCells: where the town must NOT be furnished ----------
     Street furniture is DECORATION -- it is drawn per visible block and
     never enters hazards[], so the sim cannot see it and the robot drives
     straight through it. That is fine for a bench across the street and
     actively bad for one on the robot's own sidewalk, where it would sit
     inches from a real, collidable bin and behave differently. Worse, it
     would double up on the route's own spawns, which are placed by their
     own no-stacking rule that this pass knows nothing about.

     So the fix is exclusion, not collision: bake a coarse spatial hash of
     everything within FURNISH_CLEAR of the walked path, and let the
     scatter reject any candidate that lands in it. Built AFTER the loop
     weld so the reroute lap is covered too. O(1) lookup per candidate,
     which is what makes it affordable inside a draw call. */
  const routeCells = new Set();
  {
    const end = loop ? loop.sEnd : totalLen;
    const R = Math.ceil(FURNISH_CLEAR / FURNISH_CELL);
    for(let s = 0; s <= end; s += TILE){
      /* both sidewalk rows, so the exclusion covers the full walkable
         width rather than just the centre line */
      for(const off of [laneOffset(0), laneOffset(3)]){
        const wp = segsWorldOf(segs, Math.min(s, end), off);
        const ci = Math.round(wp.x/FURNISH_CELL), cj = Math.round(wp.y/FURNISH_CELL);
        for(let a = -R; a <= R; a++)
          for(let b = -R; b <= R; b++) routeCells.add((ci+a) + "," + (cj+b));
      }
    }
  }

  /* The decorative world set minus anything that would land on top of a
     route ramp -- those carry the physics and must stay the only ramp at
     their spot. Route ramps are route-s anchored (straight crossings) or
     world anchored (turn crossings), so both forms get resolved to world
     coordinates before comparing. The tolerance is loose on purpose: the
     nearest legitimately-different ramp is the one across the street,
     2*598 units away, so there is nothing to accidentally delete. */
  const routeRampPts = hazards
    .filter(h => h.type === "sidewalkend" || h.type === "sidewalkbegin")
    .map(h => h.wx !== undefined ? { x: h.wx, y: h.wy }
                                 : segsWorldOf(segs, h.s, laneOffset(h.row)));
  const RAMP_DEDUP = 150;
  const curbRamps = grid.curbRamps.filter(cr => !routeRampPts.some(
    p => Math.abs(p.x - cr.x) < RAMP_DEDUP && Math.abs(p.y - cr.y) < RAMP_DEDUP));

  worldgenReconcile(grid);
  return { hood: addressHood, grid, segs, totalLen: loop ? loop.sEnd : totalLen, loop, tiles, hazards, props, pal, night, traffic, crossings, cutEdges, cutExt, challenge, crime, routeCells, curbRamps, signals: grid.signals,
           address:`${number} ${street}`, doorS, pickupS, pickupSpot, pickupShopName, addressBlock, pickupBlock, addressEdgeIdx, pickupEdgeIdx, addressUnitIdx, pickupUnitIdx, addressUsesGate, order, parMs, dateStr };
}

/* ---------- robot palette (approved in sprite lab) ---------- */
/* SKIN is read directly by every robot draw call, so a skin is EQUIPPED
   by overwriting its fields in place — SKIN_BASE keeps the stock palette
   so equipping is reversible. Before this there was no equip system at
   all: TP_SKINS entries carried only a CSS `filter` for the store
   swatch, and equippedSkin was never read anywhere in the file.

   INVARIANT: only the PLAYER's drawRobot may read SKIN. The sidewalk
   NPC robots (kind === "robot") read SKIN_BASE instead — they shared
   SKIN before, so equipping Fire Chief repainted every robot in the
   city to match. NPC-specific accents live in ROBOT_NPC. */
const SKIN = {
  bodyTop:0xf7f8fa, bodyRight:0xe3e6ea, bodyLeft:0xc9cdd4, outline:0x30343d,
  stripe:0xc2452e, stripeDk:0xa03824,
  wheel:0x24262c, wheelDark:0x1a1c21, wheelHubFace:0x3d424c, wheelHub:0x8a919c,
  visor:0x22242b, eye:0x7fe3ff, eyeAlert:0xffb04d,
  lidInner:0xb2b7bf, cavityWall:0x9ba1a9, cavityFloor:0x7b818a,
  belly:0x494e58, flagPole:0x2e3138, flag:0xff5722, shadow:0x000000
};

const BODY = { hx:26, hy:20, z0:14, z1:54 };
const LID  = { hx:22, hy:16, z0:54, z1:61 };
const STRIPE = { z0:20, z1:27 };
const WHEEL = { r:8, z:10, xs:[-16, 0, 16], side:22 };
const FLAG = { base:{x:-25, y:17}, z0:54, z1:97 };  // anchored to the body's top edge, at a
                                                      // corner outside the lid's footprint
                                                      // (lid hx:22/hy:16 vs body hx:26/hy:20) —
                                                      // was anchored to the lid (z0 matched
                                                      // LID.z1 exactly, base x/y sat inside the
                                                      // lid's own footprint)

/* other robots (requested 2026-07-24): Tipsey's exact look, one swap --
   blue stripe/flag instead of red (confirmed on-device, dropped the
   earlier multi-color variety in favor of just this). */
const ROBOT_NPC = { stripe:0x2e6fd1, stripeDk:0x24569f, flag:0x2e6fd1 };

class WorldScene extends Phaser.Scene {
  constructor(){ super("world"); }

  create(){
    /* was a hard-coded 1.5. Seeded from the persisted camera depth so a
       player who set depth 3 keeps it across route rebuilds, mode
       switches and reloads. ZOOM_K[0] IS 1.5 — depth 1 is byte-identical
       to the old behaviour. */
    this.K = ZOOM_K[zoomLoad() - 1];
    /* reused every frame by the sidewalk hash queries so the lookup does
       not allocate a fresh result array sixty times a second */
    this._qRuns = [];
    this._qCorner = [];
    this.f = 0;
    this.roll = 0;
    this.pitch = 0;
    this.drawAngle = 0;
    this.wheelPhase = 0;
    this.flagLean = 0;
    this.blinkT = 0;
    this.camX = 0;

    /* game state */
    this.mode = "delivery";     // delivery | challenge  (see loadChallenge)
    this.state = "idle";        // idle | play | tipped | won
    /* Attract is deliberately NOT a fifth state. Roughly twenty sim
       branches gate on state === "play" (traffic, William, hazards,
       cargo, the drive integrator); a new state would switch every one
       of them off and the splash would show a frozen city. Attract runs
       AS "play" and carries a flag alongside it, so the whole sim comes
       along unchanged and the flag only has to own the endings. */
    this.attract = false;
    this.attractTimer = null;
    this.attractHopAt = 0;
    this.attractStuckMs = 0;
    this.attractWantRow = null;
    this.speed = 0;
    this.tilt = 0;              // stability: fail beyond ±1
    this.botRow = 1;            // lane 0 (building side) .. lane 3 (curb side), 4 lanes total
    this.botY = 0;
    this.hopAnim = null;        // active lane-change maneuver
    this.yaw = 0;               // nose steer during lane change
    this.hopKick = 0;           // stability cost, bled in over the maneuver
    this.damage = 0;            // cargo damage %
    this.runT = 0;
    this.throttle = 0;          // -1 brake, 0 coast, 1 gas
    this.tipT = 0; this.tipStartRoll = 0; this.postSpillMs = 0; this.lidAng = 0; this.items = []; this.spilled = false;
    this.wonT = 0; this.wonFrac = 0; this.wonLiftT = 0; this.wonLidClosing = false; this.wonWalkAt = null; this.wonWalk = 0; this.wonOutT = 0; this.wonOutFrac = 0; this.wonMeet = null;
    this.bagOnBoard = false;
    this.cornerLean = 0;
    this.corneringSpeedSmooth = 0;   // lagged speed feeding cornering lean —
                                      // see loadRoute() reset for the full note
    this.stuckAmt = 0; this.isBlocked = false;

    this.gSky = this.add.graphics();
    this.gWorld = this.add.graphics();
    this.gFade = this.add.graphics();      // the one wall being faded out/in — separate object so it can have its own alpha
    this.g = this.add.graphics();
    this.gFront = this.add.graphics();     // hazards nearer the camera than the robot
    this.gNight = this.add.graphics();     // NIGHT: one multiply rect over the world (night-lab v1: NAVY 0.65)
    this.gNight.setBlendMode(Phaser.BlendModes.MULTIPLY);
    this.gGlow = this.add.graphics();      // warm accents ABOVE the tint (lamps, eyes)
    this.gGlow.setBlendMode(Phaser.BlendModes.ADD);
    this.hud = this.add.graphics().setDepth(5);
    /* see memoGraphicsStyles: drops the ~13k redundant style changes a
       frame that were fragmenting Phaser's batches. Applied to every
       Graphics this scene draws into, including the ones with their own
       alpha and blend mode, since the memo is per instance. */
    [this.gSky, this.gWorld, this.gFade, this.g, this.gFront,
     this.gNight, this.gGlow, this.hud].forEach(memoGraphicsStyles);
    this.qtext = this.add.text(0, 0, "?!", { fontSize:"30px", fontStyle:"bold", color:"#ffb04d" })
      .setOrigin(0.5).setDepth(4).setVisible(false);

    this.bindInput();
    this.loadRoute(new Date().toISOString().slice(0,10));
    this.scale.on("resize", () => this.layout());
    this.layout();
  }

  bindInput(){
    let downY = 0, downT = 0, hopped = false;
    this.input.on("pointerdown", p => {
      if(this.attract) return;   // the splash drives itself; see attractStart
      downY = p.y; downT = this.time.now; hopped = false;
      this.throttle = p.x > this.scale.gameSize.width/2 ? 1 : -1;
    });
    this.input.on("pointermove", p => {
      if(this.attract || !p.isDown || hopped) return;
      const dy = p.y - downY;
      if(Math.abs(dy) > 34 && this.time.now - downT < 320){
        hopped = true; this.throttle = 0;
        this.hop(dy < 0 ? -1 : 1);
      }
    });
    this.input.on("pointerup", () => { if(this.attract) return; this.throttle = 0; hopped = false; });
    /* WASD mirrors the arrows exactly: W/S hop (screen-relative, same
       translation as swipes), A/D throttle. */
    this.keys = this.input.keyboard.addKeys({ up:"UP", down:"DOWN", left:"LEFT", right:"RIGHT",
                                              w:"W", a:"A", s:"S", d:"D" });
    this.input.keyboard.on("keydown-UP",   () => this.hop(-1));
    this.input.keyboard.on("keydown-DOWN", () => this.hop(1));
    this.input.keyboard.on("keydown-W",    () => this.hop(-1));
    this.input.keyboard.on("keydown-S",    () => this.hop(1));
  }

  /* screenDir: -1 = the swipe/key said UP-screen, +1 = DOWN-screen.
     Lanes live in fixed world-space (row 0 road side, row 3 building
     side), but which row direction is visually up-screen flips with
     heading — the lane axis rv rotates under the fixed camera, so the
     old direct dy -> row mapping made the same swipe move the robot
     up-screen on one street and down-screen on the next (on-device:
     "switches direction depending on the f="). Translate here: one
     sign test on the lane axis's screen-y projection, using the same
     quantized heading the renderer uses. Muscle memory follows the
     SCREEN, the map follows along. */
  /* The screen<->row direction flip, in ONE place. A swipe arrives in
     screen space, lanes live in row space, and which way a +1 row step
     moves on screen depends on the current heading. The mapping is its
     own inverse (it is a sign flip), so hop() uses it to turn a swipe
     into a row step and the attract driver uses the same call to turn a
     wanted row step back into the swipe that produces it. Extracted
     rather than copied: two copies of this could disagree about which
     way is up on exactly one heading, and the symptom would be an
     attract robot that calmly steers INTO hazards while heading north. */
  rowScreenFlip(d){
    const hdg = this.headingAt(this.botS);
    const fq = ((Math.round(hdg / (Math.PI/2)) % 4) + 4) % 4;
    const rv = DIRV[(fq + 1) % 4];
    /* screen-y of one +1 row step: rows step by (laneOffset(r+1) -
       laneOffset(r)) along rv; screen y grows with (x + y). Sign is all
       we need — spacing is uniform, so sample rows 0->1. */
    const rowPlusDown = (rv.x + rv.y) * (laneOffset(1) - laneOffset(0)) > 0;
    return rowPlusDown ? d : -d;
  }

  hop(screenDir){
    if(this.state !== "play") return;
    const dir = this.rowScreenFlip(screenDir);
    /* no lane changes mid-turn: a hop's lateral swing (up to 276 units,
       nearly the turn's own radius) happening over the short arc-length
       distance covered during a turn was overwhelming the actual
       quarter-circle geometry — the ROBOT'S real path, not just the
       debug trail, hooks and loops when this happens. Same rule real
       driving already has: commit to your lane before the turn, not
       mid-turn. */
    if(this.segAt(this.botS).type === "arc") return;
    const target = Phaser.Math.Clamp(this.botRow + dir, 0, 3);
    if(target === this.botRow) return;
    this.botRow = target;
    this.hopAnim = { from: this.laneOff, to: laneOffset(target), start: this.time.now, dir };
    /* the math problem: lane changes cost stability, scaled by speed —
       bled in across the maneuver rather than spiked */
    this.hopKick += dir * (0.16 + this.speed * 4.5);
  }

  /* ---------- HYDRANT CHALLENGE ----------
     Runs INSIDE WorldScene, on a real Costa Palma route, rather than in
     a scene of its own. That is the whole point: the city draws itself,
     drawRobot() brings the flag and the full robot with it, and the
     course is a place you drive to instead of a void you get warped
     into. The route is a normal Flats route with one straight leg
     reserved for the course (see generateRoute's findCourseLeg). */
  /* one press of the tap button (or A/S/D), per-source deduped */
  hjTap(now, src){
    if(this.mode !== "challenge" || this.hjAir || this.state === "tipped") return;
    const t = now === undefined ? performance.now() : now;
    const k = src === undefined ? "x" : src;
    this.hjSrcLast = this.hjSrcLast || {};
    if(this.hjSrcLast[k] && t - this.hjSrcLast[k] < 20) return;   // one input, two events
    this.hjSrcLast[k] = t;
    this.hjAddCharge();
  }

  /* ONE place a tap becomes charge. Factored out so the autoTap driver
     below cannot drift from what a real thumb does — they were two
     copies of the same line for about five minutes and that is exactly
     how a bench ends up measuring something the game does not do. */
  hjAddCharge(){
    this.hjCharge = Math.min(HJ_CH.chargeMax, this.hjCharge + HJ_CH.add);
  }

  /* the jump, in ROUTE space. botS is already a 1-D along-axis, so the
     lab's run-space maths port straight onto it — no second coordinate
     system, and the arc rides the real street's grade. */
  hjSim(dt, ch){
    if(!ch) return;
    /* ---- AUTO TAP ----
       HJ_CH.autoTap was declared with a "headless testing only" comment
       and then never read by anything, so the dial did nothing at all.
       It is wired here because a tap RATE is the unit the whole jump is
       tuned in — every band in the table above is quoted against
       taps/sec — and comparing two tunings by thumb is not a
       measurement. 0 (the default) leaves live play untouched.

       The accumulator carries its remainder rather than resetting, so a
       rate that does not divide the frame time stays honest over a whole
       run-up instead of quietly rounding down to the frame rate. */
    if(HJ_CH.autoTap > 0 && this.state === "play"
       && !this.hjAir && !this.hjRolling && !this.hjEnded){
      const iv = 1000 / HJ_CH.autoTap;
      this.hjAutoAcc = (this.hjAutoAcc || 0) + dt;
      while(this.hjAutoAcc >= iv){ this.hjAutoAcc -= iv; this.hjAddCharge(); }
    }
    /* charge only bleeds while grounded; locked for the whole flight */
    if(!this.hjAir){
      this.hjCharge = Math.max(0, this.hjCharge - HJ_CH.decay*this.hjCharge*dt);
      this.hjChargeSm += (this.hjCharge - this.hjChargeSm) * Math.min(1, HJ_CH.smooth*dt);
    }
    /* ---- END OF THE COURSE ----
       Without this the attempt never ends: creep over the kicker below
       minSpeed and no launch fires, so Tipsey just drives on down
       Palmline Ave and out of the mission entirely. Rolling past the
       catch ramp on the ground ends the run the same way a crash does —
       progress banked, crash screen, no free wandering. */
    if(!this.hjAir && !this.hjRolling && !this.hjEnded &&
       this.botS > ch.catchS + 2*T2){
      this.hjEnded = true;
      this.hjResult = "NEVER LEFT THE GROUND";
      this.hjSaveProgress();
      this.state = "tipped"; this.tipDir = 1; this.hjFace = false;
      setTimeout(() => { if(this.mode === "challenge") hjShowCrash(this); }, 900);
      return;
    }
    /* and once he has landed, the roll-out is not a licence to keep
       driving — end it a little past the ramp */
    if(this.hjRolling && !this.hjEnded && this.botS > ch.catchS + 4*T2){
      this.hjEnded = true;
      this.hjSaveProgress();
      /* a CLEAN run already queued its own advance; only a botched
         landing that rolled out needs the crash screen here */
      if(!(this.hjResult || "").startsWith("CLEAN"))
        setTimeout(() => { if(this.mode === "challenge") hjShowCrash(this); }, 400);
      return;
    }
    const prev = this.hjPrevS === undefined ? this.botS : this.hjPrevS;
    /* LAUNCH at the kicker lip */
    const lip = ch.kickerS + TILE;
    if(!this.hjAir && prev < lip && this.botS >= lip && this.speed >= HJ_JUMP.minSpeed){
      const c = this.hjLocked = Phaser.Math.Clamp(this.hjChargeSm, 0, HJ_CH.chargeMax);
      const pow = HJ_CH.pw0 + Math.min(c,1)*(HJ_CH.pw1 - HJ_CH.pw0);
      this.hjFlightSpeed = this.speed;
      /* Start at the TOP OF THE LIP. hjAir.z is absolute height above
         flat ground, so it must inherit the ramp height — starting at 0
         while hjSlabZ stops contributing dropped him 12 units the
         instant he left the lip. Same bug the lab had and fixed. */
      /* the LIP height explicitly. hjSlabZ(botS) reads 0 or a partial
         value here because the slab test is |da| < TILE exclusive and
         the launch fires exactly at da = TILE — the same off-by-one the
         lab hit. Take the kicker's lift directly. */
      const kick = this.route.hazards.find(h => h.hjRole === "kicker");
      this.hjAir = { vz: this.speed*pow, z: kick ? kick.lift : 0, idx: 0 };
      this.hjPassed = 0; this.hjResult = "";
    }
    if(this.hjAir){
      this.hjAir.vz -= HJ_JUMP.grav*dt;
      this.hjAir.z  += this.hjAir.vz*dt;
      /* clearance, every hydrant, checked as we cross it */
      while(this.hjAir && this.hjAir.idx < ch.hydS.length){
        const hs = ch.hydS[this.hjAir.idx];
        if(!(prev < hs && this.botS >= hs)) break;
        this.hjAir.idx++;
        const hz = this.route.hazards.find(h => h.hjRole==="hydrant" && h.s===hs);
        if(this.hjAir.z < HYD.height + HJ_JUMP.clear){
          if(hz && !hz.burst){ hz.burst = true; hz.burstT = this.runT; }
          this.hjAir.vz = -Math.abs(this.hjAir.vz) - 0.01;
          this.hjAir.clipped = true;
          this.hjResult = "BURST A HYDRANT";
        } else this.hjPassed++;
      }
      /* touchdown */
      /* PITCH: nose follows the velocity vector, eased so leaving the lip
         does not snap the attitude. Straight from the lab. */
      const pT = Math.atan2(this.hjAir.vz, Math.max(this.speed, 1e-4)) * 0.6;
      this.pitch += (pT - this.pitch) * Math.min(1, 0.030*dt);
      /* Land on the CATCH ramp's plane — deliberately NOT hjSlabZ(),
         which also reports the kicker he is still standing over at
         launch and made him touch down instantly. */
      const cz = this.route.hazards.find(h => h.hjRole === "catch");
      const gz = (cz && Math.abs(this.botS - cz.s) < TILE)
        ? this.hjWedgeTop(cz, this.botS - cz.s) : 0;
      if(this.hjAir.vz < 0 && this.hjAir.z <= gz){
        const dL = this.botS - ch.catchS;
        const onRamp = Math.abs(dL) < TILE;
        /* absorption by CENTREDNESS — the catch ramp's down-slope takes
           the impact best where it matches the descent, in the middle.
           A flat value cannot work across the charge range: at high
           charge even a perfect landing exceeds the clean threshold. */
        const centre = 1 - Math.min(1, Math.abs(dL)/TILE);
        const absorb = HJ_CH.absMin + HJ_CH.absGrad*(1 - centre);
        const impact = Math.abs(this.hjAir.vz);
        const clean = this.hjPassed >= ch.hydS.length && onRamp
                   && !this.hjAir.clipped && impact*HJ_JUMP.slam*absorb < 0.6;
        this.hjResult = this.hjAir.clipped ? "BURST A HYDRANT"
                      : clean   ? "CLEAN"
                      : dL >= TILE ? "OVERSHOT THE RAMP"
                      : onRamp  ? "ROUGH LANDING" : "CAME UP SHORT";
        if(clean){
          /* a clean landing barely registers — the kick only ever existed
             to discriminate clean from not, and `clean` already does */
          this.tilt += impact*HJ_JUMP.slam*absorb*HJ_CH.cleanDamp
                     * (Math.random() < 0.5 ? 1 : -1);
          this.hjClear();
        } else {
          /* POSE is direction: anything that is not an overshoot puts him
             down nose-first — short, botched on the ramp, or clipping the
             last hydrant. Only sailing past goes over the side. */
          this.hjFace = !(dL >= TILE);
          if(this.hjFace){
            this.hjTipT = 0; this.hjTipPitch0 = this.pitch;
            this.state = "tipped";
          } else {
            const dir = Math.abs(this.tilt) > 0.02 ? Math.sign(this.tilt)
                                                   : (Math.random() < 0.5 ? 1 : -1);
            this.tilt += dir * 1.6;      // over the side
            this.hjTipT = 0;
          }
          /* SKID: decided by what is UNDER him, not by which failure it
             was. Ramp under him (or past it) and he slides; short on the
             flat, or into cast iron, and he stops. */
          /* SKID ON A NEAR MISS. The rule was "is there ramp under him",
             which never fired in practice: the clean window and the ramp
             are the same size, so you either land clean or miss the ramp
             entirely — ROUGH measured 0% of the charge range.
             The real near miss is coming up SHORT after clearing every
             hydrant: you made the jump, you just did not carry to the
             ramp. That slides. A short that clipped a hydrant, or never
             got past them, has already hit something and stops dead. */
          const clearedAll = this.hjPassed >= ch.hydS.length && !this.hjAir.clipped;
          this.hjSkidV = (onRamp || dL >= TILE || clearedAll) ? this.speed : 0;
        }
        this.hjAir = null;
        /* KEEP the locked charge. Zeroing it here made speed fall to
           speedFor(0) = 0.030 on the very frame he touched down — a
           0.14 -> 0.03 snap that read as hitting a wall. The lab holds
           the charge through the roll-out and only clears it on reset,
           so he lands carrying his speed and coasts. */
        this.hjRolling = true;
        if(clean){
          /* a clean run rolls straight on to the next jump */
          this.hjPendingReset = 1500;
        } else {
          /* A CRASH ENDS THE ATTEMPT. It used to auto-restart at the same
             jump, which meant a bad run just looped forever with no
             consequence and no way to stop and take stock. The level is
             banked, and the player chooses: go again, or leave. */
          this.hjSaveProgress();
          this.hjPendingReset = 0;
          setTimeout(() => { if(this.mode === "challenge") hjShowCrash(this); }, 1400);
        }
      }
    }
    this.hjPrevS = this.botS;
  }

  /* ---------- BUILD LEVEL n ----------
     n hydrants, catch ramp moved out to match — the lab's geometry, in
     route units. Lab: launch at 4.5 tile-pairs, landing at
     6.75 + (n-1)*gap, so reach_n = (2.25 + (n-1)*gap) tile-pairs. */
  /* ---------- THE LAB'S KICKER, IN THE GAME ----------
     The game's "slab" hazard is a CROSS-SLOPE trip heave: lifted along
     one SIDE edge, meant to catch a wheel. The lab's kicker is a
     TRAVEL-AXIS wedge: flush at the near edge, lifted at the far edge,
     so you ride UP it and launch off the lip. Using the game's slab for
     the ramp was wrong — it is a completely different shape. This is the
     lab's geometry and art, re-expressed in route/world space. */
  hjWedgeTop(hz, da){
    const v = (hz.hjDir*da + TILE) / (2*TILE);        // 0 flush, 1 raised
    return hz.lift * Phaser.Math.Clamp(v, 0, 1);
  }
  /* extra ground height from the course wedges — this is what makes the
     robot actually climb the ramp instead of clipping through it */
  hjSlabZ(s){
    if(this.mode !== "challenge" || !this.route) return 0;
    for(const hz of this.route.hazards){
      if(hz.hjRole !== "kicker" && hz.hjRole !== "catch") continue;
      const da = s - hz.s;
      if(Math.abs(da) < TILE) return this.hjWedgeTop(hz, da);
    }
    return 0;
  }
  hjDrawWedge(hz){
    const g = this.gWorld || this.g;
    const rng = mulberry32(Math.round(hz.s)*7919);
    const c = this.posAt(hz.s), hdg = this.headingAt(hz.s);
    const ax = Math.cos(hdg), ay = Math.sin(hdg);          // along
    const rx = -Math.sin(hdg), ry = Math.cos(hdg);         // cross
    const off = laneOffset(hz.row);          // the game's own lane geometry
    const W = (a, cc, z) => this.W(c.x + ax*a + rx*(cc+off),
                                   c.y + ay*a + ry*(cc+off), z);
    const d = hz.hjDir, L = hz.lift;
    const aUp = d*TILE, aFl = -d*TILE;
    const Z = a => this.hjWedgeTop(hz, a);
    /* soil in the opened joint at the raised end */
    this.quadOn(g, [ W(aUp-d*10,-TILE,0), W(aUp-d*10,TILE,0),
                     W(aUp+d*4,TILE+4,0), W(aUp+d*4,-TILE-4,0) ], HJ_SLABC.gap, 0.55);
    /* exposed concrete at the side joints and the end wall */
    for(const jc of [-TILE, TILE])
      this.quadOn(g, [ W(aFl,jc,0), W(aUp,jc,Z(aUp)), W(aUp,jc,0) ], HJ_SLABC.topDk, 0.9);
    const endWall = [ W(aUp,-TILE,Z(aUp)), W(aUp,TILE,Z(aUp)), W(aUp,TILE,0), W(aUp,-TILE,0) ];
    this.quadOn(g, endWall, HJ_SLABC.topDk);
    this.edgeOn(g, endWall, HJ_SLABC.gap, 1.2);
    /* the culprit: a palm root shouldering the end up */
    if(hz.root){
      for(let i=0;i<6;i++){
        const t0=i/6, t1=(i+1)/6;
        const c0=-TILE+2*TILE*t0, c1=-TILE+2*TILE*t1;
        const bump=2.2+Math.sin(t0*Math.PI)*2.2+(rng()-0.5)*1.2;
        const pts=[ W(aUp+d*2,c0,0), W(aUp+d*2,c1,0), W(aUp+d*7,c1,bump), W(aUp+d*7,c0,bump) ];
        this.quadOn(g, pts, i%2?HJ_SLABC.rootA:HJ_SLABC.rootB);
        this.edgeOn(g, pts, HJ_SLABC.rootB, 1);
      }
    }
    /* the top wedge — the face you actually ride */
    const top=[ W(aFl,-TILE,Z(aFl)), W(aFl,TILE,Z(aFl)), W(aUp,TILE,Z(aUp)), W(aUp,-TILE,Z(aUp)) ];
    this.quadOn(g, top, HJ_SLABC.top);
    this.edgeOn(g, top, HJ_SLABC.topDk, 1.5);
  }

  hjBuildCourse(level){
    const ch = this.route && this.route.challenge; if(!ch) return;
    const T = T2;
    ch.hydS = [];
    /* Drop the previous level's pieces AND clear the whole course leg of
       ordinary street furniture. Cones, cracks, bins, dogs and slabs
       spawned along this stretch by the normal route generator were
       sitting in the landing zone — you would clear ten hydrants and
       then touch down on a traffic cone. The run-up is cleared too, so
       nothing can knock him off line before the ramp. */
    const clearFrom = ch.kickerS - HJ_GEOM.runup - T2, clearTo = ch.catchS + 2*T2;
    this.route.hazards = this.route.hazards.filter(h =>
      !h.hjRole && !(h.s >= clearFrom && h.s <= clearTo && h.row === ch.lane));
    this.route.props = (this.route.props || []).filter(pr =>
      !(pr.s >= clearFrom && pr.s <= clearTo && (pr.row === ch.lane || pr.row === undefined)));
    const facing = f => f;
    const lipS = ch.kickerS + TILE;
    ch.catchS = Math.round(lipS + (2.25 + (level-1)*HJ_CH.gap) * T);

    this.route.hazards.push({ type:"slab", s: ch.kickerS, row: ch.lane, lift: 12,
      side: 1, root: true, f: ch.f, hit:false, lipHit:false,
      hjRole:"kicker", hjDir: 1 });     // hjDir +1 = rises along travel
    /* hydrants inset at BOTH ends — butting the first against the lip
       makes the level unwinnable, the arc is still climbing there */
    const a = lipS + T*0.55, bnd = ch.catchS - T*0.55;
    for(let i = 0; i < level; i++){
      const hs = Math.round(a + (i + 0.5)*(bnd - a)/level);
      ch.hydS.push(hs);
      this.route.hazards.push({ type:"hydrant", s: hs, row: ch.lane, f: ch.f,
        hit:false, burst:false, burstT: undefined, pudDir: 0,
        hjRole:"hydrant", hjIndex:i });
    }
    this.route.hazards.push({ type:"slab", s: ch.catchS, row: ch.lane, lift: 10,
      side: -1, root: false, f: ch.f, hit:false, lipHit:false,
      hjRole:"catch", hjDir: -1 });     // hjDir -1 = falls along travel
    this._hjBandLvl = -1;                    // force the meter to re-solve
  }

  /* back to the top of the run-up for another attempt */
  /* the challenge's own crash handling — the delivery fail overlay
     ("The pavement won") belongs to a delivery that went wrong, not to
     a missed jump, and its Retry reloaded the daily route. */
  hjOwnsTip(){ return this.mode === "challenge"; }

  /* ---------- ATTRACT MODE ----------
     Same shape as hjOwnsTip above: a mode flag that takes ownership of
     the run's ENDINGS so the sim underneath can stay exactly as it is.

     There is no attract "driver". The player never steers -- see the
     note above DIRV -- so Tipsey already follows the route line and
     auto-turns through the fillet arcs on his own. Holding the throttle
     down is the entire input. Writing a steering AI here would be
     re-implementing the thing that already moves the robot.

     What attract DOES have to own is what happens when a run ends,
     because every ending path writes: the tip path POSTs api/tipsy/fail
     through reportFail, and the win path pays out through showWin.
     Neither may fire for a robot nobody is driving, so all three exits
     (tipped / canceled / won) are gated and routed to attractRecycle
     instead. Missing one would quietly corrupt the leaderboard with
     runs the player never made. */
  attractOwnsTip(){ return this.attract === true; }

  /* Same shape a third time: the slalom takes ownership of the ENDINGS
     while it is attached. Without this a mid-run tip fell through to
     the delivery branch, where showFail was muzzled by tpSlalomOn — so
     the crash had NO ending at all (a dead robot, no card, no retry,
     just the Quit pill) while reportFail still FIRED: every slalom
     crash was quietly POSTing api/tipsy/fail into the daily route's
     fail feed and comment-draft machinery for a run that was never a
     delivery. */
  slOwnsTip(){ return !!this._slAPI; }

  attractStart(){
    if(!ATTRACT_ON) return;
    if(this.mode === "challenge") return;   // the challenge owns its own map screen
    if(this.attract) return;
    this.attract = true;
    document.body.classList.add("attract");
    /* Widest of the three stops, so the city reads at splash size --
       but assigned directly rather than through zoomSet(), which would
       write tipsy.zoomDepth and silently overwrite the player's own
       saved camera preference with a value they never chose. */
    this.K = ZOOM_K[ZOOM_K.length - 1];
    this.attractWantRow = null;
    this.attractStuckMs = 0;
    if(ATTRACT_BARE){
      document.body.classList.add("attractBare");
      /* Tell the embedder the world is actually moving. The splash keeps
         its own static city and robot painted until this lands, so a
         blocked iframe, a slow feed, or a thrown error leaves the reader
         looking at exactly the splash that shipped before this feature
         rather than an empty hole. Signal on the first attract frame,
         not on iframe load, because "the document loaded" and "the game
         is running" are not the same claim. */
      /* Post to WINDOW, not parent.

         `parent` was written for the abandoned iframe design, where the
         host really was the parent frame. In the same-document design
         the listener lives in THIS window, and parent only equals window
         when the page is top-level. It is not: Devvit frames
         splash.html, so `parent` is Devvit's host frame and the signal
         was being delivered to the platform instead of to the code
         waiting for it. The handshake could never have landed on Reddit.

         This is also why it passed every local test -- a file opened
         directly IS top-level, so parent === window and the bug is
         invisible. It only showed up once the page was viewed inside
         another frame.

         Both targets are posted: window is the real one, parent is kept
         for a genuine iframe embedder and is a harmless no-op when it
         is the same object. */
      /* Direct same-document call FIRST: on the native Reddit app the
         engine boots clean (diag strip: phaser up, gl yes, raf ticking,
         no errors) yet the postMessage below never reaches the listener
         in this same window -- native webviews inject JS bridges and
         wrapping window.postMessage is the standard way those bridges
         are built, which swallows the message with no error. Poster and
         listener have shared one document since the iframe design was
         removed, so no messaging API is needed at all: a plain function
         call cannot be intercepted by anything. postMessage stays below
         as a fallback for a genuine framed embedder. */
      try { if (typeof window.TIPSEY_ON_ATTRACT_READY === "function") window.TIPSEY_ON_ATTRACT_READY(); } catch(e){}
      try { window.postMessage({ tipsey: "attract-ready" }, "*"); } catch(e){}
      try {
        if (parent && parent !== window) parent.postMessage({ tipsey: "attract-ready" }, "*");
      } catch(e){}
    }
    this.state = "play";
    this.throttle = 1;
  }

  attractStop(){
    if(!this.attract) return;
    this.attract = false;
    /* Clear the pending recycle FIRST. A timer that survives into a
       real run reloads the route out from under a live player. */
    if(this.attractTimer){ clearTimeout(this.attractTimer); this.attractTimer = null; }
    document.body.classList.remove("attract");
    this.K = zoomK();                       // back to the player's own stop
    this.throttle = 0;
  }

  /* An attract run that ends is not a loss, it is a cut: reload and
     drive it again. The SAME day, specifically. loadRoute() rewrites
     #orderCard and #sheetStatus as it goes, so looping a random day
     would leave the splash advertising a neighborhood, a shop and a
     payout that GO does not then deliver. */
  attractRecycle(ms){
    if(!this.attract || this.attractTimer) return;
    this.attractTimer = setTimeout(() => {
      this.attractTimer = null;
      if(!this.attract) return;             // GO landed during the beat
      this.loadRoute(this.route ? this.route.dateStr : clientTodayUTC());
      this.state = "play";
      this.throttle = 1;
    }, ms || ATTRACT_RECYCLE_MS);
  }

  /* ---------- the driver ----------
     Runs once per frame in place of the old "throttle = 1 forever".
     Four jobs, checked in an order chosen so a later one can never talk
     an earlier one out of its decision:

       1. the door   -- once close, nothing else matters
       2. corners    -- a speed ceiling, set before lanes can raise it
       3. lanes      -- do not be somewhere with something in it
       4. commit     -- turn the resulting speed target into a throttle

     The door comes first and returns, because the approach is the one
     stretch where a hop is actively harmful: a lane change costs
     stability, and |tilt| < 0.5 is half the win gate. Dodging something
     20 units from the door is how a finished route becomes a topple on
     the doorstep. */
  attractDrive(){
    if(!this.attract || this.state !== "play" || !this.route) return;
    const s = this.botS;

    /* Stuck accounting first: the lane decision needs to know how long
       we have been pinned before it can decide whether to override its
       own safety veto. Accounted here, acted on below. */
    if(this.isBlocked || (this.stuckAmt || 0) > 0.5) this.attractStuckMs += 16;
    else this.attractStuckMs = 0;
    const pinned = this.attractStuckMs > AD.pinGrace;

    /* --- 1. the door --- */
    const remain = this.route.doorS - s;
    /* v^2/2a with the brake's own 0.00075/ms. Friction only ever helps,
       so this over-reserves slightly, which is the safe direction. */
    const brakeDist = (this.speed * this.speed) / 0.0015;
    if(remain < 42 || remain - AD.doorStop <= brakeDist + 6){
      this.throttle = -1;
      return;
    }

    const onArc   = this.segAt(s).type === "arc";
    /* No lane changes into or during a turn. hop() refuses mid-arc, and
       the maneuver block resolves an in-flight hop the instant an arc
       starts by snapping laneOff to its target -- so a hop begun just
       before a corner does not glide, it teleports. */
    const arcSoon = onArc || this.segAt(s + 120).type === "arc";
    let target = AD.cruise;

    /* --- 2. corners --- */
    let cornerAhead = onArc;
    for(let d = 40; d <= AD.arcScan && !cornerAhead; d += 40)
      if(this.segAt(s + d).type === "arc") cornerAhead = true;
    if(cornerAhead) target = Math.min(target, AD.arcSpeed);

    /* --- 3. lanes --- */
    const here = this.attractLaneClear(this.botRow, s);

    /* A street crossing is not a hazard to route around. It is a
       MANDATORY LANE. crossingGroundAt gives CROSSING_RAMP_ROW a real
       ramp -- slope down, flat crossing, slope back up -- and gives
       every other row a curb drop plus wallS, a hard wall at the far
       kerb. Approach a crossing in any other row and the robot drives
       into that wall and stops dead.

       That is exactly the jam this driver shipped with: sidewalkbegin
       51 ahead in row 1, robot sitting in rows 2/3, all four lanes
       reporting clear, rocking between rows forever. Every lane WAS
       clear -- of hazards. The thing stopping him was the kerb, and the
       driver had crossings on its ignore list. Avoiding them was
       precisely backwards; they are the one place he is not free to
       choose a lane at all. */
    const cross = this.attractCrossingAhead(s);
    let want = cross ? CROSSING_RAMP_ROW : this.attractWantRow;
    /* Commit to a destination lane rather than re-deciding every frame.
       laneCost is measured from the CURRENT row, so the instant he
       arrives anywhere, the lane he just left looks cheap again and he
       hops straight back. Measured on the 2026-08-05 route: 780 hops in
       400 seconds, tilt riding at -0.68 the whole way. Hold the target
       until it is reached, or until it stops being clear. */
    if(cross){
      /* the crossing outranks the scorer: hold the ramp lane and take
         it at a measured pace */
      this.attractWantRow = want;
      target = Math.min(target, AD.crossSpeed);
    } else if(want === null || want === undefined || want === this.botRow ||
       this.attractLaneClear(want, s) < AD.recommit){
      want = this.botRow;
      let bestScore = here;
      /* Score ALL FOUR lanes. Adjacent-only comparison deadlocks, and
         the 2026-08-05 route found the exact shape: pinned in row 0
         behind a hydrant 26 ahead, row 1 blocked, rows 2 and 3 clear at
         35 and 103. "Is my neighbour better than me" is structurally
         incapable of seeing past row 1. */
      for(let r = 0; r < 4; r++){
        if(r === this.botRow) continue;
        const score = this.attractLaneClear(r, s) - Math.abs(r - this.botRow) * AD.laneCost;
        if(score > bestScore + AD.gain){ bestScore = score; want = r; }
      }
      this.attractWantRow = want;
    }

    let step = want === this.botRow ? 0 : Math.sign(want - this.botRow);
    /* Pinned with nowhere the scorer likes: take any neighbour at all.
       Leaning on an obstruction is the one thing a player never does. */
    if(pinned && step === 0){
      for(const cand of [this.botRow + 1, this.botRow - 1]){
        if(cand < 0 || cand > 3) continue;
        step = Math.sign(cand - this.botRow);
        break;
      }
    }
    /* Never step INTO something already level with us -- unless pinned,
       in which case this veto is the thing doing the pinning. AD.behind
       is an honest guess at the robot's footprint, not a figure derived
       from the per-type contact windows (those are a world-space near()
       test, not one along-track number), so it is conservative and does
       veto hops that would have been clean. Once pinned, a certain
       failure beats a risk, so it yields. */
    if(step !== 0 && !pinned && this.attractLaneOccupied(this.botRow + step, s)) step = 0;

    if(step !== 0){
      /* THE skill this game is actually about. hopKick is
         0.16 + speed*4.5, and TILT_SENS halves it into tilt, so a lane
         change at full pace costs 0.586 tilt and two in a row put you
         over the 1.0 tip line. A good driver slows down BEFORE changing
         lanes; a bad one changes lanes and then finds out why that was
         expensive. So a wanted hop becomes a SPEED TARGET first, and
         only becomes an actual hop once the robot is calm enough to
         afford it. */
      target = Math.min(target, AD.hopSpeed);
      const ready = this.speed <= AD.hopSpeed + AD.eps &&
                    Math.abs(this.tilt) < AD.hopTilt &&
                    !this.hopAnim && !arcSoon &&
                    (this.time.now - this.attractHopAt) > AD.hopCool;
      /* Pinned overrides the patience: speed is already zero, the tilt
         cost of a hop from a standstill is the 0.16 floor, and waiting
         for a cooldown while stuck achieves nothing. */
      if(ready || (pinned && !this.hopAnim && !arcSoon)){
        /* through hop(), not by assigning botRow: hop owns the arc
           refusal, the 0..3 clamp, the glide animation and the stability
           cost. Setting botRow directly would skip all four and give the
           attract robot physics the player does not have. */
        this.hop(this.rowScreenFlip(step));
        this.attractHopAt = this.time.now;
      }
    } else if(here < 120){
      /* nowhere better to be: meet it slowly rather than at pace */
      target = Math.min(target, AD.penned);
    }

    if(Math.abs(this.tilt) > AD.tiltBrake) target = Math.min(target, 0.08);

    /* Last resort. If even the override cannot free him there is no move
       left, and a splash sitting on a motionless robot is worse than a
       cut. Recycling is honest: the run is over, it just did not end in
       a way the sim has a state for. */
    if(this.attractStuckMs > AD.stuckBail){
      this.attractStuckMs = 0; this.attractWantRow = null;
      this.attractRecycle();
      return;
    }

    /* --- 4. commit --- */
    /* deadband, or he chatters between -1 and 1 every frame at the
       target and the ride reads as a stutter. */
    if(this.speed > target + AD.eps)      this.throttle = -1;
    else if(this.speed < target - AD.eps) this.throttle = 1;
    else                                  this.throttle = 0;
  }

  /* The straight street crossing that currently owns the lane, or null.

     Turn crossings are excluded on purpose: they coincide with arc
     segments, hop() refuses lane changes mid-arc by design, and
     crossingGroundAt hands them off to turnCrossingGroundAt's
     world-space model instead of the route-s ramp geometry. Nothing the
     driver can usefully do about those.

     The window opens AD.crossLook before the rear edge of the
     descending ramp tile and closes at the rear edge of the ascending
     one, so the lane is claimed early enough to reach it and held until
     the robot is fully back up on the walk. */
  attractCrossingAhead(s){
    for(const cx of this.route.crossings){
      if(cx.kind === "turn") continue;
      const enter = cx.sA - 2*T2;
      const exit  = cx.sB + 2*T2;
      if(s >= enter - AD.crossLook && s <= exit) return { cx, enter, exit };
    }
    return null;
  }

  /* FORWARD clearance: how far this lane runs before the next thing
     worth avoiding. Answers exactly one question -- "how good is this
     lane to be in" -- and nothing else.

     It used to also fold in hazards BEHIND the robot, clamped to 0, so
     one number could double as a hop-safety check. That is the
     one-constant-one-question rule broken, and it cost a whole route: a
     walker 25 units behind reported row 1 as having ZERO clearance
     ahead, so the driver read a wide-open escape lane as a wall and sat
     pinned for 400 seconds. Two questions, two functions. */
  attractLaneClear(row, from){
    let nearest = AD.scan;
    for(const hz of this.route.hazards){
      if(hz.row !== row || !this.attractAvoids(hz)) continue;
      const d = hz.s - from;
      if(d < 0 || d > AD.scan) continue;
      nearest = Math.min(nearest, d);
    }
    return nearest;
  }

  /* OCCUPANCY: is something level with the robot right now in this lane.
     The robot has length, so hopping into a hazard beside the back
     wheels is a collision even though it is technically behind. This is
     a hop-legality test, never a lane-quality score. */
  attractLaneOccupied(row, from){
    for(const hz of this.route.hazards){
      if(hz.row !== row || !this.attractAvoids(hz)) continue;
      const d = hz.s - from;
      if(d > -AD.behind && d < AD.behind) return true;
    }
    return false;
  }

  /* What counts as worth avoiding. Deliberately a denylist over an
     allowlist: new hazard types get added to this game regularly, and
     the safe default for an unknown one is "drive around it". */
  attractAvoids(hz){
    if(hz.row === undefined) return false;   // road cracks carry roadOffset, not a lane
    switch(hz.type){
      /* No collision at all -- the hazard loop skips these outright, so
         they are not obstacles. They are not IGNORED either: the ramp
         they mark is handled as a mandatory lane by
         attractCrossingAhead, which reads route.crossings directly
         rather than inferring the span from these markers. */
      case "sidewalkend": case "sidewalkbegin": case "grade": return false;
      /* the scatter IS the reward. Driving through the flock is the
         nicest thing that happens on a route; steering around it would
         be a worse splash, not a safer one. */
      case "pigeons": return false;
      default: return true;
    }
  }

  hjResetRun(){
    const ch = this.route && this.route.challenge; if(!ch) return;
    this.hjBuildCourse(this.hjLevel);
    this.botS = Math.max(0, ch.kickerS - HJ_GEOM.runup);
    this.hjPrevS = this.botS;
    this.hjAir = null; this.hjLocked = null;
    this.hjCharge = 0; this.hjChargeSm = 0; this.hjPassed = 0;
    this.hjAutoAcc = 0;
    this.hjRolling = false; this.hjEnded = false;
    this.hjFace = false; this.hjTipT = 0; this.hjSkidV = 0;
    this.pitch = 0; this.pitchPivot = 0;
    this.speed = HJ_CH.sp0;
    this.tilt = 0; this.roll = 0; this.state = "play";
    this.tipT = 0; this.damage = 0;
    const sp = this.posAt(this.botS);
    const hdg = this.headingAt(this.botS);
    this.botX = sp.x + (-Math.sin(hdg))*this.laneOff;
    this.botY = sp.y + Math.cos(hdg)*this.laneOff;
    this.camX = this.botX; this.camY = this.botY;
    this.drawAngle = hdg;
  }

  /* big centred banner over the challenge. This lived on the old
     ChallengeScene and was lost when that class was deleted — hjClear()
     called it, so the game THREW at the exact moment a skin unlocked. */
  /* ---------- WHITE STARS ON THE BLUE BAND ----------
     Drawn in each side face's own (u, z) space and projected through
     P(), so they lie flat on the band and rotate with the robot rather
     than sliding across him. Uses the same backface test as drawBox, so
     a star never appears on a face the camera cannot see. */
  /* ---------- HULL EMBLEM ----------
     Was drawStripeStars(), which only ever knew about the Daredevil's stars.
     Porch Pirate needed a second mark on the same hook, so the method is now
     a shape switch. The hook itself is the valuable part: drawRobot calls this
     at exactly the right point in the draw order -- after the body and stripe,
     before the lid and visor -- so an emblem needs no change to drawRobot. */
  drawHullEmblem(bobZ){
    if(SKIN.emblem === "skull") return this.drawSkullEmblem(bobZ);
    return this.drawStripeStars(bobZ);
  }

  /* SKULL AND CROSSBONES on the two hull SIDE faces.
     Same face-normal backface test drawBox uses, so it can never paint onto a
     face pointing away from the camera at any heading.

     SIDES ONLY. Front (+x) carries the visor and the headlight bar. Back (-x)
     is dropped by choice -- a mark on every panel but one reads as wallpaper
     rather than as a badge, and the two long sides are the faces the iso
     camera presents at every heading anyway, so this costs nothing at f0-f3.

     The tangent on each face is chosen so tangent x normal points up. That is
     what keeps the skull from rendering MIRRORED on the face whose normal runs
     negative -- exactly the class of bug the four-heading gate exists for. */
  drawSkullEmblem(bobZ){
    const g  = this.g;
    const hy = BODY.hy + 0.8;
    /* zc/R are set by CLEARANCE, not by taste. The body spans z 14..54 and the
       stripe band occupies 20..27. The crossbones are the lowest thing here --
       their tips fall to zc - R*1.9*sin(0.62) -- so at the obvious values
       (zc 33, R 6.4) they reach 17.6 and cut straight through the stripe. On
       this skin the stripe is bone-coloured, so the emblem would have
       dissolved into it. These values put the tips at 29.1 and the cranium top
       at 43.6: clear of the stripe below, clear of the lid seam above. */
    const zc = 37 + (bobZ || 0);
    const R  = 5.4;
    const col  = SKIN.emblemColor || 0xe8e2d0;
    const dark = SKIN.emblemDark  || 0x101014;

    const faces = [
      { n:{x:0,y: 1,z:0}, at:(s,z)=>[ -s,  hy, z] },
      { n:{x:0,y:-1,z:0}, at:(s,z)=>[  s, -hy, z] }
    ];

    for(const fc of faces){
      const w = this.R(fc.n.x, fc.n.y, fc.n.z);
      if((w.x + w.y + w.z) <= 0) continue;          // backface, same rule as drawBox
      const P    = (s,z) => { const q = fc.at(s,z); return this.P(q[0], q[1], q[2]); };
      const poly = pts => pts.map(p => P(p[0], p[1]));
      const disc = (cs, cz, r, n) => {
        const o = [];
        for(let k=0;k<n;k++){ const a = k/n*Math.PI*2;
          o.push(P(cs + Math.cos(a)*r, cz + Math.sin(a)*r)); }
        return o;
      };

      /* crossbones first -- they sit BEHIND the skull */
      for(const sgn of [1,-1]){
        const ang = sgn*0.62, ca = Math.cos(ang), sa = Math.sin(ang);
        const L = R*1.9, Wd = R*0.22, bz = zc - R*0.5;
        const bar = [[-L,-Wd],[L,-Wd],[L,Wd],[-L,Wd]]
          .map(([a,b]) => [a*ca - b*sa, bz + a*sa + b*ca]);
        this.quadOn(g, poly(bar), col);
        /* the knobbed ends that make a bone read as a bone */
        for(const e of [-1,1])
          for(const o of [-1,1])
            this.quadOn(g, disc((e*L - o*Wd*0.9)*ca - (o*Wd*1.5)*sa,
                                bz + (e*L - o*Wd*0.9)*sa + (o*Wd*1.5)*ca,
                                Wd*1.6, 7), col);
      }

      /* cranium + jaw */
      this.quadOn(g, disc(0, zc + R*0.30, R*0.92, 14), col);
      this.quadOn(g, poly([[-R*0.52, zc - R*0.72], [R*0.52, zc - R*0.72],
                           [ R*0.74, zc + R*0.28], [-R*0.74, zc + R*0.28]]), col);

      /* sockets + nasal cavity */
      for(const e of [-1,1])
        this.quadOn(g, disc(e*R*0.40, zc + R*0.40, R*0.29, 9), dark);
      this.quadOn(g, poly([[0, zc - R*0.02], [R*0.16, zc + R*0.20],
                           [-R*0.16, zc + R*0.20]]), dark);
      /* teeth: two gaps cut into the jaw */
      for(const e of [-1,1])
        this.quadOn(g, poly([[e*R*0.20 - R*0.05, zc - R*0.70],
                             [e*R*0.20 + R*0.05, zc - R*0.70],
                             [e*R*0.20 + R*0.05, zc - R*0.28],
                             [e*R*0.20 - R*0.05, zc - R*0.28]]), dark);
    }
  }

  drawStripeStars(bobZ){
    const g = this.g;
    const hx = BODY.hx + 0.7, hy = BODY.hy + 0.7;
    const zc = (STRIPE.z0 + STRIPE.z1)/2 + (bobZ||0), rz = (STRIPE.z1 - STRIPE.z0)*0.40;
    const faces = [
      { n:{x: 1,y:0,z:0}, at:(u,z)=>[ hx,  u*hy, z], span:hy },
      { n:{x:-1,y:0,z:0}, at:(u,z)=>[-hx,  u*hy, z], span:hy },
      { n:{x:0,y: 1,z:0}, at:(u,z)=>[ u*hx,  hy, z], span:hx },
      { n:{x:0,y:-1,z:0}, at:(u,z)=>[ u*hx, -hy, z], span:hx }
    ];
    for(const fc of faces){
      const w = this.R(fc.n.x, fc.n.y, fc.n.z);
      if((w.x + w.y + w.z) <= 0) continue;          // backface, same rule as drawBox
      for(let i = 0; i < 3; i++){
        const u = -0.58 + (i/2)*1.16;
        const pts = [];
        for(let k = 0; k < 10; k++){
          const a = -Math.PI/2 + k*Math.PI/5;
          const rr = (k % 2 === 0) ? 1 : 0.42;      // outer / inner point
          const q = fc.at(u + Math.cos(a)*rr*(rz/fc.span), zc + Math.sin(a)*rr*rz);
          pts.push(this.P(q[0], q[1], q[2]));
        }
        this.quadOn(g, pts, SKIN.stars);
      }
    }
  }

  announce(title, sub){
    const el = document.getElementById("hjUnlock");
    if(!el) return;
    el.innerHTML = title + "<small>" + sub + "</small>";
    el.classList.add("show");
    clearTimeout(this._annT);
    this._annT = setTimeout(() => el.classList.remove("show"), 2600);
  }

  hjSaveProgress(){
    tpProfile.hjLevel = this.hjLevel;
    tpProfile.hjBest  = Math.max(tpProfile.hjBest || 0, this.hjBest || 0);
    tpSaveProfile();
    /* the one reporter for jump-hydrant -- see tpSubmitMission */
    if(tpProfile.hjBest > 0) tpSubmitMission("jump-hydrant", tpProfile.hjBest);
  }

  hjClear(){
    this.hjBest = Math.max(this.hjBest, this.hjLevel);
    /* ONE reward, at the END. The Chief used to land at jump 8 with the
       Daredevil at 10, which meant the mission handed out a skin while
       two jumps were still ahead and then handed out a second one for
       finishing. The Chief is now the prize for the whole thing --
       clear all ten or wear nothing -- and the Daredevil is reserved
       for a separate jump challenge (see the stunt-jump trophy).
       Anyone who already owns either skin keeps it; the `owned` guard
       makes this purely additive for existing profiles. */
    if(this.hjLevel >= HJ_CHIEF_AT){
      tpCompleteMission("jump-hydrant");
      /* EARNED, not worn. The skin used to equip itself here the instant
         the tenth jump landed, which spent the reward before the player
         ever saw it: the Trophy Case then read the skin as already owned
         and hid its Claim button, so the moment of collecting the prize
         never happened. The celebration stays; going and taking it is
         now the player's move. */
      if(!tpProfile.owned.has("fire-chief")){
        this.announce("\u{1F692} FIRE CHIEF UNLOCKED", "ALL TEN CLEARED \u00b7 CLAIM IT IN YOUR TROPHY CASE");
      }
    }
    this.hjLevel = Math.min(HJ_CH.maxLevel, this.hjLevel + 1);
    this.hjSaveProgress();          // bank every cleared jump
  }

  loadChallenge(){
    this.mode = "challenge";
    this.hjCharge = 0; this.hjChargeSm = 0; this.hjAir = null;
    this.hjLocked = null; this.hjLevel = 1; this.hjBest = 0;
    this.hjSrcLast = {}; this.hjResult = ""; this.hjPassed = 0;
    /* classic:true — rebuild against the pre-coast-worldgen lattice the
       course was actually tuned on (2026-07-30), immune to the swallow
       pass/terrain that shipped 2026-08-06..08. Without this the course
       still loads the right DATE but not the same ground; see the
       hydrant-drift note by HJ_SEED_DATE above. */
    this.loadRoute(HJ_SEED_DATE, { hoodIndex: HJ_ADDRESS.hoodIndex, challenge: true, classic: true });
    /* same card slot the daily uses, so the map screen reads identically */
    /* HEADLINE IS THE MISSION NAME (2026-08-10, Sir's call, reverted the
       same day it was changed): this led with HJ_ADDRESS.hood ("The
       Flats — hydrant challenge at..."), which was made to match the
       daily route's own "place leads" convention. Backwards -- side
       missions lead with their own NAME, the way Cone Slalom's card
       always did ("Cone Slalom Challenge — ..."); the daily route is
       the one case that's place-first, since it doesn't have a name of
       its own the way a mission does. */
    document.getElementById("orderCard").innerHTML =
      `<div class="tag" style="margin-bottom:4px">SIDE MISSION</div>`
      + `<b>Hydrant Challenge</b> — ten jumps down ${HJ_ADDRESS.street}, tap to charge and clear them all`;
    document.getElementById("sheetStatus").textContent = `Ten jumps · clear all ten for the Fire Chief`;
    resizeRouteMap();
    drawRouteMap(this.route);
    /* the delivery game waits on a GO press to leave "idle"; the
       challenge is already rolling when you arrive on the street. */
    /* resume where they left off, not from jump 1 */
    this.hjLevel = Phaser.Math.Clamp(tpProfile.hjLevel || 1, 1, HJ_CH.maxLevel);
    this.hjBest  = tpProfile.hjBest || 0;
    this.hjResult = "";
    this.hjBuildCourse(this.hjLevel);
    this.state = "idle";        // wait on GO, like the daily
  }

  loadRoute(dateStr, opts){
    /* Devvit bridge — no-op if not embedded (see shim near top of file).
       Skipped for the challenge: it loads a FIXED date (HJ_SEED_DATE), so
       asking the server for that day's best would cache a stale entry
       under a date the player may later play for real. */
    if(!(opts && opts.challenge)) requestDailyBest(dateStr);
    this.route = generateRoute(dateStr, opts);
    for(const hz of this.route.hazards) hz.hit = false;
    this.d = this.route.pal;
    /* no pickup shop in the challenge — clearing these stops the shop
       door, the worker and the bag from being drawn or simulated */
    if(opts && opts.challenge){
      this.route.pickupSpot = null;
      this.route.pickupShopName = null;
      this.route.pickupBlock = null;
    }
    /* the challenge starts you a little way BEFORE the course so you
       drive up to it on the real street, rather than materialising on
       the ramp */
    this.botS = (opts && opts.challenge && this.route.challenge)
      ? Math.max(0, this.route.challenge.kickerS - HJ_GEOM.runup)
      : this.route.pickupS;
    this.botZ = this.groundZ(this.botS);
    this.botRow = 1; this.laneOff = laneOffset(this.botRow);
    const hdg0 = this.headingAt(this.botS);
    if(this.route.pickupSpot){
      /* spawn exactly at the real shop-relative point, not wherever
         the route's own centerline math independently lands — pickupS
         was refined during generation to the closest ON-ROUTE position
         to this spot, so this is consistent with normal route-driven
         movement the instant the robot starts moving, not a one-frame
         override that then jumps. */
      this.botX = this.route.pickupSpot.x;
      this.botY = this.route.pickupSpot.y;
    } else {
      const sp = this.posAt(this.botS);
      this.botX = sp.x + (-Math.sin(hdg0))*this.laneOff;
      this.botY = sp.y + Math.cos(hdg0)*this.laneOff;
    }
    this.hopAnim = null; this.yaw = 0; this.hopYaw = 0; this.hopKick = 0;
    this.drawAngle = hdg0;   // position teleports on route load — rotation teleports with it
    this.slide = null; this.slipYaw = 0;
    this.camX = this.botX; this.camY = this.botY; this.camZ = this.botZ;
    this.speed = 0; this.tilt = 0; this.damage = 0; this.runT = 0;
    this.tipCause = null;
    this.roll = 0; this.tipT = 0; this.tipStartRoll = 0; this.postSpillMs = 0; this.lidAng = 0; this.items = []; this.spilled = false;
    this.wonT = 0; this.wonFrac = 0; this.wonLiftT = 0; this.wonLidClosing = false; this.wonWalkAt = null; this.wonWalk = 0; this.wonOutT = 0; this.wonOutFrac = 0; this.wonMeet = null;
    this.bagOnBoard = false;
    this.slabZ = 0; this.slabRoll = 0;
    this.crossZ = 0; this.crossSlope = 0; this.crossJitter = 0;
    this.cornerLean = 0;
    this.corneringSpeedSmooth = 0;
    this.stuckAmt = 0; this.isBlocked = false;
    this.doorTheta = 0;   // hull door hinge angle — opens once this.state becomes "won"
    this.pickupWalk = 1;  // pickup worker's walk-out amount — 1 = idle, standing a row out
                           // facing the robot's spot; eases to 0 as "go" is pressed (see
                           // drawRobot), mirroring doorTheta's ease but in reverse and
                           // driven by state instead of a hinge angle
    this.doorSwing = 0;   // shop door hinge — opens while the worker's still walking,
                           // closes once he arrives (see drawRobot)
    this.loadDone = false; // true once the loading phase (lid+bag) has finished and the
                            // walk phase can start
    this.walkAt = null;   // timestamp (this.runT-relative) captured when the walk phase
                           // actually begins, after loading finishes
    this.lidHingeFlip = false; // true only during pickup loading — opens the cargo lid
                                // from the opposite edge than the tip/spill crash animation uses
    this.pickupLidClosing = false; // latches true while the lid still owes a close-out on
                                    // that flipped hinge, even after loading itself has ended
    this.state = "idle";
    const modeTag = !IS_DEVVIT_BUILD ? "" : (dateStr === clientTodayUTC()
      ? `<div class="tag" style="margin-bottom:4px">TODAY</div>`
      : `<div class="tag" style="margin-bottom:4px">REPLAY · ${fmtReplayDate(dateStr)}</div>`);
    document.getElementById("orderCard").innerHTML = modeTag + (this.route.pickupShopName
      ? `<b>${this.route.hood.n}</b> — pickup at <b>${this.route.pickupShopName}</b>, deliver to <b>${this.route.address}</b>`
      : `<b>${this.route.hood.n}</b> — deliver to <b>${this.route.address}</b>`);
    document.getElementById("sheetStatus").textContent = `$${this.route.order.value.toFixed(2)} · ${this.route.order.text}`;
    resizeRouteMap();
    drawRouteMap(this.route);
  }

  layout(){
    const w = this.scale.gameSize.width, h = this.scale.gameSize.height;
    this.cx = w/2;
    /* center the view on the middle of the lane band, not the top lane */
    this.cy = h/2 - TILE*0.5*this.K + 10;
  }

  /* ---------- path + terrain (s = distance along the route) ---------- */
  segAt(s){
    const segs = this.route.segs;
    for(const sg of segs) if(s <= sg.s1) return sg;
    return segs[segs.length-1];
  }
  posAt(s){
    const sg = this.segAt(s);
    if(sg.type === "line"){
      const d = DIRV[sg.f], u = Phaser.Math.Clamp(s, sg.s0, sg.s1) - sg.s0;
      return { x: sg.start.x + d.x*u, y: sg.start.y + d.y*u };
    }
    const a = sg.a0 + sg.sign * (Phaser.Math.Clamp(s, sg.s0, sg.s1) - sg.s0) / sg.R;
    return { x: sg.center.x + Math.cos(a)*sg.R, y: sg.center.y + Math.sin(a)*sg.R };
  }
  headingAt(s){
    const sg = this.segAt(s);
    if(sg.type === "line") return sg.hA;
    return sg.hA + sg.sign * (Phaser.Math.Clamp(s, sg.s0, sg.s1) - sg.s0) / sg.R;
  }
  groundZ(s){
    /* flat, always. route.tiles is a VIRTUAL grade profile — consumed
       as slope only (elevAt/groundSlope below feed pitch and hill
       gravity), never as geometry, so the flat-drawn world and every
       z consumer (props, doors, robot, camera) stay in exact
       agreement. See the profile build in generateRoute. */
    return 0;
  }
  elevAt(s){
    const t = this.route.tiles;
    const fx = s / (TILE*2);
    const i = Math.floor(fx);
    if(i < 0) return t[0];
    if(i >= t.length-1) return t[t.length-1];
    return Phaser.Math.Linear(t[i], t[i+1], fx - i);
  }
  groundSlope(s){
    return (this.elevAt(s+16) - this.elevAt(s-16)) / 32;
  }

  /* ---------- projection: yaw, pitch, roll, then facing ---------- */
  T(x, y, z){
    if(this.yaw !== 0){   // small local perturbations only now (hop nose-dip, hazard slip)
      const c = Math.cos(this.yaw), s = Math.sin(this.yaw);
      const x2 = x*c - y*s; y = x*s + y*c; x = x2;
    }
    if(this.pitch !== 0){
      /* pitchPivot is 0 for every normal pitch, reproducing the original
         origin rotation exactly. The face plant sets it to the body's
         front face so he goes over his NOSE and lands on it. */
      const PX = this.pitchPivot || 0;
      const c = Math.cos(this.pitch), s = Math.sin(this.pitch);
      const x0 = x - PX;
      const x2 = x0*c - z*s; z = x0*s + z*c; x = PX + x2;
    }
    if(this.roll !== 0){
      const PIV = this.roll >= 0 ? 22 : -22;               // pivot on the grounded edge
      const y0 = y + PIV, c = Math.cos(this.roll), s = Math.sin(this.roll);
      y = -PIV + y0*c - z*s; z = y0*s + z*c;
    }
    /* heading rotation LAST — points the already-tilted local shape the
       right way on screen, same role the discrete facing-swap used to
       play (also last), just continuous now instead of 90°-snapped. */
    if(this.drawAngle !== 0){
      const c = Math.cos(this.drawAngle), s = Math.sin(this.drawAngle);
      const x2 = x*c - y*s; y = x*s + y*c; x = x2;
    }
    return { x, y, z };
  }
  R(nx, ny, nz){
    if(this.yaw !== 0){
      const cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);
      const nx2 = nx*cy - ny*sy; ny = nx*sy + ny*cy; nx = nx2;
    }
    if(this.pitch !== 0){
      const c = Math.cos(this.pitch), s = Math.sin(this.pitch);
      const x2 = nx*c - nz*s; nz = nx*s + nz*c; nx = x2;
    }
    const c = Math.cos(this.roll), s = Math.sin(this.roll);
    const ny2 = ny*c - nz*s, nz2 = ny*s + nz*c;
    let rx = nx, ry = ny2;
    if(this.drawAngle !== 0){
      const cy = Math.cos(this.drawAngle), sy = Math.sin(this.drawAngle);
      const rx2 = rx*cy - ry*sy; ry = rx*sy + ry*cy; rx = rx2;
    }
    return { x:rx, y:ry, z:nz2 };
  }
  /* world-space projection (camera tracks the bot on both iso axes + height) */
  W(x, y, z){
    const xr = x - this.camX, yr = y - this.camY;
    return { x:(xr - yr)*this.K + this.cx,
             y:((xr + yr)*0.5 - (z - this.camZ))*this.K + this.cy };
  }
  /* robot-space projection: model -> robot pose -> world */
  P(x, y, z){
    const q = this.T(x, y, z);
    return this.W(q.x + this.botX, q.y + this.botY, q.z + this.botZ);
  }
  depth(x, y, z){
    const q = this.T(x, y, z);
    return q.x + q.y + q.z*0.4;
  }

  quadOn(g, pts, color, alpha=1){
    g.fillStyle(color, alpha);
    g.fillPoints(pts.map(p => new Phaser.Geom.Point(p.x, p.y)), true, true);
  }
  edgeOn(g, pts, color=SKIN.outline, w=2){
    g.lineStyle(w, color, 1);
    g.strokePoints(pts.map(p => new Phaser.Geom.Point(p.x, p.y)), true);
  }

  /* ---------- world drawing ---------- */
  drawWorld(t){
    const d = this.d, g = this.gWorld, r = this.route; g.clear();
    this.gSky.clear();
    this.gSky.fillStyle(d.sky, 1);
    this.gSky.fillRect(0, 0, this.scale.gameSize.width, this.scale.gameSize.height);

/* THE NIGHT — screen-space multiply rect; glows redraw per-frame */
    this.gNight.clear(); this.gGlow.clear();
    if(r.night){
      this.gNight.fillStyle(NIGHT_MULT, 1);
      this.gNight.fillRect(0, 0, this.scale.gameSize.width, this.scale.gameSize.height);
    }

        const cullSpan = (this.scale.gameSize.width / this.K) * 0.9 + TILE*6 + 4000;
    const near = (wx, wy) => (Math.abs(wx - this.camX) + Math.abs(wy - this.camY)) < cullSpan;
    /* flat ground only -- see FLAT_CULL_PAD above */
    const flatSpan = flatSpanOf(this.cx, this.cy, this.scale.gameSize.width,
                                this.scale.gameSize.height, this.K, this.camZ);
    /* NARROW PHASE for ground paint.
       The hash broad phase answers a MANHATTAN RADIUS question. That is
       the right shape for the hash and the wrong shape for a screen: a
       diamond that circumscribes a tall portrait rect necessarily
       swallows a lot of area the rect does not cover. flatSpan cannot be
       shrunk to fix it -- it is already down to ~140 units of slack over
       the furthest visible tile -- because the waste is geometric, not
       slack. At depth 3 that left ~1,808 tiles queried for ~640 with any
       pixel on screen.

       So reject on the tile's projected screen AABB instead. This is
       provably invisible rather than visually acceptable: a quad whose
       bounding box misses the viewport contains no pixels inside it, so
       nothing skipped here could have been seen at any zoom or heading.

       The four W() calls are not extra work -- the draw needs those exact
       points anyway. A rejected tile costs one projection plus four
       compares and saves a fillPoints AND a strokePoints. */
    const gw = this.scale.gameSize.width, gh = this.scale.gameSize.height;
    const onScreen = (pts) => {
      let lo = pts[0].x, hi = lo, top = pts[0].y, bot = top;
      for(let i = 1; i < pts.length; i++){
        const p = pts[i];
        if(p.x < lo) lo = p.x; else if(p.x > hi) hi = p.x;
        if(p.y < top) top = p.y; else if(p.y > bot) bot = p.y;
      }
      return hi >= 0 && lo <= gw && bot >= 0 && top <= gh;
    };
    /* An edge is a WHOLE STREET, not a point. near() on its two endpoints
       is the wrong test for one: a street the camera is standing in the
       middle of has BOTH ends further away than either end of a street
       the camera is merely looking down. It survives today only because
       cullSpan is loose enough to swallow the error, which makes it a
       trap for anyone who later tightens the span.

       Test the nearest point ON the segment instead. Every grid edge is
       axis-aligned, so the Euclidean nearest point IS the Manhattan
       nearest point -- this projection is exact here, not an
       approximation that happens to be close. */
    const nearSeg = (a, b, span) => {
      const dx = b.x - a.x, dy = b.y - a.y, L2 = dx*dx + dy*dy;
      let s = L2 ? ((this.camX - a.x)*dx + (this.camY - a.y)*dy) / L2 : 0;
      s = s < 0 ? 0 : (s > 1 ? 1 : s);
      return (Math.abs(a.x + dx*s - this.camX) + Math.abs(a.y + dy*s - this.camY)) < span;
    };

    /* ---------- the edge of town (worldgen=coast) ----------
       Sea to the southwest, high ground to the northeast — the survey
       plate, in the world. Flat ground quads at z=0, drawn before the
       road pass so everything real paints over them, oversized so the
       camera can never find their far edge. Colours are the survey's
       own. */
    if(WORLDGEN_COAST){
      const gEnd = { x:(r.grid.cols-1)*BLOCK, y:(r.grid.rows-1)*BLOCK };
      const EXT = BLOCK*WG_COAST.EXT, SANDW = BLOCK*WG_COAST.SANDW, FOOTW = BLOCK*WG_COAST.FOOTW, FAR = BLOCK*40;
      const BOARD = BLOCK*WG_COAST.BOARD;
      const X0 = -EXT, X1 = gEnd.x + EXT, Y0 = -EXT, Y1 = gEnd.y + EXT;
      const band = (x0,y0,x1,y1,col) => this.quadOn(g, [
        this.W(x0,y0,0), this.W(x1,y0,0), this.W(x1,y1,0), this.W(x0,y1,0)], col);
      band(X0 - BOARD - SANDW - FAR, Y0 - FAR, X0 - BOARD - SANDW, Y1 + BOARD + SANDW + FAR, 0x6fa8c4); // ocean west
      band(X0 - BOARD - SANDW, Y1 + BOARD + SANDW, X1 + FAR, Y1 + BOARD + SANDW + FAR, 0x6fa8c4);       // ocean south
      band(X0 - BOARD - SANDW, Y0, X0 - BOARD, Y1 + BOARD, 0xf0e2ae);              // west beach
      band(X0 - BOARD - SANDW, Y1 + BOARD, X1, Y1 + BOARD + SANDW, 0xf0e2ae);      // south beach
      /* the boardwalk: a different kind of sidewalk between the town and
         the sand. Base bands always; plank seams only when the camera is
         actually near a boardwalk, clamped to a window around it, so the
         coastline costs two quads on an ordinary downtown frame and a
         hundred-odd cheap lines only when Tipsey goes to the beach. The
         south run owns the corner, same as its beach on the survey. */
      band(X0 - BOARD, Y0, X0, Y1, 0xb98a5e);                                      // west boardwalk
      band(X0 - BOARD, Y1, X1, Y1 + BOARD, 0xb98a5e);                              // south boardwalk
      /* the pier: off the center of Sunset Shore, Manhattan Beach style —
         a long deck from the boardwalk, across the sand, out over the
         water, ending in a round deck that wraps the aquarium. Round
         shapes go through quadOn, which takes any point count, so the
         pier uses the exact fill pipeline everything else does. */
      const PIER_W = BLOCK*WG_COAST.PIER_W, PIER_LEN = BLOCK*WG_COAST.PIER_LEN, pierY = (Y0 + Y1)/2;
      const pierX1 = X0 - BOARD, pierX0 = X0 - BOARD - SANDW - PIER_LEN;
      band(pierX0, pierY - PIER_W/2, pierX1, pierY + PIER_W/2, 0xb98a5e);          // deck
      const ring = (cx, cy, rad, col) => this.quadOn(g,
        Array.from({length: 20}, (_, k) => {
          const a = k/20 * Math.PI*2;
          return this.W(cx + Math.cos(a)*rad, cy + Math.sin(a)*rad, 0);
        }), col);
      ring(pierX0, pierY, BLOCK*0.36, 0xb98a5e);                                   // round deck
      ring(pierX0, pierY, BLOCK*0.17, 0x3f7d95);                                   // aquarium roof
      ring(pierX0, pierY, BLOCK*0.045, 0x2d5a6d);                                  // cupola
      /* the marina: tucked into the headland notch where the ocean meets
         the Sierra — basin of calmer water, breakwater arms north and
         west with the mouth opening south-west, a quay tying into the
         top of the boardwalk, finger docks, boats in the slips. All
         static flat quads (~20 fills), no gating needed. Boat placement
         is seeded off the route date so the same day always moors the
         same fleet. */
      const MX0 = X0 - BOARD - SANDW, MX1 = X0, MY0 = Y0 - FOOTW - BLOCK*WG_COAST.MTN_BASIN, MY1 = Y0;
      band(MX0, MY0, MX1, MY1, 0x7fb2c9);                                          // basin
      band(MX0 - BLOCK*0.10, MY0 - BLOCK*0.10, MX1, MY0 + BLOCK*0.06, 0x9a938a);   // north breakwater
      band(MX0 - BLOCK*0.10, MY0 - BLOCK*0.10, MX0 + BLOCK*0.06, MY0 + (MY1 - MY0)*0.62, 0x9a938a); // west arm
      band(MX1 - BLOCK*0.16, MY0, MX1, MY1, 0xb98a5e);                             // quay
      {
        const rr = mulberry32(hashStr(r.dateStr) ^ 0xb0a7);
        const fingers = 5, fy0 = MY0 + BLOCK*0.35, fy1 = MY1 - BLOCK*0.35;
        for(let k = 0; k < fingers; k++){
          const fy = fy0 + (fy1 - fy0) * k/(fingers - 1);
          band(MX1 - BLOCK*0.16 - BLOCK*0.72, fy - BLOCK*0.05, MX1 - BLOCK*0.16, fy + BLOCK*0.05, 0xb98a5e);
          for(const side of [-1, 1]){
            if(rr() < 0.35) continue;
            const bx = MX1 - BLOCK*0.16 - BLOCK*0.10 - rr()*BLOCK*0.5;
            const by = fy + side*(BLOCK*0.05 + BLOCK*0.075);
            band(bx - BLOCK*0.11, by - BLOCK*0.05, bx + BLOCK*0.11, by + BLOCK*0.05, 0xf6f3ea);
          }
        }
      }
      {
        const PLANK = 52, NEAR = BLOCK*2, SPAN = BLOCK*2;
        g.lineStyle(3, 0x8a6644, 0.55);
        if(this.camX < X0 + NEAR){
          const ya = Math.max(Y0, this.camY - SPAN), yb = Math.min(Y1, this.camY + SPAN);
          for(let y = Math.ceil(ya/PLANK)*PLANK; y <= yb; y += PLANK){
            const a = this.W(X0 - BOARD, y, 0), b2 = this.W(X0, y, 0);
            g.lineBetween(a.x, a.y, b2.x, b2.y);
          }
        }
        if(this.camY > Y1 - NEAR){
          const xa = Math.max(X0 - BOARD, this.camX - SPAN), xb = Math.min(X1, this.camX + SPAN);
          for(let x = Math.ceil(xa/PLANK)*PLANK; x <= xb; x += PLANK){
            const a = this.W(x, Y1, 0), b2 = this.W(x, Y1 + BOARD, 0);
            g.lineBetween(a.x, a.y, b2.x, b2.y);
          }
        }
        if(Math.abs(this.camY - pierY) < PIER_W/2 + SPAN && this.camX < X0 + NEAR){
          const xa = Math.max(pierX0, this.camX - SPAN), xb = Math.min(pierX1, this.camX + SPAN);
          for(let x = Math.ceil(xa/PLANK)*PLANK; x <= xb; x += PLANK){
            const a = this.W(x, pierY - PIER_W/2, 0), b2 = this.W(x, pierY + PIER_W/2, 0);
            g.lineBetween(a.x, a.y, b2.x, b2.y);
          }
        }
      }
      band(X0, Y0 - FOOTW, X1 + FOOTW, Y0, 0xcfc69b);                              // north foothills
      band(X1, Y0, X1 + FOOTW, Y1 + BOARD + SANDW, 0xcfc69b);                      // east foothills
      band(X0, Y0 - FOOTW - FAR, X1 + FOOTW + FAR, Y0 - FOOTW, 0xa89b82);          // north range
      band(X1 + FOOTW, Y0 - FOOTW, X1 + FOOTW + FAR, Y1 + BOARD + SANDW, 0xa89b82); // east range
      /* upscale housing in the hills: Sierra Vista Estates on the shoulder
         east of the marina, Mirador Heights terraced into the eastern
         slope — and the houses LINE the drive. Each district is one
         quadratic drive from its access-stub entry; lots sit on both
         sides of it, rotated to the local tangent, pushed out by half
         the road plus a setback so no house ever stands on the asphalt.
         Seeded skips and jitter keep it a neighbourhood instead of a
         barracks; fixed seed, houses don't move house. Access stubs in
         the city's own pal.road extend real streets past the ring road
         (2nd St north, the j=10 row east), aligned to street positions
         so they thread the perimeter-lot gaps. Visual connections only:
         routable estate addresses mean lattice extension, next phase. */
      {
        const LOT = 0xf2ece0;
        const RW = ROAD_HALF;
        const q = (a, c2, b3, t) => { const s2 = 1 - t; return s2*s2*a + 2*s2*t*c2 + t*t*b3; };
        const drive = (ex, ey, fx2, fy2, cx2, cy2) => {
          let px = ex, py = ey;
          for(let k = 1; k <= 12; k++){
            const t = k/12, hw = RW*0.45;
            const qx = q(ex, cx2, fx2, t), qy = q(ey, cy2, fy2, t);
            band(Math.min(px,qx) - hw, Math.min(py,qy) - hw,
                 Math.max(px,qx) + hw, Math.max(py,qy) + hw, r.pal.road);
            px = qx; py = qy;
          }
        };
        const lotsAlong = (ex, ey, fx2, fy2, cx2, cy2, seed, bx0, by0, bx1, by1) => {
          const r3 = mulberry32(seed);
          for(let t = 0.16; t <= 0.94; t += 0.11){
            const qx = q(ex, cx2, fx2, t), qy = q(ey, cy2, fy2, t);
            const tx = q(ex, cx2, fx2, t + 0.01) - qx, ty = q(ey, cy2, fy2, t + 0.01) - qy;
            const tl = Math.hypot(tx, ty) || 1, ux = tx/tl, uy = ty/tl;
            const nx = -uy, ny = ux;
            for(const side of [-1, 1]){
              if(r3() < 0.22) continue;
              const setback = RW*0.45 + BLOCK*0.07 + BLOCK*0.12 + r3()*BLOCK*0.05;
              const cxL = qx + nx*side*setback, cyL = qy + ny*side*setback;
              if(cxL < bx0 || cxL > bx1 || cyL < by0 || cyL > by1) continue;
              const hw2 = BLOCK*(0.16 + r3()*0.05), hd = BLOCK*0.12;
              this.quadOn(g, [
                this.W(cxL - ux*hw2 - nx*side*hd, cyL - uy*hw2 - ny*side*hd, 0),
                this.W(cxL + ux*hw2 - nx*side*hd, cyL + uy*hw2 - ny*side*hd, 0),
                this.W(cxL + ux*hw2 + nx*side*hd, cyL + uy*hw2 + ny*side*hd, 0),
                this.W(cxL - ux*hw2 + nx*side*hd, cyL - uy*hw2 + ny*side*hd, 0)], LOT);
            }
          }
        };
        /* Sierra Vista: stub up 2nd St, drive east along the shoulder */
        const svEx = BLOCK, svEy = Y0 - BLOCK*0.08;
        const svFx = X0 + BLOCK*3.3, svFy = Y0 - FOOTW/2 - BLOCK*0.5;
        const svCx = X0 + BLOCK*1.7, svCy = Y0 - FOOTW - BLOCK*0.6;
        band(BLOCK - RW, Y0 - BLOCK*0.08, BLOCK + RW, 0, r.pal.road);
        drive(svEx, svEy, svFx, svFy, svCx, svCy);
        lotsAlong(svEx, svEy, svFx, svFy, svCx, svCy, 0xe57a7e5,
                  X0 + BLOCK*0.15, Y0 - FOOTW - BLOCK*0.95, X0 + BLOCK*3.3, Y0 - BLOCK*0.08);
        /* Mirador Heights: stub east on the j=10 row, drive down the slope */
        const mhEx = X1 + BLOCK*0.08, mhEy = 10*BLOCK;
        const mhFx = (X1 + X1 + FOOTW + BLOCK*0.75)/2, mhFy = Y0 + (Y1 - Y0)*0.92;
        const mhCx = X1 + FOOTW*0.9, mhCy = Y0 + (Y1 - Y0)*0.7;
        band((r.grid.cols - 1)*BLOCK, 10*BLOCK - RW, X1 + BLOCK*0.08, 10*BLOCK + RW, r.pal.road);
        drive(mhEx, mhEy, mhFx, mhFy, mhCx, mhCy);
        lotsAlong(mhEx, mhEy, mhFx, mhFy, mhCx, mhCy, 0xe57a7e6,
                  X1 + BLOCK*0.08, Y0 + (Y1 - Y0)*0.45, X1 + FOOTW + BLOCK*0.75, Y0 + (Y1 - Y0)*0.92);
      }
    }
    /* roads: ONE quad per street, full length — no internal tile seams
       (a uniformly-colored surface built from many small quads shows
       every seam as a hairline at low zoom; a single quad has none). */
    for(const edge of r.grid.edges){
      const dv = DIRV[edge.f], rv = DIRV[(edge.f+1)%4];
      if(!nearSeg(edge.a, edge.b, cullSpan)) continue;
      const ax = edge.a.x - dv.x*OVERSHOOT, ay = edge.a.y - dv.y*OVERSHOOT;
      const bx = edge.b.x + dv.x*OVERSHOOT, by = edge.b.y + dv.y*OVERSHOOT;
      this.quadOn(g, [
        this.W(ax - rv.x*ROAD_HALF, ay - rv.y*ROAD_HALF, 0),
        this.W(bx - rv.x*ROAD_HALF, by - rv.y*ROAD_HALF, 0),
        this.W(bx + rv.x*ROAD_HALF, by + rv.y*ROAD_HALF, 0),
        this.W(ax + rv.x*ROAD_HALF, ay + rv.y*ROAD_HALF, 0)
      ], d.road);
    }

    /* sidewalks: T2-square tiles for the safe mid-block stretch (real
       panel seams, provably conflict-free by construction — no classify()
       check needed), fine classify()-verified cells only near actual
       intersections — the one place a cheap tile could be wrong. */
    /* broad phase: Manhattan hash on flatSpan. narrow phase: screen AABB. */
    for(const rn of manhattanQuery(paveHash(r.grid, "sidewalkRuns", "swRunHash"),
                                   this.camX, this.camY, flatSpan, this._qRuns)){
      const half = T2/2;
      const pts = [
        this.W(rn.x-half, rn.y-half, 0), this.W(rn.x+half, rn.y-half, 0),
        this.W(rn.x+half, rn.y+half, 0), this.W(rn.x-half, rn.y+half, 0)
      ];
      if(!onScreen(pts)) continue;
      this.quadOn(g, pts, rn.parity === 0 ? d.pave : d.paveB);
      this.edgeOn(g, pts, d.paveEdge, 1);
    }
    for(const cell of manhattanQuery(paveHash(r.grid, "sidewalkCornerCells", "swCornerHash"),
                                     this.camX, this.camY, flatSpan, this._qCorner)){
      const half = CELL/2;
      const pts = [
        this.W(cell.x-half, cell.y-half, 0), this.W(cell.x+half, cell.y-half, 0),
        this.W(cell.x+half, cell.y+half, 0), this.W(cell.x-half, cell.y+half, 0)
      ];
      if(!onScreen(pts)) continue;
      this.quadOn(g, pts, cell.parity === 0 ? d.pave : d.paveB);
      this.edgeOn(g, pts, d.paveEdge, 1);
    }
    /* center line: flat road paint, no depth. */
    /* This loop had NO cull whatsoever -- it painted the stripe on every
       street in the whole city, all 356 edges, every frame, at every
       zoom depth. Found by counting Graphics ops per frame and noticing
       the road-surface loop directly above drew 12 quads off r.grid.edges
       while this one drew 356 off the same array. */
    /* Two changes here, both about the same thing: an edge runs NODE TO
       NODE, and the intersection sits at each node. The cross street is
       the same 8 rows wide, so the junction occupies
       [node - ROAD_HALF, node + ROAD_HALF] along this edge, and the
       mid-block run that should actually carry paint is

           a0 + dv*ROAD_HALF  ..  b0 - dv*ROAD_HALF

       Both loops below used the full a0..b0 span, which painted the
       centre stripe straight across the mouth of the cross street and
       ran the curb riser through the junction as an unbroken seam. That
       is the line visible cutting across the intersection on device.

       MID() is shared by both so the stripe and the curb can never
       disagree about where the junction starts -- same class of bug as
       targetDoorS() for the GPS readout. */
    const midRun = (a0, b0, dv) => ({
      sx: a0.x + dv.x*ROAD_HALF, sy: a0.y + dv.y*ROAD_HALF,
      len: Math.hypot(b0.x - a0.x, b0.y - a0.y) - 2*ROAD_HALF
    });

    /* centre line: flat road paint, no depth. Dashed, because it divides
       two lanes of OPPOSING travel -- a solid line means no crossing,
       which is not what this road is.

       The dash count is chosen so a whole number of periods fits the
       mid-block run exactly, and the phase is offset by a quarter period
       so the run opens and closes with an identical half gap. Picking a
       fixed dash length instead would clip an arbitrary partial dash
       against one intersection and not the other, which reads as a
       mistake at view 1 even though it is only a phase artefact. */
    const LINE_HALF   = 4;          // stripe half-width, unchanged
    const DASH_TARGET = T2 * 2.5;   // desired period, snapped to fit below
    for(const edge of r.grid.edges){
      if(!nearSeg(edge.a, edge.b, cullSpan)) continue;
      const dv = DIRV[edge.f], rv = DIRV[(edge.f+1)%4];
      const { sx, sy, len } = midRun(edge.a, edge.b, dv);
      if(len <= 0) continue;
      const n = Math.max(1, Math.round(len / DASH_TARGET));
      const per = len / n, dash = per*0.5, phase = per*0.25;
      for(let i = 0; i < n; i++){
        const s0 = phase + i*per, s1 = s0 + dash;
        this.quadOn(g, [
          this.W(sx + dv.x*s0 - rv.x*LINE_HALF, sy + dv.y*s0 - rv.y*LINE_HALF, 3),
          this.W(sx + dv.x*s1 - rv.x*LINE_HALF, sy + dv.y*s1 - rv.y*LINE_HALF, 3),
          this.W(sx + dv.x*s1 + rv.x*LINE_HALF, sy + dv.y*s1 + rv.y*LINE_HALF, 3),
          this.W(sx + dv.x*s0 + rv.x*LINE_HALF, sy + dv.y*s0 + rv.y*LINE_HALF, 3)
        ], d.roadLine);
      }
    }
    /* curb: a genuine vertical riser face, not a wide sloped strip —
       zero width ACROSS the curb line, just a height difference from
       bottom to top AT that one lateral position. A sloped quad across
       a 92-unit-wide strip made an 8-unit rise basically unreadable;
       a true vertical face (same lateral spot, different height) is
       what actually looks like a curb, matching how the original
       single-path game drew it (a small wall, not a ramp).

       Now trimmed to the mid-block run: a curb does not cross the mouth
       of a side street, there is a crossing there. This loop also had no
       cull at all -- 356 edges x 2 faces = 712 quads a frame regardless
       of where the camera was -- so it gets the same nearSeg the road
       surface and the stripe use. */
    for(const edge of r.grid.edges){
      if(!nearSeg(edge.a, edge.b, cullSpan)) continue;
      const dv = DIRV[edge.f], rv = DIRV[(edge.f+1)%4];
      const { sx, sy, len } = midRun(edge.a, edge.b, dv);
      if(len <= 0) continue;
      const ex = sx + dv.x*len, ey = sy + dv.y*len;
      const curbFace = offUnits => {
        const ox = rv.x*offUnits, oy = rv.y*offUnits;
        this.quadOn(g, [
          this.W(sx+ox, sy+oy, 3),
          this.W(ex+ox, ey+oy, 3),
          this.W(ex+ox, ey+oy, -2),
          this.W(sx+ox, sy+oy, -2)
        ], d.paveEdge);
      };
      curbFace(-ROAD_HALF);
      curbFace(ROAD_HALF);
    }

    /* moved up from below: block-wrap houses/stores need the same
       front/back split props already use, so botDepth/layerFor (and
       the gFront clear that must precede any use of it) have to exist
       before the block-wrap pass, not after it. */
    this.gFront.clear();
    const botDepth = this.botX + this.botY;
    const layerFor = (px, py) => (px + py > botDepth + 14) ? this.gFront : g;

    /* moved up from below: cars/traffic now need world position before
       the body depth-sort runs (see the trafficPts block after the
       block-wrap pass), so worldOf has to exist this early too. */
    const worldOf = (s, offsetUnits) => {
      const hdg = this.headingAt(s), p = this.posAt(s);
      const rvx = -Math.sin(hdg), rvy = Math.cos(hdg);
      return { x: p.x + rvx*offsetUnits, y: p.y + rvy*offsetUnits, z: this.groundZ(s) };
    };
    const hazardOffset = hz => hz.row !== undefined ? laneOffset(hz.row) : hz.roadOffset;
    /* sidewalkend/sidewalkbegin/sidewalkbeginTurn are ADA curb ramps
       with real height and slope, not flat decals -- "crack" is the
       only genuinely flat one here. The rest can visually overlap a
       car or house the same way any other volumetric thing can, so
       they need the same depth-sort treatment, not an exemption. */
    const GROUND_KINDS = { crack:1, sidewalkend:1, sidewalkbegin:1, sidewalkbeginTurn:1, slab:1, grade:1 };

    /* ---------- block-wrap: housing/park/commercial beyond the
       sidewalk's inside line, all around the grid (interior blocks
       AND the world's outer perimeter lots). Two passes, same fix as
       the lab: flat ground fills first (order-independent, always into
       g since flat ground never needs to occlude the robot), THEN one
       global depth sort for every house/store/fence/scatter-prop —
       each one individually routed through layerFor so a house that's
       actually in FRONT of the robot (iso depth) correctly occludes
       him instead of the robot always painting over every house
       regardless of true position (the original bug: everything went
       into g unconditionally, so the robot could never be hidden
       behind a house even when it should have been). */
    const visBlocks = r.grid.blocks.filter(b => near(b.cx, b.cy));
    const visLots = r.grid.extLots.filter(l => near(l.cx, l.cy));
    for(const blk of visBlocks) this.fillBlockGround(g, blk);
    for(const lot of visLots) this.fillExteriorLot(g, lot);

    /* north-wall cutaway: heading f===2 (DIRV[2], world -x) is the ONE
       travel direction where this fixed iso camera's height-lift can
       push a nearby block's north wall over the robot's own screen
       position (confirmed from the W() projection math: world -x maps
       to up-and-left on screen, matching the reported angle exactly).
       Every other heading is untouched — this is a single-direction
       fix, not a general occlusion system, so it can't over-trigger
       across unrelated blocks. Only the CURRENT block's north edge is
       cut, identified by precise cell index, not distance.
       Segment TYPE matters too: this.f is a rounded snapshot of the
       continuous heading, and during an ARC (turning through a corner)
       that heading sweeps through all four cardinal directions —
       briefly rounding to 2 mid-turn even on a corner that isn't a
       sustained westbound leg. Gating on segAt().type==="line" as well
       means the cut only ever fires on a real straight westbound walk,
       never during the turn itself. */
    /* two headings need this, not one — f===2 (up-left) cuts the
       block's NORTH edge (edge 0), f===1 (down-left) cuts its WEST
       edge (edge 3). Same derivation both times: the robot's fixed
       sidewalk lane (ROBOT_SIDE) relative to travel direction puts it
       on one consistent side of the street, and that determines which
       single edge of the adjacent block is the "near" wall that can
       loom over his screen position under this fixed iso camera. */
    /* north-wall cutaway — STATIC now. The which-edge derivation is
       unchanged (NORTH_WALL_CUT_EDGE: f=2's westbound walk puts the
       block's north wall over the robot under this fixed iso camera,
       f=1 the west wall — confirmed from the W() projection math),
       but the trigger moved to route generation: route.cutEdges maps
       block(i,j) -> [edges] for every block the route's cut-heading
       legs traverse, permanent for the whole route. No live heading
       test, no live block test — so nothing snaps when the heading
       changes, when the robot crosses a block seam mid-leg, or through
       corner arcs (all three were reported on-device). A block can
       carry TWO cut edges if both an f=1 and an f=2 leg touch it. */
    this.addrDoorPos = null;
    const blockVQ = [];
    const topLayer = [];
    for(const blk of visBlocks){
      const cuts = (blk.type !== "park") ? this.route.cutEdges[blk.i + "," + blk.j] : null;
      this.queueBlockContent(blockVQ, blk, cuts || null);
      if(cuts) for(const cutEdgeIdx of cuts){
        const e = this.blockEdges(blk)[cutEdgeIdx];
        const eseed = ((Math.round(e.ox*3+e.dv.x)*7919) ^ (Math.round(e.oy*3+e.dv.y)*104729) ^ 0x6f2a) >>> 0;
        const ecx = e.ox + e.dv.x*e.len/2, ecy = e.oy + e.dv.y*e.len/2;
        const isCrime = !!(r.crime && r.crime.blockKey === (blk.i + "," + blk.j)
                           && r.crime.edgeIdx === cutEdgeIdx);
        /* the crime lot overrides the zoning: on a housing or park block
           its cut edge would otherwise get a fence row, and the scene
           has to be able to land on the address block (the only cut
           block on some routes) without that block being retyped */
        if(blk.type === "commercial" || isCrime){
          blockVQ.push({ depth: ecx+ecy, fn:(g,t)=>{
            const cars = this.drawParkingRow(g, e.ox, e.oy, e.dv, e.rv, e.len, eseed, t,
                                             isCrime ? CRIME_STALLS : 0);
            for(const c of cars) topLayer.push(c);
          }});
        } else {
          /* sliced (stage 1): per-strip keys AND per-strip layerFor —
             the old single edge-center test classified a whole
             block-length fence front/back of the robot by one point */
          const nF = Math.max(1, Math.ceil(e.len / TILE));
          for(let fi = 0; fi < nF; fi++){
            const fa0 = e.len*fi/nF, fa1 = fi === nF-1 ? e.len : e.len*(fi+1)/nF;
            const fam = (fa0+fa1)/2;
            const fcx = e.ox + e.dv.x*fam, fcy = e.oy + e.dv.y*fam;
            blockVQ.push({ depth: fcx+fcy, fn:()=>this.drawSolidFenceRow(layerFor(fcx, fcy), e.ox, e.oy, e.dv, e.rv, e.len, eseed, fa0, fa1) });
          }
        }
      }
    }
    for(const lot of visLots) this.queueExteriorLot(blockVQ, lot);

    /* CRIME SCENE bodies. Each cruiser and each officer is queued into
       blockVQ SEPARATELY, with its own depth and its own layerFor — so
       they sort against houses, fences and props like anything else.
       The lab drew them in a private sorted pass, which could only ever
       order them among themselves and would have put a cruiser through
       a storefront the moment one stood between the robot and the shop. */
    if(r.crime){
      for(const c of r.crime.cars){
        if(!near(c.x, c.y)) continue;
        blockVQ.push({ depth: c.x + c.y, fn:(g,t)=>this.drawProp(
          layerFor(c.x, c.y), "policecar", c.x, c.y, t, c.fdir, 0, null, c.seed,
          { strobe: c.strobe }) });
      }
      for(const o of r.crime.officers){
        if(!near(o.x, o.y)) continue;
        /* the traffic officer's arm and facing are phase state, so they
           come from the sim rather than from the static layout */
        const arm = (o.role === "traffic" && this.crimeArm) ? this.crimeArm : null;
        const oth = arm ? arm.thW : o.thW;
        blockVQ.push({ depth: o.x + o.y, fn:(g,t)=>this.drawOfficer(
          layerFor(o.x, o.y), o.x, o.y, 0, oth, o.role, o.seed, t,
          arm ? { liftT: arm.liftT } : null) });
      }
      if(r.crime.tape) r.crime.tape.forEach((sp, i) => {
        const mx = (sp.a.x + sp.b.x)/2, my = (sp.a.y + sp.b.y)/2;
        if(!near(mx, my)) return;
        blockVQ.push({ depth: mx + my, fn:(g,t)=>this.drawTapeSpan(layerFor(mx, my), i, t) });
      });
    }

    /* moving traffic + roadside parked car/truck props: computed here,
       BEFORE the body depth-sort below, and pushed into blockVQ exactly
       like any house/store body -- so a car now sorts correctly against
       buildings by real depth (x+y), instead of being painted in a
       separate pass that ran after the whole gWorld body pass had
       already finished (which meant a car always painted on top of
       every house regardless of true depth -- the reported "draw order
       confused in world space" bug). Dedup (skip a vehicle too close to
       one already queued this frame -- independent traffic routes can
       overlap with zero mutual awareness) is unchanged from before. */
    const trafficPts = [];
    for(const pr of r.props){
      if(pr.kind !== "car" && pr.kind !== "truck") continue;
      const wp = worldOf(pr.s, pr.roadOffset);
      trafficPts.push({ kind: pr.kind, wp, f: pr.f, wheelPhase: null, colorSeed: null, parked: true });
    }
    for(const tr of r.traffic){
      const { wp, fc, trS } = trafficWorldAt(tr, t);
      trafficPts.push({ kind: tr.kind, wp, f: fc, wheelPhase: trS*0.28, colorSeed: tr.colorSeed, parked: false });
    }
    /* The proximity cull applies to PARKED roadside props ONLY. Two of
       those generated on top of each other is a generation artifact and
       dropping one is correct. Applying the same rule to MOVING traffic
       was the reported "cars cut in and out" bug: whichever car was
       queued second simply vanished for however many frames the two
       overlapped, then popped back in. Moving cars are kept apart in
       the SIM instead (updateTrafficSpacing), where a car can actually
       slow down -- never by deleting one at draw time. */
    const MIN_TRAFFIC_GAP = CARC.len * 0.9;
    const drawnTrafficPts = [];
    for(const p of trafficPts){
      if(!near(p.wp.x, p.wp.y)) continue;
      if(p.parked){
        if(drawnTrafficPts.some(q => Math.hypot(q.x-p.wp.x, q.y-p.wp.y) < MIN_TRAFFIC_GAP)) continue;
        drawnTrafficPts.push(p.wp);
      }
      const pk = p.kind, pwx = p.wp.x, pwy = p.wp.y, pwz = p.wp.z, pf = p.f, pwp2 = p.wheelPhase, pcs = p.colorSeed;
      blockVQ.push({ depth: pwx+pwy, fn:(g,t)=>this.drawProp(layerFor(pwx,pwy), pk, pwx, pwy, t, pf, pwz, pwp2, pcs) });
    }

    /* other volumetric props (bins, cones, hydrants, dogs, people, etc.):
       same fix, same reason -- these used to draw in their own pass
       AFTER the whole body+roof pass had already finished, so a prop
       standing near a parked car always painted on top of it (and of
       any house) regardless of which was actually closer to camera.
       Pushing them into blockVQ here, sorted by real depth alongside
       houses/cars/traffic, fixes prop-vs-car and prop-vs-house the same
       way car-vs-house was fixed above. */
    for(const pr of r.props){
      if(pr.kind === "car" || pr.kind === "truck") continue;
      const wp = worldOf(pr.s, pr.roadOffset);
      if(!near(wp.x, wp.y)) continue;
      const prk = pr.kind, pwx2 = wp.x, pwy2 = wp.y, pwz2 = wp.z, pf2 = pr.f;
      blockVQ.push({ depth: pwx2+pwy2, fn:(g,t)=>this.drawProp(layerFor(pwx2,pwy2), prk, pwx2, pwy2, t, pf2, pwz2) });
    }

    /* ground-kind hazards: crack really is flat, but sidewalkend/
       sidewalkbegin/sidewalkbeginTurn are actual curb ramps with height
       and slope -- they got the same "always draws late, unsorted"
       treatment as the other props/cars bug above, just via a separate
       code path (the old "flat, can never occlude" assumption), so a
       ramp near a parked car painted over it regardless of depth. Same
       fix: push into blockVQ so it's depth-sorted against everything
       else instead of drawn unconditionally on top afterward. */
    const groundVQ = [];
    for(const hz of r.hazards){
      if(!GROUND_KINDS[hz.type]) continue;
      /* world-anchored ramps (turn crossings) carry their own wx/wy —
         they sit at the true curb lines, positions the route-s mapping
         can't express (the arc seg owns that s-range); everything else
         stays route-anchored via worldOf as before. */
      const wp = hz.wx !== undefined
        ? { x: hz.wx, y: hz.wy, z: hz.wz || 0 }
        : worldOf(hz.s + (hz.slide || 0), hazardOffset(hz));
      if(!near(wp.x, wp.y)) continue;
      const hzt = hz.type, hwx = wp.x, hwy = wp.y, hwz = wp.z, hf = hz.f, hzObj = hz;
      /* slab is a full T2 tile the robot drives directly across and
         rides elevated on top of (slabZ) -- a single depth-vs-robot
         flip evaluated once at the tile's center pops the whole panel
         from in-front to behind partway through the crossing (the
         reported "over for the first half, under for the second"
         bug). It should stay under the robot the entire time, same
         "always behind" guarantee houses/roofs already get, not the
         point-depth test meant for freestanding side-by-side props. */
      /* sidewalkend/sidewalkbegin get the same pin as slab, same reason:
         the robot drives DIRECTLY ACROSS them (they sit under his own
         lane at every street crossing), so a single point-depth test at
         the decal's center would flip the whole 2x3-tile panel from
         behind to in-front partway through — over-the-robot for half
         the crossing. Pinning to gWorld is orientation-independent, so
         it's correct for all 4 headings at once — no per-heading
         special-casing needed, unlike a point-depth test. Body-vs-body
         order against cars/houses is unaffected — that comes from the
         blockVQ sort, not the layer choice. */
      /* crack joined the pin list: flat ground paint the robot ALWAYS
         drives over, but it was still going through layerFor()'s
         point-depth test — which flips to the front layer the moment
         botDepth sweeps past the crack's single center point, painting
         the crack OVER the robot just after passing it (on-device
         report). Same class as the original slab pop: large flat
         objects with a known layer relationship get pinned, not
         point-tested. */
      /* KNOCKED props join the depth-anchor fixes: a downed planter /
         bin / cone / scooter's visual mass pivots or slides well away
         from its spawn anchor, so layerFor() at the anchor tests a
         point that's no longer under the art — robot pressed against a
         tipped planter drew OVER it (on-device). Can't pin these (the
         robot can be on either side), so instead test the silhouette
         point NEAREST the robot: shift the test point toward the robot
         by up to the prop's knocked radius. Far apart, either answer
         is fine (no overlap possible); close, this is the point that
         decides the truth. Orientation-independent — correct at all 4
         headings by construction. */
      let ltx = hwx, lty = hwy;
      if((hzt === "planter" || hzt === "bin" || hzt === "cone" || hzt === "scooter")
         && hzObj && (hzObj.phi || 0) > 0.5){
        let kx = this.botX - hwx, ky = this.botY - hwy;
        const kd = Math.hypot(kx, ky) || 1;
        const kR = Math.min(kd, hzt === "scooter" ? 30 : 28);
        ltx += kx/kd*kR; lty += ky/kd*kR;
      }
      const slabLayer = (hzt === "slab" || hzt === "sidewalkend" || hzt === "sidewalkbegin" || hzt === "grade" || hzt === "crack")
        ? g : layerFor(ltx, lty);
      groundVQ.push({ depth: hwx+hwy, fn:(g,t)=>this.drawProp(slabLayer, hzt, hwx, hwy, t, hf, hwz, null, null, hzObj) });
    }

    /* the world's own curb ramps -- decorative, world-anchored, no
       hazard entry (see buildWorldCurbRamps). Same ground pass and the
       same pinned layer as the route's ramps, so the two sets sort
       identically and a route ramp beside a world ramp is seamless. */
    for(const cr of (r.curbRamps || [])){
      if(!near(cr.x, cr.y)) continue;
      const crx = cr.x, cry = cr.y, crf = cr.f;
      groundVQ.push({ depth: crx+cry, fn:(g,t)=>this.drawProp(g, "sidewalkend", crx, cry, t, crf, 0, null, null, WORLD_RAMP) });
    }

    /* GROUND FIRST -- its own pass, ahead of every body.

       These used to ride in blockVQ sorted on their own depth. That is
       the right answer against cars and houses, and wrong against the
       PICKUP unit: that entry is queued WHOLE at the store wall's depth
       (the worker is entangled in drawPickupUnit -- see
       queueCommercialEdgeAt), while the worker himself stands out by
       the kerb. Any crack or slab between the wall and the kerb sorts
       after the store entry and paints straight across him (on-device
       report). Nudging one depth key would only move the seam to the
       next thing queued whole, so: nothing that stands ON the ground
       is ever behind the ground.

       This keeps the fix that pulled this list out of the old
       draw-late pass in the first place -- a car or prop near a curb
       ramp still paints over it, now by construction rather than by
       winning a sort. Only the reverse case changes, and the reverse
       case was never correct. */
    groundVQ.sort((a,b) => a.depth - b.depth);
    for(const item of groundVQ) item.fn(g, t);

    /* roofs-last pass, RETIRED for generic units (stage 1): it existed
       because the coarse single-key-per-unit sort could let a nearby
       body paint over another unit's roof; the per-strip keys from
       queueUnitStrips make that impossible, so generic house/store
       roofs now ride their own slice entries in the normal body sort.
       Only the ADDRESS house and the PICKUP store still queue whole
       (their body entries are entangled with the customer/worker
       choreography — extraction is stage 2), so this pass now carries
       at most those two roofs. */
    const bodies = blockVQ.filter(it => !it.isRoof), roofs = blockVQ.filter(it => it.isRoof);
    bodies.sort((a,b) => a.depth - b.depth);
    for(const item of bodies) item.fn(g, t); // always gWorld — the robot must stay visible over block-wrap dressing, never hidden behind it
    roofs.sort((a,b) => a.depth - b.depth);
    for(const item of roofs) item.fn(g, t);
    /* parking-row cars draw in a THIRD pass, after roofs — they were
       part of the normal body pass before, so any visible building's
       roof (drawn unconditionally last, globally, regardless of true
       depth — see the roof comment above) could paint right over a
       parked car, looking exactly like a disconnected floating panel
       near the vehicle. This wasn't a car-drawing bug at all; it was
       the roof-ordering system (built to fix a real, different bug)
       colliding with a feature added afterward that never got the
       same "must stay visible" treatment the robot itself has. */
    /* layerFor, not hardcoded g: these cars were always drawn into
       gWorld regardless of true depth vs the robot, so the robot
       painted over them unconditionally even when a car was actually
       closer to camera and should have stayed in front. Every other
       car/prop in this file already goes through layerFor; this pass
       just never got that same treatment when it was split out to fix
       the earlier roof-covering-car bug. */
    /* sorted by real world depth before drawing — otherwise cars within
       this pass draw in raw insertion order (stall 0, then 1, then 2),
       which only happens to look right when a parking row's edge
       orientation lines up with that order by coincidence, and reads
       as visibly wrong otherwise (reported on-device, f=1 specifically).
       Still its own pass, still after roofs — this only fixes ordering
       WITHIN the pass, not when the pass itself runs. */
    topLayer.sort((a, b) => (a.x + a.y) - (b.x + b.y));
    for(const c of topLayer) this.drawProp(layerFor(c.x, c.y), c.kind, c.x, c.y, t, c.fdir, 0);

    /* volumetric props (and ground-kind hazards like curb ramps) are
       handled earlier now -- pushed into blockVQ before the body
       depth-sort so they land correctly against houses and cars; see
       the comments above that block for why. */
    for(const hz of r.hazards){
      if(GROUND_KINDS[hz.type]) continue;
      const wp = worldOf(hz.s + (hz.slide || 0), hazardOffset(hz));
      /* a fallen/falling scooter (phi>0) reaches out along its own
         local a-axis well past its single anchor point once laid
         down (see the scooter draw fn's M()) -- layerFor only tests
         that one anchor, so a scooter sprawled toward the robot can
         get classified by a point that isn't where its extended deck
         actually ends up on screen. It's also, almost by definition,
         sitting right where the robot just was: the same "always
         behind" case the slab already gets, and for the same reason
         -- pin it instead of trusting a point-sample this close to
         the robot's own position. Standing (phi===0) scooters are
         compact and can be genuinely ahead of the robot on the
         sidewalk, so they still go through the normal test. */
      /* NPC robots' visual body sits at their WALKED position
         (hz.s + walkA via robotSpotAt, frozen at knockA once
         knocked), potentially a whole block from the spawn anchor.
         The collision sim already tests the walked position
         (robotOff); near()/layerFor() here still sampled the anchor,
         so a roving robot got culled and front/back-classified by a
         point it isn't standing on -- Tipsey between anchor and body
         overlapped it in the wrong layer (reported on-device
         2026-07-26). Test at the effective point; the drawProp x,y
         deliberately stays the anchor, because the robot draw branch
         applies walkA itself -- one source of truth for position.
         Knocked robots additionally get the tipped planter/bin
         nearest-silhouette shift: the fallen shell pivots ~a body
         height off the wheelbase, so nudge the test point toward
         Tipsey by up to the fallen radius -- far apart either answer
         is fine, pressed close this is the point that decides. */
      let htx = wp.x, hty = wp.y;
      /* dogs and people with a walk range (walkS0/walkS1) have the
         exact same anchor-vs-body gap as roving robots -- their spot
         functions share the .a-offset contract, so the same effective-
         point test covers all three walkers (reported on-device
         2026-07-26, follow-up to the rover fix). Idle wanderers stay
         on the plain anchor test: their +-30 box is smaller than
         layerFor's own slack. */
      const isWalker = (hz.type === "dog" || hz.type === "people")
                       && hz.walkS0 !== undefined && hz.walkS1 !== undefined;
      if(hz.type === "robot" || isWalker || hz.type === "william"){
        /* .b too, not just .a: a detouring walker is a full lane off
           its home row while sidestepping a prop (detourBAt), and a
           knocked rover freezes wherever the sidestep had it
           (knockA/knockB) -- the test point follows both axes. */
        const effSpot = hz.type === "william" ? ((hz.kst && hz.kst !== "patrol") ? { a: hz.ka || 0, b: hz.kb || 0 } : peopleSpotAt(t, hz))
                      : hz.type === "people" ? peopleSpotAt(t, hz)
                      : hz.type === "dog"    ? dogSpotAt(t, hz)
                      : (!hz.knocked && hz.roving) ? robotSpotAt(t, hz) : null;
        const effA = effSpot ? effSpot.a : (hz.knocked ? (hz.knockA || 0) : 0);
        const effB = effSpot ? (effSpot.b || 0) : (hz.knocked ? (hz.knockB || 0) : 0);
        if(effA !== 0 || effB !== 0){
          const effWp = worldOf(hz.s + effA, hazardOffset(hz) + effB);
          htx = effWp.x; hty = effWp.y;
        }
        if(hz.knocked){
          let kx = this.botX - htx, ky = this.botY - hty;
          const kd = Math.hypot(kx, ky) || 1;
          const kR = Math.min(kd, 30);
          htx += kx/kd*kR; hty += ky/kd*kR;
        }
      }
      const hzLayer = (hz.type === "scooter" && hz.phi > 0) ? g : layerFor(htx, hty);
      if(near(htx, hty)) this.drawProp(hzLayer, hz.type, wp.x, wp.y, t, hz.f, wp.z, null, null, hz);
      if(hz.clusterExtras){
        for(const ex of hz.clusterExtras){
          const exWp = worldOf(hz.s + (hz.slide || 0) + ex.ds, hazardOffset(hz) + ex.dOff);
          if(near(exWp.x, exWp.y)) this.drawProp(layerFor(exWp.x, exWp.y), ex.kind, exWp.x, exWp.y, t, hz.f, exWp.z);
        }
      }
    }

    /* SIGNALS -- drawn immediately here, NOT queued.

       game/index.html sorts its hazards through hazVQ and pushes the two
       signal pieces into it so they interleave with pedestrians by true
       depth. THIS FILE HAS NO hazVQ: it still draws hazards in spawn-array
       order, which is the code the depth-sorted pass replaced upstream, so
       there is nothing here to queue into. Drawing after the loop means a
       signal always paints over every hazard rather than sorting against
       them -- the same ordering weakness this file already has between its
       own hazards, not a new one, and it keeps the two builds feature-equal
       until the hazVQ pass is resynced across. */
    for(const sg of (r.signals || [])){
      if(!near(sg.x, sg.y)) continue;
      this.drawProp(layerFor(sg.x, sg.y), "signalpost", sg.x, sg.y, t, sg.armF, 0, null, null, sg);
      const ad = DIRV[sg.armF];
      /* see game/index.html: pulled back so the case straddles the mast */
      const reach = SIGNAL.arm ? Math.max(0, SIGNAL.armLen - SIGNAL.headR*0.9) : 0;
      const hx = sg.x + ad.x*reach, hy = sg.y + ad.y*reach;
      const hf = SIGNAL.readable ? (sg.axis === 0 ? 0 : 1) : sg.headF;
      this.drawProp(layerFor(hx, hy), "signalhead", hx, hy, t, hf, 0, null, null, sg);
    }

    /* addrDoorPos/addrDoorDV/etc. are still set below as a side effect
       of the real address house unit's own render pass (see
       queueHousingEdgeAt's isAddress branch) -- the door/mat/house/
       customer render as part of that unit, not as anything drawn
       here. The floating address label that used to read this data
       and hover near the door is gone; the win-state camera reframe
       is the only remaining consumer, blending its shot toward
       wherever this data says the door actually is. */
  }

  /* ---------- shared person-hull renderer ----------
     Single source of truth for the character design (approved in the
     customer lab, first shipped as prop.people): hull-box construction,
     top face + the two camera-facing side faces per box. Both
     prop.people and world.customer call this directly rather than
     keeping two copies of the same body, so a future tweak to one
     shows up in both automatically.
       ax,ay,z    — world anchor (already includes any wander/flee/walk offset)
       thW        — facing angle (radians)
       build      — one of PEOPLE_BUILD
       pSkin/pShirt/pPants/pHair/pShoe — color entries ({c,dk} except pHair, a bare color)
       walkPhase  — sin() walk-cycle phase, 0 if not moving
       moving     — whether the walk cycle / arm swing should animate
       startleAlpha — 0..1, draws the "!" burst at that alpha when > 0 */
  /* ---------- hull door + knob (door lab, dial bench approved) ----------
     Slab (and its panels + knob) pivot on a vertical hinge at dx=-hw.
     theta=0 reproduces the closed pose; theta=DOOR_ART.openAngle swings
     it flat against the hinge post, out over the mat. Ported verbatim. */
  drawDoorAssembly(g, ox, oy, dv, rv, doorCenterX, dz, theta){
    const D = DOOR_ART;
    const G = (dx, dy, dzz) => this.W(ox + dv.x*(doorCenterX+dx) + rv.x*dy, oy + dv.y*(doorCenterX+dx) + rv.y*dy, dz+dzz);
    const depthAt = (dx, dy, dzz) => (dv.x+dv.y)*dx*0.5 + (rv.x+rv.y)*dy*0.5 - dzz*0.35;

    const hw = D.w/2, H = D.h, dyF = 2.4;
    const cT = Math.cos(theta), sT = Math.sin(theta);
    const SL = (u, perp, dzz) => G(-hw + u*cT - perp*sT, perp*cT + u*sT, dzz);
    const slabDepthDy = dyF*cT + (2*hw)*sT;

    const shadow = () => {
      const s = G(0, 3, 0);
      g.fillStyle(D.shadow, 0.16);
      g.fillEllipse(s.x, s.y+1, (D.w+18)*this.K*0.42, 10*this.K*0.42);
    };
    const step = () => {
      const pts = [G(-hw-2, 1.5, 0), G(hw+2, 1.5, 0), G(hw+2, 7, 0), G(-hw-2, 7, 0)];
      this.quadOn(g, pts, D.step);
      this.edgeOn(g, pts, D.stepDk, 1);
    };
    const frame = () => {
      const trim = 5;
      const top = [G(-hw-trim, 1, H+trim), G(hw+trim, 1, H+trim), G(hw+trim, 1, H), G(-hw-trim, 1, H)];
      const outer = [G(-hw-trim, 1, H+trim), G(hw+trim, 1, H+trim), G(hw+trim, 1, 0), G(-hw-trim, 1, 0)];
      this.quadOn(g, outer, D.frame);
      this.quadOn(g, top, D.frameLt);
      this.edgeOn(g, outer, D.frameDk, 1.2);
      const sideSign = (dv.x+dv.y) >= 0 ? 1 : -1;
      const lip = [
        G(sideSign*(hw+trim), 1, H+trim), G(sideSign*(hw+trim), 2.6, H+trim),
        G(sideSign*(hw+trim), 2.6, -1),   G(sideSign*(hw+trim), 1, 0)
      ];
      this.quadOn(g, lip, D.frameDk, 0.8);
    };
    /* a bit of a room behind the door, lit from a window on the left */
    const interior = () => {
      const wallColor = 0xdcd4c2, floorColor = 0xb99f78;
      const face = [G(-hw, 1.02, H), G(hw, 1.02, H), G(hw, 1.02, 0), G(-hw, 1.02, 0)];
      this.quadOn(g, face, wallColor);
      const floor = [G(-hw, 1.03, H*0.3), G(hw, 1.03, H*0.3), G(hw, 1.03, 0), G(-hw, 1.03, 0)];
      this.quadOn(g, floor, floorColor);
      const lit = [G(-hw, 1.04, H*0.82), G(-hw*0.05, 1.04, H*0.82), G(-hw*0.05, 1.04, 0), G(-hw, 1.04, 0)];
      this.quadOn(g, lit, 0xf2c98a, 0.3);
      const glow = [G(-hw*0.85, 1.05, H*0.7), G(-hw*0.35, 1.05, H*0.7), G(-hw*0.35, 1.05, H*0.3), G(-hw*0.85, 1.05, H*0.3)];
      this.quadOn(g, glow, 0xfff0cf, 0.5);
    };
    const slab = () => {
      const face = [SL(0,dyF,H), SL(2*hw,dyF,H), SL(2*hw,dyF,0), SL(0,dyF,0)];
      this.quadOn(g, face, D.slab);
      this.edgeOn(g, face, D.slabDk, 1);
      const panel = (f0, f1) => {
        const z0 = H*f0, z1 = H*f1, pin = D.panelInset;
        const grooveOuter = [
          SL(pin,dyF+0.15,z1), SL(2*hw-pin,dyF+0.15,z1),
          SL(2*hw-pin,dyF+0.15,z0), SL(pin,dyF+0.15,z0)
        ];
        this.quadOn(g, grooveOuter, D.groove);
        const inner = [
          SL(pin+2,dyF+0.35,z1-2), SL(2*hw-pin-2,dyF+0.35,z1-2),
          SL(2*hw-pin-2,dyF+0.35,z0+2), SL(pin-2,dyF+0.35,z0+2)
        ];
        this.quadOn(g, inner, D.slabLt);
      };
      panel(D.panelBotFrom, D.panelBotTo);
      panel(D.panelTopFrom, D.panelTopTo);
    };
    const knob = () => {
      const u = D.knobDX + hw, dzk = D.knobDZ;
      const plate = SL(u, 2.6, dzk);
      g.fillStyle(D.plate, 1);
      g.fillCircle(plate.x, plate.y, D.knobR*this.K*0.6);
      const c = SL(u, 3.2, dzk);
      g.fillStyle(D.knobDk, 1);
      g.fillCircle(c.x, c.y, D.knobR*this.K*0.5);
      g.fillStyle(D.knob, 1);
      g.fillCircle(c.x, c.y, D.knobR*this.K*0.42);
      g.fillStyle(D.knobHi, 1);
      g.fillCircle(c.x - 1.1*this.K*0.42, c.y - 1.1*this.K*0.42, D.knobR*this.K*0.14);
    };

    const parts = [
      { d: depthAt(0, 0, 0)-50, fn: shadow },
      { d: depthAt(0, 1, H*0.5), fn: frame },
      { d: depthAt(0, 1.02, H*0.5), fn: interior },
      { d: depthAt(0, slabDepthDy, H*0.5), fn: slab },
      { d: depthAt(D.knobDX, slabDepthDy, D.knobDZ), fn: knob },
      { d: depthAt(0, 4, 0), fn: step }
    ];
    parts.sort((p1,p2) => p1.d - p2.d);
    for(const p of parts) p.fn();
  }

  /* ---------- delivery mat (door lab, dial bench approved) ----------
     Exactly one sidewalk square, sitting flush on lane 3's tile,
     flush against the door at its near edge. Border rim + fiber
     texture instead of a flat quad. */
  drawMatQuad(g, ox, oy, dv, rv, doorCenterX, dz){
    const M = (dx, dy, dzz) => this.W(ox + dv.x*(doorCenterX+dx) + rv.x*dy, oy + dv.y*(doorCenterX+dx) + rv.y*dy, dz+dzz);
    const half = T2/2;
    const matNear = T2*0.5 - half, matFar = T2*0.5 + half;
    const outer = [M(-half,matNear,0.6), M(half,matNear,0.6), M(half,matFar,0.6), M(-half,matFar,0.6)];
    this.quadOn(g, outer, MAT_ART.redDk);
    const bw = 3.5;
    const inner = [M(-half+bw,matNear+bw,0.65), M(half-bw,matNear+bw,0.65), M(half-bw,matFar-bw,0.65), M(-half+bw,matFar-bw,0.65)];
    this.quadOn(g, inner, MAT_ART.red);
    this.edgeOn(g, outer, MAT_ART.border, 1.4);
    g.lineStyle(1, MAT_ART.fiber, 0.5);
    const rows = 6, cols = 3;
    for(let i=1; i<rows; i++){
      for(let j=0; j<cols; j++){
        const u = matNear+bw + (matFar-matNear-bw*2)*(i/rows);
        const v0 = -half+bw + (T2-bw*2)*(j/cols) + 3;
        const v1 = v0 + (T2-bw*2)/cols - 6;
        const p0 = M(v0, u, 0.66), p1 = M(v1, u, 0.66);
        g.lineBetween(p0.x, p0.y, p1.x, p1.y);
      }
    }
  }


  /* ================= BLOCK-WRAP: houses/storefronts/fences/bench,
     ported from labs/block-wrap.html. Scale anchored on the real door
     (DOOR_H/DOOR_W) and a real person (PERSON_H), not picked
     independently — see PERSON_H's own comment. ================= */
  fillBlockInterior(g, blk, tone){
    const half = T2/2;
    for(let y = blk.y0 + half; y < blk.y1; y += T2){
      for(let x = blk.x0 + half; x < blk.x1; x += T2){
        const parity = (Math.round((x-blk.x0)/T2) + Math.round((y-blk.y0)/T2)) % 2;
        const pts = [this.W(x-half,y-half,0), this.W(x+half,y-half,0), this.W(x+half,y+half,0), this.W(x-half,y+half,0)];
        this.quadOn(g, pts, parity===0 ? tone.a : tone.b);
        if(tone.edge){ g.lineStyle(1, tone.edge, 0.5); g.strokePoints(pts.map(p=>new Phaser.Geom.Point(p.x,p.y)), true, true); }
      }
    }
  }

  drawHouseUnit(g, ox, oy, dv, rv, w, seed, isAddress=false, part='all', a0=0, a1=w){
    const rng = mulberry32(seed);
    /* a = along the edge (0..w), b = depth (0 at the sidewalk-facing
       front, -D back into the block interior). A real box: front,
       back, both sides, and a top all exist as actual geometry. Faces
       drawn back-to-front so the detailed front face paints last.
       'part' lets the roof be pulled out and queued as its OWN globally
       -last layer (see queueHousingEdgeAt) — the coarse single-point
       depth sort here only compares one number per unit, so a nearby
       unit could occasionally paint over another's roof even though
       both are individually correct; forcing every roof to draw after
       every body, globally, makes that impossible regardless of sort
       order. rng() calls stay unconditional/in the same order for both
       parts so a 'roof'-only call reproduces the exact same H/C a
       'body' call would have used. */
    const C = HOUSE_WRAP_PALETTES[Math.floor(rng()*HOUSE_WRAP_PALETTES.length)];
    const H = DOOR_H + 50 + rng()*40, baseH = 26, D = HOUSE_DEPTH;
    const hasDoor = isAddress ? true : rng() < 0.5;
    const winCount = 1 + Math.floor(rng()*2);
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    /* slice window [a0,a1): geometry clips to it, discrete elements
       (windows, doors, posts, end walls) belong to the slice holding
       their center — half-open so nothing draws twice at a seam, with
       the final slice (a1===w) closing the interval. rng() calls above
       stay unconditional and slice-independent, the same parity trick
       the body/roof split already relies on. */
    const inS = c => c >= a0 && (c < a1 || a1 >= w);

    if(part !== 'roof'){
      const back = [G(a0,-D,H), G(a1,-D,H), G(a1,-D,0), G(a0,-D,0)];
      this.quadOn(g, back, C.wallDk);
      if(a0 === 0){
        const left = [G(0,0,H), G(0,-D,H), G(0,-D,0), G(0,0,0)];
        this.quadOn(g, left, C.wallDk); this.edgeOn(g, left, C.trim, 1);
      }
      if(a1 >= w){
        const right = [G(w,0,H), G(w,-D,H), G(w,-D,0), G(w,0,0)];
        this.quadOn(g, right, C.wallLt); this.edgeOn(g, right, C.trim, 1);
      }
    }

    if(part !== 'body'){
      const ov = 5;
      const rL = a0 === 0 ? -ov : a0, rR = a1 >= w ? w+ov : a1;
      const roof = [G(rL,ov,H), G(rR,ov,H), G(rR,-D-ov,H), G(rL,-D-ov,H)];
      this.quadOn(g, roof, C.roof);
      /* open-edge border: front/back lips per slice, side edges only
         at the real unit ends — a closed edgeOn per slice would paint
         a seam line across the roof at every slice boundary */
      g.lineStyle(1, C.wallDk, 1);
      g.lineBetween(roof[0].x,roof[0].y,roof[1].x,roof[1].y);
      g.lineBetween(roof[3].x,roof[3].y,roof[2].x,roof[2].y);
      if(a0 === 0) g.lineBetween(roof[0].x,roof[0].y,roof[3].x,roof[3].y);
      if(a1 >= w) g.lineBetween(roof[1].x,roof[1].y,roof[2].x,roof[2].y);
    }

    if(part === 'roof') return;

    const face = [G(a0,0.4,H), G(a1,0.4,H), G(a1,0.4,0), G(a0,0.4,0)];
    this.quadOn(g, face, C.wall);
    const base = [G(a0,0.42,baseH), G(a1,0.42,baseH), G(a1,0.42,0), G(a0,0.42,0)];
    this.quadOn(g, base, C.wallDk);
    const trim = [G(a0,0.42,H), G(a1,0.42,H), G(a1,0.42,H-9), G(a0,0.42,H-9)];
    this.quadOn(g, trim, C.trim);
    g.lineStyle(1, C.wallDk, 0.35);
    for(let x = T2; x < w; x += T2){ if(!inS(x)) continue; const a=G(x,0.41,H), b=G(x,0.41,0); g.lineBetween(a.x,a.y,b.x,b.y); }

    const winW = DOOR_W*0.32, winZ0 = DOOR_H*0.16, winZ1 = DOOR_H*0.82, sillH = 4;
    const wf = 0xf4efe2, wfd = 0xd8d0bd, wg = 0x6b93a8, wgl = 0x86adc0;
    const window = cx => {
      const wHW = winW/2;
      const sill = [G(cx-wHW-3,0.5,winZ0), G(cx+wHW+3,0.5,winZ0), G(cx+wHW+3,0.5,winZ0-sillH), G(cx-wHW-3,0.5,winZ0-sillH)];
      this.quadOn(g, sill, wfd);
      const frame = [G(cx-wHW-2,0.5,winZ1+2), G(cx+wHW+2,0.5,winZ1+2), G(cx+wHW+2,0.5,winZ0), G(cx-wHW-2,0.5,winZ0)];
      this.quadOn(g, frame, wf);
      const glass = [G(cx-wHW,0.55,winZ1), G(cx+wHW,0.55,winZ1), G(cx+wHW,0.55,winZ0), G(cx-wHW,0.55,winZ0)];
      this.quadOn(g, glass, wg);
      const hl = [G(cx-wHW+2,0.56,winZ1-2), G(cx-2,0.56,winZ1-2), G(cx-2,0.56,winZ0+3), G(cx-wHW+2,0.56,winZ0+3)];
      this.quadOn(g, hl, wgl, 0.6);
    };
    const door = cx => {
      const dHW = DOOR_W*0.4, dZ1 = DOOR_H*0.85;
      const step = [G(cx-dHW-3,0.48,6), G(cx+dHW+3,0.48,6), G(cx+dHW+3,0.48,0), G(cx-dHW-3,0.48,0)];
      this.quadOn(g, step, 0x9d9687);
      const slab = [G(cx-dHW,0.5,dZ1), G(cx+dHW,0.5,dZ1), G(cx+dHW,0.5,0), G(cx-dHW,0.5,0)];
      this.quadOn(g, slab, 0x6b4530);
      const panel = [G(cx-dHW+4,0.52,dZ1-10), G(cx+dHW-4,0.52,dZ1-10), G(cx+dHW-4,0.52,12), G(cx-dHW+4,0.52,12)];
      this.quadOn(g, panel, 0x5a3a28);
      const knob = G(cx+dHW-6,0.56,dZ1*0.42);
      g.fillStyle(0xd8b23a, 1); g.fillCircle(knob.x, knob.y, 2.6*this.K*0.42);
    };

    if((hasDoor && w > T2*1.9) || isAddress){
      const dcx = w/2;
      if(!isAddress && inS(dcx)) door(dcx); // address unit's real door assembly draws separately, on top
      for(let i=1;i<=winCount;i++){
        if(dcx - i*T2*0.9 > 14 && inS(dcx - i*T2*0.9)) window(dcx - i*T2*0.9);
        if(dcx + i*T2*0.9 < w-14 && inS(dcx + i*T2*0.9)) window(dcx + i*T2*0.9);
      }
    } else {
      const n = Math.max(1, Math.min(winCount+1, Math.floor(w/T2)));
      for(let i=0;i<n;i++) if(inS(w*(i+0.5)/n)) window(w*(i+0.5)/n);
    }
  }

  drawStoreUnit(g, ox, oy, dv, rv, w, seed, isFirst, isLast, part='all', a0=0, a1=w, opts=null){
    const rng = mulberry32(seed);
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    /* slice window [a0,a1): same contract as drawHouseUnit — clip
       bands, assign discrete elements by center, rng unconditional */
    const inS = c => c >= a0 && (c < a1 || a1 >= w);
    const clipQ = (lo, hi, bOff, z0, z1, color, alpha) => {
      const q0 = Math.max(lo, a0), q1 = Math.min(hi, a1);
      if(q1 - q0 < 0.5) return;
      this.quadOn(g, [G(q0,bOff,z1),G(q1,bOff,z1),G(q1,bOff,z0),G(q0,bOff,z0)], color, alpha);
    };
    const C = STORE_PALETTES[Math.floor(rng()*STORE_PALETTES.length)];
    const D = STORE_DEPTH;
    const doorLeft = rng() < 0.5;

    /* height stack built bottom-up from the real door — a commercial
       glass door is slightly shorter than the ornate residential hull
       door but still human-scale, and window/awning/sign/roofline all
       get guaranteed clearance instead of hoping a random H fit. */
    const kickH = 18;
    const dZ1 = DOOR_H*0.88;
    const winZ0 = kickH+2, winZ1 = dZ1 + 14 + rng()*16;
    const awnZ0 = winZ1+4, awnZ1 = awnZ0+18;
    const signZ0 = awnZ1+8, signZ1 = signZ0+16;
    const H = signZ1 + 16 + rng()*12;

    if(part !== 'roof'){
      const back = [G(a0,-D,H), G(a1,-D,H), G(a1,-D,0), G(a0,-D,0)];
      this.quadOn(g, back, C.wallDk);
      if(isFirst && a0 === 0){ const l=[G(0,0,H),G(0,-D,H),G(0,-D,0),G(0,0,0)]; this.quadOn(g,l,C.wallDk); this.edgeOn(g,l,C.trim,1); }
      if(isLast && a1 >= w){  const r=[G(w,0,H),G(w,-D,H),G(w,-D,0),G(w,0,0)]; this.quadOn(g,r,C.wallLt); this.edgeOn(g,r,C.trim,1); }
    }

    if(part !== 'body'){
      const ov = isFirst||isLast ? 5 : 0;
      const rL = a0 === 0 ? (isFirst?-ov:0) : a0, rR = a1 >= w ? (isLast?w+ov:w) : a1;
      const roof = [G(rL,ov,H), G(rR,ov,H), G(rR,-D-ov,H), G(rL,-D-ov,H)];
      this.quadOn(g, roof, C.trim);
      /* open-edge border — see the house roof note */
      g.lineStyle(1, C.wallDk, 1);
      g.lineBetween(roof[0].x,roof[0].y,roof[1].x,roof[1].y);
      g.lineBetween(roof[3].x,roof[3].y,roof[2].x,roof[2].y);
      if(a0 === 0) g.lineBetween(roof[0].x,roof[0].y,roof[3].x,roof[3].y);
      if(a1 >= w) g.lineBetween(roof[1].x,roof[1].y,roof[2].x,roof[2].y);
    }

    if(part === 'roof') return;

    const face = [G(a0,0.4,H), G(a1,0.4,H), G(a1,0.4,0), G(a0,0.4,0)];
    this.quadOn(g, face, C.wall);

    clipQ(2, w-2, 0.42, 0, kickH, C.wallDk);

    const doorW = Math.min(DOOR_W*0.72, w*0.3);
    const doorX = doorLeft ? 6 : w - doorW - 6;
    /* PICKUP UNIT: the painted door is suppressed and the glass runs the
       full frontage.

       That unit gets a second, REAL door from drawShopDoor, centred on
       u.w/2 — and centre is the anchor everything else already uses:
       route.pickupSpot is built at pu.w/2, drawPickupUnit is handed
       doorCenterX = u.w/2, and the worker walks out from
       pickupDoorCenterX. Robot, door and worker agree by construction;
       see drawShopDoor's note on why centring is what makes them agree.

       The decorative door here is the one thing that does not agree. It
       sits hard against whichever end doorLeft picked, so the pickup
       unit rendered with TWO doors and the worker emerged from the one
       that was not "the" door. Chasing doorX with the spot, the swinging
       door and the worker would mean three consumers tracking a random
       number; deleting the door nothing references is the smaller and
       safer change.

       doorLeft is still drawn from rng ABOVE this branch, unconditional,
       because the slice contract requires the rng sequence to be
       identical regardless of what any one slice decides to skip. Every
       other unit on the strip must keep the frontage it had. */
    const noDoor = !!(opts && opts.noDoor);
    const glassX0 = noDoor ? 6 : (doorLeft ? doorX+doorW+4 : 6);
    const glassX1 = noDoor ? w-6 : (doorLeft ? w-6 : doorX-4);

    if(!noDoor && inS(doorX + doorW/2)){
      this.quadOn(g, [G(doorX,0.5,dZ1),G(doorX+doorW,0.5,dZ1),G(doorX+doorW,0.5,0),G(doorX,0.5,0)], C.wallDk);
      this.quadOn(g, [G(doorX+3,0.53,dZ1-4),G(doorX+doorW-3,0.53,dZ1-4),G(doorX+doorW-3,0.53,4),G(doorX+3,0.53,4)], 0x6b93a8, 0.85);
    }

    if(glassX1 - glassX0 > 12){
      clipQ(glassX0, glassX1, 0.5, winZ0-3, winZ1+3, 0xd8d0bd);
      clipQ(glassX0+2, glassX1-2, 0.54, winZ0, winZ1, 0x6b93a8);
      clipQ(glassX0+3, glassX0+(glassX1-glassX0)*0.4, 0.55, winZ0+3, winZ1-3, 0x86adc0, 0.55);
    }

    const awnOut = 20, stripeN = 6;
    for(let i=0;i<stripeN;i++){
      const sx0 = Math.max(w*i/stripeN, a0), sx1 = Math.min(w*(i+1)/stripeN, a1);
      const col = AWNING_STRIPES[i%2===0?0:1] === 0xffffff ? 0xf0ece0 : C.wallLt;
      if(sx1 - sx0 < 0.5) continue;
      this.quadOn(g, [G(sx0,0.5,awnZ1),G(sx1,0.5,awnZ1),G(sx1,0.5+awnOut*0.01,awnZ0),G(sx0,0.5+awnOut*0.01,awnZ0)], col);
    }
    clipQ(0, w, 0.42, awnZ1, awnZ1+3, C.trim);

    const gx0 = Math.max(4, a0), gx1 = Math.min(w-4, a1);
    if(gx1 - gx0 > 0.5){
      const sq = [G(gx0,0.44,signZ1),G(gx1,0.44,signZ1),G(gx1,0.44,signZ0),G(gx0,0.44,signZ0)];
      this.quadOn(g, sq, C.sign);
      /* open-edge sign border, verticals only at the sign's real ends */
      g.lineStyle(1, C.trim, 1);
      g.lineBetween(sq[0].x,sq[0].y,sq[1].x,sq[1].y);
      g.lineBetween(sq[3].x,sq[3].y,sq[2].x,sq[2].y);
      if(a0 <= 4) g.lineBetween(sq[0].x,sq[0].y,sq[3].x,sq[3].y);
      if(a1 >= w-4) g.lineBetween(sq[1].x,sq[1].y,sq[2].x,sq[2].y);
    }
  }

  /* ---------- SPECIAL CORNER STORE (2026-08-06, "flag them for special
     stores ... corner facing door") ----------
     Every corner lot renders as a dedicated corner store: the street
     corner of the footprint is chamfered 45 degrees and the door sits
     ON the chamfer, facing the intersection -- with its own richer
     palette set, a taller parapet than the neighbouring frontage, a
     marquee sign board over the corner door, and display windows
     wrapped onto the side-street flank.
     Geometry runs in u: the mirrored along-edge coordinate with u=0
     ALWAYS the corner end (u = a when the corner is at the unit start,
     w - a when at the end), so one code path serves both mirror cases;
     slice windows map into u the same way. Draw order matches
     drawStoreUnit exactly (back, flanks, facade detail per body pass;
     roof last per slice) because that order is what makes the fixed
     iso camera resolve which wall wins. Under that camera a block's SE
     corner shows the chamfer door head-on, NE/SW are edge-on, NW is
     roof-side -- the same reality every facade in the city lives with. */
  drawCornerStoreUnit(g, ox, oy, dv, rv, w, seed, cornerAtStart, part='all', a0=0, a1=w){
    const rng = mulberry32(seed);
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    const cs = !!cornerAtStart;
    const Gu = (u,b,h) => G(cs ? u : w - u, b, h);
    const u0 = cs ? a0 : w - a1, u1 = cs ? a1 : w - a0;
    const inU = c => c >= u0 && (c < u1 || u1 >= w);
    const clipQU = (lo, hi, bOff, z0, z1, color, alpha) => {
      const q0 = Math.max(lo, u0), q1 = Math.min(hi, u1);
      if(q1 - q0 < 0.5) return;
      this.quadOn(g, [Gu(q0,bOff,z1),Gu(q1,bOff,z1),Gu(q1,bOff,z0),Gu(q0,bOff,z0)], color, alpha);
    };
    const C = CORNER_STORE_PALETTES[Math.floor(rng()*CORNER_STORE_PALETTES.length)];
    const D = STORE_DEPTH, CH = CORNER_CHAMFER;
    /* same bottom-up height stack as drawStoreUnit, then a taller
       parapet -- the corner store reads as the block's anchor. rng
       calls stay unconditional per the slice contract. */
    const kickH = 18;
    const dZ1 = DOOR_H*0.88;
    const winZ0 = kickH+2, winZ1 = dZ1 + 14 + rng()*16;
    const awnZ0 = winZ1+4, awnZ1 = awnZ0+18;
    const signZ0 = awnZ1+8, signZ1 = signZ0+16;
    const H = signZ1 + 30 + rng()*10;
    const sideWinN = 1 + Math.floor(rng()*2);
    /* chamfer face parameterization: s in [0,L] runs the face from
       (CH,0) to (0,-CH); `out` steps along the face's outward normal
       (-1,+1)/sqrt(2) in (u,b) -- toward the intersection -- giving the
       same layering offsets the flat facade gets from its b nudges. */
    const L = CH*Math.SQRT2;
    const FP = (s, out, h) => {
      const t = s/L;
      return Gu(CH*(1-t) - out*0.7071, -CH*t + out*0.7071, h);
    };
    const chamQ = (s0, s1, out, z0, z1, color, alpha) =>
      this.quadOn(g, [FP(s0,out,z1),FP(s1,out,z1),FP(s1,out,z0),FP(s0,out,z0)], color, alpha);
    /* static backface handling, lidNear-style normal test (the iso
       camera never rotates; the view direction is +x+y): chamSum > 0
       means the chamfer faces the camera -> full detail; == 0 means
       edge-on -> keep the notched silhouette but skip the protruding
       door/awning/marquee, which would otherwise float as slivers past
       an edge-on plane; < 0 means the whole front is camera-hidden
       (the facade is too, for both away corners -- checked per
       edge/mirror pair), so draw the plain un-notched box the camera
       actually sees, or the notch leaks lower walls through the roof. */
    const chamSum = ((cs ? -dv.x : dv.x) + rv.x) + ((cs ? -dv.y : dv.y) + rv.y);
    const chamAway = chamSum < -0.01, chamFront = chamSum > 0.01;
    const fTop = chamAway ? 0 : -CH;   // corner flank's street-side extent

    if(part !== 'roof'){
      /* back wall */
      clipQU(0, w, -D, 0, H, C.wallDk);
      /* far flank: plain cap against the neighbouring frontage */
      if(u1 >= w - 0.01){
        const r = [Gu(w,0,H),Gu(w,-D,H),Gu(w,-D,0),Gu(w,0,0)];
        this.quadOn(g, r, C.wallDk); this.edgeOn(g, r, C.trim, 1);
      }
      /* corner-side flank faces the perpendicular STREET: a display
         wall, not a cap -- lit tone, kick strip, its own windows run
         down the b axis */
      if(u0 <= 0.01){
        /* the display treatment only when this flank actually faces the
           camera: away-facing flank windows sit deeper than the roof's
           projected cover (a window pixel at depth |b| is roofed only
           for z >= H + |b| - D) and leak over the back wall otherwise.
           Same normal test as the chamfer; an away flank is a plain cap. */
        const flankVis = ((cs ? -dv.x : dv.x) + (cs ? -dv.y : dv.y)) > 0.01;
        const f = [Gu(0,fTop,H),Gu(0,-D,H),Gu(0,-D,0),Gu(0,fTop,0)];
        if(!flankVis){
          this.quadOn(g, f, C.wallDk); this.edgeOn(g, f, C.trim, 1);
        } else {
        this.quadOn(g, f, C.wallLt); this.edgeOn(g, f, C.trim, 1);
        this.quadOn(g, [Gu(-0.4,fTop-2,kickH),Gu(-0.4,-D+2,kickH),Gu(-0.4,-D+2,0),Gu(-0.4,fTop-2,0)], C.wallDk);
        const b0 = fTop-10, b1 = -D+10, span = b1-b0;
        for(let i=0;i<sideWinN;i++){
          const bc = b0 + span*(i+0.5)/sideWinN;
          const wHW = Math.min(26, Math.abs(span)/(sideWinN*2)-6);
          this.quadOn(g, [Gu(-0.4,bc-wHW-2,winZ1+2),Gu(-0.4,bc+wHW+2,winZ1+2),Gu(-0.4,bc+wHW+2,winZ0),Gu(-0.4,bc-wHW-2,winZ0)], C.trim);
          this.quadOn(g, [Gu(-0.5,bc-wHW,winZ1),Gu(-0.5,bc+wHW,winZ1),Gu(-0.5,bc+wHW,winZ0+2),Gu(-0.5,bc-wHW,winZ0+2)], 0x6b93a8);
          this.quadOn(g, [Gu(-0.55,bc-wHW+2,winZ1-3),Gu(-0.55,bc-2,winZ1-3),Gu(-0.55,bc-2,winZ0+5),Gu(-0.55,bc-wHW+2,winZ0+5)], 0x86adc0, 0.55);
        }
        }
      }
    }

    if(part !== 'body'){
      /* roof: the chamfer cuts the street corner off the slab. Street
         boundary bs(u) = min(0, u - CH); a slice straddling the kink
         splits into two exact quads instead of approximating it. */
      const bs = u => chamAway ? 0 : Math.min(0, u - CH);
      const roofQ = (q0, q1) => {
        if(q1 - q0 < 0.5) return;
        const R = [Gu(q0,bs(q0),H), Gu(q1,bs(q1),H), Gu(q1,-D,H), Gu(q0,-D,H)];
        this.quadOn(g, R, C.trim);
        g.lineStyle(1, C.wallDk, 1);
        g.lineBetween(R[0].x,R[0].y,R[1].x,R[1].y);
        g.lineBetween(R[3].x,R[3].y,R[2].x,R[2].y);
        if(q0 <= 0.01) g.lineBetween(R[0].x,R[0].y,R[3].x,R[3].y);
        if(q1 >= w - 0.01) g.lineBetween(R[1].x,R[1].y,R[2].x,R[2].y);
      };
      if(!chamAway && u0 < CH && u1 > CH){ roofQ(u0, CH); roofQ(CH, u1); }
      else roofQ(u0, u1);
    }
    if(part === 'roof') return;

    /* facade proper: from the chamfer edge to the far flank */
    clipQU(CH, w, 0.4, 0, H, C.wall);
    clipQU(CH, w, 0.42, H-8, H, C.trim);                 // parapet band
    clipQU(CH+1, w-2, 0.42, 0, kickH, C.wallDk);
    /* full display-glass run -- the corner store is all window */
    const gX0 = CH+8, gX1 = w-8;
    clipQU(gX0, gX1, 0.5, winZ0-3, winZ1+3, 0xd8d0bd);
    clipQU(gX0+2, gX1-2, 0.54, winZ0, winZ1, 0x6b93a8);
    clipQU(gX0+3, gX0+(gX1-gX0)*0.4, 0.55, winZ0+3, winZ1-3, 0x86adc0, 0.55);
    /* facade awning: solid palette canvas (stripes are the ordinary
       store's) with a trim bar over it */
    const aw0 = Math.max(CH-1, u0), aw1 = Math.min(w, u1);
    if(aw1 - aw0 > 0.5){
      this.quadOn(g, [Gu(aw0,0.5,awnZ1),Gu(aw1,0.5,awnZ1),Gu(aw1,0.7,awnZ0),Gu(aw0,0.7,awnZ0)], C.awn);
    }
    clipQU(CH-1, w, 0.42, awnZ1, awnZ1+3, C.trim);
    /* sign band along the facade */
    const sB0 = Math.max(CH+4, u0), sB1 = Math.min(w-4, u1);
    if(sB1 - sB0 > 0.5){
      const sq2 = [Gu(sB0,0.44,signZ1),Gu(sB1,0.44,signZ1),Gu(sB1,0.44,signZ0),Gu(sB0,0.44,signZ0)];
      this.quadOn(g, sq2, C.sign);
      g.lineStyle(1, C.trim, 1);
      g.lineBetween(sq2[0].x,sq2[0].y,sq2[1].x,sq2[1].y);
      g.lineBetween(sq2[3].x,sq2[3].y,sq2[2].x,sq2[2].y);
    }

    /* ---------- the chamfer: wall, corner door, marquee ----------
       discrete elements, assigned whole to the slice holding the face
       centre (u = CH/2), the same assignment rule doors already use */
    if(!chamAway && inU(CH*0.5)){
      chamQ(0, L, 0, 0, H, C.wall);
      chamQ(0, L, 0.3, H-8, H, C.trim);                  // parapet wraps the corner
      chamQ(0, 7, 0.3, 0, H-8, C.trim);                  // pilasters at both chamfer edges
      chamQ(L-7, L, 0.3, 0, H-8, C.trim);
      chamQ(7, L-7, 0.3, 0, kickH, C.wallDk);
      /* the corner door: glass double door + transom, centred on the face */
      const dW = Math.min(DOOR_W*0.78, L*0.56), s0 = (L-dW)/2, s1 = (L+dW)/2;
      if(chamFront){
      chamQ(s0-5, s1+5, 0.35, 0, 6, 0x9d9687);           // step
      chamQ(s0-3, s1+3, 0.4, 0, dZ1+14, C.trim);         // frame incl transom
      chamQ(s0, s1, 0.5, dZ1+2, dZ1+11, 0x86adc0, 0.9);  // transom light
      chamQ(s0, s1, 0.5, 0, dZ1, 0x6b93a8, 0.95);        // glass doors
      chamQ((s0+s1)/2 - 1, (s0+s1)/2 + 1, 0.55, 6, dZ1-4, C.trim); // meeting stile
      const kn = FP(s1-8, 0.6, dZ1*0.45);
      g.fillStyle(C.accent, 1); g.fillCircle(kn.x, kn.y, 2.6*this.K*0.42);
      /* awning over the door, matching the facade run */
      this.quadOn(g, [FP(-4,0.5,awnZ1),FP(L+4,0.5,awnZ1),FP(L+4,14,awnZ0),FP(-4,14,awnZ0)], C.awn);
      this.quadOn(g, [FP(-4,0.45,awnZ1+3),FP(L+4,0.45,awnZ1+3),FP(L+4,0.45,awnZ1),FP(-4,0.45,awnZ1)], C.trim);
      /* marquee sign board over the corner door */
      const sq = [FP(-6,0.6,signZ1+8),FP(L+6,0.6,signZ1+8),FP(L+6,0.6,signZ0),FP(-6,0.6,signZ0)];
      this.quadOn(g, sq, C.sign); this.edgeOn(g, sq, C.accent, 1);
      }
    }
  }

  drawWoodFence(g, ox, oy, dv, rv, w, a0=0, a1=w){
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    const inS = c => c >= a0 && (c < a1 || a1 >= w);
    const H = PERSON_H*0.8, wood = 0x9d7a4e, woodDk = 0x7c5f3c; // ~chest height on a real person
    const post = x => this.quadOn(g, [G(x-3,0.4,H+5),G(x+3,0.4,H+5),G(x+3,0.4,0),G(x-3,0.4,0)], woodDk);
    if(inS(2)) post(2);
    if(inS(Math.max(4,w-2))) post(Math.max(4,w-2));
    const rail = [G(a0,0.42,H),G(a1,0.42,H),G(a1,0.42,H-8),G(a0,0.42,H-8)];
    this.quadOn(g, rail, woodDk);
    const pickW = 7, gap = 5;
    for(let x = 8; x < w-6; x += pickW+gap){
      if(!inS(x + pickW/2)) continue;
      const p = [G(x,0.44,H+3),G(x+pickW,0.44,H+3),G(x+pickW,0.44,0),G(x,0.44,0)];
      this.quadOn(g, p, wood); g.lineStyle(1, woodDk, 0.4); g.strokePoints(p.map(pt=>new Phaser.Geom.Point(pt.x,pt.y)), true, true);
    }
  }

  drawChainFence(g, ox, oy, dv, rv, w, a0=0, a1=w){
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    const inS = c => c >= a0 && (c < a1 || a1 >= w);
    const H = PERSON_H*1.02, post = 0x74797d, mesh = 0x9aa0a4; // just over head height
    const postAt = x => { const p0=G(x,0.4,H), p1=G(x,0.4,0); g.lineStyle(3, post, 1); g.lineBetween(p0.x,p0.y,p1.x,p1.y); };
    if(inS(2)) postAt(2);
    if(inS(Math.max(4,w-2))) postAt(Math.max(4,w-2));
    const rail = G(a0,0.4,H), rail2 = G(a1,0.4,H);
    g.lineStyle(2, post, 1); g.lineBetween(rail.x, rail.y, rail2.x, rail2.y);
    /* diamond mesh: a clean cell-grid cross-hatch, cell size fixed so
       taller/wider fences get more cells instead of stretched diamonds */
    const cell = 16;
    const cols = Math.max(1, Math.round(w/cell));
    const rows = Math.max(1, Math.round(H/cell));
    g.lineStyle(1, mesh, 0.5);
    for(let c=0; c<cols; c++){
      const x0 = c*(w/cols), x1 = (c+1)*(w/cols);
      if(!inS((x0+x1)/2)) continue;
      for(let r=0; r<rows; r++){
        const z0 = r*(H/rows), z1 = (r+1)*(H/rows);
        const p00 = G(x0,0.42,z1), p11 = G(x1,0.42,z0);
        g.lineBetween(p00.x,p00.y,p11.x,p11.y);
        const p01 = G(x0,0.42,z0), p10 = G(x1,0.42,z1);
        g.lineBetween(p01.x,p01.y,p10.x,p10.y);
      }
    }
  }

  drawFenceGap(g, ox, oy, dv, rv, w, seed, a0=0, a1=w){
    if(w < 8) return;
    const rng = mulberry32(seed);
    if(rng() < 0.5) this.drawWoodFence(g, ox, oy, dv, rv, w, a0, a1);
    else this.drawChainFence(g, ox, oy, dv, rv, w, a0, a1);
  }

  /* address fallback for the rare f===1/f===2 delivery (see
     GOOD_LEG_HEADING / route.addressUsesGate): same fence style the
     generic cutaway already uses everywhere else on the map, spanning
     the full house-unit width, with a gap at the door's exact
     position so the customer still has a real threshold to walk
     through. Static gate posts frame the opening — unlike the real
     door, there's no swing animation yet; first pass, revisit once
     it's been seen on-device. */
  drawGateFence(g, ox, oy, dv, rv, w, gateCenterX, gateHalfW, seed){
    const rng = mulberry32(seed);
    const useWood = rng() < 0.5;
    const seg = (sox, soy, sw) => {
      if(sw < 4) return;
      if(useWood) this.drawWoodFence(g, sox, soy, dv, rv, sw);
      else this.drawChainFence(g, sox, soy, dv, rv, sw);
    };
    const gLo = Math.max(0, gateCenterX - gateHalfW);
    const gHi = Math.min(w, gateCenterX + gateHalfW);
    seg(ox, oy, gLo);
    seg(ox + dv.x*gHi, oy + dv.y*gHi, w - gHi);
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    const H = PERSON_H*0.8, woodDk = 0x7c5f3c;
    const post = x => this.quadOn(g, [G(x-3,0.4,H+5),G(x+3,0.4,H+5),G(x+3,0.4,0),G(x-3,0.4,0)], woodDk);
    post(gLo); post(gHi);
  }

  /* commercial swinging door — same SL-hinge-rotation technique as
     drawDoorAssembly, restyled as glass storefront (thin frame, glass
     pane, handle bar). CENTERED on the unit rather than replicating
     drawStoreUnit's randomized doorLeft/doorX: the real pickupSpot
     already anchors to the unit's center (pu.w/2), so centering here
     is what makes robot/door/worker all agree, instead of chasing the
     door's random position with the other two. Dial-bench approved in
     labs/pickup-lab.html. */
  drawShopDoor(g, ox, oy, dv, rv, doorMidX, doorW, dZ1, dz, theta){
    const D = SHOPDOOR_ART, hw = doorW/2;
    const G = (dx, dy, dzz) => this.W(ox + dv.x*(doorMidX+dx) + rv.x*dy, oy + dv.y*(doorMidX+dx) + rv.y*dy, dz+dzz);
    const cT = Math.cos(theta), sT = Math.sin(theta);
    const SL = (u, perp, dzz) => G(-hw + u*cT - perp*sT, perp*cT + u*sT, dzz);

    const trim = 3;
    const frameOuter = [G(-hw-trim,0.5,dZ1+trim), G(hw+trim,0.5,dZ1+trim), G(hw+trim,0.5,0), G(-hw-trim,0.5,0)];
    this.quadOn(g, frameOuter, D.frame);
    const frameTop = [G(-hw-trim,0.5,dZ1+trim), G(hw+trim,0.5,dZ1+trim), G(hw+trim,0.52,dZ1), G(-hw-trim,0.52,dZ1)];
    this.quadOn(g, frameTop, D.frameLt);

    const face = [SL(0,2.2,dZ1), SL(2*hw,2.2,dZ1), SL(2*hw,2.2,0), SL(0,2.2,0)];
    this.quadOn(g, face, D.glass, 0.88);
    this.edgeOn(g, face, D.frameDk, 1.2);
    const gloss = [SL(3,2.3,dZ1-4), SL(2*hw*0.4,2.3,dZ1-4), SL(2*hw*0.4,2.3,dZ1*0.4), SL(3,2.3,dZ1*0.4)];
    this.quadOn(g, gloss, D.glassHi, 0.35);

    const h0 = SL(2*hw-6, 2.6, dZ1*0.62), h1 = SL(2*hw-6, 2.6, dZ1*0.38);
    g.lineStyle(3, D.handle, 1);
    g.lineBetween(h0.x, h0.y, h1.x, h1.y);
    const hk = SL(2*hw-6, 2.6, dZ1*0.5);
    g.fillStyle(D.handleHi, 1);
    g.fillCircle(hk.x, hk.y, 1.5*this.K*0.5);
  }

  /* ================= PICKUP SHOP: the dropoff customer's walk played
     in reverse. Same anchoring as world.customer (shop edge, not the
     robot's own spot/heading — that was the earlier bug: he landed on
     top of the robot because he was positioned relative to it instead
     of to the shop) and the same dyStart/dyEnd row-offset math, so he
     idles a full row out from the shop wall facing straight down rv
     (which is what puts him facing the robot, since rv points off the
     edge toward the road same as the customer's does). The only real
     difference from the customer: walkT here is pickupWalk, which
     eases 1->0 (out -> back inside) once "go" is pressed, instead of
     0->1 (in -> out) as doorTheta opens. */
  /* takeout bag — brown kraft paper, simple box with a lighter top
     face and a fold-line accent to read as a folded/rolled closure
     rather than a flat rectangle. Split into two passes (top/handle
     vs body) so the caller can draw the top+handle mid-sequence
     (getting covered by the carrying arm specifically) and the
     front/side after (staying visible in front). Dial-bench approved
     in labs/pickup-lab.html. */
  bagCorners(cx, cy, cz, dv, rv){
    const B = BAG_ART, hw = B.w/2, hd = B.d/2;
    /* face visibility: dv/rv are already real world-space direction
       vectors, same as drawPersonHull's G() points — no drawAngle
       rotation belongs here either, same fix/same reasoning. */
    const faceDV = Math.sign(dv.x + dv.y) || 1;
    const faceRV = Math.sign(rv.x + rv.y) || 1;
    /* hang from a top handle point rather than sitting with its
       bottom at the hand — cz is the top (grip height), bag hangs
       down from there. */
    const corner = (sx, sy, sz) => this.W(cx + rv.x*sx*hw + dv.x*sy*hd, cy + rv.y*sx*hw + dv.y*sy*hd, cz - (1-sz)*B.h);
    return { corner, faceDV, faceRV };
  }

  drawBagTop(g, cx, cy, cz, dv, rv){
    const B = BAG_ART;
    const { corner } = this.bagCorners(cx, cy, cz, dv, rv);
    const top = [corner(-1,-1,1), corner(1,-1,1), corner(1,1,1), corner(-1,1,1)];
    this.quadOn(g, top, B.paperLt);
    this.edgeOn(g, top, B.foldLine, 1);
    const f0 = corner(-0.55,-0.55,1), f1 = corner(0.55,0.55,1);
    g.lineStyle(1.5, B.foldLine, 0.8);
    g.lineBetween(f0.x, f0.y, f1.x, f1.y);
  }

  drawBagBody(g, cx, cy, cz, dv, rv){
    const B = BAG_ART;
    const { corner, faceDV, faceRV } = this.bagCorners(cx, cy, cz, dv, rv);
    const front = [corner(faceRV,-1,1), corner(faceRV,1,1), corner(faceRV,1,0), corner(faceRV,-1,0)];
    const side = [corner(-1,faceDV,1), corner(1,faceDV,1), corner(1,faceDV,0), corner(-1,faceDV,0)];
    this.quadOn(g, side, B.paperDk);
    this.quadOn(g, front, B.paper);
  }

  drawPickupUnit(g, ox, oy, dv, rv, doorCenterX, seed, t){
    if(!this.route.pickupSpot) return;
    this.pickupDoorDV = dv; this.pickupDoorRV = rv;
    this.pickupDoorUX = ox; this.pickupDoorUY = oy; this.pickupDoorCenterX = doorCenterX;
    this.pickupWorkerSeed = (seed ^ 0x77b1) >>> 0;
    const walkT = this.pickupWalk;
    const dz = this.groundZ(this.route.pickupS);

    /* door draws every frame regardless of worker visibility — it has
       its own idle-closed resting state (doorSwing eases back to 0
       whenever state !== "play", same as normal storefronts look).
       Deferred to a callback now instead of drawing here immediately:
       once he's walking back in (dy goes negative — past the door
       plane), he needs to draw BEHIND the door, not always under it. */
    const unitW = doorCenterX*2;
    const doorW = Math.min(DOOR_W*0.72, unitW*0.3);
    const dZ1 = DOOR_H*0.88;
    const drawDoor = () => this.drawShopDoor(g, ox, oy, dv, rv, doorCenterX, doorW, dZ1, dz, this.doorSwing);

    /* stay visible until he's both arrived (walkT===0) AND the door has
       actually swung shut behind him — previously this cut him at
       walkT<=0.02 regardless of the door, so he could vanish while the
       door was still wide open. */
    if(walkT <= 0.001 && this.doorSwing <= 0.02){ drawDoor(); return; }

    const wrng = mulberry32(seed ^ 0x77b1);
    const wBuild = PEOPLE_BUILD[wrng()<0.5?0:1];
    const wSkin = PEOPLE_SKIN[Math.floor(wrng()*PEOPLE_SKIN.length)];
    const wShirt = PEOPLE_SHIRT[Math.floor(wrng()*PEOPLE_SHIRT.length)];
    const wPants = PEOPLE_PANTS[Math.floor(wrng()*PEOPLE_PANTS.length)];
    const wHair = PEOPLE_HAIR[Math.floor(wrng()*PEOPLE_HAIR.length)];
    const wShoe = PEOPLE_SHOE[Math.floor(wrng()*PEOPLE_SHOE.length)];

    const wu = 1 - Math.pow(1 - walkT, 2);
    /* MEET POINT, the dropoff treatment mirrored: the worker stands at
       the real door->robot line stopped 35 units short of the bin — not
       the old fixed dy (T2*2.1-50), which left an air gap the bag had
       to be TOSSED across. This close, the hand-to-bin pass reads as
       SETTING the bag in (on-device request). pickupSpot is where the
       robot is teleported at route load, so the meet is static and
       exact; correct in all 4 headings since it's a world vector. */
    const doorPx = ox + dv.x*doorCenterX, doorPy = oy + dv.y*doorCenterX;
    const spot = this.route.pickupSpot;
    let mvx = spot.x - doorPx, mvy = spot.y - doorPy;
    const meetDist = Math.hypot(mvx, mvy) || 1; mvx /= meetDist; mvy /= meetDist;
    /* 12 from CENTER (walked in from 35 -> 20 -> 12 on-device): his hull
       overlaps the shell's footprint slightly in plan, which in iso is
       exactly what "leaning over the open bin" looks like — the hand
       lands inside the mouth. */
    const meetX = spot.x - mvx*12, meetY = spot.y - mvy*12;
    const backX = doorPx - rv.x*30, backY = doorPy - rv.y*30;   // walk-back ends past the door plane
    const workerX = Phaser.Math.Linear(backX, meetX, wu), workerY = Phaser.Math.Linear(backY, meetY, wu);
    const dy = (workerX - doorPx)*rv.x + (workerY - doorPy)*rv.y;  // signed door-plane side (draw order below)
    const facingRobot = Math.atan2(mvy, mvx) - Math.PI/2;          // faces the BIN along the true approach
    /* flip to face the shop only once the WALK phase has actually
       begun (loadDone), not just state==="play" broadly — that raw
       state check would have flipped him the instant "go" was
       pressed, mid-loading, before he'd even placed the bag yet. */
    const thW = this.loadDone ? facingRobot + Math.PI : facingRobot;
    // idle/loading: faces the robot (rv). walking back: faces the shop (-rv) — reads as
    // walking AWAY once the walk phase starts, instead of backing up while still
    // staring at the robot. drawPersonHull's forward axis is (-sin,cos), not
    // (cos,sin), hence the -PI/2 on the base term.

    const moving = walkT > 0.02 && walkT < 0.98;
    const walkPhase = moving ? Math.sin(t*PEOPLE_ART.walkSpeed) : 0;
    const liftT = this.pickupLiftT || 0, released = !!this.pickupReleased, loadFrac = this.pickupLoadFrac || 0;

    /* bag: locked to the actual hand position (handWorldPos, same
       formula the arm is drawn with) while still held — including
       idle, so he's holding it from frame one at the natural resting
       height, not floating separately or popping in. Once released,
       it arcs from the exact point it left his hand to the bin.
       Position computed here, before the worker draws, so it's ready
       for the mid-sequence callback below (top face drawn between
       torso and the carrying arm, so only the arm covers it — not
       the whole silhouette, which nearly erased it entirely in an
       earlier version). */
    const bagVisible = !this.loadDone;
    let bagX, bagY, bagZ;
    if(bagVisible){
      /* holdFwd/holdDown taper with lift, same reasoning as the
         dropoff customer's catch: the offsets are LEG clearance for
         the resting pose, not part of the raised-arm geometry — at
         full extension they floated the bag past the fingertips.
         Idle stance (liftT=0) is pixel-identical to the approved
         look; only the mid-rise tracking tightens. */
      if(!released){
        const hp = this.handWorldPos(workerX, workerY, thW, wBuild, liftT);
        const taper = 1 - liftT;
        bagX = hp.x + rv.x*BAG_ART.holdFwd*taper; bagY = hp.y + rv.y*BAG_ART.holdFwd*taper; bagZ = hp.z - BAG_ART.holdDown*taper;
      } else {
        const hp = this.handWorldPos(workerX, workerY, thW, wBuild, 1);
        const releasePt = { x: hp.x, y: hp.y, z: hp.z };   // full reach: zero taper — departs exactly from the hand
        const arcT = Phaser.Math.Clamp((loadFrac - LOAD_ART.holdEnd) / (LOAD_ART.dropFrac - LOAD_ART.holdEnd), 0, 1);
        const botX = this.botX, botY = this.botY;
        /* target the MOUTH, not the torso: the old endpoint (center,
           z+26) sent the bag diving behind the body wall — and the
           robot draws after the world pass, so the shell painted over
           the final approach and the bag just vanished into the side
           (on-device: "doesn't look like it goes into the bin"). The
           bin's mouth is at the TOP of the shell under the open lid:
           land on its NEAR RIM (worker's side, 8 units in from the
           edge line) at rim height, so the whole drop stays visible
           until the lid closes over it. Arc height ∝ distance, with a
           floor so the crest always clears the rim. */
        const tvx = releasePt.x - botX, tvy = releasePt.y - botY;
        const td = Math.hypot(tvx, tvy) || 1;
        const rimX = botX + tvx/td*8, rimY = botY + tvy/td*8;
        const rimZ = this.botZ + 50;
        const arcHz = Math.max(6, Math.min(LOAD_ART.arcH, td * 0.3));
        bagX = Phaser.Math.Linear(releasePt.x, rimX, arcT);
        bagY = Phaser.Math.Linear(releasePt.y, rimY, arcT);
        bagZ = Phaser.Math.Linear(releasePt.z, rimZ, arcT) + Math.sin(arcT*Math.PI)*arcHz;
      }
    }

    const topCb = bagVisible ? () => this.drawBagTop(g, bagX, bagY, bagZ, dv, rv) : null;
    const drawWorker = () => {
      this.drawPersonHull(g, workerX, workerY, dz, thW, wBuild, wSkin, wShirt, wPants, wHair, wShoe, walkPhase, moving, 0, liftT, topCb);
      if(bagVisible) this.drawBagBody(g, bagX, bagY, bagZ, dv, rv);
    };

    /* which side of the door plane he's actually on decides draw
       order now, not a fixed sequence — same "compute it, don't
       hardcode it" idea as lidNear()/flagNear(), just answered with
       dy (already shop-local, already correct in all 4 orientations
       by construction) instead of a raw world x+y comparison, which
       flips sign depending on which way rv happens to point and gave
       the wrong answer on two of the four shop-facing directions when
       tried. Previously the door always painted first and he always
       painted over it, which only looked right while dy>=0 (still out
       front). Once "go" sends him walking back in past the door plane
       (dy<0), he needs to be the one that gets painted over instead. */
    if(dy < 0){ drawWorker(); drawDoor(); }
    else { drawDoor(); drawWorker(); }
  }

  /* what replaces a culled housing edge: one continuous fence spanning
     the whole edge (fences are paper-thin, no real depth into the
     block, so unlike houses they don't have a corner-overlap problem
     and can safely run edge-to-edge) — the grass stays, this is just
     the yard boundary instead of a row of houses. */
  drawSolidFenceRow(g, ox, oy, dv, rv, w, seed, a0=0, a1=w){
    const margin = T2*0.4, iw = w - margin*2;
    if(iw <= 0) return;
    /* translate the row-space slice window into the inset fence's own
       local coords so slicing composes with the margin shift */
    const wa0 = Math.max(0, a0 - margin), wa1 = Math.min(iw, a1 - margin);
    if(wa1 - wa0 < 0.5) return;
    this.drawWoodFence(g, ox+dv.x*margin, oy+dv.y*margin, dv, rv, iw, wa0, wa1);
  }

  /* what replaces a culled commercial edge: painted parking stalls
     along the curb, some occupied — reads as "customer parking for
     the shop you can't currently see the front of" rather than a
     dead gap in the street. */
  drawParkingRow(g, ox, oy, dv, rv, w, seed, t=0, forceN=0){
    /* nose-in, sized to the REAL car (CARC: 450 long x 180 wide).
       Two things fixed here after the first pass:
       1. Sign — every other block-wrap element treats NEGATIVE b as
          "into the block" (houses' back wall is at -D). The first
          version positioned stalls at POSITIVE b, which extended the
          whole lot outward onto the sidewalk/street instead of inward
          — not a sizing issue, a flipped sign.
       2. Position — stalls now start behind where the culled
          building's own footprint was (STORE_DEPTH+margin), not right
          at the edge line. Cars end up parked roughly where the house
          used to be, not on the sidewalk path the robot walks.
       3. Count — a small FIXED cluster (2-3), centered on the edge,
          instead of packing however many fit across the whole block
          face, which read as a parking garage rather than a few
          customer spots for one small business. */
    /* 4. Geometry — stall count, placement and nose-in facing now come
          from parkingStallsAt (see there). It consumes the SAME single
          rng draw this function used to make for nStalls, in the same
          place, so the occupancy rolls below still read the identical
          stream and every existing lot is unchanged. */
    const rng = mulberry32(seed);
    const row = parkingStallsAt({ ox, oy, dv, rv, len: w }, rng, forceN || undefined);
    if(!row) return [];
    const G = (a,b,h) => this.W(ox + dv.x*a + rv.x*b, oy + dv.y*a + rv.y*b, h);
    g.lineStyle(2, 0xf0ece0, 0.75);
    for(let i=0; i<=row.nStalls; i++){
      const x = row.startAlong + i*row.stallW;
      const a = G(x, row.depthNear, 1), b = G(x, row.depthFar, 1);
      g.lineBetween(a.x, a.y, b.x, b.y);
    }
    const cars = [];
    /* the crime scene supplies its own vehicles — no civilian occupancy
       roll here, so nothing parks on top of a cruiser */
    if(forceN) return cars;
    for(const st of row.stalls){
      if(rng() < 0.85){
        const kind = rng() < 0.75 ? "car" : "truck";
        cars.push({ x: st.x, y: st.y, fdir: st.fdir, kind });
      }
    }
    return cars;
  }

  drawBenchProp(g, x, y, dv){
    const rv = DIRV[(DIRV.indexOf(dv)+1)%4] || {x:-dv.y,y:dv.x};
    const B = BENCH_ART;
    const G = (a,b,h) => this.W(x + dv.x*a + rv.x*b, y + dv.y*a + rv.y*b, h);
    const hw = B.w/2;

    const legL = [G(-hw+4,0.3,B.seatH), G(-hw+4,0.3,0)];
    const legR = [G(hw-4,0.3,B.seatH), G(hw-4,0.3,0)];
    g.lineStyle(4, B.leg, 1);
    g.lineBetween(legL[0].x,legL[0].y,legL[1].x,legL[1].y);
    g.lineBetween(legR[0].x,legR[0].y,legR[1].x,legR[1].y);

    const seat = [G(-hw,0.4,B.seatH), G(hw,0.4,B.seatH), G(hw,0.15,B.seatH), G(-hw,0.15,B.seatH)];
    this.quadOn(g, seat, B.wood); this.edgeOn(g, seat, B.woodDk, 1);
    const seatFace = [G(-hw,0.4,B.seatH), G(hw,0.4,B.seatH), G(hw,0.4,B.seatH-4), G(-hw,0.4,B.seatH-4)];
    this.quadOn(g, seatFace, B.woodDk);

    const back = [G(-hw,0.42,B.seatH+B.backH), G(hw,0.42,B.seatH+B.backH), G(hw,0.42,B.seatH), G(-hw,0.42,B.seatH)];
    this.quadOn(g, back, B.woodLt); this.edgeOn(g, back, B.woodDk, 1);
    g.lineStyle(1, B.woodDk, 0.4);
    for(let i=1;i<3;i++){ const yy=B.seatH + B.backH*i/3; const a=G(-hw,0.42,yy), b=G(hw,0.42,yy); g.lineBetween(a.x,a.y,b.x,b.y); }
  }

  /* park/commercial scatter: real approved props (palm/planter), not
     lab placeholders — this.drawProp already handles both kinds.
     dv defaults to DIRV[0] for callers that don't care (commercial
     interior scatter, fully random placement, no nearby edge to
     stay parallel to). */
  scatterBlockProp(g, x, y, kind, t, dv=DIRV[0]){
    if(kind === "bench") this.drawBenchProp(g, x, y, dv);
    else this.drawProp(g, kind, x, y, t);
  }

  /* shared 4-edge descriptor — edges[0] is always the block's NORTH
     edge (dv=DIRV[0], outward rv=DIRV[3]). Used by queueing AND by the
     wall-fade system, which needs to single out just edges[0] without
     duplicating this construction a third time. */
  blockEdges(blk){ return blockEdgesOf(blk); }

  /* ---------- strip slicing (depth-sort rearchitecture, stage 1) ----------
     THE STRIP INVARIANT: no queue entry may span more world distance
     ALONG its edge than the unit is DEEP. With entries keyed at their
     footprint-center x+y, that single rule makes point-vs-box ordering
     exact for every heading (proved in labs/depth-sort.html — the
     valid key band for a slice [a0,a1] is (min-corner, max-corner)
     of the OPPOSITE depth corners, which is non-empty iff sliceW < D).
     This retires the whole-unit single-key sort that caused the
     recurring heading-dependent class: a person in front of a long
     facade's low-depth end used to lose to a unit keyed at its center.
     Houses/stores slice at T2 (< HOUSE_DEPTH/STORE_DEPTH = 3*T2, and
     T2 matches the siding-line cadence so seams land on existing art).
     Fences are paper-thin (D=0): their residual misorder window is
     sliceW/2 of CONTACT distance, so they slice at TILE to keep that
     window inside the collision slack that keeps entities off them.
     drawFn receives (g, t, a0, a1) — the slice window in unit-local a.
     Stage 2 (queue unification) builds on these fine keys; until then
     the pass structure around this is unchanged. */
  queueUnitStrips(vq, ux, uy, dv, rv, w, D, sliceW, drawFn){
    const n = Math.max(1, Math.ceil(w / sliceW));
    for(let i = 0; i < n; i++){
      const a0 = w*i/n, a1 = i === n-1 ? w : w*(i+1)/n, am = (a0+a1)/2;
      const cx = ux + dv.x*am + rv.x*(-D/2), cy = uy + dv.y*am + rv.y*(-D/2);
      vq.push({ depth: cx+cy, fn: (g,t) => drawFn(g, t, a0, a1) });
    }
  }

  queueHousingEdgeAt(vq, e, isAddressEdge=false, cornerSkip=null, trim=null){
    const eseed = ((Math.round(e.ox*3+e.dv.x)*7919) ^ (Math.round(e.oy*3+e.dv.y)*104729) ^ 0x9e3779b9) >>> 0;
    const units = packEdge(e.len, mulberry32(eseed));
    units.forEach((u, idx) => {
      const hx = e.ox + e.dv.x*(u.start + u.w/2), hy = e.oy + e.dv.y*(u.start + u.w/2);
      const hseed = ((Math.round(hx)*7919) ^ (Math.round(hy)*104729)) >>> 0;
      const ux = e.ox + e.dv.x*u.start, uy = e.oy + e.dv.y*u.start;
      const isAddress = isAddressEdge && idx === this.route.addressUnitIdx;
      const isGateMode = isAddress && this.route.addressUsesGate;
      if(cornerSkip && !isAddress && cornerSkip(hx, hy)) return;   // corner-loom trim
      if(isAddress){
        const doorCenterX = u.w/2;
        const dz = this.groundZ(this.route.doorS);
        this.addrDoorPos = { x: ux + e.dv.x*doorCenterX, y: uy + e.dv.y*doorCenterX, z: dz };
        this.addrDoorDV = e.dv; this.addrDoorRV = e.rv;
        this.addrDoorUX = ux; this.addrDoorUY = uy; this.addrDoorCenterX = doorCenterX;
        this.addrCustSeed = (hseed ^ 0x4c75) >>> 0;
        vq.push({ depth:hx+hy, fn:(g,t)=>{
          if(!isGateMode) this.drawHouseUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, true, 'body');
          /* gate mode draws the customer/bag on gFront instead of
             gWorld — gFront is structurally the one layer above the
             robot's own layer (used elsewhere for "hazards nearer the
             camera than the robot"), so this is what actually puts
             him in front of the robot rather than behind it. The
             fence/gate/mat stay on gWorld, unchanged. */
          const custG = isGateMode ? this.gFront : g;
          const drawDoorAndMat = isGateMode
            ? () => {
                this.drawGateFence(g, ux, uy, e.dv, e.rv, u.w, doorCenterX, GATE_HALF_W, hseed);
                this.drawMatQuad(g, ux, uy, e.dv, e.rv, doorCenterX, dz);
              }
            : () => {
                this.drawDoorAssembly(g, ux, uy, e.dv, e.rv, doorCenterX, dz, this.doorTheta);
                this.drawMatQuad(g, ux, uy, e.dv, e.rv, doorCenterX, dz);
              };
          /* world.customer: same design as prop.people via drawPersonHull().
             Walk path from the door lab: dyStart=4, dyEnd=T2-8 (stops near
             the mat's road-side edge), triggered by the door's own hinge
             angle. Position now anchored to the real house unit instead
             of a route-relative point. */
          const custSeed = (hseed ^ 0x4c75) >>> 0;
          const crng = mulberry32(custSeed);
          const cBuild = PEOPLE_BUILD[crng() < 0.5 ? 0 : 1];
          const cSkin = PEOPLE_SKIN[Math.floor(crng()*PEOPLE_SKIN.length)];
          const cShirt = PEOPLE_SHIRT[Math.floor(crng()*PEOPLE_SHIRT.length)];
          const cPants = PEOPLE_PANTS[Math.floor(crng()*PEOPLE_PANTS.length)];
          const cHair = PEOPLE_HAIR[Math.floor(crng()*PEOPLE_HAIR.length)];
          const cShoe = PEOPLE_SHOE[Math.floor(crng()*PEOPLE_SHOE.length)];
          const walkT = Phaser.Math.Clamp(this.doorTheta / DOOR_ART.openAngle, 0, 1);
          /* the customer now walks the full line from the door to the
             robot's actual stop (this.wonMeet, computed in the won
             timeline in drawRobot), instead of stopping at the mat's
             edge and lobbing the bag through the air. Walk-out and
             walk-back both run on distance-based clocks (wonOutFrac /
             wonWalk); facing comes from the real approach vector
             (wonMeetTh), flipped +PI on the way home. */
          const meet = this.wonMeet;
          /* gate mode: he's standing there waiting from the moment the
             gate is visible at all — there's no door to knock on, so
             "wait for the knock" doesn't apply the way it does for a
             real house. Door mode is completely untouched: still bails
             to door+mat only until winning starts, exactly as before. */
          if(!meet && !isGateMode){ drawDoorAndMat(); return; }
          const doorPx = ux + e.dv.x*doorCenterX, doorPy = uy + e.dv.y*doorCenterX;
          const startPx = doorPx + e.rv.x*4,   startPy = doorPy + e.rv.y*4;    // just outside the door
          /* gate mode walks much further back before he's "gone" — a
             real house wall hides him after 24 units; an open gate has
             nothing to hide behind, so it takes actual distance to
             read as having left the scene rather than just stopping
             short. First-pass distance, worth eyeballing on-device. */
          const backDist = isGateMode ? GATE_WALKOFF_DIST : 24;
          const backPx  = doorPx - e.rv.x*backDist,  backPy  = doorPy - e.rv.y*backDist;
          const outFrac = this.wonOutFrac || 0;
          const wonWalk = this.state === "won" ? (this.wonWalk || 0) : 0;
          const inWalkBack = wonWalk > 0;
          /* doorTheta (the hinge angle) is meaningless for a gate — nothing
             ever opens it — so gate mode drops that half of the check. */
          const goneInside = inWalkBack && wonWalk >= 0.999 && (isGateMode || this.doorTheta <= 0.02);
          const custVisible = isGateMode ? !goneInside : (!goneInside && (inWalkBack || outFrac > 0.001));
          if(!custVisible){ drawDoorAndMat(); return; }
          let cx, cy, thW, moving;
          if(!meet){
            /* gate mode only, pre-win: static wait, facing out through
               the gate toward the street. */
            cx = startPx; cy = startPy; thW = Math.atan2(e.rv.y, e.rv.x); moving = false;
          } else if(inWalkBack){
            const wu2 = 1 - Math.pow(1 - wonWalk, 2);
            cx = Phaser.Math.Linear(meet.x, backPx, wu2);
            cy = Phaser.Math.Linear(meet.y, backPy, wu2);
            thW = this.wonMeetTh + Math.PI;                 // faces home
            moving = wonWalk > 0.02 && wonWalk < 0.98;
          } else {
            const wu = 1 - Math.pow(1 - outFrac, 2);
            cx = Phaser.Math.Linear(startPx, meet.x, wu);
            cy = Phaser.Math.Linear(startPy, meet.y, wu);
            thW = this.wonMeetTh;                           // faces the robot
            moving = outFrac > 0.02 && outFrac < 0.98;
          }
          /* signed distance from the door plane, along rv — the same
             computed draw-order test as before, now taken from his
             actual position since the path is no longer a pure rv line. */
          const dy = (cx - doorPx)*e.rv.x + (cy - doorPy)*e.rv.y;
          const walkPhase = moving ? Math.sin(t*PEOPLE_ART.walkSpeed) : 0;
          /* dropoff bag: the pickup's arc run in reverse — rises out
             of the bin (same z-26 grip height the worker dropped it
             to) and flies to where the customer's hand WILL be at
             full reach, not where the mid-rise hand currently is,
             then locks to the hand while his arm eases back down and
             stays there for the whole carry back inside. Timeline
             values come from the won-handoff block in drawRobot
             (this.wonFrac / this.wonLiftT) — the same "compute in
             drawRobot, read in the world draw" pattern drawPickupUnit
             already uses. Same interleave as the worker too: bag top
             via the onBeforeCarryArm callback (so only the carrying
             arm covers it), body after. */
          const liftT = this.wonLiftT || 0;
          const wonFrac = this.wonFrac || 0;
          let bagVisible = false, bagX, bagY, bagZ;
          if(this.state === "won" && wonFrac > LOAD_ART.holdEnd){
            bagVisible = true;
            /* the catch point is the bare hand at full reach — the
               holdFwd/holdDown offsets are worker-only (his dialed
               "presenting it out in front" pose); the customer's bag
               targets and rides the hand itself. */
            if(wonFrac < LOAD_ART.dropFrac){
              const arcT = (wonFrac - LOAD_ART.holdEnd) / (LOAD_ART.dropFrac - LOAD_ART.holdEnd);
              const hp1 = this.handWorldPos(cx, cy, thW, cBuild, 1);   // catch point: full reach, zero taper
              /* arc height scales with the flight distance now that he
                 stands right at the bin — a fixed 26-unit loop over a
                 ~40-unit pass read as a moon shot. */
              const arcHz = Math.min(LOAD_ART.arcH, Math.hypot(this.botX - cx, this.botY - cy) * 0.3);
              bagX = Phaser.Math.Linear(this.botX, hp1.x, arcT);
              bagY = Phaser.Math.Linear(this.botY, hp1.y, arcT);
              bagZ = Phaser.Math.Linear(this.botZ + 26, hp1.z, arcT) + Math.sin(arcT*Math.PI)*arcHz;
            } else {
              /* held: locked EXACTLY to the hand — no holdFwd/holdDown
                 at all. Those offsets are the WORKER's dialed
                 "presenting the delivery out in front" pose; the
                 customer just carries it, so it rides the hand down
                 the whole descent and settles hanging at his SIDE
                 (hand at rest sits below the shoulder on his flank,
                 bag hangs from the grip). Draws after the hull, so
                 it reads in front of the near leg, like a carried
                 bag brushing it. Through the turn-around, thW's flip
                 moves hand and bag together — it stays in his grip. */
              const hp = this.handWorldPos(cx, cy, thW, cBuild, liftT);
              bagX = hp.x; bagY = hp.y; bagZ = hp.z;
            }
          }
          const topCb = bagVisible ? () => this.drawBagTop(custG, bagX, bagY, bagZ, e.dv, e.rv) : null;
          const drawCust = () => {
            this.drawPersonHull(custG, cx, cy, dz, thW, cBuild, cSkin, cShirt, cPants, cHair, cShoe, walkPhase, moving, 0, liftT, topCb);
            if(bagVisible) this.drawBagBody(custG, bagX, bagY, bagZ, e.dv, e.rv);
          };
          /* which side of the door plane he's on decides draw order —
             same computed test as the pickup worker (his dy<0 branch):
             once he's back through the doorway he draws BEHIND the
             door/mat, not painted over them. */
          if(dy < 0){ drawCust(); drawDoorAndMat(); }
          else { drawDoorAndMat(); drawCust(); }
        }});
        vq.push({ depth:hx+hy, isRoof:true, fn:(g)=>{ if(!isGateMode) this.drawHouseUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, true, 'roof'); } });
      } else if(isAddressEdge && this.route.addressUsesGate){
        /* every OTHER house packed on the gate's own edge — the address
           unit above already got its own gate via isGateMode, but this
           edge's blanket exemption from cutEdges (needed so that gate
           can render at all) meant every neighboring house on the same
           edge was still drawing as a full, un-cut house right next to
           it, on a heading where the cutaway exists specifically
           because that's not safe. Fence them too, same as the generic
           cutaway would if this edge weren't specially exempted. */
        this.queueUnitStrips(vq, ux, uy, e.dv, e.rv, u.w, 0, TILE, (g,t,a0,a1)=>this.drawFenceGap(g, ux, uy, e.dv, e.rv, u.w, hseed, a0, a1));
      } else {
        /* body then roof per slice, preserving the old body→roof paint
           order within each strip; the fine per-strip keys replace the
           globally-last roof pass for every generic unit */
        this.queueUnitStrips(vq, ux, uy, e.dv, e.rv, u.w, HOUSE_DEPTH, T2, (g,t,a0,a1)=>{
          this.drawHouseUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, false, 'body', a0, a1);
          this.drawHouseUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, false, 'roof', a0, a1);
        });
      }
    });
    for(const gp of gapsFromUnits(units, e.len)){
      /* corner-lot trim: a corner unit now sits on this edge's own line
         inside the head/tail cornerMargin these gaps otherwise cover --
         clip the fence span so it never draws across that facade */
      let g0 = gp.start, g1 = gp.start + gp.w;
      if(trim){ g0 = Math.max(g0, trim[0]); g1 = Math.min(g1, e.len - trim[1]); }
      if(g1 - g0 < 2) continue;
      const gw = g1 - g0;
      const gx = e.ox + e.dv.x*(g0+gw/2), gy = e.oy + e.dv.y*(g0+gw/2);
      const gseed = ((Math.round(gx)*7919) ^ (Math.round(gy)*104729) ^ 0x2f6c) >>> 0;
      const fx = e.ox + e.dv.x*g0, fy = e.oy + e.dv.y*g0;
      this.queueUnitStrips(vq, fx, fy, e.dv, e.rv, gw, 0, TILE, (g,t,a0,a1)=>this.drawFenceGap(g, fx, fy, e.dv, e.rv, gw, gseed, a0, a1));
    }
  }
  /* which of a block's four corner units actually draw. A corner unit
     hugs BOTH of its streets by construction, so a cut on EITHER
     adjoining edge suppresses it -- tested against excludeEdges
     directly, NOT via cornerSkip: CORNER_TRIM (420) is measured from
     the grid lines while block content starts inset (736) from them,
     so that closure's thresholds are unreachable for any unit center
     and it cannot be relied on here (reported separately, not fixed
     in this change). */
  liveCornerUnits(blk, excludeEdges){
    const out = [];
    for(const cu of cornerUnitsOf(blk)){
      if(excludeEdges && cu.adjEdges.some(a => excludeEdges.includes(a))) continue;
      out.push(cu);
    }
    return out;
  }
  queueCornerUnit(vq, blk, cu){
    const hseed = ((Math.round(cu.hx)*7919) ^ (Math.round(cu.hy)*104729)) >>> 0;
    /* every corner lot is a SPECIAL corner store, both districts -- the
       classic neighbourhood corner store -- with its chamfered door
       facing the intersection (drawCornerStoreUnit). cu.kind carries
       the "cornerStore" flag for future systems (names, unlocks). */
    this.queueUnitStrips(vq, cu.ux, cu.uy, cu.e.dv, cu.e.rv, cu.w, STORE_DEPTH, T2, (g,t,a0,a1)=>{
      this.drawCornerStoreUnit(g, cu.ux, cu.uy, cu.e.dv, cu.e.rv, cu.w, hseed, cu.atStart, 'body', a0, a1);
      this.drawCornerStoreUnit(g, cu.ux, cu.uy, cu.e.dv, cu.e.rv, cu.w, hseed, cu.atStart, 'roof', a0, a1);
    });
  }
  queueHousingBlock(vq, blk, excludeEdges=null, cornerSkip=null){
    const isAddressBlock = (blk === this.route.addressBlock);
    const corners = this.liveCornerUnits(blk, excludeEdges);
    /* per-edge [head, tail] fence-gap clip for the surviving corners */
    const trims = [[0,0],[0,0],[0,0],[0,0]];
    for(const cu of corners) trims[cu.edgeIdx][cu.atStart ? 0 : 1] = CORNER_LOT_INSET + cu.w;
    this.blockEdges(blk).forEach((e, idx) => {
      if(excludeEdges && excludeEdges.includes(idx)) return;
      this.queueHousingEdgeAt(vq, e, isAddressBlock && idx === this.route.addressEdgeIdx, cornerSkip, trims[idx]);
    });
    for(const cu of corners) this.queueCornerUnit(vq, blk, cu);
    this.queueStreetFurniture(vq, blk, excludeEdges);
  }

  queueCommercialEdgeAt(vq, e, isPickupEdge=false, cornerSkip=null){
    const eseed = ((Math.round(e.ox*3+e.dv.x)*7919) ^ (Math.round(e.oy*3+e.dv.y)*104729) ^ 0x51b3) >>> 0;
    const units = packEdgeNoGap(e.len, mulberry32(eseed));
    units.forEach((u, idx) => {
      const hx = e.ox + e.dv.x*(u.start + u.w/2), hy = e.oy + e.dv.y*(u.start + u.w/2);
      const hseed = ((Math.round(hx)*7919) ^ (Math.round(hy)*104729)) >>> 0;
      const ux = e.ox + e.dv.x*u.start, uy = e.oy + e.dv.y*u.start;
      const isFirst = idx===0, isLast = idx===units.length-1;
      const isPickup = isPickupEdge && idx === this.route.pickupUnitIdx;
      if(cornerSkip && !isPickup && cornerSkip(hx, hy)) return;    // corner-loom trim
      if(isPickup){
        /* pickup unit stays whole: its body entry is entangled with the
           worker/loading choreography (drawPickupUnit) — extracting the
           worker to his own strip-keyed entry is stage 2. The CLEAR
           sweep keeps hazards away from it meanwhile. */
        vq.push({ depth:hx+hy, fn:(g,t)=>{
          this.drawStoreUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, isFirst, isLast, 'body',
                             0, u.w, { noDoor:true });
          this.drawPickupUnit(g, ux, uy, e.dv, e.rv, u.w/2, hseed, t);
        }});
        vq.push({ depth:hx+hy, isRoof:true, fn:(g)=>this.drawStoreUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, isFirst, isLast, 'roof') });
      } else {
        this.queueUnitStrips(vq, ux, uy, e.dv, e.rv, u.w, STORE_DEPTH, T2, (g,t,a0,a1)=>{
          this.drawStoreUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, isFirst, isLast, 'body', a0, a1);
          this.drawStoreUnit(g, ux, uy, e.dv, e.rv, u.w, hseed, isFirst, isLast, 'roof', a0, a1);
        });
      }
    });
  }
  /* ---------- commercial interior fill (2026-08-06, "commercial
     buildings should fill in the center of the block") ----------
     1-2 bigger standalone stores in the block's middle. The perimeter
     ring (edge + corner units) reaches cornerMargin in from the block
     line on every side; INTERIOR ring insets one further tile so a
     plaza walkway always separates ring and interior. Facing is a
     seeded cardinal pick using blockEdgesOf's own dv/rv pairing
     (rv = DIRV[(f+3)%4]), rendered through queueUnitStrips like every
     other store so depth sorting stays strip-exact on all four
     headings. Two-building days split the interior in halves along a
     seeded axis, one building per half, so they cannot overlap by
     construction. The crime block skips interior fill entirely: the
     scene owns that block's open ground (cordon, officer patrols) and
     nothing new should land inside it. Returns the placed footprint
     rects so the planter/bench scatter can dodge them. */
  queueCommercialInterior(vq, blk){
    const r = this.route;
    if(r.crime && r.crime.blockKey === (blk.i + "," + blk.j)) return [];
    const RING = HOUSE_DEPTH + T2*0.3 + T2;      // perimeter units' reach + one-tile walkway
    const ix0 = blk.x0 + RING, ix1 = blk.x1 - RING;
    const iy0 = blk.y0 + RING, iy1 = blk.y1 - RING;
    if(ix1 - ix0 < T2*4 || iy1 - iy0 < T2*4) return [];
    const rng = mulberry32(((Math.round((blk.x0+blk.x1)/2)*7919) ^ (Math.round((blk.y0+blk.y1)/2)*104729) ^ 0x1c7b) >>> 0);
    const n = rng() < 0.45 ? 1 : 2;
    const splitX = rng() < 0.5;                   // two-building days: halve along x or y
    const rects = [];
    for(let k = 0; k < n; k++){
      const D = STORE_DEPTH;
      const f = Math.floor(rng()*4);
      const dv = DIRV[f], rv = DIRV[(f+3)%4];
      /* placement window: whole interior for one building, its own half
         (split at the interior midline) when there are two */
      let wx0 = ix0, wx1 = ix1, wy0 = iy0, wy1 = iy1;
      if(n === 2){
        if(splitX){ if(k === 0) wx1 = (ix0+ix1)/2; else wx0 = (ix0+ix1)/2; }
        else      { if(k === 0) wy1 = (iy0+iy1)/2; else wy0 = (iy0+iy1)/2; }
      }
      const along = dv.x !== 0 ? wx1-wx0 : wy1-wy0;   // window extent on the facade axis
      const cross = dv.x !== 0 ? wy1-wy0 : wx1-wx0;
      if(along < T2*2 || cross < D) continue;         // degenerate window only
      /* wider than a street storefront -- it anchors the plaza. Clamped
         to its own window: the first cut DROPPED oversized rolls here,
         and the measured fill came out 1.30 buildings/block against the
         1.55 the n-roll implies (two-building halves are ~432 wide vs a
         506 max roll) -- including possible zero-building two-days.
         Clamping places every rolled building at the size that fits. */
      const w = Math.min(T2*(3.5 + rng()*2), along);
      const hx2 = (dv.x !== 0 ? w : D)/2, hy2 = (dv.y !== 0 ? w : D)/2;  // axis-aligned half-extents
      const bcx = wx0 + hx2 + rng()*((wx1-wx0) - hx2*2);
      const bcy = wy0 + hy2 + rng()*((wy1-wy0) - hy2*2);
      const ux = bcx + rv.x*(D/2) - dv.x*(w/2), uy = bcy + rv.y*(D/2) - dv.y*(w/2);
      const hseed = ((Math.round(bcx)*7919) ^ (Math.round(bcy)*104729) ^ 0x5e21) >>> 0;
      this.queueUnitStrips(vq, ux, uy, dv, rv, w, D, T2, (g,t,a0,a1)=>{
        this.drawStoreUnit(g, ux, uy, dv, rv, w, hseed, true, true, 'body', a0, a1);
        this.drawStoreUnit(g, ux, uy, dv, rv, w, hseed, true, true, 'roof', a0, a1);
      });
      rects.push({ x0: bcx-hx2, x1: bcx+hx2, y0: bcy-hy2, y1: bcy+hy2 });
    }
    return rects;
  }
  queueCommercialBlock(vq, blk, excludeEdges=null, cornerSkip=null){
    const isPickupBlock = (blk === this.route.pickupBlock);
    this.blockEdges(blk).forEach((e, idx) => {
      if(excludeEdges && excludeEdges.includes(idx)) return;
      this.queueCommercialEdgeAt(vq, e, isPickupBlock && idx === this.route.pickupEdgeIdx, cornerSkip);
    });
    for(const cu of this.liveCornerUnits(blk, excludeEdges)) this.queueCornerUnit(vq, blk, cu);
    const interior = this.queueCommercialInterior(vq, blk);
    const cx = (blk.x0+blk.x1)/2, cy = (blk.y0+blk.y1)/2;
    const rng = mulberry32(((Math.round(cx)*7919) ^ (Math.round(cy)*104729) ^ 0x71c4) >>> 0);
    /* scatter now dodges the interior footprints: same seed and call
       order as before, each piece just re-rolls (bounded) until it
       lands clear -- deterministic per block, retries included */
    const clear = (x,y) => !interior.some(rc => x > rc.x0-30 && x < rc.x1+30 && y > rc.y0-30 && y < rc.y1+30);
    const roll = () => {
      for(let tr = 0; tr < 6; tr++){
        const x = blk.x0 + rng()*(blk.x1-blk.x0), y = blk.y0 + rng()*(blk.y1-blk.y0);
        if(clear(x, y)) return { x, y };
      }
      return null;
    };
    const nPlanter = 2 + Math.floor(rng()*2);
    for(let k=0;k<nPlanter;k++){
      const sp = roll(); if(!sp) continue;
      vq.push({ depth:sp.x+sp.y, fn:(g,t)=>this.scatterBlockProp(g, sp.x, sp.y, "planter", t) });
    }
    const nBench = 1 + Math.floor(rng()*2);
    for(let k=0;k<nBench;k++){
      const sp = roll(); if(!sp) continue;
      vq.push({ depth:sp.x+sp.y, fn:(g,t)=>this.scatterBlockProp(g, sp.x, sp.y, "bench", t) });
    }
    this.queueStreetFurniture(vq, blk, excludeEdges);
  }

  queueParkBlock(vq, blk){
    const rng = mulberry32(((Math.round((blk.x0+blk.x1)/2)*7919) ^ (Math.round((blk.y0+blk.y1)/2)*104729) ^ 0x50a2) >>> 0);
    /* clusters, not isolated single trees — real palms/dwarf palms
       (both already exist as approved props, height ratio ~3x) mixed
       in per-tree, with each cluster member independently offset so
       drawProp's own position-seeded height jitter (±15%) gives
       natural variety within a group too, not just between groups. */
    const nClusters = 2 + Math.floor(rng()*3);
    for(let k=0;k<nClusters;k++){
      const cx = blk.x0 + rng()*(blk.x1-blk.x0), cy = blk.y0 + rng()*(blk.y1-blk.y0);
      const sizeRoll = rng();
      const clusterSize = sizeRoll < 0.5 ? 1 : sizeRoll < 0.8 ? 2 : 3;
      for(let m=0; m<clusterSize; m++){
        const tx = cx + (rng()-0.5)*T2*1.2, ty = cy + (rng()-0.5)*T2*1.2;
        const kind = rng() < 0.3 ? "palm" : "palmDwarf"; // occasional tall accent tree
        vq.push({ depth:tx+ty, fn:(g,t)=>this.scatterBlockProp(g, tx, ty, kind, t) });
      }
    }
    const nBench = 1 + Math.floor(rng()*2);
    for(let k=0;k<nBench;k++){
      const edge = Math.floor(rng()*4), tt = 0.2+rng()*0.6;
      let x,y;
      /* bench half-width is ~80 units (PERSON_H*1.3/2) -- the 14-unit
         inward offset only keeps it clear of the boundary along the
         SHORT axis (seat depth, under 1 unit). The long axis has to
         run parallel to whichever edge it's near, or it punches
         straight through onto the sidewalk on the other side. Top/
         bottom edges want it horizontal (DIRV[0]); left/right want
         it vertical (DIRV[1]) -- swapped from each other, not the
         same orientation everywhere. */
      let dv;
      if(edge===0){ x = blk.x0+(blk.x1-blk.x0)*tt; y = blk.y0+14; dv = DIRV[0]; }
      else if(edge===1){ x = blk.x1-14; y = blk.y0+(blk.y1-blk.y0)*tt; dv = DIRV[1]; }
      else if(edge===2){ x = blk.x0+(blk.x1-blk.x0)*tt; y = blk.y1-14; dv = DIRV[0]; }
      else { x = blk.x0+14; y = blk.y0+(blk.y1-blk.y0)*tt; dv = DIRV[1]; }
      vq.push({ depth:x+y, fn:(g,t)=>this.scatterBlockProp(g, x, y, "bench", t, dv) });
    }
    this.queueStreetFurniture(vq, blk);
  }

  fillBlockGround(g, blk){
    if(blk.type === "park"){
      this.fillBlockInterior(g, blk, GRASS);
      if(WORLDGEN_COAST && !this.route.grid.classic && blk.i !== undefined){
        /* merged parks: the grass owns the street it swallowed. Each
           park block extends only toward its +x/+y park neighbours —
           one owner per strip, drawn once — and takes the intersection
           square only when the diagonal is park too, i.e. only when all
           the roads around that corner are actually gone. This runs
           AFTER the road pass, so painting anywhere a street survived
           would paint over asphalt; the conditions make that impossible
           rather than unlikely. */
        const M = this.route.grid.blockByIJ;
        const pk = b => b && b.type === "park";
        const nx = M && M.get((blk.i+1) + "," + blk.j);
        const ny = M && M.get(blk.i + "," + (blk.j+1));
        const nd = M && M.get((blk.i+1) + "," + (blk.j+1));
        if(pk(nx)) this.fillBlockInterior(g, { ...blk, x0:blk.x1, x1:nx.x0 }, GRASS);
        if(pk(ny)) this.fillBlockInterior(g, { ...blk, y0:blk.y1, y1:ny.y0 }, GRASS);
        if(pk(nx) && pk(ny) && pk(nd))
          this.fillBlockInterior(g, { ...blk, x0:blk.x1, x1:nx.x0, y0:blk.y1, y1:ny.y0 }, GRASS);
      }
      return;
    }
    if(blk.type === "commercial") return this.fillBlockInterior(g, blk, PLAZA);
    this.fillBlockInterior(g, blk, GRASS); // housing yard
  }
  queueBlockContent(vq, blk, excludeEdges=null){
    if(blk.type === "park") return this.queueParkBlock(vq, blk);
    /* corner-loom trim: cutting a street-facing edge removes ITS units,
       but the perpendicular edges' corner-most units still hug that
       same street and loom over the walk near block ends (reported on
       f=1). Suppress any unit whose center falls within CORNER_TRIM of
       a cut street line — a world-space test, so it's correct for
       every cut edge and heading by construction. The pickup and
       address units are immune (guarded at the unit loops), matching
       the cutEdges guards. */
    let cornerSkip = null;
    if(excludeEdges && excludeEdges.length){
      const CORNER_TRIM = 420;
      const x0 = blk.i*BLOCK, x1 = (blk.i+1)*BLOCK, y0 = blk.j*BLOCK, y1 = (blk.j+1)*BLOCK;
      cornerSkip = (hx, hy) => excludeEdges.some(e2 =>
        (e2 === 0 && hy < y0 + CORNER_TRIM) ||
        (e2 === 2 && hy > y1 - CORNER_TRIM) ||
        (e2 === 3 && hx < x0 + CORNER_TRIM) ||
        (e2 === 1 && hx > x1 - CORNER_TRIM));
    }
    if(blk.type === "commercial") return this.queueCommercialBlock(vq, blk, excludeEdges, cornerSkip);
    this.queueHousingBlock(vq, blk, excludeEdges, cornerSkip);
  }

  /* ---------- STREET FURNITURE, every block, every frontage ----------
     Runs for housing/commercial/park alike (park calls it too, from
     queueParkBlock). Placement is world-seeded off the block corner via
     mulberry32, the same discipline every other prop uses, so a block
     furnishes identically every frame and every session with no stored
     state -- and neighbouring blocks differ because their seeds do.

     Furniture sits on the VERGE: just inside the block boundary, on the
     grass/plaza strip between the sidewalk and the fence line, which is
     where this stuff lives in a real street and, more usefully, where it
     cannot be confused for something the robot is meant to dodge.

     Two hard exclusions, both load-bearing:
       - routeCells, so nothing decorative lands within reach of the robot
         (it has no collision -- see the routeCells comment)
       - cut edges, whose units are already suppressed so the walk isn't
         loomed over; putting a lamp back on that verge would re-create
         the occlusion the cut exists to remove

     Depth keys are the item's own x+y, so each piece sorts individually
     against houses, fences and the robot -- not batched. */
  queueStreetFurniture(vq, blk, excludeEdges = null){
    const cells = this.route && this.route.routeCells;
    const rng = mulberry32(((Math.round(blk.x0)*2654435761) ^ (Math.round(blk.y0)*40503) ^ 0x9e37) >>> 0);
    /* per-type character: what a block's frontage is actually made of */
    const MENU = {
      housing:    [["lamp",0.20],["palmDwarf",0.30],["bin",0.16],["planter",0.14],["hydrant",0.10],["trash",0.10]],
      commercial: [["lamp",0.26],["planter",0.24],["bench",0.16],["bin",0.14],["hydrant",0.10],["cone",0.10]],
      park:       [["palmDwarf",0.34],["palm",0.20],["bench",0.18],["planter",0.16],["lamp",0.12]]
    };
    const menu = MENU[blk.type] || MENU.housing;
    const pick = () => {
      let r = rng();
      for(const [k, w] of menu){ if(r < w) return k; r -= w; }
      return menu[0][0];
    };
    const VERGE = 46;          // inset from the block line, on the grass strip
    blockEdgesOf(blk).forEach((e, idx) => {
      if(excludeEdges && excludeEdges.includes(idx)) return;
      /* one piece per ~250 units of frontage, jittered, so a long edge
         reads as furnished rather than as a repeating pattern */
      const n = Math.max(1, Math.round(e.len/FURNISH_SPACING));
      for(let i = 0; i < n; i++){
        if(rng() < FURNISH_GAP) continue;               // gaps: not every slot fills
        const a = e.len*(i + 0.15 + rng()*0.7)/n;
        const d = VERGE + rng()*34;
        const x = e.ox + e.dv.x*a - e.rv.x*d;
        const y = e.oy + e.dv.y*a - e.rv.y*d;
        if(cells && cells.has(Math.round(x/FURNISH_CELL) + "," + Math.round(y/FURNISH_CELL))) continue;
        const kind = pick();
        /* benches need an orientation or their long axis punches through
           the fence -- same reasoning queueParkBlock already documents.
           Everything else is radially symmetric enough not to care. */
        if(kind === "bench"){
          const bdv = e.dv;
          vq.push({ depth:x+y, fn:(g,t)=>this.scatterBlockProp(g, x, y, "bench", t, bdv) });
        } else {
          const f = idx;   // face the street the piece stands on
          vq.push({ depth:x+y, fn:(g,t)=>this.drawProp(g, kind, x, y, t, f) });
        }
      }
    });
  }

  fillExteriorLot(g, lot){
    if(lot.type === "park"){
      const rect = lotRect(lot.ox, lot.oy, lot.dv, lot.rv, lot.len, EXT_PARK_DEPTH);
      return this.fillBlockInterior(g, rect, GRASS);
    }
    const rect = lotRect(lot.ox, lot.oy, lot.dv, lot.rv, lot.len, EXT_YARD_DEPTH);
    this.fillBlockInterior(g, rect, lot.type === "commercial" ? PLAZA : GRASS);
  }
  queueExteriorLot(vq, lot){
    if(lot.type === "park"){
      const rect = lotRect(lot.ox, lot.oy, lot.dv, lot.rv, lot.len, EXT_PARK_DEPTH);
      return this.queueParkBlock(vq, rect);
    }
    const faceIn = { x:-lot.rv.x, y:-lot.rv.y }; // body sits outside the grid, front faces back IN toward the sidewalk
    /* cutaway for exterior lots (2026-07-27, "still getting f=1"):
       interior blocks get their near walls fenced on f=1/f=2 legs via
       route.cutEdges, but lots live outside the grid and never
       consulted it — full houses drew beside the robot on exactly the
       headings the cutaway exists for. route.cutExt holds the world
       spans of every cut-heading leg portion that runs along the
       perimeter; any unit whose center sits near one of those spans
       renders as the same solid fence row an interior cut edge gets
       (commercial included — no parking-row here because this path
       has no topLayer plumbing for the parked cars, and a fence is
       the same safe, view-clearing replacement). Per-unit test, so a
       long lot only fences the portion the route actually passes.
       Radius 0.75*BLOCK: probe runs one lane-band inward of the lot
       front, and modest over-reach past a leg's end just fences a
       little extra — the safe direction. */
    const cutExt = (this.route && this.route.cutExt) || [];
    const unitCut = (px, py) => {
      for(const sg2 of cutExt){
        const vx = sg2.x1 - sg2.x0, vy = sg2.y1 - sg2.y0;
        const L2 = vx*vx + vy*vy || 1;
        let tt = ((px - sg2.x0)*vx + (py - sg2.y0)*vy) / L2;
        tt = Math.max(0, Math.min(1, tt));
        const dx2 = px - (sg2.x0 + vx*tt), dy2 = py - (sg2.y0 + vy*tt);
        if(dx2*dx2 + dy2*dy2 < (BLOCK*0.75)*(BLOCK*0.75)) return true;
      }
      return false;
    };
    if(lot.type === "commercial"){
      const eseed = ((Math.round(lot.ox*3+lot.dv.x)*7919) ^ (Math.round(lot.oy*3+lot.dv.y)*104729) ^ 0x51b3) >>> 0;
      const units = packEdgeNoGap(lot.len, mulberry32(eseed));
      units.forEach((u, idx) => {
        const hx = lot.ox + lot.dv.x*(u.start+u.w/2), hy = lot.oy + lot.dv.y*(u.start+u.w/2);
        const hseed = ((Math.round(hx)*7919) ^ (Math.round(hy)*104729)) >>> 0;
        const ux = lot.ox+lot.dv.x*u.start, uy = lot.oy+lot.dv.y*u.start;
        if(unitCut(hx, hy)){
          this.queueUnitStrips(vq, ux, uy, lot.dv, faceIn, u.w, 0, TILE, (g,t,a0,a1)=>this.drawSolidFenceRow(g, ux, uy, lot.dv, faceIn, u.w, hseed, a0, a1));
          return;
        }
        const isFirst = idx===0, isLast = idx===units.length-1;
        this.queueUnitStrips(vq, ux, uy, lot.dv, faceIn, u.w, STORE_DEPTH, T2, (g,t,a0,a1)=>{
          this.drawStoreUnit(g, ux, uy, lot.dv, faceIn, u.w, hseed, isFirst, isLast, 'body', a0, a1);
          this.drawStoreUnit(g, ux, uy, lot.dv, faceIn, u.w, hseed, isFirst, isLast, 'roof', a0, a1);
        });
      });
    } else {
      const eseed = ((Math.round(lot.ox*3+lot.dv.x)*7919) ^ (Math.round(lot.oy*3+lot.dv.y)*104729) ^ 0x9e3779b9) >>> 0;
      const units = packEdge(lot.len, mulberry32(eseed));
      units.forEach((u) => {
        const hx = lot.ox + lot.dv.x*(u.start+u.w/2), hy = lot.oy + lot.dv.y*(u.start+u.w/2);
        const hseed = ((Math.round(hx)*7919) ^ (Math.round(hy)*104729)) >>> 0;
        const ux = lot.ox+lot.dv.x*u.start, uy = lot.oy+lot.dv.y*u.start;
        if(unitCut(hx, hy)){
          this.queueUnitStrips(vq, ux, uy, lot.dv, faceIn, u.w, 0, TILE, (g,t,a0,a1)=>this.drawSolidFenceRow(g, ux, uy, lot.dv, faceIn, u.w, hseed, a0, a1));
          return;
        }
        this.queueUnitStrips(vq, ux, uy, lot.dv, faceIn, u.w, HOUSE_DEPTH, T2, (g,t,a0,a1)=>{
          this.drawHouseUnit(g, ux, uy, lot.dv, faceIn, u.w, hseed, false, 'body', a0, a1);
          this.drawHouseUnit(g, ux, uy, lot.dv, faceIn, u.w, hseed, false, 'roof', a0, a1);
        });
      });
      for(const gp of gapsFromUnits(units, lot.len)){
        const gx = lot.ox + lot.dv.x*(gp.start+gp.w/2), gy = lot.oy + lot.dv.y*(gp.start+gp.w/2);
        const gseed = ((Math.round(gx)*7919) ^ (Math.round(gy)*104729) ^ 0x2f6c) >>> 0;
        const fx = lot.ox + lot.dv.x*gp.start, fy = lot.oy + lot.dv.y*gp.start;
        this.queueUnitStrips(vq, fx, fy, lot.dv, faceIn, gp.w, 0, TILE, (g,t,a0,a1)=>this.drawFenceGap(g, fx, fy, lot.dv, faceIn, gp.w, gseed, a0, a1));
      }
    }
  }

  /* THE WILLIAM's body — drawPersonHull's box construction (same
     hull-box + faceA/faceB near-face convention, same walk swing,
     same SL-hinge rotation for the kick leg and posed arms), extended
     with his signature pieces: bucket hat (clashing, camo-patched),
     seeded print patches on the matching shirt+shorts set, bare shins
     into white sneakers, beard + shades (front-facing headings ONLY —
     from behind he shows the back of his head, all four headings
     verified in the lab via SPIN), gold chain. Ported verbatim from
     labs/william-lab.html v6. */
  drawWilliamHull(g, ax, ay, z, thW, walkPhase, moving, kickAng, armLift, armAngle, fit, patternSeed){
    const build = WILLIAM_BUILD, pSkin = WILLIAM_SKIN, pShoe = WILLIAM_SHOE, hat = fit.hat;
    const cs = Math.cos(thW), sn = Math.sin(thW);
    const G = (a,b,h) => this.W(ax + a*cs - b*sn, ay + a*sn + b*cs, z + h);
    const aDir = { x: cs, y: sn }, bDir = { x: -sn, y: cs };
    const faceA = Math.sign(aDir.x + aDir.y) || 1, faceB = Math.sign(bDir.x + bDir.y) || 1;

    const box = (aC,bC,ha,hb,z0,z1,cTop,cA,cB,noTop=false) => {
      const corner = (sa,sb,zz) => G(aC+sa*ha, bC+sb*hb, zz);
      if(!noTop){
        const top = [corner(-1,-1,z1), corner(1,-1,z1), corner(1,1,z1), corner(-1,1,z1)];
        this.quadOn(g, top, cTop);
        this.edgeOn(g, top, cA, 1);
      }
      const aFace = [corner(faceA,-1,z1), corner(faceA,1,z1), corner(faceA,1,z0), corner(faceA,-1,z0)];
      this.quadOn(g, aFace, cA);
      const bFace = [corner(-1,faceB,z1), corner(1,faceB,z1), corner(1,faceB,z0), corner(-1,faceB,z0)];
      this.quadOn(g, bFace, cB);
    };

    const hipH = build.legH, shoulderH = hipH+build.torsoH, headH = shoulderH+build.headR*2;
    const kneeH = build.legH*0.52;

    const sh = G(0,0,0);
    g.fillStyle(0x000000, 0.18);
    g.fillEllipse(sh.x, sh.y+1, 22*this.K*0.42, 10*this.K*0.42);

    /* seeded print patches painted onto a face plane */
    const patches = (plane, aC, bC, ha, hb, z0, z1, n, seedSalt) => {
      const r = mulberry32((patternSeed ^ seedSalt) >>> 0);
      for(let i=0; i<n; i++){
        const col = (i % 2 === 0) ? fit.p1 : fit.p2;
        const u = -0.72 + r()*1.44;
        const zc = z0 + 3 + r()*Math.max(1, (z1-z0-6));
        const s2 = 2.2 + r()*2.6;
        let pts;
        if(plane === "a"){
          pts = [G(aC+faceA*ha, bC+u*hb - s2, zc - s2*0.7), G(aC+faceA*ha, bC+u*hb + s2, zc - s2*0.7),
                 G(aC+faceA*ha, bC+u*hb + s2, zc + s2*0.7), G(aC+faceA*ha, bC+u*hb - s2, zc + s2*0.7)];
        } else {
          pts = [G(aC+u*ha - s2, bC+faceB*hb, zc - s2*0.7), G(aC+u*ha + s2, bC+faceB*hb, zc - s2*0.7),
                 G(aC+u*ha + s2, bC+faceB*hb, zc + s2*0.7), G(aC+u*ha - s2, bC+faceB*hb, zc + s2*0.7)];
        }
        this.quadOn(g, pts, col);
      }
    };

    const leg = side => {
      const bC = walkPhase*side*8*0.35;
      const legW = build.legW*0.55, legD = build.legW*0.6;
      const shoeH = Math.max(5, build.legH*0.14);
      box(side*build.hipW*0.3, bC+legD*0.3, legW*1.25, legD*1.55, 0, shoeH, pShoe.c, pShoe.dk, pShoe.c);
      box(side*build.hipW*0.3, bC, legW*0.92, legD*0.92, shoeH, kneeH, pSkin.c, pSkin.dk, pSkin.c);
      box(side*build.hipW*0.3, bC, legW*1.3, legD*1.3, kneeH, hipH, fit.c, fit.dk, fit.c);
      patches("b", side*build.hipW*0.3, bC, legW*1.3, legD*1.3, kneeH, hipH, 2, 0x51 + side);
    };

    /* KICK LEG — SL-hinge rotation about the hip pivot into the
       forward (+b) plane; theta<0 cocked back ~30 deg, theta>0
       extended. Same seg technique as the arm-lift hinge. */
    const kickLeg = (side, theta) => {
      const cT = Math.cos(theta), sT = Math.sin(theta);
      const hipAx = side*build.hipW*0.3;
      const LC = (aOff, p, perp) => G(hipAx + aOff, p*sT + perp*cT, hipH - p*cT + perp*sT);
      const seg = (p0, p1, ha, hb, cSide, cFront, cCap) => {
        const sideFace = [LC(ha*faceA,p0,-hb), LC(ha*faceA,p1,-hb), LC(ha*faceA,p1,hb), LC(ha*faceA,p0,hb)];
        this.quadOn(g, sideFace, cSide);
        const frontFace = [LC(-ha,p0,hb*faceB), LC(ha,p0,hb*faceB), LC(ha,p1,hb*faceB), LC(-ha,p1,hb*faceB)];
        this.quadOn(g, frontFace, cFront);
        const capFar = [LC(-ha,p1,-hb), LC(ha,p1,-hb), LC(ha,p1,hb), LC(-ha,p1,hb)];
        this.quadOn(g, capFar, cCap);
        const capNear = [LC(-ha,p0,-hb), LC(ha,p0,-hb), LC(ha,p0,hb), LC(-ha,p0,hb)];
        this.quadOn(g, capNear, cCap);
      };
      const legW = build.legW*0.55;
      const thighLen = hipH - kneeH, shinLen = kneeH - 5, shoeLen = 9;
      seg(0, thighLen, legW*1.3, legW*1.3, fit.dk, fit.c, fit.c);
      seg(thighLen, thighLen + shinLen, legW*0.92, legW*0.92, pSkin.dk, pSkin.c, pSkin.c);
      seg(thighLen + shinLen, thighLen + shinLen + shoeLen, legW*1.2, legW*1.2, pShoe.dk, pShoe.c, pShoe.c);
    };

    const torso = () => {
      box(0, 0, build.torsoW/2, build.torsoD/2, hipH-2, shoulderH, fit.c, fit.dk, fit.c);
      patches("a", 0, 0, build.torsoW/2, build.torsoD/2, hipH+2, shoulderH-2, 5, 0x11);
      patches("b", 0, 0, build.torsoW/2, build.torsoD/2, hipH+2, shoulderH-2, 5, 0x22);
      box(0, 0, build.torsoW/2*0.55, build.torsoD/2*0.8, shoulderH-5, shoulderH-2.5, WILLIAM_CHAIN, WILLIAM_CHAIN, WILLIAM_CHAIN, true);
    };

    const shoulderZ = shoulderH - 1;
    const sleeveLen = build.armLen*0.48, foreLen = build.armLen*0.52;
    const elbowZ = shoulderZ - sleeveLen;
    const arm = side => {
      const shoulderAx = side*(build.torsoW/2 - 1);
      if(armLift <= 0.001){
        const armSwing = moving ? -walkPhase*side*3 : 0;
        const armB = armSwing*0.4;
        box(shoulderAx, armB, build.armW*0.58, build.armW*0.58, elbowZ, shoulderZ, fit.c, fit.dk, fit.c);
        box(shoulderAx, armB, build.armW*0.46, build.armW*0.46, elbowZ-foreLen, elbowZ+1, pSkin.c, pSkin.dk, pSkin.c, true);
        return;
      }
      const theta = armLift * armAngle;
      const cT = Math.cos(theta), sT = Math.sin(theta);
      const armCorner = (aOff, p, perp) => G(shoulderAx + aOff, p*sT + perp*cT, shoulderZ - p*cT + perp*sT);
      const seg = (p0, p1, ha, hb, cSide, cFront, cCap) => {
        const sideFace = [armCorner(ha*faceA,p0,-hb), armCorner(ha*faceA,p1,-hb), armCorner(ha*faceA,p1,hb), armCorner(ha*faceA,p0,hb)];
        this.quadOn(g, sideFace, cSide);
        const frontFace = [armCorner(-ha,p0,hb*faceB), armCorner(ha,p0,hb*faceB), armCorner(ha,p1,hb*faceB), armCorner(-ha,p1,hb*faceB)];
        this.quadOn(g, frontFace, cFront);
        const capFar = [armCorner(-ha,p1,-hb), armCorner(ha,p1,-hb), armCorner(ha,p1,hb), armCorner(-ha,p1,hb)];
        this.quadOn(g, capFar, cCap);
        const capNear = [armCorner(-ha,p0,-hb), armCorner(ha,p0,-hb), armCorner(ha,p0,hb), armCorner(-ha,p0,hb)];
        this.quadOn(g, capNear, cCap);
      };
      seg(0, sleeveLen, build.armW*0.58, build.armW*0.58, fit.dk, fit.c, fit.c);
      seg(sleeveLen, sleeveLen+foreLen, build.armW*0.46, build.armW*0.46, pSkin.dk, pSkin.c, pSkin.dk);
    };

    const head = () => {
      const z0 = shoulderH, z1 = headH;
      box(0, 0, build.headR, build.headR, z0, z1, pSkin.c, pSkin.dk, pSkin.c);
      /* BEARD + SHADES — the front (+b) is the face; painted ONLY when
         the front is camera-facing so from behind he shows the back of
         his head, not beard-through-skull (all 4 headings verified) */
      if(faceB === 1 && bDir.x + bDir.y > 0){
        const bz0 = z0, bz1 = z0 + build.headR*0.85;
        const bf = build.headR + 0.6;
        this.quadOn(g, [G(-build.headR*0.92, bf, bz0), G(build.headR*0.92, bf, bz0),
                        G(build.headR*0.92, bf, bz1), G(-build.headR*0.92, bf, bz1)], WILLIAM_BEARD);
        const af = faceA*(build.headR + 0.6);
        this.quadOn(g, [G(af, -build.headR*0.2, bz0), G(af, build.headR*0.95, bz0),
                        G(af, build.headR*0.95, bz1), G(af, -build.headR*0.2, bz1)], WILLIAM_BEARD);
        const sz0 = z0 + build.headR*1.05, sz1 = sz0 + build.headR*0.42;
        this.quadOn(g, [G(-build.headR*0.85, bf, sz0), G(build.headR*0.85, bf, sz0),
                        G(build.headR*0.85, bf, sz1), G(-build.headR*0.85, bf, sz1)], WILLIAM_SHADE);
      }
      /* BUCKET HAT — wide thin brim + camo-patched crown */
      const brimZ = z1 - build.headR*0.45;
      /* sized DOWN from 1.55/1.12 (playtest: hat read too big) —
         crown stays a hair over the head's 1.0 so the skull never
         pokes through the hat walls */
      box(0, 0, build.headR*1.30, build.headR*1.30, brimZ, brimZ + 2.2, hat.dk, hat.dk, hat.dk);
      box(0, 0, build.headR*1.04, build.headR*1.04, brimZ + 2.2, z1 + 2, hat.c, hat.c, hat.dk);
      const cr = mulberry32((patternSeed ^ 0x99) >>> 0);
      for(let i=0; i<3; i++){
        const u = -0.6 + cr()*1.2, zc = brimZ + 4 + cr()*(z1 - brimZ - 3), s2 = 2 + cr()*2;
        this.quadOn(g, [G(faceA*build.headR*1.04, u*build.headR - s2, zc - s2*0.6), G(faceA*build.headR*1.04, u*build.headR + s2, zc - s2*0.6),
                        G(faceA*build.headR*1.04, u*build.headR + s2, zc + s2*0.6), G(faceA*build.headR*1.04, u*build.headR - s2, zc + s2*0.6)], hat.p);
        const u2 = -0.6 + cr()*1.2, zc2 = brimZ + 4 + cr()*(z1 - brimZ - 3), s3 = 2 + cr()*2;
        this.quadOn(g, [G(u2*build.headR - s3, faceB*build.headR*1.04, zc2 - s3*0.6), G(u2*build.headR + s3, faceB*build.headR*1.04, zc2 - s3*0.6),
                        G(u2*build.headR + s3, faceB*build.headR*1.04, zc2 + s3*0.6), G(u2*build.headR - s3, faceB*build.headR*1.04, zc2 + s3*0.6)], hat.p);
      }
    };

    const nearSide = faceA;
    if(Math.abs(kickAng) > 0.02){
      const planted = side => {
        const legW = build.legW*0.55, legD = build.legW*0.6;
        const shoeH = Math.max(5, build.legH*0.14);
        box(side*build.hipW*0.3, legD*0.3, legW*1.25, legD*1.55, 0, shoeH, pShoe.c, pShoe.dk, pShoe.c);
        box(side*build.hipW*0.3, 0, legW*0.92, legD*0.92, shoeH, kneeH, pSkin.c, pSkin.dk, pSkin.c);
        box(side*build.hipW*0.3, 0, legW*1.3, legD*1.3, kneeH, hipH, fit.c, fit.dk, fit.c);
      };
      planted(-nearSide);
      arm(-nearSide);
      torso();
      kickLeg(nearSide, kickAng);
      arm(nearSide);
      head();
    } else {
      leg(-nearSide); leg(nearSide);
      arm(-nearSide);
      torso();
      arm(nearSide);
      head();
    }
  }

  /* STREETLAMP (lamp lab v2, style ARM): cast base + slender pole in
     3 segments (a broken lamp's lean reads as progressive shear, not
     a parallelogram) + gooseneck arm reaching the road side (+b) +
     fixture box. Per-instance variety and the malfunction verdict
     both come from lampSeed. At night the glow (layered pool + lens
     + faint column) draws into this.gGlow — ADD, ABOVE the tint —
     and broken lamps run it through flickerAt. */
  drawLampHull(g, W, t, hz){
    const L = LAMP, K = this.K;
    const r = mulberry32((hz.lampSeed || 1) >>> 0);
    const hVar = LAMP_VARY.hMin + r()*(LAMP_VARY.hMax - LAMP_VARY.hMin);
    const armVar = LAMP_VARY.armMin + r()*(LAMP_VARY.armMax - LAMP_VARY.armMin);
    const pVar = LAMP_VARY.poolMin + r()*(LAMP_VARY.poolMax - LAMP_VARY.poolMin);
    const tilt = hz.mal ? (r() - 0.5) * 2 * LAMP_VARY.malTilt : 0;
    const H = L.height * hVar;
    const lean = zz => tilt * zz;

    const box = (aC, bC, ha, hb, z0, z1, cTop, cA, cB, noTop=false) => {
      const c = (sa, sb, zz) => W(aC + sa*ha, bC + sb*hb, zz);
      /* noTop: when another segment of the SAME footprint sits flush
         on top (pole segment -> pole segment), this segment's top cap
         is never actually visible -- the segment above only draws its
         2 NEAR walls (the far 2 are assumed hidden, standard for a
         standalone box), which leaves the FAR corner of this segment's
         top cap uncovered. On a broken/leaning lamp (mal), that lean
         staggers each segment sideways just enough to expose the
         sliver. Skipping the cap on every segment but the last removes
         it. The base doesn't use this -- it's wider than the pole, so
         its top is a genuinely visible ledge, not a stacking artifact. */
      if(!noTop) this.quadOn(g, [c(-1,-1,z1), c(1,-1,z1), c(1,1,z1), c(-1,1,z1)], cTop);
      this.quadOn(g, [c(1,-1,z1), c(1,1,z1), c(1,1,z0), c(1,-1,z0)], cA);
      this.quadOn(g, [c(-1,1,z1), c(1,1,z1), c(1,1,z0), c(-1,1,z0)], cB);
    };

    const sh = W(0, 0, 0);
    g.fillStyle(L.shadow, 0.18);
    g.fillEllipse(sh.x, sh.y + 1, L.baseW*2.286*K*0.8, L.baseW*K*0.8);
    box(0, 0, L.baseW/2, L.baseW/2, 0, L.baseH, L.base, L.baseDk, L.base);
    const segN = 3;
    for(let i = 0; i < segN; i++){
      const z0 = L.baseH + (H - L.baseH)*i/segN, z1 = L.baseH + (H - L.baseH)*(i+1)/segN;
      box(lean((z0+z1)/2), 0, L.poleW/2, L.poleW/2, z0, z1, L.pole, L.poleDk, L.pole, i < segN-1);
    }
    const topA = lean(H);

    /* gooseneck arm + fixture. +b is toward the ROAD (b increases with
       offsetUnits, and laneOffset gets more negative as the lane index
       rises -- lane 0 is curb side, lane 3 building side). So the arm
       must swing +b from the building row and -b from the curb row for
       the head to hang over the WALKING band either way; the light
       never reaches out over the road. hz.armSign carries that verdict
       from the spawner (see the STREETLAMPS block), defaulting to the
       old building-row behaviour for any lamp without one. */
    const aSign = (hz.armSign === -1) ? -1 : 1;
    const armL = L.armLen * armVar * aSign, seg = 3;
    for(let i = 0; i < seg; i++){
      const u0 = i/seg, u1 = (i+1)/seg;
      const bA = armL*u0, bB = armL*u1;
      const zA = H - L.armDrop*u0*u0, zB = H - L.armDrop*u1*u1;
      const aw = L.poleW*0.4375, ad = L.poleW*0.625;   // arm half-width / underside depth, kept in proportion to the pole
      this.quadOn(g, [W(topA-aw,bA,zA), W(topA+aw,bA,zA), W(topA+aw,bB,zB), W(topA-aw,bB,zB)], L.pole);
      this.quadOn(g, [W(topA+aw,bA,zA), W(topA+aw,bB,zB), W(topA+aw,bB,zB-ad), W(topA+aw,bA,zA-ad)], L.poleDk);
    }
    const hz2 = H - L.armDrop;
    box(topA, armL, L.headW/2, L.headW/2*0.6, hz2 - L.headH, hz2, L.head, L.headDk, L.head);

    /* lens housing (always) + the light itself (night, into gGlow) */
    const lp = W(topA, armL, hz2 - L.headH);
    const lensW = L.headW*0.615, lensH = L.headW*0.269;   // lens tracks the fixture box
    g.fillStyle(L.glassDay, 1);
    g.fillEllipse(lp.x, lp.y, lensW*K*0.55, lensH*K*0.55);
    if(this.route && this.route.night){
      const lit = hz.mal ? flickerAt(hz.lampSeed, t) : 1;
      if(lit > 0){
        const gl = this.gGlow, gp = W(topA, armL, 0);
        const pR = LAMP_ACT.poolR * pVar * K * 0.8;
        /* layered pool: hot core -> mid -> soft skirt — a single
           faint wash can't even cancel the navy (lamp lab finding) */
        gl.fillStyle(L.glow, 0.34*lit); gl.fillEllipse(gp.x, gp.y, pR*0.55, pR*0.26);
        gl.fillStyle(L.glow, 0.20*lit); gl.fillEllipse(gp.x, gp.y, pR, pR*0.48);
        gl.fillStyle(L.glow, 0.10*lit); gl.fillEllipse(gp.x, gp.y, pR*1.5, pR*0.72);
        gl.fillStyle(L.glow, 0.5*lit);  gl.fillEllipse(lp.x, lp.y, L.headW*0.923*K*0.8, L.headW*0.462*K*0.8);
        gl.fillStyle(0xffe9c0, 0.9*lit); gl.fillEllipse(lp.x, lp.y, lensW*K*0.55, lensH*K*0.55);
        gl.fillStyle(L.glow, 0.07*lit);
        gl.fillPoints([new Phaser.Geom.Point(lp.x, lp.y),
                       new Phaser.Geom.Point(gp.x - pR*0.7, gp.y),
                       new Phaser.Geom.Point(gp.x + pR*0.7, gp.y)], true);
      }
    }
  }

  drawPersonHull(g, ax, ay, z, thW, build, pSkin, pShirt, pPants, pHair, pShoe, walkPhase, moving, startleAlpha=0, liftT=0, onBeforeCarryArm=null, uniform=null){
    const cs = Math.cos(thW), sn = Math.sin(thW);
    const G = (a,b,h) => this.W(ax + a*cs - b*sn, ay + a*sn + b*cs, z + h);
    /* face visibility: drawPersonHull's points (G() above) are real
       world-space, never rotated by this.drawAngle — only the robot's
       own body geometry goes through that rotation (via T()). The face
       test must match the geometry it's testing, so it stays plain
       (cs,sn)/(-sn,cs) with no drawAngle rotation applied. */
    const aDir = { x: cs, y: sn }, bDir = { x: -sn, y: cs };
    const faceA = Math.sign(aDir.x + aDir.y) || 1, faceB = Math.sign(bDir.x + bDir.y) || 1;

    const box = (aC,bC,ha,hb,z0,z1,cTop,cA,cB,noTop=false) => {
      const corner = (sa,sb,zz) => G(aC+sa*ha, bC+sb*hb, zz);
      if(!noTop){
        const top = [corner(-1,-1,z1), corner(1,-1,z1), corner(1,1,z1), corner(-1,1,z1)];
        this.quadOn(g, top, cTop);
        this.edgeOn(g, top, cA, 1);
      }
      const aFace = [corner(faceA,-1,z1), corner(faceA,1,z1), corner(faceA,1,z0), corner(faceA,-1,z0)];
      this.quadOn(g, aFace, cA);
      const bFace = [corner(-1,faceB,z1), corner(1,faceB,z1), corner(1,faceB,z0), corner(-1,faceB,z0)];
      this.quadOn(g, bFace, cB);
    };

    const hipH = build.legH, shoulderH = hipH+build.torsoH, headH = shoulderH+build.headR*2;

    const sh = G(0,0,0);
    g.fillStyle(PEOPLE_ART.shadow, 0.18);
    g.fillEllipse(sh.x, sh.y+1, 20*this.K*0.42, 9*this.K*0.42);

    const leg = side => {
      const bC = walkPhase*side*PEOPLE_ART.walkStride*0.35;
      const legW = build.legW*0.55, legD = build.legW*0.6;
      const shoeH = Math.max(5, build.legH*0.13);
      box(side*build.hipW*0.3, bC+legD*0.3, legW*1.2, legD*1.5, 0, shoeH, pShoe.c, pShoe.dk, pShoe.c);
      box(side*build.hipW*0.3, bC, legW, legD, shoeH, hipH, pPants.c, pPants.dk, pPants.c);
    };
    const torso = () => box(0, 0, build.torsoW/2, build.torsoD/2, hipH-2, shoulderH, pShirt.c, pShirt.dk, pShirt.c);
    const shoulderZ = shoulderH - 1;
    const sleeveLen = build.armLen*0.48, foreLen = build.armLen*0.52;
    const elbowZ = shoulderZ - sleeveLen;
    const arm = (side, isCarryArm) => {
      const shoulderAx = side*(build.torsoW/2 - 1);
      if(liftT <= 0.001 || !isCarryArm){
        /* at rest — flat box, walk-swing only. Also always used for
           the non-carrying arm regardless of liftT, so only the arm
           actually holding the bag lifts; the other stays down like
           a normal standing pose instead of both arms rising
           symmetrically. */
        const armSwing = moving ? -walkPhase*side*3 : 0;
        const armB = armSwing*0.4;
        box(shoulderAx, armB, build.armW*0.58, build.armW*0.58, elbowZ, shoulderZ, pShirt.c, pShirt.dk, pShirt.c);
        box(shoulderAx, armB, build.armW*0.46, build.armW*0.46, elbowZ-foreLen, elbowZ+1, pSkin.c, pSkin.dk, pSkin.c, true);
        return;
      }
      /* lift gesture: a real rotation around a fixed shoulder pivot,
         same SL-hinge technique as the door hinge / cargo lid — a
         point at distance p from the pivot, rotated by theta. Rigid
         arm length verified constant (40.00) at every liftT from 0 to
         1 in the lab. */
      const theta = liftT * LIFT_MAX_ANGLE;
      const cT = Math.cos(theta), sT = Math.sin(theta);
      const armCorner = (aOff, p, perp) => G(shoulderAx + aOff, p*sT + perp*cT, shoulderZ - p*cT + perp*sT);
      const seg = (p0, p1, ha, hb, cSide, cFront, cCap) => {
        const sideFace = [armCorner(ha*faceA,p0,-hb), armCorner(ha*faceA,p1,-hb), armCorner(ha*faceA,p1,hb), armCorner(ha*faceA,p0,hb)];
        this.quadOn(g, sideFace, cSide);
        const frontFace = [armCorner(-ha,p0,hb*faceB), armCorner(ha,p0,hb*faceB), armCorner(ha,p1,hb*faceB), armCorner(-ha,p1,hb*faceB)];
        this.quadOn(g, frontFace, cFront);
        /* end caps at both ends — a two-face box read as flat without
           a third shaded surface, and capping only the far end left
           the near-shoulder cap (visible at rest) vanishing the
           instant rotation started. */
        const capFar = [armCorner(-ha,p1,-hb), armCorner(ha,p1,-hb), armCorner(ha,p1,hb), armCorner(-ha,p1,hb)];
        this.quadOn(g, capFar, cCap);
        const capNear = [armCorner(-ha,p0,-hb), armCorner(ha,p0,-hb), armCorner(ha,p0,hb), armCorner(-ha,p0,hb)];
        this.quadOn(g, capNear, cCap);
      };
      seg(0, sleeveLen, build.armW*0.58, build.armW*0.58, pShirt.dk, pShirt.c, pShirt.c);
      seg(sleeveLen, sleeveLen+foreLen, build.armW*0.46, build.armW*0.46, pSkin.dk, pSkin.c, pSkin.dk);
    };
    const head = () => {
      const z0 = shoulderH, z1 = headH;
      box(0, 0, build.headR, build.headR, z0, z1, pSkin.c, pSkin.dk, pSkin.c);
      const hairZ0 = z0 + (z1-z0)*0.55;
      box(0, 0, build.headR*1.06, build.headR*1.06, hairZ0, z1+1.5, pHair, pHair, pHair);

      /* PEAKED CAP — crown box sitting on the same head, plus a peak on
         the body's FORWARD axis. Forward is b, not a: bDir is (-sn,cs)
         and aDir is (cs,sn), and a peak built on a points out of the
         person's shoulder instead of their face.

         The peak is drawn against DEPTH, not in a fixed order. When the
         person faces away from the camera the peak is behind the crown
         and must be painted first, or it floats detached in front of
         the head at exactly those headings. */
      if(uniform && uniform.cap){
        const cap = uniform.cap;
        const cz0 = z0 + (z1-z0)*0.52, cz1 = z1 + 2.5;
        const cR = build.headR*1.12;
        const peakB = cR + build.headR*0.55;
        const drawCrown = () => {
          box(0, 0, cR, cR, cz0, cz1, cap.top, cap.dk, cap.c);
          /* badge on the forward face of the crown */
          const bq = [ G(-cR*0.30, cR*1.005, cz1-2.0), G(cR*0.30, cR*1.005, cz1-2.0),
                       G(cR*0.30, cR*1.005, cz1-6.5), G(-cR*0.30, cR*1.005, cz1-6.5) ];
          this.quadOn(g, bq, cap.badge);
        };
        const drawPeak = () => box(0, peakB*0.62, cR*0.92, build.headR*0.42,
                                   cz0 - 0.5, cz0 + 2.0, cap.top, cap.dk, cap.c);
        /* depth of the peak's centre vs the crown's, in the same world
           metric drawWorld sorts on */
        const pw = { x: ax - peakB*0.62*sn, y: ay + peakB*0.62*cs };
        const peakNearer = (pw.x + pw.y) > (ax + ay);
        if(peakNearer){ drawCrown(); drawPeak(); } else { drawPeak(); drawCrown(); }
      }
    };
    /* long hair hangs down the BACK — has to draw before the torso/
       shoulders so the body occludes the part that's actually behind
       it; drawing it last (inside head(), after everything) made it
       always render in front instead */
    const hairBack = () => {
      if(build.hairStyle !== "long") return;
      const backB = -build.headR*0.75;
      box(0, backB, build.headR*0.62, build.headR*0.4, hipH+build.torsoH*0.35, headH-1, pHair, pHair, pHair);
    };

    const nearSide = faceA;
    leg(-nearSide); leg(nearSide);
    hairBack();
    arm(-nearSide, false);
    torso();
    /* stab vest: over the torso, under the arms — so it reads as worn
       rather than painted on. Uses the hull's own box() so it inherits
       the same face-selection as everything else. */
    if(uniform && uniform.vest){
      box(0, 0, build.torsoW/2*1.07, build.torsoD/2*1.14,
          hipH + build.torsoH*0.16, shoulderH - 1.5,
          uniform.vest.c, uniform.vest.dk, uniform.vest.c);
    }
    if(onBeforeCarryArm) onBeforeCarryArm(); // torso/legs already drawn, carrying arm not yet —
    // anything drawn here sits on top of the body but UNDER the carrying arm specifically
    arm(nearSide, true);
    head();

    if(startleAlpha > 0){
      const hp = G(0, 0, headH + build.headR + 4);
      g.lineStyle(1.5, 0xffb04d, startleAlpha);
      for(const aoff of [-0.7, 0, 0.7]){
        g.lineBetween(hp.x + Math.sin(aoff)*4, hp.y - Math.cos(aoff)*4,
                      hp.x + Math.sin(aoff)*9, hp.y - Math.cos(aoff)*9);
      }
    }
  }

  /* hand world position — mirrors arm()'s exact shoulder-pivot
     rotation for the CARRYING arm specifically, so the pickup bag can
     be locked to wherever that hand actually is (resting straight
     down at liftT=0, swung forward at liftT=1). nearSide/faceA
     matches drawPersonHull's own near-side test so this picks the
     same arm that's actually drawn as the carrying one. Dial-bench
     approved in labs/pickup-lab.html. */
  handWorldPos(ax, ay, thW, build, liftT){
    const cs = Math.cos(thW), sn = Math.sin(thW);
    const nearSide = Math.sign(cs+sn) || 1;
    const shoulderAx = nearSide*(build.torsoW/2 - 1);
    const hipH = build.legH, shoulderH = hipH + build.torsoH, shoulderZ = shoulderH - 1;
    const sleeveLen = build.armLen*0.48, foreLen = build.armLen*0.52;
    const armLen = sleeveLen + foreLen;
    const theta = liftT * LIFT_MAX_ANGLE;
    const handB = armLen * Math.sin(theta), handZ = shoulderZ - armLen * Math.cos(theta);
    return { x: ax + shoulderAx*cs - handB*sn, y: ay + shoulderAx*sn + handB*cs, z: handZ };
  }

  /* ---------- POLICE OFFICER ----------
     Deliberately NOT a new body: it is drawPersonHull with the police
     uniform, so officers inherit the walk, limb and face-selection
     conventions rather than growing their own copy of them.

     walkPhase here is a limb DISPLACEMENT, not a phase angle — the hull
     multiplies it straight into a stride offset. Feeding it t*rate
     throws limbs hundreds of units off the body. Officers are posted,
     so it stays 0 and `moving` stays false.

     role only chooses an arm lift and a build/skin salt. The traffic
     officer's lift is driven by the signal phase, so it comes in
     through opts.liftT rather than being decided here. */
  drawOfficer(g, x, y, z, thW, role, seed, t, opts = null){
    const rng = mulberry32(((seed|0) ^ 0x9e37) >>> 0);
    const build = PEOPLE_BUILD[Math.floor(rng()*PEOPLE_BUILD.length)];
    const skin  = PEOPLE_SKIN[Math.floor(rng()*PEOPLE_SKIN.length)];
    const hair  = PEOPLE_HAIR[Math.floor(rng()*PEOPLE_HAIR.length)];
    const ROLE_LIFT = { tape: 0.86, search: 0.34, post: 0.0, traffic: 0.92 };
    const liftT = (opts && opts.liftT !== undefined) ? opts.liftT : (ROLE_LIFT[role] ?? 0);
    this.drawPersonHull(g, x, y, z, thW, build, skin,
      POLICE_UNIFORM.shirt, POLICE_UNIFORM.pants, hair, POLICE_UNIFORM.shoe,
      0, false, 0, liftT, null, POLICE_UNIFORM);
  }

  drawProp(g, kind, x, y, t, fdir = 0, z = 0, wheelPhase = null, colorSeed = null, data = null){
    /* fdir may now be CONTINUOUS (a float, in quarter-turn units) --
       moving traffic passes its real heading so a car rotates smoothly
       through a corner instead of popping 90 degrees at the arc
       midpoint. Every kind except the car branch still wants a
       quantized axis pair, so the DIRV lookup rounds HERE rather than
       at the call site; that is what lets one parameter serve both.
       The car branch reads the raw float via carTheta and rotates
       rigidly, which its geometry was already built for. */
    const fq = ((Math.round(fdir) % 4) + 4) % 4;
    const dv = DIRV[fq], rv = DIRV[(fq+1)%4];
    const W = (dx, dy, dz) => this.W(x + dv.x*dx + rv.x*dy, y + dv.y*dx + rv.y*dy, z + dz);
    if(kind === "lamp"){
      this.drawLampHull(g, W, t, data || {});
    } else if(kind === "palm" || kind === "palmDwarf"){
      /* approved in palm lab — tall (165/8/1.0) and dwarf (55/8/0.3) presets */
      const P = kind === "palmDwarf" ? PALM_DWARF : PALM, K = this.K;
      const o = W(0, 0, 0);
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729)) >>> 0;
      const rng = mulberry32(seed);
      const lean = P.trunkLean * (rng()*2 - 1) * 2;
      const tallRoll = rng();
      const H = P.height * (tallRoll < 0.12 ? (1.6 + rng()*0.5) : (0.85 + rng()*0.3)); // ~12% chance of a dramatically tall specimen
      const phase = rng()*Math.PI*2;
      const sway = Math.sin(t*0.0011 + phase) * 3.2 * P.wind;

      g.fillStyle(P.shadow, 0.13);
      g.fillEllipse(o.x + lean*22*K, o.y + 3, (36 + H*0.14)*K, 12*K);

      const SEG = 8, spine = [];
      for(let i=0; i<=SEG; i++){
        const u = i/SEG;
        spine.push({ x: o.x + (lean*H*u*u + sway*u*u)*K, y: o.y - H*u*K, w: (7.5 - 4.5*u)*K });
      }
      for(let i=0; i<SEG; i++){
        const a2 = spine[i], b2 = spine[i+1];
        this.quadOn(g, [
          {x:a2.x-a2.w/2, y:a2.y}, {x:a2.x+a2.w/2, y:a2.y},
          {x:b2.x+b2.w/2, y:b2.y}, {x:b2.x-b2.w/2, y:b2.y}
        ], i % 2 === 0 ? P.trunk : P.trunkDk);
        if(i % 2 === 1){
          g.lineStyle(1.5, P.ring, 1);
          g.lineBetween(a2.x-a2.w/2, a2.y, a2.x+a2.w/2, a2.y);
        }
      }
      const crown = spine[SEG];
      const fronds = [];
      for(let i=0; i<P.fronds; i++){
        const baseA = (i/P.fronds)*Math.PI*2 + rng()*0.25;
        const dirY = Math.sin(baseA)*0.45 - 0.12;
        fronds.push({
          dirX: Math.cos(baseA), dirY,
          flut: Math.sin(t*0.0021 + phase + i*1.7) * 0.06 * P.wind,
          len: (44 + rng()*14)*(P.spread || 1)*K,
          back: dirY < -0.18
        });
      }
      const drawFrond = (f2, color) => {
        const steps = 7;
        let px = crown.x, py = crown.y;
        for(let sI=1; sI<=steps; sI++){
          const u = sI/steps;
          const nx = crown.x + f2.dirX*f2.len*u;
          const ny = crown.y + f2.dirY*f2.len*u + (P.droop*30*u*u + f2.flut*26*u)*K;
          const lw = (9 - 7*u)*K;
          const tx2 = nx - px, ty2 = ny - py;
          const tl = Math.hypot(tx2, ty2) || 1;
          const pxn = -ty2/tl, pyn = tx2/tl;
          g.fillStyle(color, 1);
          g.fillTriangle(px, py, nx, ny, px + pxn*lw + tx2*0.3, py + pyn*lw + ty2*0.3);
          g.fillTriangle(px, py, nx, ny, px - pxn*lw + tx2*0.3, py - pyn*lw + ty2*0.3);
          px = nx; py = ny;
        }
      };
      for(const f2 of fronds) if(f2.back) drawFrond(f2, P.frondB);
      for(let i=0; i<3; i++){
        const a3 = phase + i*2.1;
        g.fillStyle(i === 1 ? P.cocoHi : P.coco, 1);
        g.fillCircle(crown.x + Math.cos(a3)*6*K, crown.y + 4*K + Math.sin(a3)*3*K, 4.2*K);
      }
      for(const f2 of fronds) if(!f2.back) drawFrond(f2, P.frondA);
    } else if(kind === "scooter"){
      /* approved in scooter hit lab (2026-07-09): the dumped pose is
         a stylized squash (M below), not a rigid rotation — see the
         lab's header note. phi comes from a real fall integrator and
         drives layAmount, a blend fraction between the approved
         standing and dumped geometry. Every part already routes
         through M() via G()/dAt(), so blending it once moves the
         whole assembly. */
      const S = SCOOT;
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729)) >>> 0;
      const rng = mulberry32(seed);
      /* parked ALONG the walk, nose either way, a few degrees of slop —
         was a free ±162° roll, which parked scooters broadside or
         nose-into-the-buildings with no relationship to the street the
         leg actually runs (on-device: orientation contradicts the f=
         view). 0 in this frame IS the travel axis — W applies DIRV[f]. */
      const thSeed = (rng() < 0.5 ? 0 : Math.PI) + (rng() - 0.5) * 0.3;
      const brandSeed = BRANDS[Math.floor(rng()*BRANDS.length)];
      const th = (data && data.fallPsi !== undefined) ? data.fallPsi : ((data && data.thetaF !== undefined) ? data.thetaF : thSeed);
      const scs = Math.cos(th), ssn = Math.sin(th);
      const brand = (data && data.brand) || brandSeed;
      const slide = (data && data.slide) || 0;
      const phi = (data && data.phi) || 0;
      const layAmount = Math.min(1, phi / SCOOT_HIT.phiRest);

      const M = (a, b, h) => {
        const bLay = -h - 2, hLay = (b + 7) * 0.55;
        return {
          a,
          b: b + (bLay - b)*layAmount,
          h: h + (hLay - h)*layAmount
        };
      };
      const GG = (a, b, h) => {
        const m = M(a, b, h);
        return W((m.a + slide)*scs - m.b*ssn, (m.a + slide)*ssn + m.b*scs, m.h);
      };
      const dAt = (a, b, h) => {
        const m = M(a, b, h);
        const a2 = (m.a + slide)*scs - m.b*ssn, b2 = (m.a + slide)*ssn + m.b*scs;
        return a2 + b2 + m.h*0.4;
      };

      const wheelR = S.wheelR;
      const stemBaseA = 11, stemBaseH = 5.2;
      const stemTipA = 13, stemTipH = 4 + S.stemH;
      const fwA = 16 + wheelR*0.95;
      const rwA = -20 - wheelR*0.9;
      const wheelH = wheelR*0.72;

      const ringAt = (a0, b0, h0, r, d1, d2, n=12) => {
        const pts = [];
        for(let i=0; i<n; i++){
          const psi = (i/n)*Math.PI*2, c3 = Math.cos(psi)*r, s3 = Math.sin(psi)*r;
          pts.push(GG(a0 + c3*d1.a + s3*d2.a, b0 + c3*d1.b + s3*d2.b, h0 + c3*d1.h + s3*d2.h));
        }
        return pts;
      };
      const U = {a:1,b:0,h:0}, VV = {a:0,b:1,h:0}, HHH = {a:0,b:0,h:1};

      const WW = 4.6;
      /* RIGID wheel frame from M's normalized differentials — the hull
         treatment. M is a stylized affine squash, not a rotation, so
         pushing the wheel circles through it collapsed them into
         flattened lenses as the scooter lay down (reported: fallen
         wheels don't look right). Normalizing M's constant differential
         axes (∂/∂h = (−lay, 1−lay), ∂/∂b = (1−lay, 0.55·lay)) turns the
         same blend into a true rotation for the wheels alone: the wheel
         plane tips from vertical to flat on the ground and the axle
         swings skyward, while the HUB stays glued to the squashed frame
         the deck and fenders use. layAmount 0 reproduces the standing
         wheel byte-for-byte (frame degenerates to U/HHH exactly). */
      let ehB = -layAmount, ehH = 1 - layAmount;
      { const L2 = Math.hypot(ehB, ehH) || 1; ehB /= L2; ehH /= L2; }
      let ebB = 1 - layAmount, ebH = 0.55*layAmount;
      { const L2 = Math.hypot(ebB, ebH) || 1; ebB /= L2; ebH /= L2; }
      const GRAW = (ma, mb, mh) => W((ma + slide)*scs - mb*ssn, (ma + slide)*ssn + mb*scs, mh);
      const dRAW = (ma, mb, mh) => { const a2 = (ma + slide)*scs - mb*ssn, b2 = (ma + slide)*ssn + mb*scs; return a2 + b2 + mh*0.4; };
      const swheel = (a, r) => {
        const hub = M(a, 0, wheelH);
        const ringR = (k, rr, n = 14) => {
          const pts = [];
          for(let i = 0; i < n; i++){
            const psi = (i/n)*Math.PI*2, c3 = Math.cos(psi)*rr, s3 = Math.sin(psi)*rr;
            pts.push(GRAW(hub.a + c3, hub.b + k*ebB + s3*ehB, hub.h + k*ebH + s3*ehH));
          }
          return pts;
        };
        this.quadOn(g, convexHull(ringR(-WW/2, r).concat(ringR(WW/2, r))), S.wheelDk);
        const kF = dRAW(hub.a, hub.b + (WW/2)*ebB, hub.h + (WW/2)*ebH) >
                   dRAW(hub.a, hub.b - (WW/2)*ebB, hub.h - (WW/2)*ebH) ? WW/2 : -WW/2;
        this.quadOn(g, ringR(kF, r), S.wheel);
        this.quadOn(g, ringR(kF, r*0.42), S.hubFace);
        this.quadOn(g, ringR(kF, r*0.2), S.hub);
      };
      const sdeck = () => {
        const top = [], bot = [];
        for(const bc of [[-20,-7],[16,-7],[16,7],[-20,7]]){
          top.push(GG(bc[0], bc[1], 5.2)); bot.push(GG(bc[0], bc[1], 0.8));
        }
        this.quadOn(g, convexHull(top.concat(bot)), brand.cDk);
        const topVisible = layAmount < 0.5 ? true : (ssn - scs) > 0;
        if(topVisible){
          this.quadOn(g, top, brand.c);
          this.quadOn(g, [GG(-16,-4,5.6), GG(8,-4,5.6), GG(8,4,5.6), GG(-16,4,5.6)], S.grip);
        }
      };
      const sstem = () => {
        const da = stemTipA - stemBaseA, dh = stemTipH - stemBaseH;
        const slen = Math.hypot(da, dh) || 1;
        const perp = {a:-dh/slen, b:0, h:da/slen};
        const base = ringAt(stemBaseA, 0, stemBaseH, 3.1, VV, perp, 10);
        const tip  = ringAt(stemTipA, 0, stemTipH, 2.0, VV, perp, 10);
        this.quadOn(g, convexHull(base.concat(tip)), brand.c);
      };
      const sbar = () => {
        const capsule = (b0, b1, r, col) => {
          const e0 = ringAt(stemTipA, b0, stemTipH, r, U, HHH, 8);
          const e1 = ringAt(stemTipA, b1, stemTipH, r, U, HHH, 8);
          this.quadOn(g, convexHull(e0.concat(e1)), col);
        };
        capsule(-S.barW, S.barW, 1.6, S.metal);
        capsule(-S.barW, -S.barW + 6, 2.5, S.deck);
        capsule(S.barW - 6, S.barW, 2.5, S.deck);
      };
      const skick = () => {
        const ks0 = GG(-4, -7, 4), ks1 = GG(-6, -12, 0);
        g.lineStyle(2.5, S.metalDk, 1);
        g.lineBetween(ks0.x, ks0.y, ks1.x, ks1.y);
      };

      const sparts = [
        { d: dAt(rwA, 0, wheelH),  fn: () => swheel(rwA, wheelR) },
        { d: dAt(-2, 0, 3),        fn: sdeck },
        { d: dAt((stemBaseA + stemTipA)/2, 0, (stemBaseH + stemTipH)/2), fn: sstem },
        { d: dAt(fwA, 0, wheelH),  fn: () => swheel(fwA, wheelR*0.92) },
        { d: dAt(stemTipA, 0, stemTipH), fn: sbar },
        { d: dAt(-5, -9, 3),       fn: skick }
      ];
      sparts.sort((p1, p2) => p1.d - p2.d);
      for(const pt of sparts) pt.fn();
    } else if(kind === "trash"){
      /* approved in trash lab v1: seeded litter cluster — water bottle
         on its side (translucent body, crush dent, label, blue cap),
         crumpled plastic bag (raised crumple + creases + knot), and
         rubbish bits (paper balls, cans, wrapper scraps). Composition
         and layout roll per instance from the position seed; items
         depth-sorted (iso x+y). Physics unchanged (sev 7 + drag). */
      const T3 = TRASH_ART, K = this.K;
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x7e2d) >>> 0;
      const rng = mulberry32(seed);
      const spread = 0.7 + rng()*0.6;
      const bits = 2 + Math.floor(rng()*4);
      const bagS = 0.8 + rng()*0.5;
      const botS = 0.8 + rng()*0.5;
      const poly = (pts, col, a=1) => this.quadOn(g, pts, col, a);
      const circ = (cx2, cy2, r, z2, col, outC, n=10) => {
        const pts = [];
        for(let i=0; i<n; i++){
          const a2 = (i/n)*Math.PI*2;
          pts.push(W(cx2 + Math.cos(a2)*r, cy2 + Math.sin(a2)*r, z2));
        }
        poly(pts, col);
        if(outC !== undefined) this.edgeOn(g, pts, outC, 1.1);
      };
      const items = [];

      if(rng() < 0.85){   /* crumpled plastic bag */
        const bx = (rng()-0.5)*12*spread, by = (rng()-0.5)*12*spread;
        const R = (7.5 + rng()*3) * bagS;
        const lump = [];
        for(let i=0; i<9; i++){
          const a2 = (i/9)*Math.PI*2;
          const rr = R * (0.72 + rng()*0.55);
          lump.push({ x: bx + Math.cos(a2)*rr, y: by + Math.sin(a2)*rr });
        }
        const kx = bx + (rng()-0.5)*R*0.5, ky = by + (rng()-0.5)*R*0.5;
        items.push({ x:bx, y:by, r:R, draw: () => {
          poly(lump.map(p => W(p.x, p.y, 0.8)), T3.bagC);
          this.edgeOn(g, lump.map(p => W(p.x, p.y, 0.8)), T3.bagShade, 1.2);
          const top = [];
          for(let i=0; i<8; i++){
            const a2 = (i/8)*Math.PI*2;
            top.push(W(bx + Math.cos(a2)*R*0.55*(0.75+rng()*0.4),
                       by + Math.sin(a2)*R*0.55*(0.75+rng()*0.4), 3.4*bagS));
          }
          poly(top, T3.bagHi);
          this.edgeOn(g, top, T3.bagShade, 1);
          for(let i=0; i<2; i++){
            const a2 = rng()*Math.PI*2;
            poly([
              W(bx + Math.cos(a2)*R*0.2, by + Math.sin(a2)*R*0.2, 1.4),
              W(bx + Math.cos(a2+0.7)*R*0.7, by + Math.sin(a2+0.7)*R*0.7, 0.9),
              W(bx + Math.cos(a2-0.5)*R*0.8, by + Math.sin(a2-0.5)*R*0.8, 0.9)
            ], T3.bagShade, 0.55);
          }
          circ(kx, ky, 1.8*bagS, 5*bagS, T3.bagDeep);
        }});
      }

      if(rng() < 0.85){   /* water bottle on its side */
        const cx2 = (rng()-0.5)*16*spread, cy2 = (rng()-0.5)*16*spread;
        const th = rng()*Math.PI*2;
        const L = 13*botS, r = 3*botS;
        const dxu = Math.cos(th), dyu = Math.sin(th);
        const nx = -dyu, ny = dxu;
        const p0 = { x: cx2 - dxu*L/2, y: cy2 - dyu*L/2 };
        const p1 = { x: cx2 + dxu*L/2, y: cy2 + dyu*L/2 };
        items.push({ x:cx2, y:cy2, r:L/2, draw: () => {
          const zB = 1.4*botS;
          poly([
            W(p0.x + nx*r, p0.y + ny*r, zB), W(p1.x + nx*r*0.72, p1.y + ny*r*0.72, zB),
            W(p1.x - nx*r*0.72, p1.y - ny*r*0.72, zB), W(p0.x - nx*r, p0.y - ny*r, zB)
          ], T3.botBody);
          circ(p0.x, p0.y, r, zB, T3.botBody, T3.botShade);
          poly([
            W(p0.x + dxu*L*0.22 + nx*r*0.9, p0.y + dyu*L*0.22 + ny*r*0.9, zB),
            W(p0.x + dxu*L*0.38 + nx*r*0.55, p0.y + dyu*L*0.38 + ny*r*0.55, zB),
            W(p0.x + dxu*L*0.38 - nx*r*0.55, p0.y + dyu*L*0.38 - ny*r*0.55, zB),
            W(p0.x + dxu*L*0.22 - nx*r*0.9, p0.y + dyu*L*0.22 - ny*r*0.9, zB)
          ], T3.botShade, 0.7);
          poly([
            W(cx2 - dxu*L*0.14 + nx*r, cy2 - dyu*L*0.14 + ny*r, zB),
            W(cx2 + dxu*L*0.14 + nx*r, cy2 + dyu*L*0.14 + ny*r, zB),
            W(cx2 + dxu*L*0.14 - nx*r, cy2 + dyu*L*0.14 - ny*r, zB),
            W(cx2 - dxu*L*0.14 - nx*r, cy2 - dyu*L*0.14 - ny*r, zB)
          ], T3.botLabel);
          poly([
            W(p1.x + nx*r*0.72, p1.y + ny*r*0.72, zB), W(p1.x + dxu*2.4*botS + nx*r*0.42, p1.y + dyu*2.4*botS + ny*r*0.42, zB),
            W(p1.x + dxu*2.4*botS - nx*r*0.42, p1.y + dyu*2.4*botS - ny*r*0.42, zB), W(p1.x - nx*r*0.72, p1.y - ny*r*0.72, zB)
          ], T3.botBody);
          circ(p1.x + dxu*3.2*botS, p1.y + dyu*3.2*botS, r*0.55, zB, T3.botCap, T3.outline);
          g.lineStyle(1.1, T3.botHi, 0.9);
          const h0 = W(p0.x + nx*r*0.45, p0.y + ny*r*0.45, zB + r*0.5);
          const h1 = W(p1.x + nx*r*0.35, p1.y + ny*r*0.35, zB + r*0.5);
          g.lineBetween(h0.x, h0.y, h1.x, h1.y);
        }});
      }

      for(let i=0; i<bits; i++){   /* rubbish bits */
        const bx = (rng()-0.5)*30*spread, by = (rng()-0.5)*30*spread;
        const kind2 = rng();
        if(kind2 < 0.4){
          const r = 2.4 + rng()*1.6;
          items.push({ x:bx, y:by, r, draw: () => {
            circ(bx, by, r, 1, T3.paper, T3.paperShade, 8);
            circ(bx + r*0.3, by + r*0.3, r*0.45, 1.4, T3.paperShade, undefined, 7);
          }});
        } else if(kind2 < 0.7){
          const th = rng()*Math.PI*2, L2 = 6, r2 = 2;
          const du = {x:Math.cos(th), y:Math.sin(th)}, nu = {x:-du.y, y:du.x};
          const col = rng() < 0.5 ? T3.canA : T3.canB;
          items.push({ x:bx, y:by, r:L2/2, draw: () => {
            poly([
              W(bx - du.x*L2/2 + nu.x*r2, by - du.y*L2/2 + nu.y*r2, 1),
              W(bx + du.x*L2/2 + nu.x*r2, by + du.y*L2/2 + nu.y*r2, 1),
              W(bx + du.x*L2/2 - nu.x*r2, by + du.y*L2/2 - nu.y*r2, 1),
              W(bx - du.x*L2/2 - nu.x*r2, by - du.y*L2/2 - nu.y*r2, 1)
            ], col);
            circ(bx + du.x*L2/2, by + du.y*L2/2, r2, 1, T3.canHi, T3.outline, 8);
          }});
        } else {
          const th = rng()*Math.PI*2;
          const du = {x:Math.cos(th), y:Math.sin(th)}, nu = {x:-du.y, y:du.x};
          const col = T3.wrap[Math.floor(rng()*T3.wrap.length)];
          const w2 = 2.4 + rng()*2, h2 = 1.6 + rng()*1.4;
          items.push({ x:bx, y:by, r:w2, draw: () => {
            poly([
              W(bx - du.x*w2 + nu.x*h2, by - du.y*w2 + nu.y*h2, 0.8),
              W(bx + du.x*w2 + nu.x*h2, by + du.y*w2 + nu.y*h2, 0.8),
              W(bx + du.x*w2 - nu.x*h2, by + du.y*w2 - nu.y*h2, 0.8),
              W(bx - du.x*w2 - nu.x*h2, by - du.y*w2 - nu.y*h2, 0.8)
            ], col);
            g.lineStyle(0.8, T3.outline, 0.5);
            const f0 = W(bx - du.x*w2*0.3, by - du.y*w2*0.3, 0.9);
            const f1 = W(bx + du.x*w2*0.4, by + du.y*w2*0.4, 0.9);
            g.lineBetween(f0.x, f0.y, f1.x, f1.y);
          }});
        }
      }

      for(const it of items){
        const sh = W(it.x + 1, it.y + 1, 0.3);
        g.fillStyle(T3.shadow, 0.12);
        g.fillEllipse(sh.x, sh.y, it.r*2.2*K*0.5, it.r*1.2*K*0.5);
      }
      items.sort((a2,b2) => (a2.x + a2.y) - (b2.x + b2.y));
      for(const it of items) it.draw();
    } else if(kind === "cone"){
      /* approved in cone hit lab (2026-07-09): ONE rigid geometry driven
         by a continuous tip angle phi about a physical pivot — every
         frame between standing (phi=0) and knocked (phi=phiRest) is the
         same solid mid-fall, no keyframe swap. phase 1 pivots on the
         front base-rim edge; phase 2 hands off to the landed slab
         corner at 90°. fallPsi (set once, at the hit that starts the
         fall) plays the same role the old per-tile rotation did: it
         orients the fall within this prop's local frame. */
      /* PALETTE IS PER-INSTANCE when the hazard carries one. CONE remains the
         single source of a normal cone's colours; a hazard may supply its own
         {...CONE, band, band_c} and draw with that instead. This is what lets
         the slalom flag its gate cones red/blue while every other cone in the
         city is untouched — and it costs nothing, because the band ring below
         was already written and simply never fires at the global CONE.band 0.
         One constant, one question: which palette does THIS cone draw with. */
      const C = (data && data.cone) || CONE, K = this.K;
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729)) >>> 0;
      const rng = mulberry32(seed);
      /* SQUARE-based cone: squared to the street (seeded quarter + a few
         degrees of slop) instead of a free 2π roll that cocked the base
         at any stray angle to the curb line. Variety survives in which
         quarter, the slop, and the height jitter below. */
      const cthSeed = Math.floor(rng()*4) * (Math.PI/2) + (rng() - 0.5) * 0.16;
      const H = C.height * (0.9 + rng()*0.2);
      const phi = (data && data.phi) || 0;
      const ph2 = !!(data && data.phase === 2);
      const cth = (data && data.fallPsi !== undefined) ? data.fallPsi : cthSeed;
      const fc = Math.cos(cth), fsn = Math.sin(cth);
      const cphi = Math.cos(phi), sphi = Math.sin(phi);
      const pvt = C.base/2;

      /* tip(u,h): the one function that encodes the pose, in the
         (fall-axis, height) plane — bends within a frame fixed by cth */
      const tip = (u, h) => {
        if(phi === 0) return { u, z: h };
        if(!ph2) return { u: pvt + (u - pvt)*cphi + h*sphi, z: -(u - pvt)*sphi + h*cphi };
        return { u: pvt + 3 + (u - pvt)*cphi + (h - 3)*sphi, z: -(u - pvt)*sphi + (h - 3)*cphi };
      };
      const L = (u, v, h) => {
        const tt = tip(u, h);
        return W(tt.u*fc - v*fsn, tt.u*fsn + v*fc, tt.z);
      };
      const dAt = (u, v, h) => {
        const tt = tip(u, h);
        return (tt.u*fc - v*fsn) + (tt.u*fsn + v*fc) + tt.z*0.4;
      };
      const rOf = hh => 8.5 - (8.5 - 1.8) * (hh / H);   // per-instance taper (visual variety, as before)
      const place = (hh, r, n=12) => {
        const pts = [];
        for(let i=0; i<n; i++){
          const psi2 = (i/n)*Math.PI*2;
          pts.push(L(Math.cos(psi2)*r, Math.sin(psi2)*r, hh));
        }
        return pts;
      };

      /* shadow removed (requested) — the cone sits directly on its
         base slab with no cast ellipse. */

      const baseSlab = () => {
        const hb = C.base/2, pts = [];
        for(const bc of [[-hb,-hb],[hb,-hb],[hb,hb],[-hb,hb]]){
          pts.push(L(bc[0], bc[1], 0)); pts.push(L(bc[0], bc[1], 3));
        }
        this.quadOn(g, convexHull(pts), C.bodyDk);
        const nu = sphi, nz = cphi;
        if(nu*fc + nu*fsn + nz > 0.05){
          const top = [L(-hb,-hb,3), L(hb,-hb,3), L(hb,hb,3), L(-hb,hb,3)];
          this.quadOn(g, top, C.body);
          this.edgeOn(g, top, C.bodyDk, 1.5);
        }
      };
      const body = () => {
        this.quadOn(g, convexHull(place(2, rOf(2)).concat(place(H, 1.8))), C.body);
        if(C.band > 0){
          const b0 = H*0.52, b1 = Math.min(H*0.52 + C.band, H*0.9);
          this.quadOn(g, convexHull(place(b0, rOf(b0)+0.5).concat(place(b1, rOf(b1)+0.5))), C.band_c);
        }
        this.quadOn(g, place(H, 1.8, 8), C.bodyDk);
      };
      const cparts = [
        { d: dAt(0, 0, 1.5), fn: baseSlab },
        { d: dAt(0, 0, H*0.45), fn: body }
      ];
      cparts.sort((p1, p2) => p1.d - p2.d);
      for(const pt of cparts) pt.fn();
    } else if(kind === "hydrant" || kind === "hydrantBurst"){
      /* approved in hydrant lab: height 20 · base 8 · dome 6.5 · nozzle 2.6.
         hydrantBurst shears the front nozzle open with an animated water
         arc and a puddle that paints early (ground layer, like the
         shadow) so the hydrant's own body always draws over it. */
      const HH = HYD;
      const bursting = kind === "hydrantBurst" || !!(data && data.burst);
      /* the "facing" checks below (puddle, spray, breakable nozzle) all
         gate on hth -- a per-hydrant RANDOM decorative rotation, not the
         route's actual heading or camera direction. For the static lab
         gallery (kind==="hydrantBurst", no live data) that randomness is
         fine, just visual variety across instances. But for a real,
         player-triggered burst (data.burst) it meant roughly half of
         all burst hydrants never showed water at all -- the slip/
         collision physics don't care about hth, so the player could
         hydroplane with nothing visible to explain it (reported
         2026-07-24). forceVisible makes the breakable nozzle's spray +
         puddle always show for a live burst; the decorative rear nozzle
         and the static gallery kind are untouched. */
      const forceVisible = !!(data && data.burst);
      const grow = (data && data.burstT !== undefined)
        ? Math.min(1, (t - data.burstT)/1800) : 1;
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x4a7d) >>> 0;
      const rng = mulberry32(seed);
      const hth = rng()*Math.PI*2;
      const hcs = Math.cos(hth), hsn = Math.sin(hth);
      const height = HH.height;
      const GG = (a, b, h) => W(a*hcs - b*hsn, a*hsn + b*hcs, h);
      const dAt = (a, b, h) => a*(hcs+hsn) + b*(hcs-hsn) + h*0.4;

      const rOf = h => {
        const u = h / height;
        if(u < 0.08) return HH.baseR;
        if(u < 0.75) return HH.baseR*0.62 - (HH.baseR*0.62 - HH.baseR*0.5)*((u-0.08)/0.67);
        return HH.baseR*0.5 + (HH.baseR*0.78 - HH.baseR*0.5) * ((u-0.75)/0.25);
      };
      const place = (h, r, n=14) => {
        const pts = [];
        for(let i=0; i<n; i++){
          const phi = (i/n)*Math.PI*2, c3 = Math.cos(phi)*r, s3 = Math.sin(phi)*r;
          pts.push(GG(c3, s3, h));
        }
        return pts;
      };

      const hsh = GG(0, 0, 0);
      g.fillStyle(HH.shadow, 0.14);
      g.fillEllipse(hsh.x, hsh.y + 2, HH.baseR*2.1*this.K*0.42, HH.baseR*0.95*this.K*0.42);

      /* puddle: ground decal, paints BEFORE the hydrant's own body
         parts so the barrel/dome/nozzles naturally draw over it. */
      if(bursting){
        const nc0 = 1, ns0 = 0;
        const facing0 = (nc0*(hcs+hsn) + ns0*(hcs-hsn) > 0) || forceVisible;
        if(facing0){
          const tipA0 = HH.baseR*0.55 + HH.nozR*2.2;
          /* robot-burst floods pool around the base (that's where the
             slip zone lives); the lab's static gallery kind keeps the
             original thrown-landing rings */
          /* pre-burst (pudDir set at spawn): the flood a full tile over
             along the walk; fresh robot-bursts still pool at the base. */
          const preOff = (data && data.pudDir) ? data.pudDir * T2 : 0;
          const isLiveBurst = !!(data && data.burst);
          const landA = isLiveBurst ? 8 + preOff : tipA0 + nc0*26;
          const landB = isLiveBurst ? 0 : ns0*26;
          const place2D = isLiveBurst ? W : GG;
          /* the puddle must TELL THE TRUTH about the slip zone
             (2026-07-27, "spinning out but the puddle isn't on the
             square"): the sim's hydroplane test is a RECTANGLE —
             |sdx| < HYD_SLIP.pud along the route by ±1.5·T2 across
             the lanes (the lateral band was deliberately widened
             2026-07-24 so a row-1 driver gets wet too), but the art
             stayed a circle of radius pud=41 centered on row 0 —
             not even reaching row 1's center 92 units away. Live
             bursts now draw an ELLIPSE with exactly the sim's two
             semi-axes, so wherever the robot can slip, there is
             visible water. Gallery/decorative rings keep the
             original circles (radB === radA). */
          /* puddleRing takes separate B radii for the two lateral sides
             (radBPos for local +b, radBNeg for local -b) instead of one
             symmetric radius. */
          const puddleRing = (radA, radBPos, radBNeg, nn=16) => {
            const pts = [];
            for(let i=0; i<nn; i++){
              const phi = (i/nn)*Math.PI*2;
              const radB = Math.sin(phi) >= 0 ? radBPos : radBNeg;
              pts.push(place2D(landA + Math.cos(phi)*radA, landB + Math.sin(phi)*radB, 0.3));
            }
            return pts;
          };
          const outerA = ((data && data.burst) ? HYD_SLIP.pud : TILE*0.85) * grow;
          /* cone/hydrant clutter pass (2026-08-10, "overflowing into the
             street... too oval"): live bursts used to draw a SYMMETRIC
             ellipse using the sim's full +-1.5*T2 lateral reach on both
             sides. But hydrants only ever spawn at row 0, closest to the
             curb (see the hazard spawn note above), and local +b here is
             the curb/road-ward side -- confirmed against ROBOT_SIDE (a
             fixed constant, so this holds for all 4 headings, not just
             the one tested): increasing row (away from the curb) is -b,
             so +b is the road. The sim's inFlood test can only ever fire
             for the robot, which never leaves the sidewalk lanes, so the
             +b reach was pure visual overflow with zero gameplay
             function. outerBPos now clamps to the same TILE*0.85 radius
             the static gallery puddle already uses (comfortably inside
             the curb, row 0's center sits T2*0.5=46 units from it) while
             outerBNeg keeps the full sim-matching reach toward row 1, so
             the truth-telling for the one lane that's actually reachable
             stays intact. */
          const outerBNeg = isLiveBurst ? T2*1.5 * grow : outerA;
          const outerBPos = isLiveBurst ? TILE*0.85 * grow : outerA;
          const innerA = ((data && data.burst) ? HYD_SLIP.pud*0.62 : TILE*0.55) * grow;
          const innerBNeg = isLiveBurst ? outerBNeg*0.62 : innerA;
          const innerBPos = isLiveBurst ? outerBPos*0.62 : innerA;
          this.quadOn(g, puddleRing(outerA, outerBPos, outerBNeg), HH.water, 0.28);
          this.quadOn(g, puddleRing(innerA, innerBPos, innerBNeg), HH.water, 0.22);
        }
      }

      const hbarrel = () => {
        const n = 6, all = [];
        for(let i=0; i<=n; i++) all.push(...place(i/n*height*0.9, rOf(i/n*height*0.9)));
        this.quadOn(g, convexHull(all), HH.cap);
      };
      const hshoulder = () => {
        const h0 = height*0.75, h1 = height*0.9;
        this.quadOn(g, convexHull(place(h0, rOf(h0)).concat(place(h1, rOf(h1)))), HH.cap);
      };
      const hdome = () => {
        const domeBase = height*0.9, domeR = HH.domeR;
        const n = 8, rings = [];
        for(let i=0; i<=n; i++){
          const u = i/n, r2 = domeR * Math.cos(u*Math.PI*0.5);
          rings.push(place(domeBase + u*domeR*0.9, r2));
        }
        const all = []; for(const r2 of rings) all.push(...r2);
        this.quadOn(g, convexHull(all), HH.cap);
        const capTop = GG(0, 0, domeBase + domeR*0.9 + 1);
        g.fillStyle(HH.capDk, 1);
        g.fillCircle(capTop.x, capTop.y, 1.8*this.K*0.45);
      };
      const hnozzleSpray = (ang, r) => () => {
        if(!bursting) return;
        const nc = Math.cos(ang), ns = Math.sin(ang);
        const facing = (nc*(hcs+hsn) + ns*(hcs-hsn) > 0) || forceVisible;
        if(!facing) return;
        const tipA = nc*(HH.baseR*0.55 + r*2.2), tipB = ns*(HH.baseR*0.55 + r*2.2);
        const hgt = height*0.42;
        const n = 9;
        for(let i=0; i<n; i++){
          const u = ((t*0.0026 + i/n) % 1);
          const dist = u * 26;
          const arcH = hgt + 14*u - 26*u*u;
          const pt = GG(tipA + nc*dist, tipB + ns*dist, Math.max(arcH, 0.5));
          const alpha = 0.9 * (1 - u*0.55);
          const r2 = Math.max(0.6, 1.6 - u*1.0);
          g.fillStyle(u > 0.82 ? HH.waterDk : HH.water, alpha);
          g.fillCircle(pt.x, pt.y, r2*this.K*0.4);
        }
      };
      const hnozzle = (ang, r, breakable) => () => {
        const nc = Math.cos(ang), ns = Math.sin(ang);
        const baseA = nc*(HH.baseR*0.55), baseB = ns*(HH.baseR*0.55);
        const tipA = nc*(HH.baseR*0.55 + r*2.2), tipB = ns*(HH.baseR*0.55 + r*2.2);
        const hgt = height*0.42;
        const ring = (a0,b0,rad) => {
          const pts = [];
          for(let i=0;i<10;i++){
            const phi=(i/10)*Math.PI*2;
            const perpA = -ns, perpB = nc;
            pts.push(GG(a0 + Math.cos(phi)*rad*perpA, b0 + Math.cos(phi)*rad*perpB, hgt + Math.sin(phi)*rad));
          }
          return pts;
        };
        this.quadOn(g, convexHull(ring(baseA,baseB,r).concat(ring(tipA,tipB,r))), HH.cap);
        const facing = (nc*(hcs+hsn) + ns*(hcs-hsn) > 0) || (breakable && forceVisible);
        if(!facing) return;
        if(bursting && breakable){
          this.quadOn(g, ring(tipA,tipB,r*0.9), HH.nut);
          this.quadOn(g, ring(tipA,tipB,r*0.5), HH.capDk);
        } else {
          this.quadOn(g, ring(tipA,tipB,r*0.8), HH.capDk);
        }
      };

      const domeBase = height*0.9, domeR = HH.domeR;
      const hparts = [
        { d: dAt(0,0,height*0.3), fn: hbarrel },
        { d: dAt(0,0,height*0.82), fn: hshoulder },
        { d: dAt(HH.baseR*0.55*Math.cos(0), HH.baseR*0.55*Math.sin(0), height*0.42), fn: hnozzle(0, HH.nozR, true) },
        { d: dAt(HH.baseR*0.55*Math.cos(Math.PI), HH.baseR*0.55*Math.sin(Math.PI), height*0.42), fn: hnozzle(Math.PI, HH.nozR, false) },
        { d: dAt(0,0, domeBase+domeR*0.9), fn: hdome },
        { d: dAt(HH.baseR*0.55 + HH.nozR*2.2 + 20, 0, height*0.42 + 8), fn: hnozzleSpray(0, HH.nozR) }
      ];
      hparts.sort((p1, p2) => p1.d - p2.d);
      for(const pt of hparts) pt.fn();

      /* burst droplets: plain local W(), not decoratively rotated —
         same convention as bin/planter debris. Airborne droplets get
         a short fall streak; landed ones flatten into little splash
         ellipses that fade as life runs out (they evaporate into the
         flood rather than settling like leaves). */
      if(data && data.items && data.items.length){
        for(const it of data.items){
          const p = W(it.x, it.y, it.z);
          const a = Math.max(0, Math.min(1, it.life));
          if(!it.landed){
            g.fillStyle(it.col, 0.9*a);
            g.fillCircle(p.x, p.y, it.size*this.K*0.42);
            const p2 = W(it.x - it.vx*1.4, it.y - it.vy*1.4, it.z - it.vz*1.4 + 0.6);
            g.lineStyle(Math.max(1, it.size*this.K*0.25), it.col, 0.4*a);
            g.lineBetween(p2.x, p2.y, p.x, p.y);
          } else {
            g.fillStyle(it.col, 0.5*a);
            g.fillEllipse(p.x, p.y, it.size*this.K*1.1*(2-a), it.size*this.K*0.45*(2-a));
          }
        }
      }
    } else if(kind === "robot"){
      /* other robots (requested 2026-07-24): a simplified sibling body,
         NOT a call into the player's own 1300-line drawRobot -- too
         tightly coupled to the pickup/dropoff timeline and live tilt/
         roll/pitch state to safely reuse. Same BODY/LID/WHEEL/STRIPE/
         FLAG dimensions and SKIN-family colors as Tipsey though, so the
         silhouette reads as unmistakably "one of these" even with all
         new code.

         Two variants (phase 2, 2026-07-25): parked robots face ACROSS
         the lane band (fwd=rv) toward the road, same as before. Roving
         ones (data.roving) face their actual direction of TRAVEL
         (fwd=dv) via robotSpotAt, flipping RA with the walk direction
         so they turn around like a real vehicle at each end of their
         route instead of driving backwards. Once knocked, a roving
         robot freezes at hz.knockA (captured by the collision code at
         the moment of impact) rather than continuing to animate or
         snapping back toward its spawn point.

         Fixed 2026-07-25: the body was drawing BOTH its left and
         right side faces (b=+hy AND b=-hy) instead of the one real
         camera-facing pair -- there's no viewing angle where you'd
         see both sides of a box at once, so the true front face was
         never drawn at all. Now resolves which "a" face and which "b"
         face actually face the camera -- same faceA/faceB test
         drawPersonHull already uses -- and draws exactly those two. */
      const col = ROBOT_NPC;
      const knocked = !!(data && data.knocked);
      const roving = !!(data && data.roving);
      const spot = (roving && !knocked) ? robotSpotAt(t, data) : null;
      const walkA = knocked ? ((data && data.knockA) || 0) : (spot ? spot.a : 0);
      /* detour sidestep (see detourBAt): lateral along rv, the same
         axis laneOffset lives on -- a rover eases a lane over around
         a static prop and back. Frozen at knockB once knocked, same
         contract as knockA. */
      const walkB = knocked ? ((data && data.knockB) || 0) : (spot ? spot.b : 0);
      const ex = x + dv.x*walkA + rv.x*walkB, ey = y + dv.y*walkA + rv.y*walkB;

      const fwdV = roving ? dv : rv, sideV = roving ? rv : dv;
      /* RA freeze (fixed 2026-07-27): a knocked rover keeps the travel
         direction it had AT IMPACT (hz.knockRA, captured by the
         collision code) instead of snapping to +1. The old expression
         fell through to 1 the instant knocked went true, mirroring the
         whole travel frame -- a rover on its return leg (dir=-1)
         visibly flipped 180 degrees as it fell, which is why the face
         appeared to jump to the other end. Same freeze contract as
         knockA/knockB. */
      const RA = roving
        ? (knocked ? ((data && data.knockRA) || 1) : (spot ? spot.dir : 1))
        : 1;

      const bDir = { x: sideV.x, y: sideV.y };
      const faceB = Math.sign(bDir.x + bDir.y) || 1;

      const hx = BODY.hx, hy = BODY.hy;

      /* tipped-over pose (requested 2026-07-25; physics rework
         2026-07-27 to match Tipsey's own tip): a 90-degree pivot
         rotation in the (b,h) plane, wrapping RW itself so every part
         (body, wheels, lid, face) rotates together automatically.

         Three fixes from the reported "tipping wrong / draw wrong"
         (2026-07-27):
         1. ROTATION SENSE. The old code pivoted on the +b edge but
            rotated the body DOWN past it -- verified numerically, at
            full tip the whole shell sat at h=-hy, 17 units below the
            pavement, mirrored. The face-normal test rotated the same
            inverted way, so face selection kept picking back faces as
            it sank -- that's most of the "draw wrong". tps now
            carries the sign (-knockDir), the same pivot-side/rotation
            pairing Tipsey's own roll transform in T() uses (pivot on
            the edge it falls TOWARD, body sweeps up and over it,
            everything stays at h>=0).
         2. DIRECTION. Was hardcoded to the camera-facing edge; now
            hz.knockDir (captured by the collision code at impact,
            Tipsey's own tipDir = sign(tilt) idea): side hits tip away
            from Tipsey across the lane axis, head-on tips pick the
            axis the impact actually pushed along (random side where
            the impact axis can't map to b, matching Tipsey's own
            random-sign convention for its robot collisions).
         3. EASING. Was a constant-velocity 450ms ramp (read robotic);
            now the closed-form equivalent of Tipsey's own per-frame
            tipT = Linear(tipT, 1, 0.09) @60fps -- exponential
            ease-out, tau ~185ms: fast initial fall settling into
            rest. Closed form because this draw is stateless in t. */
      const knockT = knocked ? ((data && data.knockT) || t) : t;
      const knockDir = knocked ? ((data && data.knockDir) || faceB) : 1;
      const tipProg = knocked ? 1 - Math.exp(-(t - knockT)/185) : 0;
      const tipAngle = tipProg * (Math.PI/2);
      const tpc = Math.cos(tipAngle), tps = -knockDir*Math.sin(tipAngle);
      const pivotB = knockDir*hy, pivotH = 0;
      const RW = (a, b, h) => {
        let b2 = b, h2 = h;
        if(tipAngle !== 0){
          const db = b - pivotB, dh = h - pivotH;
          b2 = pivotB + db*tpc - dh*tps;
          h2 = pivotH + db*tps + dh*tpc;
        }
        return this.W(ex + fwdV.x*a*RA + sideV.x*b2, ey + fwdV.y*a*RA + sideV.y*b2, h2);
      };

      /* shadow: Tipsey's own tipped shadow ring, ported verbatim (his
         ring is P(cos*34, -tipT*26*tipDir + sin*(30+tipT*26), 0.5)) --
         a ground-plane ring that slides 26 toward the fall side and
         stretches +26 along b as the body goes down. Same constants,
         so NPC shadows match the player exactly, upright and fallen.
         (Replaced the screen-space fillEllipse 2026-07-27: an ellipse
         can't align with sideV, and its slide/stretch constants were
         ad-hoc rather than Tipsey's. Earlier bug in the same spot: the
         shadow went through RW(0,0,0), which the tip rotation lifts 17
         units into the air -- a shadow is cast geometry, it never
         rotates.) NPC fall side is +knockDir along b, so his
         -tipT*26*tipDir maps to +tipProg*26*knockDir here. */
      const shPts = [];
      for(let i = 0; i < 12; i++){
        const a = (i/12)*Math.PI*2;
        const sb = knockDir*tipProg*26 + Math.sin(a)*(30 + tipProg*26);
        const sa = Math.cos(a)*34;
        shPts.push(this.W(ex + fwdV.x*sa + sideV.x*sb, ey + fwdV.y*sa + sideV.y*sb, 0.5));
      }
      this.quadOn(g, shPts, SKIN_BASE.shadow, 0.15);

      /* Every box face tested individually against its OWN rotated
         normal, same technique drawLid already uses (6 face normals,
         draw whichever ones actually face the camera) -- NOT the
         fixed "always top + one A-face + one B-face" from before.
         That fixed selection was only ever valid for the UPRIGHT
         case; once tipped, which faces are actually camera-facing
         changes too, but the old code kept drawing the same three
         regardless of rotation -- that's what produced the
         fragmented, wrong-looking pieces (reported 2026-07-25).
         World-facing test: rotate each face's local normal by the
         same (b,h) tip rotation as points, map to world via fwdV/
         sideV (the "h" component maps straight to world vertical,
         same as points), sum x+y+z > 0 -- exactly drawLid's own
         HN()+w.x+w.y+w.z test. At tipAngle=0 this reduces exactly to
         the old faceA/faceB single-face selection (verified
         algebraically before shipping), so the standing pose is
         pixel-identical to before -- only the tipped pose changes. */
      const box = (bhx, bhy, z0, z1, cTop, cA, cB, hingeAngle=0) => {
        /* lid hinge (requested 2026-07-25, follow-up to the tip fix):
           an independent swing-open rotation, composed with the whole-
           body tip rather than replacing it -- same relationship
           Tipsey's own lidAng has to his body roll. Position: rotate
           around the hinge's own pivot (one edge of THIS box, matching
           drawLid's -hy,z0 convention) first, then let the outer RW
           apply the body-tip rotation on top -- two rotations applied
           in sequence. Visibility only needs their SUM: rotations in
           the same plane add for a direction vector regardless of
           what pivots the position math used, so there's no need to
           redo the full two-pivot chain just for the normal test.
           The body term is SIGNED (-knockDir*tipAngle) because RW's
           tps carries the knockDir sign -- the normals must rotate
           the same sense as the points or face selection breaks again
           (that mismatch was the fragmented-draw bug's other half). */
        const hpc = Math.cos(hingeAngle), hps = Math.sin(hingeAngle);
        const hPivotB = -bhy, hPivotH = z0;
        const localRW = (a, b, h) => {
          let b2 = b, h2 = h;
          if(hingeAngle !== 0){
            const db = b - hPivotB, dh = h - hPivotH;
            b2 = hPivotB + db*hpc - dh*hps;
            h2 = hPivotH + db*hps + dh*hpc;
          }
          return RW(a, b2, h2);
        };
        const effA = -knockDir*tipAngle + hingeAngle;
        const epc = Math.cos(effA), eps = Math.sin(effA);
        const faces = [
          { na:0, nb:0,  nh:1,  col:cTop, pts:[[-bhx,-bhy,z1],[bhx,-bhy,z1],[bhx,bhy,z1],[-bhx,bhy,z1]] },
          { na:0, nb:0,  nh:-1, col:cTop, pts:[[-bhx,-bhy,z0],[-bhx,bhy,z0],[bhx,bhy,z0],[bhx,-bhy,z0]] },
          { na:1, nb:0,  nh:0,  col:cA,   pts:[[bhx,-bhy,z0],[bhx,bhy,z0],[bhx,bhy,z1],[bhx,-bhy,z1]] },
          { na:-1,nb:0,  nh:0,  col:cA,   pts:[[-bhx,bhy,z0],[-bhx,-bhy,z0],[-bhx,-bhy,z1],[-bhx,bhy,z1]] },
          { na:0, nb:1,  nh:0,  col:cB,   pts:[[bhx,bhy,z0],[-bhx,bhy,z0],[-bhx,bhy,z1],[bhx,bhy,z1]] },
          { na:0, nb:-1, nh:0,  col:cB,   pts:[[-bhx,-bhy,z0],[bhx,-bhy,z0],[bhx,-bhy,z1],[-bhx,-bhy,z1]] },
        ];
        for(const f of faces){
          if(f.col === null) continue;
          let nb2 = f.nb, nh2 = f.nh;
          if(effA !== 0){
            nb2 = f.nb*epc - f.nh*eps;
            nh2 = f.nb*eps + f.nh*epc;
          }
          const wx = fwdV.x*f.na*RA + sideV.x*nb2, wy = fwdV.y*f.na*RA + sideV.y*nb2;
          if(wx + wy + nh2 <= 0) continue;
          const pts = f.pts.map(([a,b,h]) => localRW(a, b, h));
          this.quadOn(g, pts, f.col);
          this.edgeOn(g, pts, SKIN_BASE.outline, this.kw(1));
        }
      };

      /* undercarriage: same dark base box Tipsey's own body sits on */
      /* wheels: Tipsey's own two-sided mounting-face system, ported
         (rework 2026-07-27; replaces both the static camera-side
         faceB pick AND the short-lived wheelsUnder ordering hack).
         BOTH wheel rows exist; each row draws iff the body face it's
         bolted to (local (0, side, 0)) faces the camera after the tip
         rotation -- the same projection-exact normal test box() uses
         for every hull face. Far row draws BEFORE the body (occluded
         by the shell, only slivers peek below the undercarriage, same
         as Tipsey upright), near row AFTER. Tipped, the test hands the
         sky-facing row to the near pass in BOTH fall directions --
         exactly Tipsey's fallen pose -- and the ground row to the far
         pass where the shell hides it. Each ring is TWO rings offset
         along the tread width combined via convexHull, drawWheel's
         own degenerate-outline fix. The trio is depth-sorted per
         Tipsey's wheels.sort (his depth(): x+y+z*0.4), not fixed array
         order. Hub face picks whichever tread face's outward normal
         faces the camera (his b0/b1 depth pick, normal-test form). */
      const W2 = 7.5;
      const wheelRingAt = (wx, ob, r) => {
        const pts = [];
        for(let i=0; i<14; i++){
          const a = (i/14)*Math.PI*2;
          pts.push(RW(wx + Math.cos(a)*r, ob, WHEEL.z + Math.sin(a)*r));
        }
        return pts;
      };
      /* spin phase multiplied by RA: RW mirrors the wheel through the
         travel axis when RA=-1, which would flip the bolt's apparent
         rotation direction -- negating the phase with it keeps the
         wheels visually rolling forward on both legs of the route
         (fixed 2026-07-26, part of the reverse-driving cleanup). */
      const wheelSpinPhase = (roving && !knocked) ? t*0.03*RA : 0;
      const bodyAngC = Math.cos(-knockDir*tipAngle), bodyAngS = Math.sin(-knockDir*tipAngle);
      const wNormFaces = (nS) => {           // does a local b-normal of sign nS face camera?
        const nb2 = nS*bodyAngC, nh2 = nS*bodyAngS;
        return sideV.x*nb2 + sideV.y*nb2 + nh2;
      };
      const rotBH = (b, h) => {
        if(tipAngle === 0) return { b, h };
        const db = b - pivotB;
        return { b: pivotB + db*tpc - h*tps, h: db*tps + h*tpc };
      };
      const drawWheelAt = (wx, side) => {
        const wb = side*WHEEL.side;
        const bA = wb - W2/2, bB = wb + W2/2;
        const bOut = wNormFaces(1) >= wNormFaces(-1) ? bB : bA;   // camera-facing tread face
        this.quadOn(g, convexHull(wheelRingAt(wx, bA, WHEEL.r)
                                   .concat(wheelRingAt(wx, bB, WHEEL.r))), SKIN_BASE.wheelDark);
        const faceRing = wheelRingAt(wx, bOut, WHEEL.r);
        this.quadOn(g, faceRing, SKIN_BASE.wheel);
        this.edgeOn(g, faceRing, SKIN_BASE.outline, this.kw(2));
        this.quadOn(g, wheelRingAt(wx, bOut, WHEEL.r*0.55), SKIN_BASE.wheelHubFace);
        const spinA = wheelSpinPhase + wx*0.2;
        const boltPt = RW(wx + Math.cos(spinA)*WHEEL.r*0.34, bOut, WHEEL.z + Math.sin(spinA)*WHEEL.r*0.34);
        g.fillStyle(SKIN_BASE.wheelHub, 1);
        g.fillCircle(boltPt.x, boltPt.y, 2.4*this.kScale());
      };
      const drawWheelRows = (near) => {
        const row = [];
        for(const side of [-1, 1]){
          if((wNormFaces(side) > 0) !== near) continue;
          for(const wx of WHEEL.xs){
            const r2 = rotBH(side*WHEEL.side, WHEEL.z);
            const wxw = ex + fwdV.x*wx*RA + sideV.x*r2.b;
            const wyw = ey + fwdV.y*wx*RA + sideV.y*r2.b;
            row.push({ wx, side, d: wxw + wyw + r2.h*0.4 });
          }
        }
        row.sort((a, b) => a.d - b.d);
        for(const w of row) drawWheelAt(w.wx, w.side);
      };
      drawWheelRows(false);   // far row first -- the shell paints over it

      box(24, 17, 6, BODY.z0+1, 0x3f434c, 0x3a3d45, 0x2e3138);

      /* body */
      box(hx, hy, BODY.z0, BODY.z1, SKIN_BASE.bodyTop, SKIN_BASE.bodyRight, SKIN_BASE.bodyLeft);

      /* stripe band, blue accent -- no top, just the two side faces */
      box(hx+0.6, hy+0.6, STRIPE.z0, STRIPE.z1, null, col.stripe, col.stripeDk);

      /* lid: swings open on its own hinge as it falls, same relationship
         Tipsey's own lidAng has to his body roll. Reworked 2026-07-27 to
         mirror Tipsey's TWO physical outcomes (his tipped-state lid code,
         "confirmed in-game 2026-07-10 -- first guess had this
         backwards"): the hinge is a fixed edge (-bhy), so which way the
         body fell decides what gravity does to the lid afterward.
         Hinge edge lands DOWN (knockDir<0 here): lid falls open to 1.78
         and stays. Hinge edge lands UP (knockDir>=0): lid pops to ~0.9
         to spill, then gravity flops it back shut. Timing is the
         closed-form of Tipsey's own per-frame lerps: gate at tip
         half-way (~130ms, his tipT>0.5), approach at tau~333ms (his
         0.05/frame @60fps), close starting ~420ms after the gate (his
         postSpillMs>400). Closed form because this draw is stateless
         in t -- no lidAng state to lerp. */
      const lidT = knocked ? Math.max(0, t - knockT - 130) : 0;
      let lidHingeAng = 0;
      if(lidT > 0){
        if(knockDir < 0){
          lidHingeAng = 1.78 * (1 - Math.exp(-lidT/333));
        } else if(lidT < 420){
          lidHingeAng = 0.9 * (1 - Math.exp(-lidT/333));
        } else {
          lidHingeAng = 0.9 * (1 - Math.exp(-420/333)) * Math.exp(-(lidT - 420)/333);
        }
      }
      box(LID.hx, LID.hy, LID.z0, LID.z1, SKIN_BASE.bodyTop, SKIN_BASE.bodyRight, SKIN_BASE.bodyLeft, lidHingeAng);

      /* near wheel row after the body, Tipsey's own sequence -- see the
         mounting-face rationale above the undercarriage. */
      drawWheelRows(true);

      if(!knocked){
        /* flag: pinned to the REAR of the vehicle (-A in the RA travel
           frame -- RW applies RA, so it turns around with the robot),
           NOT "opposite the camera-facing face" as before. The old
           -faceA*25 made the flag teleport ends whenever the camera-
           facing test flipped (fixed 2026-07-26, same root cause as
           the reverse-driving face bug below). Straight pole (no lean
           animation for a static NPC) -- its screen-space direction is
           exactly (0,-1), so this reduces to the same triangle
           drawFlag builds for an unbent pole. */
        const flagA = -25, flagB = 17;
        const poleBase = RW(flagA, flagB, FLAG.z0);
        const poleTip = RW(flagA, flagB, FLAG.z1);
        /* pole width and pennant are SCREEN pixels, same as Tipsey's
           own drawFlag -- scale or the pennant swamps the robot at
           depth 3 */
        const fks = this.kScale();
        g.lineStyle(this.kw(3), SKIN_BASE.flagPole, 1);
        g.lineBetween(poleBase.x, poleBase.y, poleTip.x, poleTip.y);
        g.fillStyle(col.flag, 1);
        g.fillTriangle(poleTip.x, poleTip.y,
                       poleTip.x + 11*fks, poleTip.y,
                       poleTip.x, poleTip.y - 16*fks);
      }

      /* face: visor + eyes pinned to the TRUE FRONT (+A in the RA
         travel frame), drawn only when that front actually faces the
         camera -- same normal test the body's own +A panel uses (the
         tip rotation is in the (b,h) plane, so the a-normal is
         unaffected and the plain fwdV*RA test stays valid even while
         knocked). This replaces the old faceA*(hx+0.8) placement,
         which stamped the face on whichever END was camera-facing:
         guaranteed-visible, but on any leg where the robot's front
         pointed away from camera the face landed on its tail and the
         robot read as driving in reverse (reported on-device
         2026-07-26). Accepted tradeoff, confirmed: when a robot
         drives/faces away, you simply don't see its face -- exactly
         like a real vehicle. Position/size from Tipsey's own drawRobot
         (x=hx+0.8, visor z in [40,50], eyes at z=45). */
      if(fwdV.x*RA + fwdV.y*RA > 0){
        const fa = hx+0.8;
        const visor = [RW(fa,-13,50), RW(fa,13,50), RW(fa,13,40), RW(fa,-13,40)];
        const eks = this.kScale();
        this.quadOn(g, visor, SKIN_BASE.visor);
        this.edgeOn(g, visor, SKIN_BASE.outline, this.kw(1.5));
        if(knocked){
          g.lineStyle(this.kw(2), SKIN_BASE.eyeAlert, 1);
          for(const ey of [-7, 7]){
            const c = RW(fa, ey, 45), x = 4*eks;
            g.lineBetween(c.x-x, c.y-x, c.x+x, c.y+x);
            g.lineBetween(c.x-x, c.y+x, c.x+x, c.y-x);
          }
        } else {
          for(const ey of [-7, 7]){
            const c = RW(fa, ey, 45);
            g.fillStyle(SKIN_BASE.eye, 1);
            g.fillEllipse(c.x, c.y, 7*eks, 7*eks);
          }
        }
      }

      /* spilled cargo: burrito + fries, same per-hazard hz.items
         pattern bin/planter already use for their own spilled stuff.
         Drawn in WORLD space (not through the tip-rotated RW) since
         these are meant to be lying on the ground next to the fallen
         robot, not attached to its rotating body. */
      if(data && data.items && data.items.length){
        for(const it of data.items){
          const s2 = this.W(ex + it.x + 1, ey + it.y + 1, 0.4);
          g.fillStyle(0x000000, 0.15);
          g.fillEllipse(s2.x, s2.y, it.size*this.K*0.9, it.size*this.K*0.4);
        }
        for(const it of data.items){
          const p = this.W(ex + it.x, ey + it.y, it.z);
          if(it.kind === "burrito"){
            g.fillStyle(0xE8C468, 1);
            g.fillEllipse(p.x, p.y, it.size*this.K*1.3, it.size*this.K*0.7);
            g.fillStyle(0xC9A83E, 1);
            g.fillRect(p.x - it.size*this.K*0.55, p.y - 1, it.size*this.K*1.1, 2);
          } else {
            const c2 = Math.cos(it.ang), s3 = Math.sin(it.ang);
            g.fillStyle(0xF2C55C, 1);
            this.quadOn(g, [
              { x:p.x + c2*it.size*this.K*0.5, y:p.y + s3*it.size*this.K*0.3 },
              { x:p.x - s3*it.size*this.K*0.3, y:p.y + c2*it.size*this.K*0.3 },
              { x:p.x - c2*it.size*this.K*0.5, y:p.y - s3*it.size*this.K*0.3 },
              { x:p.x + s3*it.size*this.K*0.3, y:p.y - c2*it.size*this.K*0.3 }
            ], 0xF2C55C);
          }
        }
      }
    } else if(kind === "planter"){
      /* approved in planter lab (2026-07-08), sized up in the planter
         makeover (2026-07-10), variety + collision ported from the
         planter collision lab (2026-07-10): tapered concrete box +
         layered stalked bush. Two callers: the pure-decoration far-
         sidewalk placement (data===null, seeded random scale/variant,
         never falls) and the collidable hazard (data has its own
         scale/variantIdx/phi/pose/fallPsi/items — same convention
         bin/cone/scooter already use for their hazard data). */
      const PL = PLANTER;
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x2f61) >>> 0;
      const rng = mulberry32(seed);
      const isHaz = !!(data && data.scale !== undefined);
      const V = isHaz ? PLANTER_VARIANTS[data.variantIdx || 0] : PLANTER_VARIANTS[Math.floor(rng()*PLANTER_VARIANTS.length)];
      const scale = isHaz ? data.scale : (0.85 + rng()*0.5);
      const phi = isHaz ? (data.phi || 0) : 0;
      const boxW = 22*scale, boxD = 14*scale, boxH = 14*scale;
      const bushH = 20*scale, fullness = 5 + Math.floor(rng()*4);
      const flowering = rng() < 0.3;
      const GG = W;
      /* (dAt is defined below, through the tip transform) */
      const hw = boxW/2, hd = boxD/2, H = boxH;

      /* ONE continuous geometry (2026-07-26, blink fix): standing is
         just phi=0 of the tipped pose, the same architecture the cone
         and bin already use. The old version had TWO geometries -- a
         tapered pot with a domed bush for standing, a crude straight
         box with a ground-level bush ring for phi>0 -- with a hard
         switch at phi>0. The sim legitimately produces brief
         sub-balance phi excursions (a wobble that rocks and settles
         back), and every one of them popped the art to the fallen
         geometry for a few frames and back: the "blinked like it
         tipped but never did" artifact. Now the FULL standing art
         (taper, soil, stalked bush, flowers) is drawn through a rigid
         rotation about the pivot edge, so a wobble looks like a pot
         rocking and a real fall carries the same art all the way to
         the ground. fallPsi orients the fall in the LOCAL walk frame
         (cone's convention); the pivot-edge distance |fc|*hw+|fsn|*hd
         is exact for cardinal fall azimuths (fore/aft and cross-axis)
         and a fine approximation under the sim's small psi jitter. */
      const cth = (isHaz && data.fallPsi) || 0;
      const fc = Math.cos(cth), fsn = Math.sin(cth);
      const pivotA = Math.abs(fc)*hw + Math.abs(fsn)*hd;
      const cphi = Math.cos(phi), sphi = Math.sin(phi);
      const pslide = (isHaz && data.slide) || 0;   // the shove skid — bin's data.slide, same convention
      const tip = (u, h) => ({ u: pslide + pivotA - (pivotA-u)*cphi + h*sphi, z: (pivotA-u)*sphi + h*cphi });
      /* TP: local (a,b,h) offset -> project onto the fall frame,
         rigid-rotate about the pivot edge, map back to dv/rv offsets.
         GT feeds that through the locally-shadowed W (offsets from
         x,y, added exactly once -- the old double-add bug came from
         pre-adding x,y INTO the argument as well). Identity at phi=0,
         so standing/decoration planters render pixel-identically. */
      const TP = (a, b, h) => {
        const u = a*fc + b*fsn, v = -a*fsn + b*fc;
        const tt = tip(u, h);
        return { dx: tt.u*fc - v*fsn, dy: tt.u*fsn + v*fc, z: tt.z };
      };
      const GT = (a, b, h) => { const p = TP(a, b, h); return GG(p.dx, p.dy, p.z); };
      const dAt = (a, b, h) => { const p = TP(a, b, h); return p.dx + p.dy + p.z*0.4; };
      const baseShrink = 0.82;
      const corner = (sx, sy, h, shrink=1) => GT(sx*hw*shrink, sy*hd*shrink, h);

      /* planter body shadow removed (requested). */

      {
        const pbox = () => {
          /* silhouette backstop, tipped poses only: the two visible
             side faces below are picked by the STANDING camera test
             (faceX/faceY from dv) -- once the pot rotates, the set of
             camera-facing faces changes (the base can come into view)
             and gaps would show. A filled hull of all 8 corners
             underneath keeps every mid-fall/fallen pose solid without
             touching the standing art (guarded, phi=0 skips it). */
          if(phi > 0.05){
            const hull = [];
            for(const sx of [-1,1]) for(const sy of [-1,1]){
              hull.push(corner(sx,sy,H)); hull.push(corner(sx,sy,0,baseShrink));
            }
            this.quadOn(g, convexHull(hull), PL.boxDk);
          }
          const top = [corner(-1,-1,H), corner(1,-1,H), corner(1,1,H), corner(-1,1,H)];
          this.quadOn(g, top, PL.box);
          this.edgeOn(g, top, PL.boxDk, 1.2);
          /* the two outward faces visible under this fixed camera —
             was hardcoded to faceX=1,faceY=1, which is ONLY correct
             when fdir===0 (dv={1,0}). The collidable planter hazard
             (and now block-wrap scatter) can spawn at any of the 4
             facings via facingAt()/scatterBlockProp, and for the other
             3 the hardcoded version drew the WRONG two faces — this is
             the exact same "which 2 box faces face the camera" problem
             drawPersonHull already solves correctly for a continuous
             heading (faceA=sign(cs+sn), faceB=sign(cs-sn)); dv is just
             (cos,sin) of this box's 90°-snapped heading, so the same
             formula applies directly, for any orientation. */
          const faceX = Math.sign(dv.x + dv.y) || 1;
          const faceY = Math.sign(dv.x - dv.y) || 1;
          const xFace = [
            corner(faceX,-1,H), corner(faceX,1,H),
            corner(faceX,1,0,baseShrink), corner(faceX,-1,0,baseShrink)
          ];
          this.quadOn(g, xFace, faceX > 0 ? PL.boxDk : PL.boxDk2);
          /* yFace overlaps xFace by a hair at their shared edge (sx
             pushed just past 1) — a defensive seam guard. The two
             faces meet at an exact edge, and without a tiny overlap,
             sub-pixel rasterization gaps at that seam can make the
             face drawn first (xFace) show through as a sliver on some
             renderers, even though both faces are geometrically valid
             (verified: comparable non-degenerate area on every facing
             direction, nothing else drawn over it — this is purely a
             rasterization seam fix, invisible at normal zoom).
             The far corner used to be hardcoded to -1, written back
             when "past 1" only ever meant the +1 case — it never
             tracked faceX flipping to -1 (fdir 2/3), so instead of
             spanning the box's actual far edge it sat 0.03 units from
             the near corner: a sliver, not a face. -faceX is that far
             edge for either sign, so this is now the same full-width
             face (plus the same seam overlap) at every heading. */
          const yFace = [
            corner(-faceX,faceY,H), corner(faceX*1.03,faceY,H),
            corner(faceX*1.03,faceY,0,baseShrink), corner(-faceX,faceY,0,baseShrink)
          ];
          this.quadOn(g, yFace, faceY > 0 ? PL.boxDk2 : PL.boxDk);
          const soil = [corner(-0.82,-0.82,H-0.6), corner(0.82,-0.82,H-0.6), corner(0.82,0.82,H-0.6), corner(-0.82,0.82,H-0.6)];
          this.quadOn(g, soil, PL.soil);
        };
        const pbush = () => {
          const baseH = H + 1;
          const n = fullness;
          const puffs = [];
          puffs.push({ a:0, b:0, h:baseH + bushH*0.55, r:bushH*0.5, c:V.leafA });
          for(let i=0; i<n; i++){
            const ang = (i/n)*Math.PI*2 + rng()*0.4;
            const rr = (boxW*0.28 + rng()*boxW*0.12);
            const hh = baseH + bushH*(0.3 + rng()*0.55);
            const size = bushH*(0.28 + rng()*0.16);
            const shade = rng();
            const col = shade < 0.33 ? V.leafA : shade < 0.66 ? V.leafB : V.leafC;
            puffs.push({ a: Math.cos(ang)*rr, b: Math.sin(ang)*rr, h: hh, r: size, c: col, ang });
          }
          puffs.sort((p1,p2) => dAt(p1.a,p1.b,p1.h) - dAt(p2.a,p2.b,p2.h));
          for(const pf of puffs){
            const s0 = GT(pf.a*0.25, pf.b*0.25, baseH - 0.4);
            const s1 = GT(pf.a, pf.b, Math.max(pf.h - pf.r*0.35, baseH));
            g.lineStyle(Math.max(1, 1.1*this.K*0.4), PL.stalk, 1);
            g.lineBetween(s0.x, s0.y, s1.x, s1.y);
            const c = GT(pf.a, pf.b, pf.h);
            g.fillStyle(pf.c, 1);
            if(V.style === "spiky"){
              // ornamental-grass blade: thin triangles radiating from
              // the stalk tip instead of one round puff
              const nb = 4;
              for(let bIdx=0; bIdx<nb; bIdx++){
                const bAng = (pf.ang || 0) + (bIdx/nb)*Math.PI*2 + rng()*0.3;
                const tip = GT(pf.a + Math.cos(bAng)*pf.r*1.3, pf.b + Math.sin(bAng)*pf.r*1.3, pf.h + pf.r*0.7);
                const base1 = GT(pf.a + Math.cos(bAng+0.3)*pf.r*0.3, pf.b + Math.sin(bAng+0.3)*pf.r*0.3, pf.h - pf.r*0.3);
                const base2 = GT(pf.a + Math.cos(bAng-0.3)*pf.r*0.3, pf.b + Math.sin(bAng-0.3)*pf.r*0.3, pf.h - pf.r*0.3);
                g.fillTriangle(tip.x, tip.y, base1.x, base1.y, base2.x, base2.y);
              }
            } else {
              g.fillCircle(c.x, c.y, pf.r*this.K*0.42);
            }
          }
          if(flowering){
            const nf = Math.max(2, Math.round(n*0.6));
            for(let i=0; i<nf; i++){
              const ang = rng()*Math.PI*2;
              const rr = boxW*0.22 + rng()*boxW*0.16;
              const hh = baseH + bushH*(0.45 + rng()*0.5);
              const c = GT(Math.cos(ang)*rr, Math.sin(ang)*rr, hh);
              g.fillStyle(V.flower, 1);
              g.fillCircle(c.x, c.y, (1.6+rng())*this.K*0.42);
            }
          }
        };

        const pparts = [
          { d: dAt(0,0,H*0.4), fn: pbox },
          { d: dAt(0,0,H + bushH*0.6), fn: pbush }
        ];
        pparts.sort((p1, p2) => p1.d - p2.d);
        for(const pt of pparts) pt.fn();
      }

      /* spilled leaves/flowers: independent projectiles once launched,
         same "plain local W(), not tip()-rotated" convention bin's
         flung debris uses. */
      if(data && data.items && data.items.length){
        for(const it of data.items){
          const s2 = W(it.x + 1, it.y + 1, 0.4);
          g.fillStyle(PL.shadow, 0.13);
          g.fillEllipse(s2.x, s2.y, it.size*this.K*0.9, it.size*this.K*0.4);
        }
        for(const it of data.items){
          const p = W(it.x, it.y, it.z);
          g.fillStyle(it.col, 1);
          g.fillCircle(p.x, p.y, it.size*this.K*0.42);
        }
      }
    } else if(kind === "dog"){
      /* approved in dog lab v2: the one-eyed sidewalk chihuahua.
         SIZE unchanged — the game's approved DOG preset (0.8 scale)
         drives all proportions. Seeded per spawn: coat (3), scar
         side (L/R), and behavior — ~40% sit at a fixed spot, the
         rest patrol their spawn tile via dogSpotAt(t, seed): a pure
         function of time + seed, so the sim shifts the hitbox with
         the exact same call and the robot can bump a dog that walks
         into the lane (or be bumped by one). Trot is diagonal-pair
         legs, easing in/out between waypoints; he trembles when he
         stands still, because he is a chihuahua. */
      const D = DOG, L = D.len;
      const pseed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x6d0a) >>> 0;
      const dseed = (data && data.dogSeed !== undefined) ? data.dogSeed : pseed;
      const sitSeed = data ? !!data.sit : ((dseed >> 3) % 5 < 2);
      const spot = dogSpotAt(t, data || {dogSeed: dseed, sit: sitSeed});
      const flee = dogFleeAt(t, data);
      const settled = flee && flee.gone;
      const settledSpot = settled ? dogSettledSpot(data) : null;
      const sit = (sitSeed && !flee) || settled;     // a hit sitter leaps up; a settled dog sits too
      let spotA = spot.a, spotB = spot.b, spotTh = spot.th, walk = spot.walk;
      let tailCurlNow = D.tailCurl, scramble = false;
      if(settled){
        spotA = settledSpot.a;                        // stays right where the flee left him,
        spotB = settledSpot.b;                        // not wherever the old wander cycle
        spotTh = settledSpot.th;                       // has drifted to by now
        walk = 0;
      } else if(flee){
        spotA += flee.da;                            // no clamp: he is LEAVING the tile
        spotB += flee.db;
        spotTh = Math.atan2(-0.45, (data.fleeA || 1)); // face the run: along the flee, angled to the buildings
        walk = 1;                                    // flat-out the whole way
        tailCurlNow = 0;                             // tail stays tucked till he's gone
        scramble = true;                             // panic legs, no easing off
      }
      const thW = fdir*Math.PI/2 + spotTh;
      const cs = Math.cos(thW), sn = Math.sin(thW);
      const coat = DOG_COATS[dseed % 3];
      const blindSide = (dseed & 4) ? 1 : -1;
      const ax = x + dv.x*spotA + rv.x*spotB;
      const ay = y + dv.y*spotA + rv.y*spotB;
      const G = (a, b, h) => this.W(ax + a*cs - b*sn, ay + a*sn + b*cs, z + h);
      const depthAt = (a, b, h) => (ax + a*cs - b*sn) + (ay + a*sn + b*cs) + h*0.4;
      const walkPhase = t * (scramble ? 0.038 : 0.014);   // panic legs
      const walkAmt = walk;
      const tr = (walk < 0.25 && !flee) ? 1 : 0;   // tremble only while calmly standing
      const jb = tr * (Math.sin(t*0.052) + Math.sin(t*0.083)*0.5) * 0.28 * L;
      const jh = tr * Math.sin(t*0.097) * 0.18 * L;

    /* ---- pose anchors ---- */
    /* sit: seeded per spawn (see header) */
    const legH = D.legH * L;
    const bodyR = 5.0 * L, chestR = 5.6 * L;
    const headR = D.headR * L;
    const earH = D.earH * L;

    const rearA  = sit ? -8*L  : -9*L;
    const rearH  = sit ? bodyR*0.95 : legH + bodyR*0.72;
    const chestA = sit ? 4.5*L : 6*L;
    const chestH = sit ? legH + chestR*0.85 : legH + bodyR*0.72;
    const headA  = (sit ? 7.5*L : 9.5*L) + jb*0.15;
    const headH  = chestH + 6.2*L + headR*0.35 + jh;

    const ringAt = (a0, b0, h0, r, d1, d2, n=12) => {
      const pts = [];
      for(let i=0; i<n; i++){
        const phi = (i/n)*Math.PI*2, c = Math.cos(phi)*r, s2 = Math.sin(phi)*r;
        pts.push(G(a0 + c*d1.a + s2*d2.a, b0 + c*d1.b + s2*d2.b, h0 + c*d1.h + s2*d2.h));
      }
      return pts;
    };
    const V = {a:0,b:1,h:0}, HH = {a:0,b:0,h:1};
    const px = r => r * this.K * 1.12;          // sphere → screen radius

    /* ---- shadow ---- */
    const sh = G((rearA + chestA)/2, 0, 0);
    g.fillStyle(D.shadow, 0.13);
    g.fillEllipse(sh.x, sh.y + 1, (sit ? 34 : 40)*L, 14*L);

    /* ---- parts (built as closures, depth-sorted) ---- */

    const body = () => {
      const rear = ringAt(rearA, 0, rearH, bodyR, V, HH, 12);
      const chest = ringAt(chestA, 0, chestH, chestR, V, HH, 12);
      this.quadOn(g, convexHull(rear.concat(chest)), coat.body);
      const cap = ringAt(rearA - bodyR*0.25, 0, rearH, bodyR*0.9, V, HH, 12);
      this.quadOn(g, cap, coat.dk);                   // shaded rump cap
    };

    const haunch = s => () => {                  // sitting only: folded rear leg
      const c = G(rearA + 0.5*L, s*bodyR*0.72, bodyR*1.0);
      g.fillStyle(coat.body, 1);
      g.fillCircle(c.x, c.y, px(bodyR*0.9));
      g.lineStyle(1.5, coat.dk, 1);
      g.strokeCircle(c.x, c.y, px(bodyR*0.9));
      const f = G(rearA + 3*L, s*bodyR*0.8, 0.6);
      g.fillStyle(coat.dk, 1);
      g.fillEllipse(f.x, f.y, px(1.7*L)*1.6, px(1.7*L)*0.8);
    };

    const leg = (a0, s, foot) => () => {         // pin leg + paw
      const top = G(a0, s*2.9*L, chestH - 1*L);
      const bot = G(a0 + foot, s*2.9*L, 0.8);
      g.lineStyle(Math.max(2, 0.9*L*this.K*0.42), coat.body, 1);
      g.lineBetween(top.x, top.y, bot.x, bot.y);
      g.fillStyle(coat.dk, 1);
      g.fillEllipse(bot.x, bot.y + 1, px(1.4*L)*1.5, px(1.4*L)*0.7);
    };

    const chestPatch = () => {
      const c = G(chestA + chestR*0.45, 0, chestH - chestR*0.3);
      g.fillStyle(coat.chest, 1);
      g.fillCircle(c.x, c.y, px(chestR*0.52));
    };

    const neck = () => {
      const n0 = ringAt(chestA + 1*L, jb*0.3, chestH + 2*L, 2.5*L, V, HH, 10);
      const n1 = ringAt(headA - 1*L, jb*0.6, headH - headR*0.55, 2.2*L, V, HH, 10);
      this.quadOn(g, convexHull(n0.concat(n1)), coat.body);
    };

    const collar = () => {
      const cA = chestA + 1.6*L, cH = chestH + 2.8*L;
      const c0 = ringAt(cA, jb*0.35, cH, 2.7*L, V, HH, 10);
      const c1 = ringAt(cA + 0.7*L, jb*0.35, cH + 0.9*L, 2.6*L, V, HH, 10);
      this.quadOn(g, convexHull(c0.concat(c1)), D.collar);
      const tag = G(cA + 2.4*L, jb*0.35, cH - 1.4*L);
      g.fillStyle(0xe8c34a, 1);
      g.fillCircle(tag.x, tag.y, px(0.7*L));
    };

    const head = () => {                          // the apple dome
      const c = G(headA, jb, headH);
      g.fillStyle(coat.body, 1);
      g.fillCircle(c.x, c.y, px(headR));
    };

    const ear = s => () => {                      // giant bat ear
      const b1 = G(headA - headR*0.15, jb + s*headR*0.35, headH + headR*0.6);
      const b2 = G(headA - headR*0.7,  jb + s*headR*0.6,  headH + headR*0.28);
      const tp = G(headA - headR*0.5,  jb + s*(headR*0.85 + earH*0.32), headH + headR*0.45 + earH);
      g.fillStyle(coat.body, 1);
      g.fillTriangle(b1.x, b1.y, b2.x, b2.y, tp.x, tp.y);
      g.lineStyle(1.5, coat.dk, 1);
      g.strokeTriangle(b1.x, b1.y, b2.x, b2.y, tp.x, tp.y);
      const cx2 = (b1.x + b2.x + tp.x)/3, cy2 = (b1.y + b2.y + tp.y)/3;
      const lerp = (p2, k) => ({ x: p2.x + (cx2 - p2.x)*k, y: p2.y + (cy2 - p2.y)*k });
      const i1 = lerp(b1, 0.38), i2 = lerp(b2, 0.38), i3 = lerp(tp, 0.3);
      g.fillStyle(coat.ear, 1);
      g.fillTriangle(i1.x, i1.y, i2.x, i2.y, i3.x, i3.y);
    };

    const scarEye = s => () => {                  // the missing one: healed shut
      /* a short closed-lid stroke where the bug eye would sit, plus a
         faint scar nick crossing it — the street-veteran squint */
      const c0 = G(headA + headR*0.42, jb + s*headR*0.30, headH + headR*0.12);
      const c1 = G(headA + headR*0.42, jb + s*headR*0.58, headH + headR*0.08);
      g.lineStyle(px(headR*0.10), D.eye, 1);
      g.lineBetween(c0.x, c0.y, c1.x, c1.y);
      const n0 = G(headA + headR*0.32, jb + s*headR*0.44, headH + headR*0.32);
      const n1 = G(headA + headR*0.54, jb + s*headR*0.44, headH - headR*0.06);
      g.lineStyle(px(headR*0.05), coat.dk, 1);
      g.lineBetween(n0.x, n0.y, n1.x, n1.y);
      if(coat.n === "blk&tan"){                   // eyebrow dot survives the scar
        const eb = G(headA + headR*0.28, jb + s*headR*0.46, headH + headR*0.46);
        g.fillStyle(0xc98d4b, 1);
        g.fillCircle(eb.x, eb.y, px(headR*0.12));
      }
    };

    const eye = s => () => {                      // bug eye + glint
      const c = G(headA + headR*0.42, jb + s*headR*0.44, headH + headR*0.12);
      g.fillStyle(D.eye, 1);
      g.fillCircle(c.x, c.y, px(headR*0.21));
      g.fillStyle(D.glint, 1);
      g.fillCircle(c.x - px(headR*0.07), c.y - px(headR*0.08), px(headR*0.06));
      if(coat.n === "blk&tan"){                   // tan eyebrow dots
        const eb = G(headA + headR*0.28, jb + s*headR*0.46, headH + headR*0.46);
        g.fillStyle(0xc98d4b, 1);
        g.fillCircle(eb.x, eb.y, px(headR*0.12));
      }
    };

    const muzzle = () => {                        // short tapered snoot + nose
      const m0 = ringAt(headA + headR*0.5,  jb, headH - headR*0.28, headR*0.4,  V, HH, 10);
      const m1 = ringAt(headA + headR*0.95, jb, headH - headR*0.34, headR*0.22, V, HH, 10);
      this.quadOn(g, convexHull(m0.concat(m1)), coat.chest);
      const n = G(headA + headR*1.02, jb, headH - headR*0.3);
      g.fillStyle(D.nose, 1);
      g.fillCircle(n.x, n.y, px(headR*0.13));
    };

    const tail = () => {                          // sickle curl over the back
      const rr = 3.9*L;
      const Ca = rearA - 0.8*L, Ch = rearH + bodyR*0.15 + rr;
      const thMax = Math.min((0.55 + 0.85*tailCurlNow) * Math.PI, 1.9*Math.PI);
      const n = 8;
      for(let i=0; i<=n; i++){
        const u = i/n, ang = u*thMax;
        const a2 = Ca - rr*Math.sin(ang);
        const h2 = Ch - rr*Math.cos(ang);
        const b2 = 1.0*L + u*0.8*L;
        const p2 = G(a2, b2, h2);
        g.fillStyle(u > 0.75 ? coat.chest : coat.dk, 1);
        g.fillCircle(p2.x, p2.y, px((1.25 - u*0.55)*L));
      }
    };

    /* ---- depth-sorted assembly ---- */
    const parts = [
      { d: depthAt(rearA - 2*L, 1*L, rearH + bodyR), fn: tail },
      { d: depthAt(rearA, 0, rearH), fn: body },
      { d: depthAt(chestA + chestR*0.45, 0, chestH - chestR*0.3), fn: chestPatch },
      { d: depthAt(chestA + 1.5*L, 0, chestH + 2*L), fn: neck },
      { d: depthAt(chestA + 2*L, 0, chestH + 3*L), fn: collar },
      { d: depthAt(headA, 0, headH), fn: head },
      { d: depthAt(headA - headR*0.5, headR*0.85 + earH*0.3, headH + earH*0.6), fn: ear(1) },
      { d: depthAt(headA - headR*0.5, -(headR*0.85 + earH*0.3), headH + earH*0.6), fn: ear(-1) },
      { d: depthAt(headA + headR*0.42, headR*0.44, headH),
        fn: (blindSide !== 1) ? eye(1) : scarEye(1) },
      { d: depthAt(headA + headR*0.42, -headR*0.44, headH),
        fn: (blindSide !== -1) ? eye(-1) : scarEye(-1) },
      { d: depthAt(headA + headR*0.8, 0, headH - headR*0.3), fn: muzzle }
    ];
    /* legs: front pair always; rear pair standing, haunches sitting.
       Trot: diagonal pairs swing together (FL+RR vs FR+RL), feet
       reaching fore/aft by walkPhase; walkAmt eases the stride in
       and out so he settles to a stand instead of freezing mid-step */
    const sw = ph => Math.sin(walkPhase + ph) * 1.5 * L * walkAmt;
    parts.push({ d: depthAt(chestA + 0.5*L,  2.9*L, legH*0.4), fn: leg(chestA + 0.5*L, 1, 0.4*L + sw(0)) });
    parts.push({ d: depthAt(chestA + 0.5*L, -2.9*L, legH*0.4), fn: leg(chestA + 0.5*L, -1, 0.4*L + sw(Math.PI)) });
    if(sit){
      parts.push({ d: depthAt(rearA + 0.5*L,  bodyR*0.72, bodyR), fn: haunch(1) });
      parts.push({ d: depthAt(rearA + 0.5*L, -bodyR*0.72, bodyR), fn: haunch(-1) });
    } else {
      parts.push({ d: depthAt(rearA + 1*L,  2.9*L, legH*0.4), fn: leg(rearA + 1*L, 1, -0.4*L + sw(Math.PI)) });
      parts.push({ d: depthAt(rearA + 1*L, -2.9*L, legH*0.4), fn: leg(rearA + 1*L, -1, -0.4*L + sw(0)) });
    }
    parts.sort((x, y) => x.d - y.d);
    for(const pt of parts) pt.fn();

    /* startle marks: three short strokes radiating above the head,
       fading through the first 40% of the reaction */
    if(flee && flee.u < 0.4){
      const hp = G(headA, jb, headH + headR + earH*0.6 + 2);
      const alpha = 1 - flee.u/0.4;
      g.lineStyle(1.5, 0xffb04d, alpha);
      for(const aoff of [-0.7, 0, 0.7]){
        const r1 = px(headR*0.5), r2 = px(headR*1.05);
        g.lineBetween(hp.x + Math.sin(aoff)*r1, hp.y - Math.cos(aoff)*r1,
                      hp.x + Math.sin(aoff)*r2, hp.y - Math.cos(aoff)*r2);
      }
    }
    } else if(kind === "signalpost" || kind === "signalhead"){
      /* Box faces are picked by WORLD normal, never by fdir, which is what
         keeps these identical at f0..f3: under this fixed iso only a face
         whose outward normal has a positive x or y component is turned
         toward the camera, and that test does not care how the prop is
         rotated. dv/rv already carry the world directions.

         Two side colours rather than one, chosen by which world axis the
         face's normal leans along -- flat single-colour boxes are most of
         what made these read as parts rather than an object. */
      const S = data || SIGNAL;
      /* the dark green every DOT signal pole and mast arm in the world is
         painted, not the neutral grey these shipped with */
      const C_SIDE_X = 0x33523d, C_SIDE_Y = 0x27412f, C_TOP = 0x3e6149;
      const C_DARK_X = 0x24382b, C_DARK_Y = 0x1c2d22, C_DARK_T = 0x2c4634;
      const C_HOUSE_X = 0x22392a, C_HOUSE_Y = 0x192a1f, C_HOOD = 0x122019;
      /* an unlit lens at 0x14201a sat within a few points of the housing it
         is set into, so a dark head read as one blank slab with a single
         floating dot on it. Near-black separates the lenses from the case. */
      const C_OFF = 0x0b120e, C_RED = 0xd8392b, C_AMB = 0xe8a021, C_GRN = 0x3fbf62;
      const box = (a0, a1, b0, b1, z0, z1, cx, cy, cTop) => {
        const P = (a, b, z) => W(a, b, z);
        const faces = [
          [ dv,                   [P(a1,b0,z1), P(a1,b1,z1), P(a1,b1,z0), P(a1,b0,z0)]],
          [ { x:-dv.x, y:-dv.y }, [P(a0,b0,z1), P(a0,b1,z1), P(a0,b1,z0), P(a0,b0,z0)]],
          [ rv,                   [P(a0,b1,z1), P(a1,b1,z1), P(a1,b1,z0), P(a0,b1,z0)]],
          [ { x:-rv.x, y:-rv.y }, [P(a0,b0,z1), P(a1,b0,z1), P(a1,b0,z0), P(a0,b0,z0)]]
        ];
        for(const [n, pts] of faces)
          if(n.x > 0 || n.y > 0) this.quadOn(g, pts, Math.abs(n.x) > Math.abs(n.y) ? cx : cy);
        this.quadOn(g, [P(a0,b0,z1), P(a1,b0,z1), P(a1,b1,z1), P(a0,b1,z1)], cTop);
      };
      const armZ = SIGNAL.poleH - 18;
      /* The housing top sits ABOVE the arm's centreline, not below its
         underside. It hung off a thin neck before, which read as two parts
         near each other rather than one fitting: the arm ended, a gap, then
         a box. Now the arm's lower half runs INTO the housing and only its
         top shows above -- and because the head is drawn after the post in
         the same queue entry, the housing reliably paints over the arm it
         swallows, at every heading. */
      const headTopZ = armZ + 2;             // arm spans armZ-7 .. armZ+7
      if(kind === "signalpost"){
        /* base collar, shaft, arm collar, arm, cap. The collars are the
           polish: an arm butting straight into a bare shaft, and a shaft
           meeting the pavement with no foot, is what read as disjointed. */
        /* slimmer than the first pass: a 22-wide shaft carrying an 18-deep
           arm was heavier than the cones and palms beside it. */
        box(-14, 14, -14, 14, 0, 18, C_DARK_X, C_DARK_Y, C_DARK_T);
        box(-10, 10, -10, 10, 0, SIGNAL.poleH, C_SIDE_X, C_SIDE_Y, C_TOP);
        if(SIGNAL.arm){
          box(-13, 13, -13, 13, armZ-13, armZ+13, C_DARK_X, C_DARK_Y, C_DARK_T);
          /* the arm rides with the post, pointing along fdir = armF */
          box(0, SIGNAL.armLen, -6, 6, armZ-7, armZ+7, C_SIDE_X, C_SIDE_Y, C_TOP);
        }
        box(-12, 12, -12, 12, SIGNAL.poleH, SIGNAL.poleH+7, C_DARK_X, C_DARK_Y, C_TOP);
      } else {
        const R = SIGNAL.headR, gap = R*2.3;
        const botZ = headTopZ - gap*3.05;
        box(-R*1.4, R*1.4, -R*1.4, R*1.4, botZ, headTopZ, C_HOUSE_X, C_HOUSE_Y, C_HOOD);
        /* FACING. headF aims at the cars this signal stops, which is right
           and is not the whole story: the camera never rotates, so exactly
           two of the four heads at an intersection show it their BACK.
           Drawing the lamps regardless painted them through the rear of the
           housing -- reported on device as lights facing the wrong way.
           Lamps are drawn only on a camera-visible face; SIGNAL.readable
           decides whether the head is turned to guarantee that (legible
           everywhere, and nothing on screen can reveal the head is not aimed
           at its own queue, because the camera cannot orbit) or left on true
           aim (two blank housings per intersection, which is what a real
           one looks like from a single fixed viewpoint). */
        if(dv.x > 0 || dv.y > 0){
          const st = signalAxisState(S.node, t, S.axis);
          const lamps = [["red", C_RED], ["amber", C_AMB], ["green", C_GRN]];
          const face = R*1.42;
          for(let i = 0; i < 3; i++){
            const z = headTopZ - gap*(0.75 + i);
            const lit = st === lamps[i][0];
            /* visor over each lens, then a recessed ring, then the lens --
               three flat circles on a flat face is what made the head look
               like a sticker rather than a fitting */
            const p = W(face, 0, z);
            g.fillStyle(C_HOOD, 1);   g.fillCircle(p.x, p.y, R*1.16*this.K);
            g.fillStyle(lit ? lamps[i][1] : C_OFF, 1); g.fillCircle(p.x, p.y, R*this.K);
            if(lit){ g.fillStyle(0xffffff, 0.22); g.fillCircle(p.x, p.y, R*0.5*this.K); }
            /* No visors. At headR 8 a hood is a couple of units of
               protrusion on a lens a few pixels across -- it only ever
               added clutter around the lamp it was meant to frame. The
               recess ring below already does the job of setting the lens
               into the case. */
          }
        }
      }
    } else if(kind === "people"){
      /* ported from the customer lab (dial bench approved), now drawn
         via the shared drawPersonHull() so prop.people and
         world.customer stay visually identical. Patrols the spawn
         tile via peopleSpotAt() — same construction as the dog — until
         hit; flee/settle use the dog's exact DUR/DIST curve. */
      const pseed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x9c3a) >>> 0;
      const pSeed = (data && data.peopleSeed !== undefined) ? data.peopleSeed : pseed;
      const prng = mulberry32(pSeed);
      const build = PEOPLE_BUILD[prng() < 0.5 ? 0 : 1];
      const pSkin = PEOPLE_SKIN[Math.floor(prng()*PEOPLE_SKIN.length)];
      const pShirt = PEOPLE_SHIRT[Math.floor(prng()*PEOPLE_SHIRT.length)];
      const pPants = PEOPLE_PANTS[Math.floor(prng()*PEOPLE_PANTS.length)];
      const pHair = PEOPLE_HAIR[Math.floor(prng()*PEOPLE_HAIR.length)];
      const pShoe = PEOPLE_SHOE[Math.floor(prng()*PEOPLE_SHOE.length)];

      const spot = peopleSpotAt(t, data || {peopleSeed: pSeed});
      const flee = peopleFleeAt(t, data);
      const settled = flee && flee.gone;
      const settledSpot = settled ? peopleSettledSpot(data) : null;
      let spotA = spot.a, spotB = spot.b, spotTh = spot.th, walkAmt = spot.walk;
      if(settled){ spotA = settledSpot.a; spotB = settledSpot.b; spotTh = settledSpot.th; walkAmt = 0; }
      else if(flee){ spotA += flee.da; spotB += flee.db; spotTh = Math.atan2(-0.45, (data.fleeA || 1)); walkAmt = 1; }

      const thW = fdir*Math.PI/2 + spotTh;
      const ax = x + dv.x*spotA + rv.x*spotB, ay = y + dv.y*spotA + rv.y*spotB;
      const moving = walkAmt > 0.05;
      const walkPhase = moving ? Math.sin(t*PEOPLE_ART.walkSpeed) : 0;
      const startleAlpha = (flee && flee.u < 0.4) ? 1 - flee.u/0.4 : 0;

      this.drawPersonHull(g, ax, ay, z, thW, build, pSkin, pShirt, pPants, pHair, pShoe, walkPhase, moving, startleAlpha);
    } else if(kind === "william"){
      /* the wrap-lap robot-hater — labs/william-lab.html v6 (approved).
         Pose derives from the SAME hz fields the sim writes (cone
         pattern) + this t, so art always matches the state machine. */
      const kz = data || {};
      const kseed = (kz.williamSeed !== undefined) ? kz.williamSeed : 7;
      const kfit = WILLIAM_FITS[kseed % WILLIAM_FITS.length];
      const kst = kz.kst || "patrol";
      const kel = t - (kz.kt0 || 0);
      let ka = kz.ka || 0, kb = kz.kb || 0, klth = kz.kth || 0, kWalkAmt = 0;
      if(kst === "patrol"){
        const ksp = peopleSpotAt(t, kz);
        ka = ksp.a; kb = ksp.b || 0; kWalkAmt = ksp.walk || 0;
        if(kz.walkS0 !== undefined) klth = ksp.th;
        else if(kWalkAmt > 0.05){
          /* idle wander: derive facing from motion with the verified
             (-sin,cos)-forward convention (two-sample tangent) */
          const ksp2 = peopleSpotAt(t + 90, kz);
          klth = Math.atan2(-(ksp2.a - ksp.a), (ksp2.b - (ksp.b || 0)) || 0.0001);
        }
      } else if(kst === "intercept" || kst === "return"){ kWalkAmt = 1; }
      let kickAng = 0, kArmLift = 0, kArmAngle = LIFT_MAX_ANGLE;
      if(kst === "block"){ kArmLift = WILLIAM_ACT.armBlock + Math.sin(t*0.004)*0.03; }
      else if(kst === "windup"){
        const ku = Math.min(1, kel/WILLIAM_ACT.windup), ke = ku*ku*(3-2*ku);
        kickAng = WILLIAM_ACT.cock * ke; kArmLift = WILLIAM_ACT.armEngage * ke;
      } else if(kst === "kick"){
        const ku = Math.min(1, kel/WILLIAM_ACT.swing);
        const ke = ku < 0.5 ? 2*ku*ku : 1 - Math.pow(-2*ku+2, 2)/2;
        kickAng = WILLIAM_ACT.cock + (WILLIAM_ACT.extend - WILLIAM_ACT.cock)*ke;
        kArmLift = WILLIAM_ACT.armEngage;
      } else if(kst === "gloat"){
        kArmLift = WILLIAM_ACT.armGloat * Math.min(1, kel/280);
        kArmAngle = WILLIAM_ACT.gloatAngle;
      } else if(kst === "whiff"){
        kickAng = WILLIAM_ACT.extend * Math.max(0, 1 - kel/300);
      }
      const thWk = fdir*Math.PI/2 + klth;
      const kax = x + dv.x*ka + rv.x*kb, kay = y + dv.y*ka + rv.y*kb;
      const kMoving = kWalkAmt > 0.05;
      const kWalkPhase = kMoving ? Math.sin(t*PEOPLE_ART.walkSpeed) : 0;
      this.drawWilliamHull(g, kax, kay, z, thWk, kWalkPhase, kMoving, kickAng, kArmLift, kArmAngle, kfit, kseed);
      if(kst === "intercept" || kst === "block" || kst === "windup"){
        /* the tell — "!" over the hat */
        const khp = this.W(kax, kay, z + WILLIAM_BUILD.legH + WILLIAM_BUILD.torsoH + WILLIAM_BUILD.headR*2 + 14);
        g.fillStyle(0xc2452e, 1);
        g.fillRect(khp.x - 1.6, khp.y - 10, 3.2, 7);
        g.fillCircle(khp.x, khp.y - 0.5, 1.8);
      }
    } else if(kind === "car" || kind === "truck" || kind === "policecar"){
      /* rebuilt (2026-07-12) on the SAME rigid-rotation pattern the
         robot's own body already uses (T()/P()/depth()): the car's
         entire shape -- chassis, cabin, wheels, everything -- is
         defined ONCE in a fixed local frame (a=length, b=width,
         h=height, car always "facing +a" in this local space), then
         the WHOLE THING rotates together as one rigid unit into world
         space via carT/carP, exactly like the robot rotates as one
         piece via T()/P(). This is a structural fix, not a patch: the
         previous version independently hand-tuned each panel's (a,b,h)
         and just swapped which world axis stood in for "front" per
         fdir, so the body's own coverage and the wheels' own position
         could drift apart depending on facing (the wheel-on-the-hood
         bug). With one rigid rotation, body and wheels can never
         drift apart -- whatever relationship holds in local space
         holds in every orientation. Where a specific panel needs to
         know which side is camera-facing (side glass), it uses
         carDepth to pick dynamically -- the same technique the
         robot's own drawWheel already uses to pick its visible face. */
      const CR = CARC, isTruck = kind === "truck", isPolice = kind === "policecar";
      const seed = colorSeed !== null
        ? (colorSeed ^ 0x9c31) >>> 0
        : ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x9c31) >>> 0;
      const rng = mulberry32(seed);
      /* the rng draw happens either way, so a cruiser and a civilian car
         at the same spot consume the same stream — the colour is simply
         overridden afterwards rather than the draw being skipped. */
      const rolled = CAR_COLORS[Math.floor(rng()*CAR_COLORS.length)];
      const col = isPolice ? POLICE_LIVERY : rolled;
      const hl = CR.len/2, hw = CR.wid/2, cz = CR.wheelR;
      const chassisTop = cz + CR.chassisH, cabinTop = chassisTop + CR.cabinH;
      const cl = isTruck ? hl*0.24 : hl*0.62;

      /* rigid rotation: local (a,b,h) -> world -> screen, and a matching
         depth() for camera-relative comparisons -- same pair the robot
         uses (T/P and depth), just yaw-only (fdir snapped to 90 deg
         steps today; ready for free rotation later without touching
         any panel below, since they never reference fdir directly). */
      const carTheta = fdir * (Math.PI/2);
      const cTh = Math.cos(carTheta), sTh = Math.sin(carTheta);
      const carT = (a, b, h) => ({ x: a*cTh - b*sTh, y: a*sTh + b*cTh, z: h });
      const carP = (a, b, h) => { const q = carT(a, b, h); return this.W(x + q.x, y + q.y, z + q.z); };
      const carDepth = (a, b, h) => { const q = carT(a, b, h); return q.x + q.y + q.z*0.4; };

      const csh = carP(0, 0, 0);
      g.fillStyle(CR.shadow, 0.16);
      g.fillEllipse(csh.x, csh.y + 3, (CR.len+8)*this.K*0.42, (CR.wid+10)*this.K*0.36);

      const wheel = (a0, r, side) => () => {
        const WW = 3.6*(CR.wheelR/16);
        const ringAt = (bc, rad, n=12) => {
          const pts = [];
          for(let i=0; i<n; i++){
            const phi = (i/n)*Math.PI*2;
            pts.push(carP(a0 + Math.cos(phi)*rad, bc, cz + Math.sin(phi)*rad));
          }
          return pts;
        };
        const bIn = side*(hw - 1), bOut = side*(hw + WW - 1);
        this.quadOn(g, convexHull(ringAt(bIn, r).concat(ringAt(bOut, r))), CR.wheelDk);
        /* which of the two rings is actually camera-facing -- same
           depth-comparison technique the robot's own drawWheel uses,
           instead of assuming bOut is always the visible one. */
        const faceB = carDepth(a0, bOut, cz) > carDepth(a0, bIn, cz) ? bOut : bIn;
        const faceRing = rr => ringAt(faceB, rr);
        this.quadOn(g, faceRing(r), CR.wheel);
        this.quadOn(g, faceRing(r*0.5), CR.hubFace);
        if(wheelPhase !== null){
          const wp2 = wheelPhase + a0*0.02;
          const hub = carP(a0 + Math.cos(wp2)*r*0.34, faceB, cz + Math.sin(wp2)*r*0.34);
          g.fillStyle(CR.hub, 1);
          g.fillCircle(hub.x, hub.y, r*0.2*this.K*0.42);
        } else {
          const hub = carP(a0, faceB, cz);
          g.fillStyle(CR.hub, 1);
          g.fillCircle(hub.x, hub.y, r*0.34*this.K*0.42);
        }
      };

      const chassis = () => {
        const top = [carP(-hl,-hw,chassisTop), carP(hl,-hw,chassisTop), carP(hl,hw,chassisTop), carP(-hl,hw,chassisTop)];
        const bot = [carP(-hl,-hw,cz), carP(hl,-hw,cz), carP(hl,hw,cz), carP(-hl,hw,cz)];
        this.quadOn(g, convexHull(top.concat(bot)), col.bodyDk);
        this.quadOn(g, top, col.body);
      };
      const bumperFront = () => {
        const q = [carP(hl-0.3,-hw,cz), carP(hl,-hw,cz+3), carP(hl,hw,cz+3), carP(hl-0.3,hw,cz)];
        this.quadOn(g, q, CR.bumper);
        g.fillStyle(CR.light, 1);
        for(const side of [-1, 1]){
          const hlp = carP(hl-0.4, side*(hw-3), cz+5);
          g.fillCircle(hlp.x, hlp.y, 2*this.K*0.42);
        }
      };
      const bumperRear = () => {
        const q = [carP(-hl+0.3,-hw,cz), carP(-hl,-hw,cz+3), carP(-hl,hw,cz+3), carP(-hl+0.3,hw,cz)];
        this.quadOn(g, q, CR.bumper);
        g.fillStyle(CR.tail, 1);
        for(const side of [-1, 1]){
          const tlp = carP(-hl+0.4, side*(hw-3), cz+5);
          g.fillCircle(tlp.x, tlp.y, 1.8*this.K*0.42);
        }
      };

      const bed = () => {
        if(!isTruck) return;
        const bedBackA = -hl+1, bedFrontA = -cl-2;
        const railTop = chassisTop + CR.chassisH*0.55;
        const floorH = chassisTop + 1;
        const wallFar = [carP(bedBackA,-hw,floorH), carP(bedFrontA,-hw,floorH), carP(bedFrontA,-hw,railTop), carP(bedBackA,-hw,railTop)];
        const floor = [carP(bedBackA,-hw*0.88,floorH), carP(bedFrontA,-hw*0.88,floorH), carP(bedFrontA,hw*0.88,floorH), carP(bedBackA,hw*0.88,floorH)];
        const cabBackWall = [carP(bedFrontA,-hw*0.88,floorH), carP(bedFrontA,hw*0.88,floorH), carP(bedFrontA,hw*0.88,railTop), carP(bedFrontA,-hw*0.88,railTop)];
        const wallNear = [carP(bedBackA,hw,floorH), carP(bedFrontA,hw,floorH), carP(bedFrontA,hw,railTop), carP(bedBackA,hw,railTop)];
        this.quadOn(g, wallFar, col.bodyDk);
        this.quadOn(g, floor, CR.bedFloor);
        this.quadOn(g, cabBackWall, col.bodyDk);
        this.quadOn(g, wallNear, col.body);
      };

      const cabin = () => {
        const roofF = isTruck ? -cl : -cl*0.55, roofR = cl*0.55;
        const roofPts = [carP(roofF,-hw*0.86,cabinTop), carP(roofR,-hw*0.86,cabinTop), carP(roofR,hw*0.86,cabinTop), carP(roofF,hw*0.86,cabinTop)];
        const beltPts = [carP(cl,-hw*0.92,chassisTop), carP(cl,hw*0.92,chassisTop), carP(-cl,hw*0.92,chassisTop), carP(-cl,-hw*0.92,chassisTop)];
        /* ONE hull over every cabin corner -- same technique chassis's
           own hullBody already uses. Guarantees full, gap-free coverage
           of anything behind it (like a wheel) in every orientation,
           instead of separately-tuned windshield/backlight/side-glass
           panels that only happened to line up for one assumed facing. */
        this.quadOn(g, convexHull(roofPts.concat(beltPts)), col.roof);
        this.quadOn(g, roofPts, col.roof);
        this.edgeOn(g, roofPts, col.bodyDk, 1);

        /* windshield: local front is always +cl regardless of fdir,
           since rotation happens after this is defined -- no per-
           orientation logic needed here. */
        const windFront = [carP(roofR,-hw*0.85,cabinTop), carP(roofR,hw*0.85,cabinTop), carP(cl,hw*0.9,chassisTop), carP(cl,-hw*0.9,chassisTop)];
        this.quadOn(g, windFront, CR.windshield);
        this.edgeOn(g, windFront, CR.windshieldEdge, 1);

        if(isTruck){
          const winW = hw*0.5;
          const winH0 = chassisTop + (cabinTop-chassisTop)*0.35;
          const winH1 = chassisTop + (cabinTop-chassisTop)*0.85;
          const back = [carP(roofF,-winW,winH1), carP(roofF,winW,winH1), carP(roofF,winW,winH0), carP(roofF,-winW,winH0)];
          this.quadOn(g, back, CR.windshield);
          this.edgeOn(g, back, CR.windshieldEdge, 1);
        } else {
          const back = [carP(roofF,-hw*0.86,cabinTop), carP(roofF,hw*0.86,cabinTop), carP(-cl,hw*0.92,chassisTop), carP(-cl,-hw*0.92,chassisTop)];
          this.quadOn(g, back, CR.windshield);
          this.edgeOn(g, back, CR.windshieldEdge, 1);
        }

        /* roof redraw: this car's greenhouse used to be front/back
           asymmetric, and iso projection isn't rotationally uniform, so
           the windshield/backlight panels above could end up overlapping
           part of the roof's own screen footprint at some headings even
           though they never did at others. Repainting the roof top face
           here guarantees it always wins that overlap regardless of fdir. */
        this.quadOn(g, roofPts, col.roof);
        this.edgeOn(g, roofPts, col.bodyDk, 1);

        /* side glass: which physical side (+b or -b) is camera-facing
           is picked dynamically via carDepth -- same technique the
           robot's own drawWheel uses for its visible face, rather than
           the old hardcoded "always +b" assumption. */
        const sgSide = carDepth(0, hw*0.9, cabinTop) > carDepth(0, -hw*0.9, cabinTop) ? 1 : -1;
        const sgB = sgSide*hw*0.86, beltB = sgSide*hw*0.92;
        const sgPts = [
          { a: roofF, b: sgB,   h: cabinTop },
          { a: roofR, b: sgB,   h: cabinTop },
          { a: cl,    b: beltB, h: chassisTop },
          { a: -cl,   b: beltB, h: chassisTop }
        ];
        const cA = sgPts.reduce((s,p) => s+p.a, 0)/4;
        const cB = sgPts.reduce((s,p) => s+p.b, 0)/4;
        const cH = sgPts.reduce((s,p) => s+p.h, 0)/4;
        const shrink = 0.7;
        const sideFrame = sgPts.map(p => carP(p.a, p.b, p.h));
        const sidePane = sgPts.map(p => carP(cA+(p.a-cA)*shrink, cB+(p.b-cB)*shrink, cH+(p.h-cH)*shrink));
        this.quadOn(g, sideFrame, col.body);
        this.quadOn(g, sidePane, CR.windshield);
      };

      const mirror = side => () => {
        const roofR = cl*0.55;
        const mb = carP(roofR - 3, hw*0.9*side, chassisTop + 3);
        g.fillStyle(col.bodyDk, 1);
        g.fillCircle(mb.x, mb.y, 1.6*this.K*0.42);
      };

      /* the far-side wheels are reliably hidden by chassis's own hull
         (verified), so they always draw early. Near-side wheels and both
         bumpers get placed by comparing depth against the cabin's own,
         same as before -- but WHICH physical side (+b or -b) counts as
         "near" for each wheel is now picked dynamically via carDepth,
         same technique faceB/sgSide already use, instead of hardcoding
         side=+1. The hardcoded version only happened to be correct at
         two of the four fdir headings (0 and 3); at 1 and 2 it picked
         the wrong side entirely, so neither near wheel poked through. */
      const cabinRefDepth = carDepth(0, 0, (chassisTop+cabinTop)/2);
      const rearNearSide = carDepth(-hl*0.55, hw, cz) > carDepth(-hl*0.55, -hw, cz) ? 1 : -1;
      const frontNearSide = carDepth(hl*0.55, hw, cz) > carDepth(hl*0.55, -hw, cz) ? 1 : -1;
      const nearRearWheelDepth = carDepth(-hl*0.55, hw*rearNearSide, cz);
      const nearFrontWheelDepth = carDepth(hl*0.55, hw*frontNearSide, cz);
      const bumperFrontDepth = carDepth(hl-0.15, 0, cz+1.5);
      const bumperRearDepth = carDepth(-hl+0.15, 0, cz+1.5);

      wheel(-hl*0.55, CR.wheelR, -rearNearSide)();
      wheel(hl*0.55, CR.wheelR*0.95, -frontNearSide)();
      chassis();
      bed();
      if(nearRearWheelDepth <= cabinRefDepth) wheel(-hl*0.55, CR.wheelR, rearNearSide)();
      if(nearFrontWheelDepth <= cabinRefDepth) wheel(hl*0.55, CR.wheelR*0.95, frontNearSide)();
      mirror(-1)();
      cabin();
      /* bumpers: chassis() above already unconditionally paints the far
         tip's silhouette, and cabin() never reaches out to a=+-hl to
         occlude anything there -- so drawing both bumperFront/bumperRear
         every frame (the old early/late-vs-cabin split) meant whichever
         one drew second always painted over chassis and stayed visible,
         regardless of facing. Only the one actually facing the camera
         should be drawn at all; the far one is already represented by
         chassis's own solid end. */
      if(bumperFrontDepth > bumperRearDepth) bumperFront(); else bumperRear();
      if(nearRearWheelDepth > cabinRefDepth) wheel(-hl*0.55, CR.wheelR, rearNearSide)();
      if(nearFrontWheelDepth > cabinRefDepth) wheel(hl*0.55, CR.wheelR*0.95, frontNearSide)();
      mirror(1)();

      /* ---- POLICE HARDWARE ----
         Drawn last, in the car's OWN local frame via carP/carDepth, so it
         rotates with the body as one piece and cannot drift from it. It
         sits entirely above the tyre tops and below the glass line, so
         nothing already painted can legitimately occlude it. */
      if(isPolice){
        const ts = t/1000 + ((data && data.strobe) || 0);
        const ph = (ts*POLC.flashHz) % 2;
        const redOn  = ph < 0.82;
        const blueOn = ph >= 1.0 && ph < 1.82;

        const bB = hw*POLC.barBF;
        const h0 = cabinTop, h1 = cabinTop + POLC.barH;
        const aF = POLC.barA, aR = -POLC.barA;

        const barCorners = [];
        for(const a of [aR, aF]) for(const b of [-bB, bB]) for(const h of [h0, h1])
          barCorners.push(carP(a, b, h));
        this.quadOn(g, convexHull(barCorners), POLC.housing);

        const lensTop = (b0, b1, c) => this.quadOn(g,
          [carP(aR,b0,h1), carP(aF,b0,h1), carP(aF,b1,h1), carP(aR,b1,h1)], c);

        /* housing -> camera-facing side -> top LAST. The top of a bar can
           never be occluded by that same bar's own side at any heading, so
           this order is correct by construction rather than by luck at
           three headings of four. */
        const sideB = carDepth(0, bB, (h0+h1)/2) > carDepth(0, -bB, (h0+h1)/2) ? bB : -bB;
        const sideLit = sideB > 0 ? blueOn : redOn;
        const sideCol = sideB > 0 ? (blueOn ? POLC.blueHot : POLC.blue)
                                  : (redOn  ? POLC.redHot  : POLC.red);
        const sideQuad = [carP(aR,sideB,h0), carP(aF,sideB,h0), carP(aF,sideB,h1), carP(aR,sideB,h1)];
        this.quadOn(g, sideQuad, sideCol);
        this.edgeOn(g, sideQuad, POLC.housingDk, 1);

        lensTop(-bB, 0, redOn  ? POLC.redHot  : POLC.lensDim);
        lensTop(0,  bB, blueOn ? POLC.blueHot : POLC.lensDim);

        if(sideLit){
          const gl = carP(0, sideB, (h0+h1)/2);
          g.fillStyle(sideB > 0 ? POLC.blueHot : POLC.redHot, 0.26);
          g.fillCircle(gl.x, gl.y, POLC.barH*this.K*0.9);
        }

        /* door decal: sized off the REAL wheel geometry, not the cabin.
           The wheels sit at a=+-hl*0.55 and reach z = wheelR*0.72 + wheelR,
           so a decal spanning the cabin's own length started below the tyre
           tops and painted straight over both wheels. This one sits BETWEEN
           the arches and ABOVE the tyres, in the door band under the glass. */
        const wheelTop = CR.wheelR*0.72 + CR.wheelR;
        const dB  = carDepth(0, hw, chassisTop) > carDepth(0, -hw, chassisTop) ? hw : -hw;
        const dB1 = dB * 1.015;                 // a hair proud of the skin
        const dh0 = wheelTop + 5;               // clear of the tyre
        const dh1 = chassisTop - 5;             // under the glass line
        const da  = 26;                         // inside both wheel arches
        this.quadOn(g, [carP(-da,dB1,dh0), carP(da,dB1,dh0),
                        carP(da,dB1,dh1), carP(-da,dB1,dh1)], POLC.decal);
      }
    } else if(kind === "bin"){
      /* approved in bin hit lab (2026-07-09): ONE rigid geometry
         driven by a continuous tip angle phi about the base rim —
         single phase, since a barrel's own round bottom is the whole
         base (phiRest is exactly 90°, no slab-corner handoff like
         the cone needed). fallPsi is set once, at the hit that starts
         the fall, and plays the same role the old per-tile rotation
         did. The lid rides shut until phi crosses the balance angle,
         then springs open — same trigger that flings the trash. */
      const B = BIN, K = this.K;
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x8177) >>> 0;
      const rng = mulberry32(seed);
      /* a BOX squared to the curb — seeded quarter (faces street, walk,
         or either along-axis, all believable placements) + a few degrees
         of slop, replacing the free 2π roll that left bins cocked at
         arbitrary angles to the street. fallPsi knocks stay free: falls
         are chaos, PARKED is order. */
      const cthSeed = Math.floor(rng()*4) * (Math.PI/2) + (rng() - 0.5) * 0.16;
      const H = B.height;
      const phi = (data && data.phi) || 0;
      const cth = (data && data.fallPsi !== undefined) ? data.fallPsi : cthSeed;
      const fc = Math.cos(cth), fsn = Math.sin(cth);
      const cphi = Math.cos(phi), sphi = Math.sin(phi);
      const slide = (data && data.slide) || 0;

      const tip = (u, h) => {
        if(phi === 0) return { u, z: h };
        return { u: binR(0) + (u - binR(0))*cphi + h*sphi, z: -(u - binR(0))*sphi + h*cphi };
      };
      const L = (u, v, h) => {
        const tt = tip(u, h);
        return W((tt.u + slide)*fc - v*fsn, (tt.u + slide)*fsn + v*fc, tt.z);
      };
      const dAt = (u, v, h) => {
        const tt = tip(u, h);
        const a2 = (tt.u + slide)*fc - v*fsn, b2 = (tt.u + slide)*fsn + v*fc;
        return a2 + b2 + tt.z*0.4;
      };
      const place = (h, r, n=14) => {
        const pts = [];
        for(let i=0; i<n; i++){
          const psi = (i/n)*Math.PI*2;
          pts.push(L(Math.cos(psi)*r, Math.sin(psi)*r, h));
        }
        return pts;
      };

      const mid = tip(0, H*0.5);
      const kk = Math.min(1, sphi*1.1);
      const sh = W((mid.u*kk + slide)*fc, (mid.u*kk + slide)*fsn, 0);
      g.fillStyle(B.shadow, 0.14);
      g.fillEllipse(sh.x, sh.y + 2,
        (B.lidR*2.1 + (H + 20 - B.lidR*2.1)*kk) * K * 0.42,
        (B.lidR*0.95 + (22 - B.lidR*0.95)*kk) * K * 0.42);

      const bbody = () => {
        const n = 6, all = [];
        for(let i=0; i<=n; i++) all.push(...place(i/n*H, binR(i/n*H)));
        this.quadOn(g, convexHull(all), B.body);
        const ribN = 6, ribs = [];
        for(let i=0; i<=ribN; i++) ribs.push(place(i/ribN*H, binR(i/ribN*H)));
        for(let i=0; i<ribN; i++){
          this.quadOn(g, convexHull(ribs[i].concat(ribs[i+1])), i % 2 === 0 ? B.body : B.bodyDk);
        }
        const lowerN = 3, lower = [];
        for(let i=0; i<=lowerN; i++) lower.push(...place(i/lowerN*(H*0.5), binR(i/lowerN*(H*0.5))));
        this.quadOn(g, convexHull(lower), B.bodyDk, 0.2);
        const b0 = H*0.6, b1 = Math.min(b0 + B.band, H*0.92);
        if(B.band > 0){
          this.quadOn(g, convexHull(place(b0, binR(b0)+0.3).concat(place(b1, binR(b1)+0.3))), B.band_c);
          this.quadOn(g, place(b1, binR(b1)*0.7, 12), B.liner);
        }
        /* liner lip: camera-facing test, same pattern used everywhere
           else in this projection (rotated local normal dotted with
           the view direction) */
        const nu = cphi, nh = -sphi;
        const mouthFacing = (nu*fc + nu*fsn + nh) > 0.05;
        if(mouthFacing) this.quadOn(g, place(H - 0.5, binR(H)*0.86, 12), B.liner);
      };
      const lidOpen = phi >= BIN_HIT.phiBal;
      const blid = () => {
        if(!lidOpen){
          const rim = place(H, B.lidR, 14);
          this.quadOn(g, rim, B.lidDk);
          const dome = [];
          for(let i=0; i<12; i++){
            const psi = (i/12)*Math.PI*2, r2 = B.lidR*0.82;
            dome.push(L(Math.cos(psi)*r2, Math.sin(psi)*r2, H + 2.6));
          }
          this.quadOn(g, dome, B.lid);
          const knob = L(0, 0, H + 4.4);
          g.fillStyle(B.lidDk, 1);
          g.fillCircle(knob.x, knob.y, 2.6*K*0.45);
          const hinge = L(-B.lidR*0.85, 0, H + 0.6);
          g.fillStyle(B.pedalDk, 1);
          g.fillCircle(hinge.x, hinge.y, 1.6*K*0.45);
        } else {
          const La = H + B.lidR*0.75;
          const disc = [], inner = [];
          for(let i=0; i<12; i++){
            const psi = (i/12)*Math.PI*2;
            disc.push(L(La + Math.cos(psi)*B.lidR, Math.sin(psi)*B.lidR, 1));
            const r2 = B.lidR*0.8;
            inner.push(L(La + Math.cos(psi)*r2, Math.sin(psi)*r2, 1.7));
          }
          this.quadOn(g, disc, B.lidDk);
          this.quadOn(g, inner, B.lid);
          const knob = L(La, 0, 2.3);
          g.fillStyle(B.lidDk, 1);
          g.fillCircle(knob.x, knob.y, 2.2*K*0.45);
        }
      };
      const bpedal = () => {
        if(phi > 0.05) return;
        const a0 = L(B.baseR*0.55, 0, 1.5);
        const a1 = L(B.baseR*0.95, 0, 5.5);
        g.lineStyle(Math.max(1.5, 1.4*K*0.4), B.pedalDk, 1);
        g.lineBetween(a0.x, a0.y, a1.x, a1.y);
        const p0 = L(B.baseR*0.95, -3.2, 0.6), p1 = L(B.baseR*1.25, 3.2, 0.6);
        g.fillStyle(B.pedal, 1);
        g.fillEllipse((p0.x+p1.x)/2, (p0.y+p1.y)/2, 7*K*0.42, 3*K*0.42);
      };

      const bparts = [
        { d: dAt(0, 0, 1.5), fn: bbody },
        { d: dAt(B.baseR*0.9, 0, 3), fn: bpedal },
        { d: lidOpen ? dAt(H + B.lidR*0.75, 0, 1) : dAt(0, 0, H*0.95), fn: blid }
      ];
      bparts.sort((p1, p2) => p1.d - p2.d);
      for(const pt of bparts) pt.fn();

      /* flung debris: independent projectiles once launched, stored
         in the hazard's own local (u,v,h) frame — drawn with the
         PLAIN local W(), not tip()-rotated, since they've detached
         from the rigid body by the time they're airborne */
      if(data && data.items && data.items.length){
        for(const it of data.items){
          const s2 = W(it.x + 1, it.y + 1, 0.4);
          g.fillStyle(TRASH_ART.shadow, 0.15);
          g.fillEllipse(s2.x, s2.y, it.size*K*0.9, it.size*K*0.4);
        }
        for(const it of data.items){
          const p = W(it.x, it.y, it.z);
          if(it.kind === "paper"){
            g.fillStyle(TRASH_ART.paper, 1);
            g.fillRect(p.x - it.size*K*0.4, p.y - it.size*K*0.3, it.size*K*0.8, it.size*K*0.6);
            g.lineStyle(1, TRASH_ART.paperShade, 1);
            g.strokeRect(p.x - it.size*K*0.4, p.y - it.size*K*0.3, it.size*K*0.8, it.size*K*0.6);
          } else if(it.kind === "can"){
            g.fillStyle(TRASH_ART.canA, 1);
            g.fillEllipse(p.x, p.y, it.size*K*0.7, it.size*K*1.1);
            g.fillStyle(TRASH_ART.canHi, 1);
            g.fillEllipse(p.x - it.size*K*0.15, p.y, it.size*K*0.2, it.size*K*0.9);
            g.lineStyle(1, TRASH_ART.outline, 1);
            g.strokeEllipse(p.x, p.y, it.size*K*0.7, it.size*K*1.1);
          } else {
            const col = TRASH_ART.wrap[Math.floor(it.ang) % TRASH_ART.wrap.length];
            const c2 = Math.cos(it.ang), s3 = Math.sin(it.ang);
            g.fillStyle(col, 1);
            this.quadOn(g, [
              { x:p.x + c2*it.size*K*0.6, y:p.y + s3*it.size*K*0.35 },
              { x:p.x - s3*it.size*K*0.35, y:p.y + c2*it.size*K*0.35 },
              { x:p.x - c2*it.size*K*0.6, y:p.y - s3*it.size*K*0.35 },
              { x:p.x + s3*it.size*K*0.35, y:p.y - c2*it.size*K*0.35 }
            ], col);
          }
        }
      }
    } else if(kind === "slab" && data && data.hjRole){
      /* COURSE WEDGE, not a trip heave. The art below is the cross-slope
         slab (lifted along a SIDE edge to catch a wheel); the challenge
         needs the lab's travel-axis wedge you ride up and launch off.
         Completely different shape, so it gets its own renderer. */
      this.hjDrawWedge(data);
    } else if(kind === "slab"){
      /* approved in ramp lab v2: heaved slab — the ramp concept redesigned
         into ONE sidewalk tile (92×92), lifted along one side edge by a
         palm root, flush at the other. Draw order: soil gap under the
         raised edges → exposed joint walls → root bulge → top wedge +
         seeded cracks + chipped lip. lift/side/root ride on the hazard
         object (data); cracks/chips are position-seeded like every prop. */
      const D = data || { lift: 6, side: 1, root: true };
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x51ab) >>> 0;
      const rng = mulberry32(seed);
      const A = SLAB_ART, L = D.lift, sd = D.side;
      const yFlush = -sd*TILE, yUp = sd*TILE;
      const ZT = dy => L * ((sd*dy + TILE) / (2*TILE));

      /* soil shadow in the opened gap */
      this.quadOn(g, [
        W(-TILE, yUp - sd*10, 0), W(TILE, yUp - sd*10, 0),
        W(TILE + 4, yUp + sd*4, 0), W(-TILE - 4, yUp + sd*4, 0)
      ], A.gap, 0.55);

      /* exposed joint walls: triangles at both travel joints, full
         lifted wall along the raised side edge */
      for(const jx of [-TILE, TILE]){
        this.quadOn(g, [W(jx, yFlush, 0), W(jx, yUp, ZT(yUp)), W(jx, yUp, 0)], A.topDk, 0.9);
      }
      this.quadOn(g, [
        W(-TILE, yUp, ZT(yUp)), W(TILE, yUp, ZT(yUp)),
        W(TILE, yUp, 0), W(-TILE, yUp, 0)
      ], A.topDk);
      this.edgeOn(g, [
        W(-TILE, yUp, ZT(yUp)), W(TILE, yUp, ZT(yUp)),
        W(TILE, yUp, 0), W(-TILE, yUp, 0)
      ], A.gap, 1.2);

      /* the culprit: palm root shouldering the raised edge up */
      if(D.root){
        const segsN = 6;
        for(let i=0; i<segsN; i++){
          const t0 = i/segsN, t1 = (i+1)/segsN;
          const x0 = -TILE + 2*TILE*t0, x1 = -TILE + 2*TILE*t1;
          const bump = 2.2 + Math.sin(t0*Math.PI)*2.2 + (rng()-0.5)*1.2;
          const pts = [
            W(x0, yUp + sd*2, 0), W(x1, yUp + sd*2, 0),
            W(x1, yUp + sd*7, bump), W(x0, yUp + sd*7, bump)
          ];
          this.quadOn(g, pts, i%2 ? A.rootA : A.rootB);
          this.edgeOn(g, pts, A.rootB, 1);
        }
      }

      /* top wedge */
      const top = [
        W(-TILE, yFlush, ZT(yFlush)), W(TILE, yFlush, ZT(yFlush)),
        W(TILE, yUp, ZT(yUp)), W(-TILE, yUp, ZT(yUp))
      ];
      this.quadOn(g, top, A.top);
      this.edgeOn(g, top, A.topDk, 1.5);

      /* hairline cracks radiating from the stressed (raised) edge */
      g.lineStyle(1.2, A.topDk, 0.8);
      const nCracks = 2 + Math.floor(rng()*3);
      for(let i=0; i<nCracks; i++){
        let px = -TILE*0.7 + rng()*TILE*1.4;
        let py = yUp - sd*(4 + rng()*8);
        let p = W(px, py, ZT(py) + 0.1);
        g.beginPath(); g.moveTo(p.x, p.y);
        for(let k=0; k<4; k++){
          px += (rng()-0.5)*22;
          py -= sd*(8 + rng()*14);
          py = Math.max(-TILE+3, Math.min(TILE-3, py));
          const q = W(px, py, ZT(py) + 0.1);
          g.lineTo(q.x, q.y);
        }
        g.strokePath();
      }

      /* chipped lip along the raised edge */
      for(let i=0; i<4; i++){
        const cxp = -TILE + 8 + rng()*(2*TILE - 16);
        const p = W(cxp, yUp - sd*1.5, ZT(yUp) + 0.1);
        g.fillStyle(A.gap, 0.5);
        g.fillEllipse(p.x, p.y, (3 + rng()*4)*this.K*0.6, (1.5 + rng()*2)*this.K*0.6);
      }
    } else if(kind === "sidewalkend"){
      /* approved in sidewalkend lab: ADA curb ramp, exactly 2x3 sidewalk
         tiles (184 along-travel x 276 cross-width). Ground decal only,
         same z-varying-quad-on-flat-tiles ground-decal convention (as
         tile field) — static visual, no tilt/pitch/stuck physics wired
         in yet; see docs/DESIGN.md "Sidewalkend curb ramps" for the full
         spec and the open placement question. This is the DOWN variant
         (sidewalk -> street); tile 1 slopes, tile 2 (pad) is the flat
         landing with the ADA dome texture. */
      const T2s = TILE*2, wHalf = 92;
      /* the base PATCH is 3 tiles across while the ramp itself is only
         one -- at a corner the two streets' patches cross, and each
         carries its own outline, which is half of what reads as a mess
         there. Both are overridable per instance (world ramps pass
         WORLD_RAMP; the route's own ramps pass their hazard object,
         which carries neither key, so they keep the approved look). */
      const crossHalf = (data && data.baseCross !== undefined) ? data.baseCross : 1.5*T2s;
      const baseOutline = (data && data.baseOutline !== undefined) ? data.baseOutline : 2;
      const sidewalkZ = 2, streetZ = -3;
      this.quadOn(g, [W(-wHalf,-crossHalf,sidewalkZ), W(wHalf,-crossHalf,sidewalkZ),
                      W(wHalf,crossHalf,sidewalkZ), W(-wHalf,crossHalf,sidewalkZ)], 0xb5afa2);
      if(baseOutline > 0)
        this.edgeOn(g, [W(-wHalf,-crossHalf,sidewalkZ), W(wHalf,-crossHalf,sidewalkZ),
                        W(wHalf,crossHalf,sidewalkZ), W(-wHalf,crossHalf,sidewalkZ)], 0x968f81, baseOutline);
      g.lineStyle(1.5, 0x968f81, 0.9);
      for(const u of [-0.62, 0, 0.62]){
        const a = W(wHalf*u,-crossHalf,sidewalkZ), b = W(wHalf*u,crossHalf,sidewalkZ);
        g.lineBetween(a.x, a.y, b.x, b.y);
      }
      // tile 1: slopes sidewalk->street. tile 2: flat landing at street height.
      this.quadOn(g, [W(-wHalf,-T2s/2,sidewalkZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,sidewalkZ)], 0xb5afa2);
      this.edgeOn(g, [W(-wHalf,-T2s/2,sidewalkZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,sidewalkZ)], 0x968f81, 1.5);
      this.quadOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0xb5afa2);
      this.edgeOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0x968f81, 1.5);
      // ADA pad: the flat landing tile, dome-textured
      this.quadOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0xf4c430);
      this.edgeOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0xb9911f, 1.5);
      for(let ri=0; ri<5; ri++) for(let ci=0; ci<5; ci++){
        const py = -T2s/2 + T2s*(ri/4), px = wHalf*(ci/4);
        const p = W(px, py, streetZ);
        g.fillStyle(0xc9911f, 0.8);
        g.fillCircle(p.x, p.y, 1.5);
      }
    } else if(kind === "sidewalkbegin"){
      /* the ascending mirror of prop.sidewalkend — completes the pair.
         Restored: this and sidewalkbeginTurn were added in 728c97d but
         silently lost the very next commit (5db2940) when a past
         session pushed from a stale local copy. Real ADA design in
         both directions: the pad sits on a flat landing, never the
         active slope. Here that means tile 1 (the street-facing end)
         is the flat pad, tile 2 is the climb up to sidewalk height —
         reversed from sidewalkend, not just its mirror image; see
         docs/DESIGN.md for why (drawRampDown/Up in the lab are
         independent functions, not one flipped by a flag — that
         approach kept producing mismatches). Static gallery/decal
         visual only, not wired into spawn logic yet. */
      const T2s = TILE*2, wHalf = 92, crossHalf = 1.5*T2s;
      const sidewalkZ = 2, streetZ = -3;
      this.quadOn(g, [W(-wHalf,-crossHalf,sidewalkZ), W(wHalf,-crossHalf,sidewalkZ),
                      W(wHalf,crossHalf,sidewalkZ), W(-wHalf,crossHalf,sidewalkZ)], 0xb5afa2);
      this.edgeOn(g, [W(-wHalf,-crossHalf,sidewalkZ), W(wHalf,-crossHalf,sidewalkZ),
                      W(wHalf,crossHalf,sidewalkZ), W(-wHalf,crossHalf,sidewalkZ)], 0x968f81, 2);
      g.lineStyle(1.5, 0x968f81, 0.9);
      for(const u of [-0.62, 0, 0.62]){
        const a = W(wHalf*u,-crossHalf,sidewalkZ), b = W(wHalf*u,crossHalf,sidewalkZ);
        g.lineBetween(a.x, a.y, b.x, b.y);
      }
      // tile 1: flat landing at street height. tile 2: slopes street->sidewalk.
      this.quadOn(g, [W(-wHalf,-T2s/2,streetZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,streetZ)], 0xb5afa2);
      this.edgeOn(g, [W(-wHalf,-T2s/2,streetZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,streetZ)], 0x968f81, 1.5);
      this.quadOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,sidewalkZ),
                      W(wHalf,T2s/2,sidewalkZ), W(0,T2s/2,streetZ)], 0xb5afa2);
      this.edgeOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,sidewalkZ),
                      W(wHalf,T2s/2,sidewalkZ), W(0,T2s/2,streetZ)], 0x968f81, 1.5);
      // ADA pad: the flat landing tile, dome-textured — street-facing end
      this.quadOn(g, [W(-wHalf,-T2s/2,streetZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,streetZ)], 0xf4c430);
      this.edgeOn(g, [W(-wHalf,-T2s/2,streetZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,streetZ)], 0xb9911f, 1.5);
      for(let ri=0; ri<5; ri++) for(let ci=0; ci<5; ci++){
        const py = -T2s/2 + T2s*(ri/4), px = -wHalf + wHalf*(ci/4);
        const p = W(px, py, streetZ);
        g.fillStyle(0xc9911f, 0.8);
        g.fillCircle(p.x, p.y, 1.5);
      }
    } else if(kind === "pigeons"){
      /* the flock — ported verbatim from labs/pigeon-lab.html (v5).
         Everything is seeded off the flock's WORLD anchor (x,y) and
         drawn through drawProp's local W, so the dv/rv frame rotation
         the lab's bench did by hand happens here by construction —
         correct at all 4 headings for free. data is the hazard object:
         data.fledAt (sim-stamped) drives the scatter burst. */
      const fledAt = (data && data.fledAt != null) ? data.fledAt : null;
      const fled = fledAt;
      if(fled !== null && t - fled > 2600){ /* long gone */ }
      else {
        const drawPigeon = (bx, by, b) => {
            const s = b.size;
            let px = bx + b.ox, py = by + b.oy, wing = 0, thB = b.th;
            let z = fled === null ? Math.abs(Math.sin(t*0.012 + b.flapPh))*0.6 : 0;   // waddle bob
            if(fled !== null){
              const ft = (t - fled)/1000;
              px += Math.cos(b.scatterA) * b.scatterV * 1000 * ft;
              py += Math.sin(b.scatterA) * b.scatterV * 1000 * ft;
              z = 14*ft + 90*ft*ft;                            // up and accelerating away
              wing = Math.sin(t*PIG.flapRate + b.flapPh);      // full beat
              thB = b.scatterA + Math.PI/2;                    // flies the way it flees
            }
            const c = Math.cos(thB), sn = Math.sin(thB);
            const L = (fx, fy, fz) => W(px + fx*c - fy*sn, py + fx*sn + fy*c, z + fz);
            const peck = fled === null ? Math.pow(Math.max(0, Math.sin(t*b.peckRate + b.peckPh)), 6) : 0;
        
            /* shadow — shrinks and fades as the bird climbs */
            const shA = Math.max(0, 0.16 - z*0.0016);
            if(shA > 0.01){
              const sh = []; for(let i=0;i<8;i++){ const a=(i/8)*Math.PI*2;
                sh.push(W(px + Math.cos(a)*7*s, py + Math.sin(a)*5*s, 0.4)); }
              this.quadOn(g, sh, PIG.shadow, shA);
            }
            /* legs (grounded only) */
            if(fled === null){
              g.lineStyle(1.6, PIG.leg, 1);
              for(const ly of [-2.2, 2.2]){
                const a1 = L(-1, ly, 2.4), a2 = L(-1, ly, 0);
                g.lineBetween(a1.x, a1.y, a2.x, a2.y);
              }
            }
            /* ---------- the HULL: a tapered volumetric loaf, mini-drawBox style ----------
               Real faces with backface culling instead of stacked flat planes:
               top strip (back plumage), two side flanks, the lit breast face at
               the front, and the tail-end face. Visibility per face is the same
               projection-exact test the game's boxes use — local normal rotated
               by the bird's facing, summed against the iso view axis. */
            const B = PIG.bodyL*s, H = PIG.bodyH*s;
            const c2 = Math.cos(thB), s2 = Math.sin(thB);
            const vis = (nx, ny) => (nx*c2 - ny*s2) + (nx*s2 + ny*c2) > 0;
            /* corner frame: chest end high and narrow-ish, tail end lower/wider */
            const FT = B*0.45, FB = B*0.5, RT = -B*0.42, RB = -B*0.55;
            const yFT = 2.1*s, yFB = 2.9*s, yRT = 2.5*s, yRB = 3.4*s;
            const zT = 2 + H, zTr = 2 + H*0.85, zB = 2, zBr = 2.4;
            /* far-to-near face order: rear, far-side handled by culling, top, near side, chest */
            if(vis(-1, 0))
              this.quadOn(g, [L(RB,-yRB,zBr), L(RB,yRB,zBr), L(RT,yRT,zTr), L(RT,-yRT,zTr)], b.pal.wing);
            for(const side of [-1, 1]){
              if(!vis(0, side)) continue;
              /* flank */
              this.quadOn(g, [L(FB,side*yFB,zB), L(FT,side*yFT,zT), L(RT,side*yRT,zTr), L(RB,side*yRB,zBr)], b.pal.body);
              /* folded WING: a raised panel lying on the flank — pushed outboard
                 and inset from the body outline, so it reads as a wing resting
                 on the body instead of a painted seam */
              if(fled === null)
                this.quadOn(g, [L(FT*0.7, side*(yFT+0.9), zT - H*0.15),
                           L(FT*0.2, side*(yFB+0.9), zB + H*0.45),
                           L(RB*0.92, side*(yRB+0.7), zBr + H*0.25),
                           L(RT*0.95, side*(yRT+0.9), zTr - H*0.1)], b.pal.wing);
            }
            /* top strip — the back */
            this.quadOn(g, [L(FT,-yFT,zT), L(FT,yFT,zT), L(RT,yRT,zTr), L(RT,-yRT,zTr)], b.pal.body);
            /* the lit breast face */
            if(vis(1, 0))
              this.quadOn(g, [L(FB,-yFB,zB), L(FB,yFB,zB), L(FT,yFT,zT), L(FT,-yFT,zT)], b.pal.breast);
            /* tail: dark fan off the tail-end top edge, twitches at rest */
            const tw = fled === null ? Math.sin(t*0.004 + b.peckPh)*0.6 : 0;
            this.quadOn(g, [L(RT,-1.8*s,zTr), L(-B*1.05, (-1.2+tw)*s, zTr + 0.8),
                       L(-B*1.05, (1.2+tw)*s, zTr + 0.8), L(RT,1.8*s,zTr)], b.pal.wing);
            /* flight wings: two segments each with a dihedral BEND — inner panel
               rises to a mid joint, outer panel continues to the tip at extra
               lift, both riding the flap, so the beat reads as a folding 3D
               wing instead of a flapping triangle */
            if(fled !== null){
              const spread = 10*s + wing*7*s, lift = 3 + Math.abs(wing)*5;
              for(const side of [-1, 1]){
                const shF = L(FT*0.7, side*yFT, zT - 0.5), shR = L(RT*0.8, side*yRT, zTr - 0.5);
                const midF = L(B*0.28, side*spread*0.55, zT + lift*0.55);
                const midR = L(-B*0.42, side*spread*0.5, zTr + lift*0.5);
                const tip  = L(-B*0.1, side*spread, zT + lift + Math.abs(wing)*2);
                this.quadOn(g, [shF, midF, midR, shR], b.pal.wing);
                this.quadOn(g, [midF, tip, midR], b.pal.body);   // outer panel catches light
              }
            }
            /* head: dark knob; peck dips it forward and down */
            const hx = B*0.5 + 2.1*s + peck*3.5*s, hz = 2 + H + 2.3*s - peck*5*s;
            const hs = 3.1*s;
            /* the NECK — a tapered dark quad from the body's shoulder up to the
               head base, drawn before the head so the knob caps it. Follows the
               peck (its far end IS the head anchor), so it stretches and bows
               into every dip instead of the head detaching. */
            this.quadOn(g, [L(B*0.3, -2.4*s, 2+H*0.8), L(hx - hs*0.2, -1.7*s, hz - hs*0.35),
                       L(hx - hs*0.2,  1.7*s, hz - hs*0.35), L(B*0.3,  2.4*s, 2+H*0.8)], b.pal.head);
            this.quadOn(g, [L(B*0.3, -2.4*s, 2+H*0.5), L(hx - hs*0.2, -1.7*s, hz - hs*0.8),
                       L(hx - hs*0.2, -1.7*s, hz - hs*0.35), L(B*0.3, -2.4*s, 2+H*0.8)], b.pal.head);
            this.quadOn(g, [L(B*0.3,  2.4*s, 2+H*0.5), L(hx - hs*0.2,  1.7*s, hz - hs*0.8),
                       L(hx - hs*0.2,  1.7*s, hz - hs*0.35), L(B*0.3,  2.4*s, 2+H*0.8)], b.pal.head);
            const hd = []; for(let i=0;i<8;i++){ const a=(i/8)*Math.PI*2;
              hd.push(L(hx + Math.cos(a)*hs, Math.sin(a)*hs, hz + Math.sin(a)*hs*0.4)); }
            this.quadOn(g, hd, PIG.head);
            /* the iridescent neck fleck */
            this.quadOn(g, [L(hx-hs*0.9,-1.4*s,hz-1.6), L(hx-hs*0.2,-1.1*s,hz-1.2),
                       L(hx-hs*0.2,1.1*s,hz-1.2), L(hx-hs*0.9,1.4*s,hz-1.6)], PIG.neck);
            /* beak tick + eye */
            this.quadOn(g, [L(hx+hs*0.8,-0.8*s,hz), L(hx+hs*1.7,0,hz-0.6*s - peck*1.2), L(hx+hs*0.8,0.8*s,hz)], PIG.beak);
            const eye = L(hx + hs*0.35, -hs*0.75, hz + hs*0.35);
            g.fillStyle(PIG.eye, 1); g.fillCircle(eye.x, eye.y, 1.3*s*this.K*0.8);   // K is scene state in-game (lab had it module-level)
        };
        const birds = flockBirds(x, y);
        const placedB = birds.map(b => {
          const wo = birdWanderAt(b, t);
          return { b: { ...b, ox: b.ox + wo.x, oy: b.oy + wo.y, th: wo.th },
                   d: (b.ox + wo.x)*(dv.x + dv.y) + (b.oy + wo.y)*(rv.x + rv.y) };
        }).sort((a2, b2) => a2.d - b2.d);
        for(const p of placedB) drawPigeon(0, 0, p.b);
      }
    } else if(kind === "grade"){
      /* grade chevrons — flat road-paint on the walk marking a steep
         stretch of the virtual grade profile. Three nested V's pointing
         DOWNhill (data.dir: +1 = downhill along +dv, -1 = reversed),
         same warning-yellow family as the ADA pads so "yellow paint =
         terrain talking to you" stays one visual language. Pure paint:
         z=0, no volume, no physics (skipped in the sim loop), pinned
         under the robot like the ramps. Two leg quads per V, all
         through W() — correct in all 4 headings by construction. */
      const dir = (data && data.dir) || 1;
      const paint = 0xf4c430, edge = 0xb9911f;
      for(let k = -1; k <= 1; k++){
        const bx = k*30, tip = bx + 15, tail = bx - 13, thick = 7;
        for(const side of [-1, 1]){
          const q = [
            W(dir*tip,           0,       0),
            W(dir*(tip - thick), 0,       0),
            W(dir*(tail - thick), side*22, 0),
            W(dir*tail,           side*22, 0)];
          this.quadOn(g, q, paint, 0.9);   // 4th arg is ALPHA in quadOn — slight fade reads as paint
          this.edgeOn(g, q, edge, 0.8);
        }
      }
    } else if(kind === "sidewalkbeginTurn"){
      /* approved in sidewalkendturn lab: the full junction — curb ramp
         down, a wide arc turn onto a new heading, curb ramp back up.
         Full 1:1 geometry (the actual arc, the second road crossing)
         is many tiles across — too large for a gallery card, so this
         is a compact L-shaped diorama: down ramp, a corner tile
         standing in for the turn, up ramp rotated 90°. Same slope/pad
         technique as prop.sidewalkend, used twice. Static visual only,
         no physics — built + physics-tested in
         labs/sidewalkendturn-lab.html, not yet ported into the game. */
      const T2s = TILE*2, wHalf = 92, crossHalf = 1.5*T2s;
      const sidewalkZ = 2, streetZ = -3;

      // DOWN ramp — identical to prop.sidewalkend, anchored at origin
      this.quadOn(g, [W(-wHalf,-crossHalf,sidewalkZ), W(wHalf,-crossHalf,sidewalkZ),
                      W(wHalf,crossHalf,sidewalkZ), W(-wHalf,crossHalf,sidewalkZ)], 0xb5afa2);
      this.edgeOn(g, [W(-wHalf,-crossHalf,sidewalkZ), W(wHalf,-crossHalf,sidewalkZ),
                      W(wHalf,crossHalf,sidewalkZ), W(-wHalf,crossHalf,sidewalkZ)], 0x968f81, 2);
      this.quadOn(g, [W(-wHalf,-T2s/2,sidewalkZ), W(0,-T2s/2,streetZ),
                      W(0,T2s/2,streetZ), W(-wHalf,T2s/2,sidewalkZ)], 0xb5afa2);
      this.quadOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0xb5afa2);
      this.quadOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0xf4c430);
      this.edgeOn(g, [W(0,-T2s/2,streetZ), W(wHalf,-T2s/2,streetZ),
                      W(wHalf,T2s/2,streetZ), W(0,T2s/2,streetZ)], 0xb9911f, 1.5);
      for(let ri=0; ri<5; ri++) for(let ci=0; ci<5; ci++){
        const py = -T2s/2 + T2s*(ri/4), px = wHalf*(ci/4);
        const p = W(px, py, streetZ);
        g.fillStyle(0xc9911f, 0.8);
        g.fillCircle(p.x, p.y, 1.5);
      }

      // CORNER: a road-colored square standing in for the arc turn
      const cx = wHalf + 46, cy = 0;
      this.quadOn(g, [W(cx-46,cy-46,streetZ), W(cx+46,cy-46,streetZ),
                      W(cx+46,cy+46,streetZ), W(cx-46,cy+46,streetZ)], 0x4a4d55);

      // UP ramp — rotated 90°: Wup swaps dx/dy roles, anchored off the corner
      const Wup = (dx, dy, dz) => W(cx+46+dy, cy+dx, dz);
      this.quadOn(g, [Wup(-wHalf,-crossHalf,sidewalkZ), Wup(wHalf,-crossHalf,sidewalkZ),
                      Wup(wHalf,crossHalf,sidewalkZ), Wup(-wHalf,crossHalf,sidewalkZ)], 0xb5afa2);
      this.edgeOn(g, [Wup(-wHalf,-crossHalf,sidewalkZ), Wup(wHalf,-crossHalf,sidewalkZ),
                      Wup(wHalf,crossHalf,sidewalkZ), Wup(-wHalf,crossHalf,sidewalkZ)], 0x968f81, 2);
      this.quadOn(g, [Wup(-wHalf,-T2s/2,streetZ), Wup(0,-T2s/2,streetZ),
                      Wup(0,T2s/2,streetZ), Wup(-wHalf,T2s/2,streetZ)], 0xf4c430);
      this.edgeOn(g, [Wup(-wHalf,-T2s/2,streetZ), Wup(0,-T2s/2,streetZ),
                      Wup(0,T2s/2,streetZ), Wup(-wHalf,T2s/2,streetZ)], 0xb9911f, 1.5);
      for(let ri=0; ri<5; ri++) for(let ci=0; ci<5; ci++){
        const py = -T2s/2 + T2s*(ri/4), px = -wHalf + wHalf*(ci/4);
        const p = Wup(px, py, streetZ);
        g.fillStyle(0xc9911f, 0.8);
        g.fillCircle(p.x, p.y, 1.5);
      }
      this.quadOn(g, [Wup(0,-T2s/2,streetZ), Wup(wHalf,-T2s/2,sidewalkZ),
                      Wup(wHalf,T2s/2,sidewalkZ), Wup(0,T2s/2,streetZ)], 0xb5afa2);
    } else if(kind === "crack"){
      /* approved in crack lab v3: broken-off piece (spall). A jagged
         fracture runs between two seeded points on the tile boundary;
         everything between fracture and boundary is a broken-off
         piece, sunken below grade — corner break-offs and edge bites
         fall out of the same code depending where the seeds land.
         Per-instance: size (hz.len from the generator, or seeded),
         raggedness, branch count, drop depth. Palette follows the
         explicit surface tag set at generation time — sidewalk cracks
         (from the sidewalk hazard loop) always get sidewalk tones,
         road cracks (from the decorative road-crack loop) always get
         asphalt tones. The old data.row>=2 guess was wrong both ways:
         sidewalk cracks in lanes 2-3 got asphalt tones, and road
         cracks (which never had a `row` field at all) fell through
         to sidewalk tones by default. */
      const seed = ((Math.round(x)*7919) ^ (Math.round(y)*104729) ^ 0x3c99) >>> 0;
      const rng = mulberry32(seed);
      const pal = (data && data.surface === "road") ? CRACK_ART.road : CRACK_ART.sidewalk;
      const len = (data && data.len) || (24 + Math.floor(rng()*49));
      const jag = 0.6 + rng()*1.0;
      const nBr = 1 + Math.floor(rng()*3);
      const drop = 3.3 + rng()*2.2;
      const T = TILE - 2, ZT = 0.5;
      const arc = 0.4 + (len/84) * 1.4;
      const bite = Math.min(58, 10 + len*0.5);

      const perim = tv => {
        tv = ((tv % 4) + 4) % 4;
        const e = Math.floor(tv), u = tv - e;
        if(e === 0) return { x:-T + 2*T*u, y:-T };
        if(e === 1) return { x: T, y:-T + 2*T*u };
        if(e === 2) return { x: T - 2*T*u, y: T };
        return { x:-T, y: T - 2*T*u };
      };
      const tA = rng()*4, tB = tA + arc;
      const A = perim(tA), B = perim(tB);

      /* fracture path A->B, pulled inward by the bite, seeded jitter */
      const N = Math.max(5, 4 + Math.round(len/10));
      const frac = [];
      for(let i=0; i<=N; i++){
        const u = i/N;
        let fx = A.x + (B.x - A.x)*u, fy = A.y + (B.y - A.y)*u;
        const inward = Math.pow(Math.sin(Math.PI*u), 0.8) * bite;
        const mag = Math.hypot(fx, fy) || 1;
        fx -= (fx/mag) * inward;
        fy -= (fy/mag) * inward;
        if(i > 0 && i < N){
          fx += (rng()-0.5) * 9 * jag;
          fy += (rng()-0.5) * 9 * jag;
        }
        frac.push({ x: Math.max(-T, Math.min(T, fx)),
                    y: Math.max(-T, Math.min(T, fy)) });
      }

      /* piece region: fracture + boundary walk back B->A */
      const bound = [];
      for(let c2 = Math.ceil(tA); c2 < tB; c2++) bound.push(perim(c2));
      const region = frac.concat([B]).concat(bound.reverse());

      /* sunken piece top */
      this.quadOn(g, region.map(p => W(p.x, p.y, ZT - drop)), pal.piece);
      this.edgeOn(g, region.map(p => W(p.x, p.y, ZT - drop)), pal.core, 1);

      /* hairline across the piece itself when it's big */
      if(bite > 26){
        const m0 = frac[Math.floor(N*0.3)], m1 = frac[Math.floor(N*0.7)];
        g.lineStyle(1, pal.core, 0.9);
        const q0 = W(m0.x*0.6, m0.y*0.6, ZT - drop + 0.1);
        const q1 = W(m1.x*0.9, m1.y*0.9, ZT - drop + 0.1);
        g.lineBetween(q0.x, q0.y, q1.x, q1.y);
      }

      /* rubble chips on the piece near the break */
      const nCh = 3 + Math.floor(rng()*3);
      for(let i=0; i<nCh; i++){
        const fp = frac[1 + Math.floor(rng()*(N-1))];
        const p = W(fp.x*(0.82 + rng()*0.1), fp.y*(0.82 + rng()*0.1), ZT - drop + 0.3);
        g.fillStyle(rng() < 0.5 ? pal.crack : pal.rubble, 0.95);
        g.fillEllipse(p.x, p.y, (2 + rng()*3.5)*this.K*0.5, (1.2 + rng()*2)*this.K*0.5);
      }

      /* exposed fracture wall: the intact slab's broken face */
      for(let i=0; i<frac.length-1; i++){
        const a2 = frac[i], b2 = frac[i+1];
        this.quadOn(g, [
          W(a2.x, a2.y, ZT), W(b2.x, b2.y, ZT),
          W(b2.x, b2.y, ZT - drop), W(a2.x, a2.y, ZT - drop)
        ], i % 2 ? pal.core : pal.wall);
      }

      /* ragged lip along the fracture at top level */
      g.lineStyle(1.4, pal.crack, 1);
      g.beginPath();
      const l0 = W(frac[0].x, frac[0].y, ZT);
      g.moveTo(l0.x, l0.y);
      for(let i=1; i<frac.length; i++){
        const q = W(frac[i].x, frac[i].y, ZT);
        g.lineTo(q.x, q.y);
      }
      g.strokePath();

      /* hairlines radiating into the intact slab */
      for(let b=0; b<nBr; b++){
        const i0 = 1 + Math.floor(rng()*(N-1));
        let bx = frac[i0].x, by = frac[i0].y;
        const mag = Math.hypot(bx, by) || 1;
        let ba = Math.atan2(-by/mag, -bx/mag) + (rng()-0.5)*1.4;
        let bl = 5 + rng()*8;
        for(let k=0; k<3; k++){
          const nx2 = Math.max(-T, Math.min(T, bx + Math.cos(ba)*bl));
          const ny2 = Math.max(-T, Math.min(T, by + Math.sin(ba)*bl));
          g.lineStyle(Math.max(0.8, (1.5 - k*0.45)*this.K*0.4), pal.crack, 0.95);
          const p1 = W(bx, by, ZT), p2 = W(nx2, ny2, ZT);
          g.lineBetween(p1.x, p1.y, p2.x, p2.y);
          bx = nx2; by = ny2;
          ba += (rng()-0.5)*1.2*jag;
          bl *= 0.6;
        }
      }
    }
  }

  /* ---------- robot (approved sprite, driving) ---------- */
  drawRobot(t, dt){
    const g = this.g; g.clear();

    /* house door hinge: opens once the route is won, and swings shut
       again once the customer is carrying the bag back through it
       (wonWalk past the door-plane crossing) — eases every frame
       independent of sim state (same DOOR_ART.openEase rate approved
       in the door lab) */
    const doorTarget = (this.state === "won" && (this.wonWalk || 0) < 0.55) ? DOOR_ART.openAngle : 0;
    this.doorTheta += (doorTarget - this.doorTheta) * DOOR_ART.openEase;
    if(Math.abs(doorTarget - this.doorTheta) < 0.002) this.doorTheta = doorTarget;

    /* pickup timeline: GO -> [loading phase: lid opens, worker lifts
       and places a bag, lid closes] -> [walk phase: existing 2s
       walk-back + shop door open/close]. The walk phase doesn't start
       counting until loading actually finishes — previously the walk
       timer fired the instant "go" was pressed, leaving no room for
       a loading beat. loadT/loadFrac driven by this.runT (real
       elapsed ms only while state==="play"), same frame-rate-
       independent approach as PICKUP_ART.walkMs already used. */
    let loadFrac = 0;
    /* CHALLENGE: there is no delivery here. No pickup shop, no worker
       walking out, no bag, no loading beat — you are on Palmline Ave to
       jump hydrants. Skipping the whole pickup timeline rather than
       trying to fast-forward it, because every downstream effect
       (lid hinge, shop door, worker walk-back, cargo spill) keys off
       these same flags. */
    if(this.mode === "challenge"){
      this.loadDone = false; this.walkAt = null; this.pickupWalk = 1;
      this.bagOnBoard = false; this.doorSwing = 0; this.pickupLidClosing = false;
    } else if(this.state === "play"){
      const loadT = this.runT;
      loadFrac = Phaser.Math.Clamp(loadT / LOAD_ART.ms, 0, 1);
      this.loadDone = loadT >= LOAD_ART.ms;
      /* persistent latch for the spill: loadDone itself is VOLATILE —
         the else branch below wipes it the instant state leaves "play",
         and spillCargo fires frames AFTER state becomes "tipped", so
         gating the spilled bag on loadDone always missed. This flag
         survives the state change; spillCargo consumes it. */
      if(this.loadDone) this.bagOnBoard = true;
      if(this.loadDone){
        if(this.walkAt === null) this.walkAt = this.runT;
        /* duration from the REAL walk distance (meet point -> past the
           door plane) at 0.18 u/ms — a hustle, ~60% quicker than the
           customer's 0.11 stroll, because this walk happens BEHIND a
           player who already has the bag and the camera. The fixed
           walkMs was tuned for the old short dy and would sprint the
           longer meet-to-door return. */
        let backMs = PICKUP_ART.walkMs;
        if(this.route.pickupSpot && this.pickupDoorDV){
          const dpx = this.pickupDoorUX + this.pickupDoorDV.x*this.pickupDoorCenterX;
          const dpy = this.pickupDoorUY + this.pickupDoorDV.y*this.pickupDoorCenterX;
          let bvx = this.route.pickupSpot.x - dpx, bvy = this.route.pickupSpot.y - dpy;
          const bd = Math.hypot(bvx, bvy) || 1;
          const mx = this.route.pickupSpot.x - bvx/bd*12, my = this.route.pickupSpot.y - bvy/bd*12;
          const bx2 = dpx - this.pickupDoorRV.x*30, by2 = dpy - this.pickupDoorRV.y*30;
          backMs = Math.max(400, Math.hypot(mx - bx2, my - by2) / 0.18);
        }
        this.pickupWalk = Phaser.Math.Clamp(1 - (this.runT - this.walkAt)/backMs, 0, 1);
      } else {
        this.walkAt = null;
        this.pickupWalk = 1; // still idle at the robot during loading
      }
    } else {
      this.loadDone = false; this.walkAt = null;
      this.pickupWalk = 1;
    }

    /* ---------- dropoff handoff timeline: the pickup's loading phase
       mirrored (dial choreography shared via LOAD_ART so both handoffs
       read as the same beat). won -> [customer walks out, driven by
       doorTheta exactly as before] -> [lid opens, bag rises out of the
       bin and arcs to the customer's raised hand, lid closes, he holds
       it]. The clock only starts once he's actually arrived at the mat
       (doorTheta nearly fully open — walkT and the door share that
       driver), so the bag never launches at a customer who's still in
       the doorway. showWin is untouched: the overlay fires immediately
       and this plays out underneath it. */
    if(this.state === "won"){
      /* the MEET POINT: the customer now walks all the way to the
         robot, not just to the mat's edge — straight line from the
         door to wherever the robot actually stopped (the win window
         allows ~94 units of s-slop plus any lane, so this is a real
         vector, correct in all 4 headings), stopping 35 units short so
         he stands facing the bin. Robot is frozen in "won", so these
         are stable frame to frame. Recomputed cheaply each frame
         because the door anchors (addrDoor*) are only refreshed by the
         world draw. */
      if(this.addrDoorDV){
        const ddv = this.addrDoorDV, drv = this.addrDoorRV;
        const doorX = this.addrDoorUX + ddv.x*this.addrDoorCenterX;
        const doorY = this.addrDoorUY + ddv.y*this.addrDoorCenterX;
        let vx = this.botX - doorX, vy = this.botY - doorY;
        const dist = Math.hypot(vx, vy) || 1; vx /= dist; vy /= dist;
        this.wonDoor = { x: doorX, y: doorY };
        this.wonMeet = { x: this.botX - vx*35, y: this.botY - vy*35 };
        this.wonMeetTh = Math.atan2(vy, vx) - Math.PI/2;  // faces the robot along the real approach
        this.wonApproachDist = dist;
      }
      /* walk-out: his own clock at constant pace (the pickup worker's
         ~0.11 units/ms), duration proportional to the actual distance —
         riding the door angle like before would make a far-parked robot
         look like a sprint. Steps out once the door is half open. */
      const WON_WALK_SPEED = 0.11;
      if(this.wonMeet){
        const sx = this.wonDoor.x + this.addrDoorRV.x*4, sy = this.wonDoor.y + this.addrDoorRV.y*4;
        const outLen = Math.max(1, Math.hypot(this.wonMeet.x - sx, this.wonMeet.y - sy));
        if(this.doorTheta >= DOOR_ART.openAngle * 0.5) this.wonOutT = (this.wonOutT || 0) + dt;
        this.wonOutFrac = Math.min(1, (this.wonOutT || 0) / (outLen / WON_WALK_SPEED));
      }
      /* handoff clock: gated on ARRIVAL at the meet point now (not the
         door angle) — and once started it never re-gates, since the
         door closes during the walk-back and re-checking would freeze
         the timeline mid-walk. */
      if((this.wonT || 0) > 0 || (this.wonOutFrac || 0) >= 1)
        this.wonT = (this.wonT || 0) + dt;
      this.wonFrac = Phaser.Math.Clamp((this.wonT || 0) / LOAD_ART.ms, 0, 1);
      /* receiving arm: rises through the bag's flight so full reach
         lands exactly when the bag does, then eases back down with the
         bag locked to the hand (drops with him into a natural carry) */
      if(this.wonFrac <= LOAD_ART.holdEnd) this.wonLiftT = 0;
      else if(this.wonFrac < LOAD_ART.dropFrac)
        this.wonLiftT = (this.wonFrac - LOAD_ART.holdEnd) / (LOAD_ART.dropFrac - LOAD_ART.holdEnd);
      else this.wonLiftT = Math.max(0, (this.wonLiftT || 0) - dt/600);
      /* walk-back: once the handoff has fully settled, he carries it
         inside at the same pace — duration from the real return
         distance (meet -> just past the door plane). */
      const settled = this.wonFrac >= 1 && this.wonLiftT <= 0.01;
      if(settled && this.wonWalkAt == null) this.wonWalkAt = this.wonT;
      let backMs = PICKUP_ART.walkMs;
      if(this.wonMeet){
        /* must match queueHousingEdgeAt's backDist exactly, or this
           duration calc budgets the wrong distance and he covers the
           real (gate-mode) distance at the wrong speed — confirmed
           on-device: this is what caused the "sprinting" walk-back. */
        const backDist = (this.route && this.route.addressUsesGate) ? GATE_WALKOFF_DIST : 24;
        const bx = this.wonDoor.x - this.addrDoorRV.x*backDist, by = this.wonDoor.y - this.addrDoorRV.y*backDist;
        backMs = Math.max(400, Math.hypot(this.wonMeet.x - bx, this.wonMeet.y - by) / WON_WALK_SPEED);
      }
      this.wonWalk = this.wonWalkAt == null ? 0
        : Phaser.Math.Clamp((this.wonT - this.wonWalkAt) / backMs, 0, 1);
    } else { this.wonT = 0; this.wonFrac = 0; this.wonLiftT = 0; this.wonWalkAt = null; this.wonWalk = 0;
             this.wonOutT = 0; this.wonOutFrac = 0; this.wonMeet = null; }

    /* cargo lid: opens early in the loading phase, closes again once
       the bag has dropped in — reuses the existing lidAng hinge
       (normally driven by the tip/spill state machine below, gated on
       state==="tipped" so the two never fight), just with a plain
       open/close target instead of the tip/spill's asymmetric ones.
       lidHingeFlip used to be gated on state==="play" alone, which is
       the whole drive, not just this beat — it leaked into the "crack
       the lid open when cornering gets risky" effect further down,
       which writes to this same lidAng but should use the tip/spill's
       fixed hinge.
       Tying it directly to loadingLidOpen fixed that but broke the
       close-out: lidAng EASES toward its target (LOAD_ART.lidEase),
       it doesn't snap, so the instant loadingLidOpen goes false the
       lid is still most of the way open (confirmed: still 0.42 rad
       the same frame, 0.35 rad the next) — flipping the hinge right
       then swaps which side it's swinging from while still visibly
       open. pickupLidClosing latches true for the whole time we owe
       that close-out, and only releases once lidAng has actually
       eased under 0.15 (lidNear()'s own "basically closed" bar) — a
       latch instead of a raw lidAng>=0.15 check specifically so the
       cornering-crack effect, which opens this same lidAng for an
       unrelated reason, can't re-trigger it: the latch only ever gets
       set by loadingLidOpen itself, never by lidAng's value alone. */
    const loadingLidOpen = this.state === "play" && loadFrac > 0.05 && loadFrac < LOAD_ART.dropFrac;
    const lidLoadTarget = loadingLidOpen ? LOAD_ART.lidOpenAngle : 0;
    if(loadingLidOpen) this.pickupLidClosing = true;
    else if(this.lidAng < 0.02) this.pickupLidClosing = false;
    /* 0.02 rad (~1 degree), NOT the old 0.15 (~8.5 degrees): the hinge
       mirrors the instant this latch releases, and at 0.15 the lid was
       still visibly open — the reported "switches the hinge to the
       other side" pop. At 0.02 the swap is invisible. (0.15 was
       borrowed from lidNear's draw-order bar, which has nothing to do
       with hinge correctness.) */
    /* won-handoff lid: same hinge, same open target, same close-out
       latch pattern as the loading phase above — gated on state==="won"
       so it can never fight the loading driver (play), the tip/spill
       writer (tipped), or the cornering-crack effect (play). Opens
       while the bag is still in the bin, closes once it's out. */
    const wonLidOpen = this.state === "won" && this.wonFrac > 0.02 && this.wonFrac < LOAD_ART.dropFrac;
    if(wonLidOpen) this.wonLidClosing = true;
    else if(this.lidAng < 0.02) this.wonLidClosing = false;   // same invisible-swap bar as the pickup latch
    this.lidHingeFlip = (this.state === "play" && (loadingLidOpen || this.pickupLidClosing))
                     || (this.state === "won" && (wonLidOpen || this.wonLidClosing));
    if(this.state === "play"){
      this.lidAng += (lidLoadTarget - this.lidAng) * LOAD_ART.lidEase;
      if(Math.abs(lidLoadTarget - this.lidAng) < 0.002) this.lidAng = lidLoadTarget;
    } else if(this.state === "won"){
      const lidWonTarget = wonLidOpen ? LOAD_ART.lidOpenAngle : 0;
      this.lidAng += (lidWonTarget - this.lidAng) * LOAD_ART.lidEase;
      if(Math.abs(lidWonTarget - this.lidAng) < 0.002) this.lidAng = lidWonTarget;
    }

    /* rise -> hold -> release: the carrying arm starts at his side
       (liftT=0, natural rest), pivots up through RISE_END, holds
       briefly, then eases back down while the bag detaches and
       continues on its own arc to the bin. Stored on this so
       drawPickupUnit (called separately) can read the same values. */
    const RISE_END = LOAD_ART.riseEnd, HOLD_END = LOAD_ART.holdEnd, RELEASE_END = LOAD_ART.releaseEnd;
    this.pickupLiftT = 0; this.pickupReleased = false;
    if(this.state === "play"){
      if(this.loadDone){ this.pickupLiftT = 0; this.pickupReleased = true; }
      else if(loadFrac <= RISE_END) this.pickupLiftT = loadFrac / RISE_END;
      else if(loadFrac <= HOLD_END) this.pickupLiftT = 1;
      else { this.pickupLiftT = Math.max(0, 1 - (loadFrac-HOLD_END)/(RELEASE_END-HOLD_END)); this.pickupReleased = true; }
    }
    this.pickupLoadFrac = loadFrac;

    /* shop door: opens while he's still walking toward it, starts
       closing the instant he arrives (pickupWalk hits 0) — NOT just
       tracking state==="play" directly, which would open it once and
       leave it open for the rest of the route instead of it actually
       swinging shut behind him. */
    const shopDoorTarget = (this.state === "play" && this.loadDone && this.pickupWalk > 0) ? SHOPDOOR_ART.openAngle : 0;
    this.doorSwing += (shopDoorTarget - this.doorSwing) * SHOPDOOR_ART.openEase;
    if(Math.abs(shopDoorTarget - this.doorSwing) < 0.002) this.doorSwing = shopDoorTarget;

    /* ---------- simulation ---------- */
    if(this.state === "play"){
      const _botS_frameStart = this.botS;   // debug: for the backward-motion assertion below
      this.runT += dt;

      /* throttle / brake / hill gravity / friction */
      const slope = this.groundSlope(this.botS);          // + uphill
      if(this.throttle === 1) this.speed += 0.00042*dt;
      if(this.throttle === -1) this.speed -= 0.00075*dt;
      this.speed -= slope * 0.00030 * dt;                 // gravity
      this.speed -= this.speed * 0.0009 * dt;             // rolling friction
      /* THE CEILING IS A FIELD, NOT A LITERAL. 0.225 is delivery's top
         speed and stays the default for every mode that does not say
         otherwise. A speciality event that wants a different roof sets
         speedCap and gets ordinary throttle physics underneath it —
         accelerate, brake, gravity, friction, all unchanged, just a
         different lid.

         DELIBERATELY NOT THE CHALLENGE BRANCH BELOW. That one ASSIGNS
         speed outright because the tap meter IS its throttle, which is
         right for the hydrant course and wrong for anything that still
         wants to be driven. Reusing it would have handed the throttle
         to the tap meter. This is a separate, simpler thing: a lid.

         Left as a plain field rather than a mode test so the two cannot
         drift — there is one ceiling, whoever set it, and a mode that
         forgets to clear it will be obvious rather than subtle. */
      this.speed = Phaser.Math.Clamp(this.speed, 0, this.speedCap || 0.225);
      /* CHALLENGE: the tap meter IS the throttle. Overriding here rather
         than in hjSim because this block runs afterwards and would
         otherwise stomp it — the charge has to win, and it has to win
         BEFORE botS advances a few lines below. Speed is frozen for the
         whole flight (no air control). */
      if(this.mode === "challenge" && this.route && this.route.challenge){
        this.speed = (this.hjAir || this.hjRolling)
          ? this.hjFlightSpeed              // frozen through flight AND roll-out
          : HJ_CH.sp0 + this.hjChargeSm*(HJ_CH.sp1 - HJ_CH.sp0);
      }
      /* ground-speed correction (ported from the corner+robot lab): botS
         parameterizes the CENTERLINE arc length, but the robot draws
         offset sideways by laneOff. On an arc, the robot's actual traced
         radius is (R - seg.sign*laneOff) — smaller toward the turn's
         inside (crawls), larger toward the outside (speeds up) — a
         5x-30x real ground-speed difference between turn directions at a
         fixed lane, purely from parameterizing by the wrong arc length.
         Scale botS's advance by (R / effectiveR) so actual ground speed
         matches the throttle-controlled speed regardless of which way
         the lane sits relative to the curve. */
      const _preSeg = this.segAt(this.botS);
      let _stretch = 1;
      if(_preSeg.type === "arc"){
        const _effR = _preSeg.R - _preSeg.sign*this.laneOff;
        _stretch = Phaser.Math.Clamp(_effR / _preSeg.R, 0.05, 20);
      }
      this.botS += (this.speed/_stretch) * dt;
      this.wheelPhase -= this.speed * dt * 0.28;

      /* corners: Tipsey turns himself — centrifugal lean (∝ v²) is YOUR problem */
      const seg = this.segAt(this.botS);
      /* cornering lean reacts to this SMOOTHED speed, not raw this.speed —
         reapplying throttle after coasting/braking mid-corner used to spike
         tilt instantly (confirmed: coast ~1s then punch it spiked tilt
         0.263->0.924 and tipped within another second), since raw speed can
         rise much faster than the tilt spring can react. Steady cornering
         (the common case) tracks actual speed closely within a couple
         hundred ms and is unaffected; a sudden speed spike now takes a
         moment to reach the lean formula, giving the spring room to keep up
         instead of getting outrun. */
      this.corneringSpeedSmooth = Phaser.Math.Linear(this.corneringSpeedSmooth, this.speed, Math.min(1, 0.0018*dt));
      /* cornering-lean sensitivity tapers off as you get further through
         the turn — full strength for the first 40% (still risky to gun it
         right from turn entry, that's intentional and unchanged), easing
         down to 35% by the exit. This is the direct fix for "tipping
         should be way less once you're past the curve" — the speed
         smoothing above only softens a sudden reflex-correction spike, it
         can't by itself prevent a tip if the player just holds throttle
         long enough for the smoothed speed to catch up anyway. */
      const arcProgress = seg.type === "arc" ? Phaser.Math.Clamp((this.botS - seg.s0)/(seg.s1 - seg.s0), 0, 1) : 0;
      const tiltTaper = arcProgress < 0.4 ? 1 : Phaser.Math.Linear(1, 0.35, (arcProgress - 0.4)/0.6);
      if(seg.type === "arc") this.tilt += seg.sign * this.corneringSpeedSmooth * this.corneringSpeedSmooth * CORNER_TILT_COEF * tiltTaper * dt * TILT_SENS;
      /* visual banking: only the INSIDE lane lifts wheels; center + outside stay flat.
         The sidewalk band sits entirely on ONE side of the street now (not
         straddling the centerline like the old 3-lane system), which means
         a whole turn direction puts the ENTIRE band either fully inside or
         fully outside — that's the dominant effect. Using deviation from
         the band's center (my earlier fix) only captured the smaller
         lane-to-lane gradient and got the dominant direction backwards.
         The full laneOff, normalized against the band's own max extent,
         captures both correctly: same sign convention the arc's own
         center offset uses (sign*rv*R), so sign*laneOff > 0 means the
         band is on the same side as the turn's center — i.e. inside. */
      const inside = seg.type === "arc"
        ? Phaser.Math.Clamp(seg.sign * this.laneOff / (ROAD_HALF + SIDEWALK_W), 0, 1) : 0;
      const leanTarget = seg.type === "arc"
        ? seg.sign * Math.min(this.speed/0.15, 1) * 0.32 * inside : 0;
      this.cornerLean = Phaser.Math.Linear(this.cornerLean, leanTarget, 0.07);

      /* crack the lid open once actually in tip danger — matches the HUD
         gauge's own red threshold (drawHUD: danger > 0.75) exactly, instead
         of a flat speed threshold that didn't track real risk (a wide
         outside turn at speed>0.11 has very low actual tilt; a tight
         inside turn is genuinely dangerous at that same speed) */
      const lidCrackTarget = Math.abs(this.tilt) > 0.75 ? 0.4 : 0;
      /* stand down while the pickup loading latch owns the lid: this
         writer runs every play frame, so during the loading phase it
         was FIGHTING the loading ease (open toward 1.1 in drawRobot,
         then Linear'd back toward 0 here, every single frame) — the
         lid ground to a half-open ~0.6 equilibrium instead of the
         dialed 1.1, on the flipped hinge, then popped hinges at the
         latch release. pickupLidClosing spans the loading open AND its
         close-out, so gating on it hands the lid back to this writer
         only once it's genuinely shut. */
      if(!this.pickupLidClosing)
        this.lidAng = Phaser.Math.Linear(this.lidAng, lidCrackTarget, 0.08);

      /* lane maneuver: eased diagonal glide with nose steer */
      if(this.hopAnim && seg.type === "arc"){
        /* a hop that was already in progress when the turn started —
           resolve it immediately instead of letting it keep swinging
           mid-arc, same reasoning as hop() refusing to start a new one. */
        this.laneOff = this.hopAnim.to;
        this.hopAnim = null; this.hopYaw = 0;
      }
      if(this.hopAnim){
        const HOP_MS = 480;
        const k = Phaser.Math.Clamp((this.time.now - this.hopAnim.start) / HOP_MS, 0, 1);
        const e = k*k*(3 - 2*k);                           // smoothstep
        this.laneOff = this.hopAnim.from + (this.hopAnim.to - this.hopAnim.from)*e;
        this.hopYaw = this.hopAnim.dir * 0.26 * Math.sin(Math.PI*k);
        if(k >= 1){ this.hopAnim = null; this.hopYaw = 0; }
      } else {
        this.hopYaw = Phaser.Math.Linear(this.hopYaw, 0, 0.2);
      }
      /* bleed the hop's stability cost in over ~0.3s */
      if(this.hopKick !== 0){
        const apply = this.hopKick * Math.min(1, dt/300);
        this.tilt += apply * TILT_SENS;
        this.hopKick -= apply;
        if(Math.abs(this.hopKick) < 0.002) this.hopKick = 0;
      }

      /* hazards: each one is the math problem */
      this.isBlocked = false;
      let slabUnder = null;
      /* botRow updates the INSTANT hop() is called, but the robot's
         actual visual position (laneOff) animates toward it over
         480ms. Using botRow directly for collision meant a hazard on
         the TARGET lane could hard-stop you the moment you started a
         hop, before you'd visually arrived — if your botS was already
         past where it'd stop you, that snapped you backward. This
         checks where the robot actually IS instead of where it's
         logically headed. */
      const onLane = row => Math.abs(this.laneOff - laneOffset(row)) < T2*0.5;
      /* defensive floor: no single hazard-triggered stop should ever move
         botS backward by more than the largest legitimate offset already
         in use (palm=30, hydrant=26, bin's own small creep). Whatever the
         exact trigger for the reported "reversing around the arc" turns
         out to be, this makes a LARGE backward jump structurally
         impossible regardless of cause, while leaving the small
         intentional wall-stop nudges untouched. */
      const safeStop = target => Math.max(target, this.botS - 60);
      for(const hz of this.route.hazards){
        /* curb ramps are static ground visuals for now — no tilt/pitch/
           curb physics wired yet (docs/DESIGN.md "Sidewalkend curb
           ramps"). Without this skip they'd fall through to the generic
           bump else-branch at the bottom of this chain and kick/damage
           the robot on every street crossing. hit:true at spawn is the
           belt to this suspender. */
        if(hz.type === "sidewalkend" || hz.type === "sidewalkbegin" || hz.type === "grade") continue;   // ramps + grade paint: no collision
        let dx = this.botS - hz.s;
        /* lateral offset of a MOVING hazard's hitbox: a walker mid-
           detour (detourBAt) is a full lane off its home row, and a
           settled fleer stopped wherever the flee's own db left it.
           Both spot/settled functions already report .b; the contact
           gate below adds it to laneOffset(hz.row) so hitbox = art
           on both axes, not just along-route. 0 for everything else
           keeps the gate exactly what onLane(hz.row) was. */
        let hzB = 0;
        if(hz.type === "pigeons"){
          /* pure trigger: drive into the flock and it bursts. Generous
             cross window (the flock mills ±30 around its row); no
             damage, no tilt, ever — the scatter is the whole event. */
          if(hz.fledAt == null && Math.abs(dx) < 60 &&
             Math.abs(this.laneOff - laneOffset(hz.row)) < T2*1.3)
            hz.fledAt = this.time.now;
          continue;
        }
        /* the dog moves; his hitbox moves with him — same pure
           function the renderer uses, so art and impact agree */
        if(hz.type === "dog"){
          if(hz.hitT !== undefined){
            /* once settled (flee finished) he's parked at a fixed spot -
               dogSettledSpot, not the old time-based wander cycle, which
               would've drifted somewhere else entirely by now. Re-arm
               hz.hit so he can be startled again from wherever he's
               sitting, same as the first time. */
            const flee = dogFleeAt(t, hz);
            if(flee && !flee.gone) continue;   // still actively fleeing - no collision check yet
            hz.hit = false;
            const dsp = dogSettledSpot(hz);
            dx -= dsp.a; hzB = dsp.b || 0;
          } else {
            const dsp = dogSpotAt(t, hz);
            dx -= dsp.a; hzB = dsp.b || 0;
          }
        }
        if(hz.type === "people"){
          /* same contract as the dog: his hitbox moves with him. While
             actively fleeing, no collision check; once settled, re-arm
             so they can be startled again from wherever they landed.
             Before ever being hit, track the same patrol wander the
             renderer uses via peopleSpotAt(). */
          if(hz.hitT !== undefined){
            const flee = peopleFleeAt(t, hz);
            if(flee && !flee.gone) continue;
            hz.hit = false;
            const psp = peopleSettledSpot(hz);
            dx -= psp.a; hzB = psp.b || 0;
          } else {
            const psp = peopleSpotAt(t, hz);
            dx -= psp.a; hzB = psp.b || 0;
          }
        }
        if(hz.type === "william"){
          /* THE WILLIAM — the lap's resident robot-hater, ported from
             labs/william-lab.html v6 (approved). Integrated state lives
             on hz (cone pattern: sim writes ka/kb/kst, renderer reads
             the same fields, so hitbox == art by construction); patrol
             position is the shared pure peopleSpotAt, same contract as
             prop.people. Timeline: PATROL -> INTERCEPT (steps into
             YOUR lane) -> BLOCK (palm-contract wall) -> you swerve ->
             WINDUP (facing FROZEN at entry: tracking here rotated the
             body and made the cocked leg sweep sideways, lab-reported)
             -> KICK (contact-checked boot) -> GLOAT/WHIFF -> return.
             One attempt per pass (spent, hazard-standard re-arm).
             Counterplay: commit the swerve early and pass fast — he
             leads the target, so accelerating AFTER his windup starts
             breaks the prediction and he boots air. */
          const KA = WILLIAM_ACT;
          if(hz.kst === undefined){ hz.kst = "patrol"; hz.kt0 = t; hz.ka = 0; hz.kb = 0; hz.kth = 0; hz.spent = false; }
          const kel = t - hz.kt0;
          const kLat = () => this.laneOff - (laneOffset(hz.row) + hz.kb);
          if(hz.kst === "patrol"){
            const ksp = peopleSpotAt(t, hz);
            hz.ka = ksp.a; hz.kb = ksp.b || 0;
            const kdx = dx - hz.ka;
            if(hz.spent && Math.abs(kdx) > KA.blockTrig + 40) hz.spent = false;
            if(!hz.spent && this.state === "play"){
              const lead = this.speed*(KA.windup + KA.swing*KA.contactU);
              if(Math.abs(kLat()) < 34 && kdx > -KA.blockTrig && kdx < -KA.standoff - 6){
                hz.kst = "intercept"; hz.kt0 = t; hz.kicked = false; hz.klanded = false;
                /* he steps into YOUR lane, wherever you are — clamped
                   to the sidewalk band so he never plants in traffic */
                hz.ktargetB = Phaser.Math.Clamp(this.laneOff - laneOffset(hz.row), -T2*1.5, T2*1.5);
              } else if(Math.abs(kLat()) >= 40 && Math.abs(kdx + lead) < KA.hitAlong*0.9){
                hz.kst = "windup"; hz.kt0 = t; hz.kicked = false; hz.klanded = false;
                hz.kickDir = Math.sign(kLat()) || 1;
                hz.kb0 = hz.kb;
                hz.kth = Math.atan2(-kdx, kLat() || hz.kickDir);   // COMMIT: frozen
              }
            }
          } else if(hz.kst === "intercept"){
            const kdx = dx - hz.ka;
            const kdb = hz.ktargetB - hz.kb;
            hz.kth = Math.atan2(-kdx, kdb || -1);
            hz.kb += Math.sign(kdb) * Math.min(Math.abs(kdb), KA.chase * dt);
            if(Math.abs(hz.ktargetB - hz.kb) < 2){ hz.kb = hz.ktargetB; hz.kst = "block"; hz.kt0 = t; }
          } else if(hz.kst === "block"){
            const kdx = dx - hz.ka;
            hz.kth = Math.atan2(-kdx, kLat() || -1);
            const lead = this.speed*(KA.windup + KA.swing*KA.contactU);
            if(Math.abs(kLat()) >= 40 && Math.abs(kdx + lead) < KA.hitAlong*0.9){
              hz.kst = "windup"; hz.kt0 = t; hz.kicked = false; hz.klanded = false;
              hz.kickDir = Math.sign(kLat()) || 1;
              hz.kb0 = hz.kb;
              hz.kth = Math.atan2(-kdx, kLat() || hz.kickDir);     // COMMIT: frozen
            } else if(kdx < -(KA.blockTrig + 60) || kdx > 40){
              hz.kst = "return"; hz.kt0 = t; hz.retA = hz.ka; hz.retB = hz.kb;
            }
          } else if(hz.kst === "windup"){
            /* facing frozen; he steps toward your lane while cocking.
               PHASE-driven, not dt-integrated: position and the state
               timers share ONE clock (wall t), so at contact he has
               ALWAYS fully stepped in regardless of framerate — the
               dt-integrated version whiffed under dropped frames
               because the 120ms windup expired before the body moved */
            const kPh = Math.min(1, kel / (KA.windup + KA.swing*KA.contactU));
            hz.kb = hz.kb0 + hz.kickDir * T2 * KA.lungeMax * kPh;
            if(kel >= KA.windup){ hz.kst = "kick"; hz.kt0 = t; }
          } else if(hz.kst === "kick"){
            if(kel < KA.swing*KA.contactU){
              const kPh = Math.min(1, (KA.windup + kel) / (KA.windup + KA.swing*KA.contactU));
              hz.kb = hz.kb0 + hz.kickDir * T2 * KA.lungeMax * kPh;
            }
            if(!hz.kicked && kel >= KA.swing*KA.contactU){
              hz.kicked = true;
              const kdx = dx - hz.ka;
              /* CONTACT, not proximity: the boot tip has to actually
                 reach the hull — alongside AND within lateral reach
                 (kicks were "landing" with daylight, lab-reported) */
              if(this.state === "play" && Math.abs(kdx) < KA.hitAlong && Math.abs(kLat()) < KA.reach){
                hz.klanded = true;
                /* THE BOOT — deliberate attack, deliberately NOT
                   scaled by TILT_SENS (the established "deliberate,
                   not routine" carve-out). SIGN: positive tilt leans
                   toward the BUILDINGS (the slab hazard's documented
                   convention); the kick pushes the bot AWAY from him,
                   so the impulse is NEGATED kickDir (lab-verified v6).
                   power 1.4 > the balance threshold: a clean boot
                   knocks Tipsey over. */
                this.tilt += KA.power * -(hz.kickDir || 1);
                this.damage = Math.min(95, this.damage + KA.power*14*CARGO_DAMAGE_SENS);
                this.speed *= 0.8;
                /* who knocked us over, for the fail copy. Cleared again
                   below the moment the robot is back near upright, so a
                   survived boot followed by an ordinary cone tip still
                   reads as an ordinary cone tip. */
                this.tipCause = "william";
              }
            }
            if(kel >= KA.swing){
              hz.spent = true;
              hz.kst = hz.klanded ? "gloat" : "whiff"; hz.kt0 = t;
            }
          } else {
            /* gloat / whiff / return -- the tail of the timeline, which
               has no dependency on the robot at all. It lives in
               williamSettleStep so the post-tip pass can run the exact
               same code: duplicating a state machine across two call
               sites is how the two quietly drift apart. */
            this.williamSettleStep(hz, t);
          }
          /* THE WALL — palm contract while he's stepping out or
             planted in your lane: you stop at standoff. The only way
             through is AROUND him. */
          if((hz.kst === "intercept" || hz.kst === "block") && Math.abs(kLat()) < 34){
            const wallS = hz.s + hz.ka;
            if(this.botS > wallS - KA.standoff && this.botS < wallS + 20){
              this.botS = safeStop(wallS - KA.standoff);
              this.isBlocked = true;
              this.speed = 0;
            }
          }
          continue;
        }
        if(hz.type === "lamp"){
          /* the pole is a thin palm-contract wall: you stop, you do
             not pass; a fast approach bonks (softer than a trunk) */
          if(onLane(hz.row) && this.botS > hz.s - LAMP_ACT.standoff && this.botS < hz.s){
            this.botS = safeStop(hz.s - LAMP_ACT.standoff);
            this.isBlocked = true;
            if(this.speed > 0.08 && !hz.hit){
              hz.hit = true; this.tipCause = hz.type;
              const kick = this.speed * 5 * (Math.random() < 0.5 ? 1 : -1);
              this.tilt += kick * TILT_SENS;
              this.damage = Math.min(95, this.damage + Math.abs(kick)*30*CARGO_DAMAGE_SENS);
            }
            this.speed = 0;
          }
          if(Math.abs(dx) > 40) hz.hit = false;
          continue;
        }
        if(hz.type === "palm"){
          /* a trunk is a wall: you stop, you do not pass */
          if(onLane(hz.row) && this.botS > hz.s - 30 && this.botS < hz.s){
            this.botS = safeStop(hz.s - 30);
            this.isBlocked = true;
            if(this.speed > 0.08 && !hz.hit){
              hz.hit = true; this.tipCause = hz.type;                               // the bonk (once per approach)
              const kick = this.speed * 7 * (Math.random() < 0.5 ? 1 : -1);
              this.tilt += kick * TILT_SENS;
              this.damage = Math.min(95, this.damage + Math.abs(kick)*40*CARGO_DAMAGE_SENS);
            }
            this.speed = 0;
          }
          if(Math.abs(dx) > 40) hz.hit = false;            // re-arm after backing off
        } else if(hz.type === "slab"){
          /* heaved slab (approved in ramp lab v2): one sidewalk tile,
             lifted along one side edge (side ±1), flush at the other.
             Two-stage, physically ordered: (a) the wheels on the raised
             side climb the lip at the leading joint — one-shot roll
             kick toward the low side, ∝ speed × lift, so creeping over
             is the counterplay; (b) sustained cross-slope tilt while
             riding the wedge, continuous cross-slope tilt scaled by lift.
             Positive roll leans −dy, so side=+1 (road edge up) feeds
             tilt POSITIVE — falls toward the buildings. */
          /* COURSE PIECES ARE NOT HAZARDS. The kicker is a lift-12 slab and
             the normal slab physics (tilt += side*speed*lift*0.9) tip the
             robot over the instant he touches it — he never reaches the
             lip to launch. hjSim owns these; the world just draws them. */
          if(onLane(hz.row) && !hz.hjRole){
            if(!hz.lipHit && dx > -TILE && dx < -TILE + 14){
              hz.lipHit = true;
              const kick = hz.side * this.speed * hz.lift * 0.9;
              this.tilt += kick * TILT_SENS;
              this.damage = Math.min(95, this.damage + Math.abs(kick)*30*CARGO_DAMAGE_SENS);
            }
            if(Math.abs(dx) > TILE + 20) hz.lipHit = false; // re-arm after clearing it
            if(Math.abs(dx) < TILE){
              this.tilt += hz.side * this.speed * 0.030 * (hz.lift/5) * dt * TILT_SENS;
              slabUnder = hz;
            }
          }
        } else if(hz.type === "hydrant" && hz.hjRole){
          /* course hydrant: hjSim owns the clearance test and the burst.
             Leaving the normal hydrant collision on would stop the robot
             dead at the first one instead of letting him fly over it. */
        } else if(hz.type === "hydrant"){
          /* cast iron: a wall, same contract as the palm — you stop.
             Arriving fast adds the bonk; past the burst threshold the
             nozzle shears: water arc + a flood that grows around the
             base and stays wet for the rest of the route. */
          if(onLane(hz.row) && this.botS > hz.s - 26 && this.botS < hz.s){
            this.botS = safeStop(hz.s - 26);
            this.isBlocked = true;
            if(this.speed > 0.08 && !hz.hit){
              hz.hit = true; this.tipCause = hz.type;
              const kick = this.speed * HYD_SLIP.bonk * (Math.random() < 0.5 ? 1 : -1);
              this.tilt += kick * TILT_SENS;
              this.damage = Math.min(95, this.damage + Math.abs(kick)*40*CARGO_DAMAGE_SENS);
              if(!hz.burst && this.speed >= HYD_SLIP.thresh){
                hz.burst = true; hz.burstT = t;
                /* the shear payoff: one-shot droplet eruption from the
                   broken nozzle (spillHydrantWater), simmed each frame
                   below alongside the flood. */
                hz.items = hz.items || [];
                this.spillHydrantWater(hz);
              }
            }
            this.speed = 0;
          }
          if(Math.abs(dx) > 40) hz.hit = false;
          /* the flood: wheels in the wet with speed -> hydroplane.
             Pre-burst floods sit a tile over (hz.pudDir), so the slick
             tests against the flood's REAL center — same s-offset the
             puddle draws at. */
          const slickS = hz.s + (hz.pudDir ? hz.pudDir * T2 : 0);
          const sdx = this.botS - slickS;
          /* water spreads off the curb — the flood shouldn't need the
             exact lane the hydrant itself sits in (onLane's T2*0.5 half-
             tile band). Widened to 1.5 tiles so the puddle also catches
             the adjacent lane; hydrants only ever spawn at row 0, and a
             player who isn't hugging the curb was never getting wet. */
          const inFlood = Math.abs(this.laneOff - laneOffset(hz.row)) < T2*1.5;
          if(hz.burst && !this.slide && !hz.slid){
            const grow = Math.min(1, (t - hz.burstT)/1800);
            if(inFlood && Math.abs(sdx) < HYD_SLIP.pud*grow && this.speed > 0.02){
              hz.slid = true;
              this.slide = { t0: t, dur: 800 + 300*HYD_SLIP.spin,
                             dir: Math.random() < 0.5 ? 1 : -1,
                             turns: HYD_SLIP.spin * (this.speed/0.05) };
              this.tilt += this.speed * 3 * (Math.random() < 0.5 ? 1 : -1) * TILT_SENS;
            }
          }
          if(Math.abs(sdx) > HYD_SLIP.pud + 40) hz.slid = false;
          this.simHydrantWater(hz, dt);
        } else if(hz.type === "cone"){
          /* not a wall — a light plastic prop. ONE integrator, no
             keyframes: gravity torque about the live pivot runs every
             frame while hz.moving (approved cone hit lab, 2026-07-09).
             The hit itself just adds angular + slide impulse; whether
             it clears the balance angle decides rock-back vs topple. */
          if(hz.moving){
            const KG = 1.5e-5 * CONE_HIT.grav;
            const steps = Math.max(1, Math.ceil(dt/8));
            const hdt = dt/steps;
            for(let i=0; i<steps; i++){
              hz.angVel += KG * Math.sin(hz.phi - CONE_HIT.phiBal) * hdt;
              hz.phi += hz.angVel * hdt;
              if(hz.phase === 1 && hz.phi >= Math.PI/2) hz.phase = 2;
              if(hz.phase === 2 && hz.phi < Math.PI/2) hz.phase = 1;
              if(hz.phi >= CONE_HIT.phiRest){
                hz.phi = CONE_HIT.phiRest;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "knocked"; break;
                }
                hz.angVel = -hz.angVel * 0.22;
              }
              if(hz.phi <= 0){
                hz.phi = 0; hz.phase = 1;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "standing"; break;
                }
                hz.angVel = -hz.angVel * 0.25;
              }
            }
          }
          if(hz.slideVel > 0.0001){
            hz.slide += hz.slideVel * dt;
            hz.slideVel *= Math.exp(-0.004 * dt);
          } else hz.slideVel = 0;

          /* one-shot per approach — same convention as every other
             hazard (hz.hit, re-armed once the robot is well clear).
             Uses the UNADJUSTED route distance (dx), not the
             slide-shifted position: gating re-arm on the slide would
             feed the punt back into re-triggering itself, stacking
             redundant tilt/damage on the robot for what should read
             as a single clean bonk. */
          if(!hz.hit && Math.abs(dx) < 26 && onLane(hz.row) && this.speed > 0.08){
            hz.hit = true; this.tipCause = hz.type;
            if(hz.fallPsi === undefined) hz.fallPsi = (Math.random() - 0.5) * 0.5;
            const sp = this.speed;
            if(hz.pose !== "knocked"){
              hz.moving = true;
              hz.angVel += sp * 0.06 * CONE_HIT.kick;
            }
            hz.slideVel += sp * 1.2 * CONE_HIT.punt;
            const kick = sp * 2.2 * (Math.random() < 0.5 ? 1 : -1);
            this.tilt += kick * TILT_SENS;
            this.damage = Math.min(95, this.damage + Math.abs(kick)*20*CARGO_DAMAGE_SENS);
            this.speed *= 0.86;
          }
          if(Math.abs(dx) > 40) hz.hit = false;
        } else if(hz.type === "bin"){
          /* the wall IS the bin (approved bin hit lab, 2026-07-09):
             a municipal bin is too big to plow through standing OR
             lying down — same cast-iron contract as the hydrant, but
             permanent. Restored to the hydrant's exact fixed-clearance
             trigger pattern: the dynamic binNearEdge-based creeping
             stop line stopped firing collision entirely at some point
             after the lane system was rebuilt (3-lane -> 4-lane band),
             and a static analysis pass couldn't isolate why without
             being able to run it live. This is simpler and uses the
             one pattern in this file proven to still work, even
             though it loses the stop line creeping forward as the
             bin topples. */
          /* clearance eases from 26 (standing — the lab-calibrated
             figure) down to 16 fully knocked: a lying barrel presents
             low and the standing clearance read as daylight between
             nose and barrel (on-device: "still a little too far
             back"). */
          const BOT_CLEAR = 26 - Math.min(1, (hz.phi || 0)/(Math.PI/2)) * 10;
          /* the wall tracks the BIN, not the anchor: binShiftAt gives
             the knocked footprint's real +s displacement (slide +
             topple reach), so after a shove the robot stops at the
             lying barrel instead of at the empty spot it left. */
          const binS = hz.s + binShiftAt(hz);
          if(onLane(hz.row) && this.botS > binS - BOT_CLEAR && this.botS < binS){
            this.botS = safeStop(binS - BOT_CLEAR);
            this.isBlocked = true;
            if(this.speed > 0.08 && !hz.bonked && hz.pose !== "knocked"){
              hz.bonked = true;
              if(hz.fallPsi === undefined) hz.fallPsi = (Math.random() - 0.5) * 0.5;
              const sp = this.speed;
              hz.moving = true;
              hz.angVel += sp * 0.06 * BIN_HIT.kick;
              hz.slideVel += sp * 0.6 * BIN_HIT.punt;   // a shove as it goes over, not a full punt
              const kick = sp * 2.6 * (Math.random() < 0.5 ? 1 : -1);
              this.tilt += kick * TILT_SENS;
              this.damage = Math.min(95, this.damage + Math.abs(kick)*40*CARGO_DAMAGE_SENS);
            }
            this.speed = 0;
          }
          if(Math.abs(this.botS - (hz.s + binShiftAt(hz))) > 40) hz.bonked = false;   // re-arm after backing off, measured from the MOVED footprint

          /* single-phase gravity pivot about the base rim — no slab
             handoff needed, a barrel just lies flat on its side */
          if(hz.moving){
            const KG = 1.5e-5 * BIN_HIT.grav;
            const steps = Math.max(1, Math.ceil(dt/8));
            const hdt = dt/steps;
            for(let i=0; i<steps; i++){
              hz.angVel += KG * Math.sin(hz.phi - BIN_HIT.phiBal) * hdt;
              hz.phi += hz.angVel * hdt;
              if(!hz.spilled && hz.phi >= BIN_HIT.phiBal){ hz.spilled = true; this.spillBinTrash(hz); }
              if(hz.phi >= BIN_HIT.phiRest){
                hz.phi = BIN_HIT.phiRest;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "knocked"; break;
                }
                hz.angVel = -hz.angVel * 0.2;
              }
              if(hz.phi <= 0){
                hz.phi = 0;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "standing"; break;
                }
                hz.angVel = -hz.angVel * 0.22;
              }
            }
          }
          if(hz.slideVel > 0.0001){
            hz.slide += hz.slideVel * dt;
            hz.slideVel *= Math.exp(-0.0045 * dt);
          } else hz.slideVel = 0;
          this.simBinTrash(hz, dt);
        } else if(hz.type === "robot"){
          /* another robot on the sidewalk (requested 2026-07-24;
             roving variant + full collision rework 2026-07-25). Three
             approach geometries, three outcomes:
               - REAR/HEAD-ON (approaching along the route, from
                 either direction -- both read the same to the player,
                 "I drove straight into it"): full speed -> BOTH tip
                 (same instant-fail as traffic for Tipsey; the other
                 robot goes down too and spills its cargo). Below full
                 speed -> Tipsey is just stuck against it, wall-blocked
                 like a bin/planter -- nobody tips, nothing spills.
               - SIDE (a lane-change/hop brings Tipsey alongside it):
                 the OTHER robot always tips, regardless of speed --
                 Tipsey never tips from a side hit and doesn't hard-
                 stop, just bumps through (you slid into it, you keep
                 going). Detected via this.hopAnim (mid lane-change)
                 while roughly alongside the robot's current position.
             Roving robots use their CURRENT walked position
             (robotSpotAt), not their spawn spot, same idea as people/
             dogs adjusting dx by their own wander offset. */
          const robotSpot = (hz.roving && !hz.knocked) ? robotSpotAt(t, hz) : null;
          const robotOff = robotSpot ? robotSpot.a : 0;
          /* detour lateral (see detourBAt): while sidestepping a prop
             the rover genuinely occupies the adjacent lane, so the
             lane test uses its EFFECTIVE offset (home laneOffset + b)
             -- hitbox follows art, the house rule. Captured as knockB
             on impact so the fallen shell stays where it was hit. */
          const robotB = robotSpot ? (robotSpot.b || 0) : 0;
          const onRobotLane = Math.abs(this.laneOff - (laneOffset(hz.row) + robotB)) < T2*0.5;
          const effS = hz.s + robotOff;
          /* contact at EXTERIOR FACES, not the midpoint (fixed
             2026-07-27): the old 28/30-unit windows measured to the
             robot's CENTER -- Tipsey's nose (his own half-length, 26)
             ended up 2 units from the robot's midpoint before a
             head-on registered, visually buried half-way inside it.
             Face-to-face gap = the robot's along-route half-extent +
             Tipsey's, using the same BODY dims the renderer draws:
             rovers lie long-axis along the route (hx=26), parked ones
             cross-ways (hy=20). Hitbox follows art, the house rule. */
          const robotHalfS = hz.roving ? BODY.hx : BODY.hy;
          const contactGap = robotHalfS + BODY.hx;
          if(!hz.knocked){
            const alongside = onRobotLane && Math.abs(this.botS - effS) < contactGap;
            const sideHit = this.hopAnim && alongside;
            if(sideHit && !hz.hit){
              hz.hit = true; this.tipCause = hz.type;
              hz.knocked = true;
              hz.knockA = robotOff;
              hz.knockB = robotB;
              hz.knockT = t;
              hz.knockRA = robotSpot ? robotSpot.dir : 1;   // freeze travel mirror (see draw RA)
              /* tip direction (2026-07-27, Tipsey's own tipDir=sign(tilt)
                 idea): a side hit is a shove across the LANE axis (rv),
                 so tip away from Tipsey's lane. Rovers' draw b-axis IS
                 rv, so the lane-space sign maps straight through.
                 Parked robots' b-axis is dv (they face across the
                 band) -- the rv impact can't map to their tip plane,
                 so random side, Tipsey's own convention when the axis
                 is ambiguous (his robot-collision tilt kick). */
              hz.knockDir = hz.roving
                ? (Math.sign((laneOffset(hz.row) + robotB) - this.laneOff) || 1)
                : (Math.random() < 0.5 ? 1 : -1);
              /* spill ~150ms into the fall, Tipsey's own tipT>0.55
                 moment, not at the instant of impact. One-shot timer
                 rather than a sim-loop gate: the post-play cargo
                 ticker is contractually side-effect-free, and a
                 head-on that tips BOTH robots ends play before the
                 in-play gate would ever fire. */
              setTimeout(() => this.spillRobotCargo(hz), 150);
              const kick = this.speed * 6 * (Math.random() < 0.5 ? 1 : -1);
              this.tilt += kick * TILT_SENS;
              this.damage = Math.min(95, this.damage + Math.abs(kick)*40*CARGO_DAMAGE_SENS);
              this.speed *= 0.7;   // bump-through, not a hard stop
            } else if(onRobotLane && this.botS > effS - contactGap && this.botS < effS){
              this.botS = safeStop(effS - contactGap);
              this.isBlocked = true;
              if(this.speed > ROBOT_HIT_MIN && !hz.hit){
                hz.hit = true; this.tipCause = hz.type;
                if(this.speed >= ROBOT_TIP_THRESH){
                  this.tilt = 1.1 * (Math.random() < 0.5 ? 1 : -1);
                  hz.knocked = true;
                  hz.knockA = robotOff;
                  hz.knockB = robotB;
                  hz.knockT = t;
                  hz.knockRA = robotSpot ? robotSpot.dir : 1;   // freeze travel mirror (see draw RA)
                  /* head-on: the shove is along the ROUTE axis (dv).
                     Parked robots' b-axis is dv, so they tip straight
                     away from the impact (sign of the approach --
                     always +s here since the stop-line clamp only
                     fires from behind, but computed anyway). Rovers'
                     b-axis is rv, perpendicular to the shove: random
                     side, same as Tipsey's own head-on tilt above. */
                  hz.knockDir = hz.roving
                    ? (Math.random() < 0.5 ? 1 : -1)
                    : (Math.sign(effS - this.botS) || 1);
                  setTimeout(() => this.spillRobotCargo(hz), 150);   // same 150ms fall-spill as the side hit
                }
                // below full speed: just stuck against it, no tip either way
              }
              this.speed = 0;
            }
            /* release hysteresis: must clear the face-gap stop line
               (gap+12), or a blocked Tipsey parked AT the line would
               re-arm hz.hit every frame. Was 40 back when the stop
               line was 28. */
            if(Math.abs(this.botS - effS) > contactGap + 12) hz.hit = false;
          } else {
            this.simRobotCargo(hz, dt);
          }
        } else if(hz.type === "planter"){
          /* approved in planter collision lab (2026-07-10) — see
             PLANTER_HIT for the constants. Below thresh: one hit
             topples it, never a wall (cone/bin-style, uses the same
             hz.hit/dx<26 convention every simple hazard here uses).
             At/above thresh: too heavy to plow through standing or
             lying down — bin's exact BOT_CLEAR contract, the one
             fixed-clearance pattern proven to still work in this
             file. Difference from bin: this box's balance angle
             (~55deg, much higher than bin's round base) doesn't
             reliably clear from one impulse at real gameplay speeds,
             and the robot can't back off and re-approach once it's
             clamped at the stop line — so the oversized case grinds
             against it every frame instead of a single hit. */
          const oversized = hz.scale >= PLANTER_HIT.thresh;
          const immovable = hz.scale >= PLANTER_HIT.largeMin;   // LARGE tier: pure wall, never moves
          const halfW = (PLANTER_BASE.boxW/2) * hz.scale;

          if(oversized){
            /* wall tracks the planter's ACTUAL current footprint span
               (planterSpanS): standing near edge is -halfW, a fore/aft
               fall extends the fallen side by the laid height+bush.
               Replaces the single knocked-edge clearance that was
               applied to the standing pose too and let the robot end
               up ON TOP of a standing planter before stopping
               (reported on-device 2026-07-26). A side-fallen planter
               (cross-axis fall, below) additionally blocks the lane
               it fell into (hz.spillRow) across the same ±halfW
               s-span, once it's laid past the balance angle. */
            const span = planterSpanS(hz);
            const wallLo = hz.s + span.lo, wallHi = hz.s + span.hi;
            const spillBlocks = hz.spillRow !== undefined && hz.spillRow !== null
                                && this.botRow === hz.spillRow && hz.phi > PLANTER_HIT.phiBal;
            if((onLane(hz.row) || spillBlocks) && this.botS > wallLo - BODY.hx && this.botS < wallHi + 20){
              const impactSp = this.speed;   // BEFORE the wall zeroes it — this is the hit energy
              this.botS = safeStop(wallLo - BODY.hx);
              this.isBlocked = true;
              this.speed = 0;
              if(hz.pose !== "knocked" && !hz.hit){
                hz.hit = true; this.tipCause = hz.type;
                /* bump feedback for the robot on any first contact,
                   scaled to how hard he actually hit (floor keeps a
                   creep-in touch from being completely free). */
                const kick = Math.max(impactSp, 0.05) * 1.6 * (Math.random() < 0.5 ? 1 : -1);
                this.tilt += kick * TILT_SENS;
                this.damage = Math.min(95, this.damage + Math.abs(kick)*40*CARGO_DAMAGE_SENS);
                if(!immovable){
                  /* MEDIUM tier only (2026-07-26): tips like the bin
                     — a real speed-scaled kick, so a solid hit sends
                     it over the balance angle and all the way down
                     (then planterSpanS keeps blocking the fallen
                     footprint), while a slow push just rocks it and
                     it settles back. LARGE (>= largeMin) skips this
                     whole block: immovable street furniture, no
                     fallPsi, no angVel, no motion, ever — which is
                     also what killed its wobble-blink at the source.

                     Fall direction: AWAY from the robot, always.
                     Cross-axis: a hit taken mid-lane-hop is a SIDE
                     impact — the planter falls ACROSS the lane band,
                     away from the row the robot hopped from. sin-sign
                     of ψ maps hop direction (row index) into the
                     local rv axis via ROBOT_SIDE (laneOffset's own
                     sign); spillRow is the lane the fallen box lands
                     in, null when it fell off the band (road/building
                     side). Driving hits keep the fore/aft pick. */
                  if(hz.fallPsi === undefined){
                    if(this.hopAnim){
                      hz.fallPsi = this.hopAnim.dir * ROBOT_SIDE * (Math.PI/2) + (Math.random()-0.5)*0.4;
                      const sr = hz.row + this.hopAnim.dir;
                      hz.spillRow = (sr >= 0 && sr <= 3) ? sr : null;
                    } else {
                      hz.fallPsi = (this.botS <= hz.s ? 0 : Math.PI) + (Math.random()-0.5)*0.4;
                    }
                  }
                  hz.moving = true;
                  hz.angVel += impactSp * 0.06 * PLANTER_HIT.kick / Math.pow(hz.scale, PLANTER_HIT.potPower);
                }
              }
            }
          } else if(!hz.hit && Math.abs(dx) < BODY.hx + halfW && onLane(hz.row) && this.speed > 0.08 && hz.pose !== "knocked"){
            hz.hit = true; this.tipCause = hz.type;
            /* contact distance scaled to the actual geometry (robot
               half-length + this planter's half-width) instead of the
               old fixed 26 -- the nose was half a robot deep before
               the topple fired (2026-07-26, same sync pass as the
               oversized wall above). Fall pick: same cross-axis rule
               as the oversized case -- side impact mid-hop falls
               across the lane band, driving hit falls fore/aft. */
            if(hz.fallPsi === undefined){
              if(this.hopAnim){
                hz.fallPsi = this.hopAnim.dir * ROBOT_SIDE * (Math.PI/2) + (Math.random()-0.5)*0.4;
                const sr = hz.row + this.hopAnim.dir;
                hz.spillRow = (sr >= 0 && sr <= 3) ? sr : null;
              } else {
                hz.fallPsi = (this.botS <= hz.s ? 0 : Math.PI) + (Math.random()-0.5)*0.4;   // away from the robot, like before
              }
            }
            const sp = this.speed;
            hz.moving = true;
            hz.angVel += sp * 0.09 * PLANTER_HIT.kick / Math.pow(hz.scale, PLANTER_HIT.potPower);
            /* the SHOVE — the bin's slide, the missing half of its
               knock feel: a light planter skids away from the impact
               as it topples (oversized stays planted: too heavy to
               shove, which is the point of oversized). */
            hz.slideVel = (hz.slideVel || 0) + sp * 0.45 / Math.pow(hz.scale, PLANTER_HIT.potPower);
            const kick = sp * 1.6 * (Math.random() < 0.5 ? 1 : -1);
            this.tilt += kick * TILT_SENS;
            this.damage = Math.min(95, this.damage + Math.abs(kick)*40*CARGO_DAMAGE_SENS);
            this.speed *= 0.9;
          }
          if(oversized){
            const span2 = planterSpanS(hz);
            if(this.botS < hz.s + span2.lo - 40 || this.botS > hz.s + span2.hi + 40) hz.hit = false;
          } else if(Math.abs(dx) > BODY.hx + halfW + 14) hz.hit = false;

          if(hz.moving){
            const KG = 1.5e-5;
            const steps = Math.max(1, Math.ceil(dt/8));
            const hdt = dt/steps;
            for(let i=0; i<steps; i++){
              hz.angVel += KG * Math.sin(hz.phi - PLANTER_HIT.phiBal) * hdt;
              hz.phi += hz.angVel * hdt;
              if(!hz.spilled && hz.phi >= PLANTER_HIT.phiBal){ hz.spilled = true; this.spillPlanterLeaves(hz); }
              if(hz.phi >= PLANTER_HIT.phiRest){
                hz.phi = PLANTER_HIT.phiRest;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "knocked"; break;
                }
                hz.angVel = -hz.angVel * 0.18;
              }
              if(hz.phi <= 0){
                hz.phi = 0;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "standing"; break;
                }
                hz.angVel = -hz.angVel * 0.3;
              }
            }
          }
          if(hz.slideVel > 0.0001){
            hz.slide = (hz.slide || 0) + hz.slideVel * dt;
            hz.slideVel *= Math.exp(-0.0045 * dt);   // bin's exact skid decay
          } else hz.slideVel = 0;
          this.simPlanterLeaves(hz, dt);
        } else if(hz.type === "scooter"){
          /* soft hazard, same contract as before (sev 9, 55% speed
             loss) — this doesn't change. What's new: a standing
             scooter now actually topples via a real fall integrator
             (approved scooter hit lab, 2026-07-09) instead of the
             pose being a fixed coin-flip at spawn. One-shot hit
             using the UNADJUSTED route distance — the same fix the
             cone needed, since gating re-arm on the slide feeds the
             punt back into re-triggering itself. */
          if(!hz.hit && Math.abs(dx) < 26 && onLane(hz.row)){
            hz.hit = true; this.tipCause = hz.type;
            if(hz.fallPsi === undefined) hz.fallPsi = (Math.random() - 0.5) * 0.6;
            const sp = this.speed;
            if(hz.pose !== "knocked"){
              hz.moving = true;
              hz.angVel += sp * 0.06 * SCOOT_HIT.kick;
            }
            hz.slideVel += sp * 1.2 * SCOOT_HIT.punt;
            const kick = sp * 9 * (Math.random() < 0.5 ? 1 : -1);
            this.tilt += kick * TILT_SENS;
            this.damage = Math.min(95, this.damage + Math.abs(kick)*46*CARGO_DAMAGE_SENS);
            this.speed *= 0.45;
          }
          if(Math.abs(dx) > 40) hz.hit = false;

          if(hz.moving){
            const KG = 1.5e-5 * SCOOT_HIT.grav;
            const steps = Math.max(1, Math.ceil(dt/8));
            const hdt = dt/steps;
            for(let i=0; i<steps; i++){
              hz.angVel += KG * Math.sin(hz.phi - SCOOT_HIT.phiBal) * hdt;
              hz.phi += hz.angVel * hdt;
              if(hz.phi >= SCOOT_HIT.phiRest){
                hz.phi = SCOOT_HIT.phiRest;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "knocked"; break;
                }
                hz.angVel = -hz.angVel * 0.18;
              }
              if(hz.phi <= 0){
                hz.phi = 0;
                if(Math.abs(hz.angVel) < 0.0006){
                  hz.angVel = 0; hz.moving = false; hz.pose = "standing"; break;
                }
                hz.angVel = -hz.angVel * 0.2;
              }
            }
          }
          if(hz.slideVel > 0.0001){
            hz.slide += hz.slideVel * dt;
            hz.slideVel *= Math.exp(-0.004 * dt);
          } else hz.slideVel = 0;
        } else if(!hz.hit && Math.abs(dx) < 26 &&
                  Math.abs(this.laneOff - (laneOffset(hz.row) + hzB)) < T2*0.5){
          hz.hit = true; this.tipCause = hz.type;
          const sev = hz.type === "crack"
            ? Math.min(8, Math.max(2, 4 * (hz.len || 46) / 46))   // bigger spall, bigger jolt (crack lab v3)
            : ({ trash:7, dog:5, palmDwarf:6, people:8 }[hz.type] ?? 5);   // hitting a person costs more than a dog bump — same mechanism that tips you on a hard palm/hydrant hit applies here too
          const kick = this.speed * sev * (Math.random() < 0.5 ? 1 : -1);
          this.tilt += kick * TILT_SENS;
          this.damage = Math.min(95, this.damage + Math.abs(kick)*46*CARGO_DAMAGE_SENS);
          if(hz.type === "trash") this.speed *= 0.65;
          if(hz.type === "palmDwarf") this.speed *= 0.5;   // dragging through fronds
          if(hz.type === "dog"){
            /* the dog reacts: remember when, and which way he bolts —
               along the route away from the robot, sideways at random */
            hz.hitT = t;
            hz.fleeA = dx >= 0 ? -1 : 1;
            hz.fleeB = Math.random() < 0.5 ? 1 : -1;
          }
          if(hz.type === "people"){
            /* same reaction as the dog: bolt away from the robot,
               toward the buildings, sideways at random */
            hz.hitT = t;
            hz.fleeA = dx >= 0 ? -1 : 1;
            hz.fleeB = Math.random() < 0.5 ? 1 : -1;
          }
        }
      }

      /* wedge underfoot: the wheels ride the slab's mid-height and its
         actual surface angle — smoothed so entering/leaving the lip
         reads as a climb, not a teleport */
      this.slabZ = Phaser.Math.Linear(this.slabZ || 0, slabUnder ? slabUnder.lift*0.5 : 0, 0.25);
      this.slabRoll = Phaser.Math.Linear(this.slabRoll || 0,
        slabUnder ? slabUnder.side * Math.atan(slabUnder.lift/(2*TILE)) : 0, 0.2);

      /* ---------- street-crossing curb ramps ----------
         Physics ported from labs/sidewalkend-lab.html (constants
         verbatim: 0.055 cross-slope coefficient, 0.35 curb-drop kick,
         0.55 already-leaning threshold, 0.85 post-kick tip line, ±0.05
         pad jitter). Everything routes through the game's OWN machinery
         instead of the lab's local copies: isBlocked feeds the existing
         stuckAmt rattle + "?!" bubble, and a tip hands the robot to the
         existing |tilt|>=1 pipeline (same pattern as the traffic hit)
         rather than setting state="tipped" from a second place.
         The row used everywhere is the VISUAL row (nearest laneOff),
         same reasoning as onLane() in the hazard loop: botRow flips the
         instant hop() is called, but the robot takes 480ms to actually
         arrive — the ground under him is where he IS. */
      const _vRow = [0,1,2,3].reduce((b,r) =>
        Math.abs(this.laneOff - laneOffset(r)) < Math.abs(this.laneOff - laneOffset(b)) ? r : b, 0);
      let _cg = crossingGroundAt(this.route.crossings, this.botS, _vRow);
      /* far-curb wall for the no-ramp lanes: clamp forward motion right
         at the boundary (lab clamped at boundary-1 too), then re-sample
         the ground from the corrected position so z/tilt never read a
         spot the robot was just pushed back from. Only ever shortens
         THIS frame's own advance — can't violate the safeStop floor. */
      if(_cg && _cg.wallS !== null && this.botS >= _cg.wallS - 1 && this.botS > _botS_frameStart){
        this.botS = Math.max(_cg.wallS - 1, _botS_frameStart);
        this.isBlocked = true;
        _cg = crossingGroundAt(this.route.crossings, this.botS, _vRow);
      }
      /* turn crossings (world-space model — see turnCrossingGroundAt):
         gated by the arc span's route-s range, then everything keys off
         the robot's actual world position, because the ramps sit at the
         true curb lines and his arc crosses them diagonally. The wall
         here is the generalized climb rule: he can DROP any height and
         can mount the ramp's 2-unit rear lip, but cannot climb a real
         curb face (3 or 5 units) — blocking clamps this frame's own
         advance only, then re-samples, same discipline as the straight
         wall above. */
      let _tg = null;
      if(!_cg){
        for(const cx of this.route.crossings){
          if(cx.kind !== "turn") continue;
          if(this.botS < cx.sA - 3*T2 || this.botS > cx.sB + 3*T2) continue;
          const wp0 = segsWorldOf(this.route.segs, this.botS, this.laneOff);
          _tg = turnCrossingGroundAt(cx, wp0.x, wp0.y, this.route.grid.classify, _vRow);
          if(_tg.z - (this.crossZ || 0) > 2.5 && this.botS > _botS_frameStart){
            this.botS = _botS_frameStart;
            this.isBlocked = true;
            const wp1 = segsWorldOf(this.route.segs, this.botS, this.laneOff);
            _tg = turnCrossingGroundAt(cx, wp1.x, wp1.y, this.route.grid.classify, _vRow);
          }
          break;
        }
      }
      const _prevCrossZ = this.crossZ || 0;
      if(_cg){
        this.crossZ = _cg.z;
        this.crossSlope = _cg.slope;
        /* truncated-dome rumble crossing the yellow pad — roll-only,
           layered on at the roll composition line below, never folded
           into this.tilt, so it can't push toward a tip or outlive the
           pad (lab: jitterRoll = (rand-0.5)*0.1, center lane only). */
        this.crossJitter = _cg.onPad ? (Math.random()-0.5) * 0.1 : 0;
        /* cross-slope lean off the ramp's flared sides — mirrored sign in
           the two lanes flanking the ramp strip, zero on the strip and on
           row 3 (lab: tilt += botRow * speed * 0.055 * dt) */
        if(_cg.tiltSign) this.tilt += _cg.tiltSign * this.speed * 0.055 * dt * TILT_SENS;
        /* curb drop: falling off the unramped edge in any non-ramp lane.
           A stumble kick in the direction you were already leaning (or
           away from the ramp strip if upright); if you were ALREADY
           leaning hard, or the kick lands you past the lab's 0.85 line,
           push tilt to 1.1 and let the game's own tip pipeline take it. */
        if(_vRow !== CROSSING_RAMP_ROW && _prevCrossZ - this.crossZ > 1){
          const _wasLeaning = Math.abs(this.tilt) > 0.55;
          this.tilt += Math.sign(this.tilt || (2 - _vRow) || 1) * 0.35;   // (2 - row): same axis mirror as tiltSign
          if(_wasLeaning || Math.abs(this.tilt) > 0.85)
            this.tilt = CURB_DROP_TILT_CAP * Math.sign(this.tilt);
        }
      } else if(_tg){
        this.crossZ = _tg.z;
        /* pitch along TRAVEL: the surface gradient is axis-aligned (old
           heading on the down slope, new on the up) but the robot's
           heading rotates through the arc — project the gradient onto
           his actual travel direction. */
        const _hdg = segsHeadingAt(this.route.segs, this.botS);
        this.crossSlope = _tg.gx*Math.cos(_hdg) + _tg.gy*Math.sin(_hdg);
        this.crossJitter = _tg.onPad ? (Math.random()-0.5) * 0.1 : 0;
        /* cross-slope lean off the down-ramp's flared side, rows 0/2
           only — same mirrored (1-row) tiltSign the straight model
           uses, now actually wired up here too (previously computed by
           turnCrossingGroundAt's row split but never read). Own rate,
           NOT the straight model's 0.055: this crossing sits on top of
           the arc segment (TURN_R aligned them by construction), so a
           flanking lane is already picking up the arc's own centrifugal
           cornering tilt at the same time — whichever lane's flank sign
           matches the turn's own direction gets both added together.
           Straight crossings never have that second force, so 0.055
           was tuned for fighting alone; halved-ish here so the two
           stacking doesn't tip him before he reaches the curb. Tune
           further after playtesting like everything else in this file. */
        if(_tg.tiltSign) this.tilt += _tg.tiltSign * this.speed * 0.03 * dt * TILT_SENS;
        /* curb drop off an unramped edge — same lab kick/tip handoff.
           Threshold 2.5, NOT the straight model's 1: on turns every
           lane exits the up-ramp over its 2-unit rear lip (verified in
           the per-lane trace), and only the real curb faces (3-unit
           plain-walk curb, 5-unit prop curb) should stumble. Rows 0/2
           now get their own flank tilt above (turnCrossingGroundAt's
           row split), so the upright fallback direction here still
           just falls back to the current lean or +. */
        if(_prevCrossZ - this.crossZ > 2.5){
          const _wasLeaning = Math.abs(this.tilt) > 0.55;
          this.tilt += Math.sign(this.tilt || 1) * 0.35;
          if(_wasLeaning || Math.abs(this.tilt) > 0.85)
            this.tilt = CURB_DROP_TILT_CAP * Math.sign(this.tilt);
        }
      } else {
        this.crossZ = 0; this.crossSlope = 0; this.crossJitter = 0;
      }

      /* hydroplane: eased pirouette from a burst hydrant's flood.
         slipYaw layers into the facing yaw; when the slide ends,
         Grip unwinds it the short way back to straight. */
      if(this.slide){
        const su = (t - this.slide.t0)/this.slide.dur;
        if(su >= 1){ this.slide = null; }
        else {
          const se = su < 0.5 ? 2*su*su : 1 - Math.pow(-2*su + 2, 2)/2;
          this.slipYaw = this.slide.dir * Math.PI*2 * this.slide.turns * se;
          this.speed *= (1 - 0.0006*dt);
          this.tilt += (Math.random()-0.5) * this.speed * 0.05 * dt * TILT_SENS;
        }
      } else if(this.slipYaw){
        let y2 = this.slipYaw % (Math.PI*2);
        if(y2 > Math.PI) y2 -= Math.PI*2;
        if(y2 < -Math.PI) y2 += Math.PI*2;
        const step = HYD_SLIP.grip * 0.012 * dt;
        this.slipYaw = Math.abs(y2) <= step ? 0 : y2 - Math.sign(y2)*step;
      }

      /* stuck on a trunk: wheels churn, robot rattles, dignity evaporates */
      const stuckTarget = (this.isBlocked && this.throttle === 1) ? 1 : 0;
      this.stuckAmt = Phaser.Math.Linear(this.stuckAmt, stuckTarget, stuckTarget ? 0.12 : 0.1);
      if(this.stuckAmt > 0.05)
        this.wheelPhase += dt * 0.02 * this.stuckAmt * (Math.random() > 0.5 ? 1 : -1);

      /* stability spring + rough-pavement rumble */
      this.tilt -= this.tilt * 0.0021 * dt;
      this.tilt += (Math.random()-0.5) * this.speed * (1-this.route.hood.pave) * 0.012 * dt * TILT_SENS;

      /* cargo damage meter (spec, red-zone dwell): riding past the same
         0.75 danger line the HUD gauge and lid-crack already key off
         bleeds cargo damage continuously, not just on impact — a near-
         tip you HOLD costs more than one you snap out of. Unlike a
         hazard kick this is dt-scaled (per second, not per hit), and
         still respects the same 95 cap every other damage source uses. */
      if(Math.abs(this.tilt) > 0.75)
        this.damage = Math.min(95, this.damage + DAMAGE_REDZONE_DPS * dt/1000);

      /* traffic collision: unlike the other hazards above, this isn't
         gated on the robot's own speed -- a moving car can hit a robot
         that's standing still, not just the other way around. Position
         comes from trafficWorldAt, the exact same pure function the
         renderer uses, so the hitbox always matches what's on screen
         (same principle as dogSpotAt/dogFleeAt). A hit forces a full
         tip rather than a partial tilt kick like the cone -- getting
         hit by a car should always tip the robot, not just sometimes --
         by pushing tilt straight past the existing |tilt|>=1 threshold
         below, reusing all of that machinery instead of duplicating it. */
      /* two test points per vehicle now, not one: the old single
         center-point circle (r=70) let half a 225-unit-long car pass
         visually THROUGH the robot before the hit registered — the
         bumper reached him ~112 units before the center did. The NOSE
         point sits at the drawn front (center + DIRV of the same
         quantized facing the renderer uses, so hitbox matches art in
         all 4 headings), with a tighter radius sized to bumper-meets-
         robot; the center point keeps side impacts honest. Tilt sign
         still pushes away from the car's CENTER. */
      const CAR_HIT_CENTER_R = 60, CAR_HIT_NOSE_R = 50;
      for(const tr of this.route.traffic){
        const { wp, fc } = trafficWorldAt(tr, t);
        /* continuous heading, matching the renderer exactly. With the
           quantized facing the nose point jumped to the wrong corner of
           the car mid-turn, so the hitbox left the art precisely where
           a car is most likely to clip the robot. */
        const nth = fc * (Math.PI/2);
        const nx = wp.x + Math.cos(nth)*CARC.len*0.45, ny = wp.y + Math.sin(nth)*CARC.len*0.45;
        const ddx = this.botX - wp.x, ddy = this.botY - wp.y;
        const cSq = ddx*ddx + ddy*ddy;
        const nnx = this.botX - nx, nny = this.botY - ny;
        const nSq = nnx*nnx + nny*nny;
        if(!tr.hit && (cSq < CAR_HIT_CENTER_R*CAR_HIT_CENTER_R || nSq < CAR_HIT_NOSE_R*CAR_HIT_NOSE_R)){
          tr.hit = true; this.tipCause = "car";
          this.tilt = 1.1 * (Math.sign(ddx || ddy) || 1);
          this.damage = Math.min(95, this.damage + 45);
        }
        if(cSq > (CAR_HIT_CENTER_R*4)*(CAR_HIT_CENTER_R*4)) tr.hit = false;
      }

      /* back near upright: whatever knocked us sideways did not finish
         the job, so it no longer owns the fail copy. */
      if(Math.abs(this.tilt) < 0.15) this.tipCause = null;

      /* fail: we are horizontal */
      if(Math.abs(this.tilt) >= 1){
        this.state = "tipped";
        this.tipDir = Math.sign(this.tilt);
        /* cargo damage meter: a crash always fully ruins the goods,
           independent of whatever the accumulated damage number
           happened to be. Without this, a single fatal hit early in an
           otherwise-clean run could tip the robot while the bar was
           still green -- the crash itself IS the worst thing that can
           happen to the cargo, so it should always read that way. */
        this.damage = 95;
        this.tipStartRoll = this.roll;   // whatever lean we actually had the instant
                                          // we tipped — the fall animation eases FROM
                                          // this, not from an implicit flat start
        this.speed = 0;
        /* the lid's hinge rotation compounds with whatever yaw/pitch is
           still active when we go over — mid-turn yaw was only ever
           eased toward 0 (not reset), and pitch from hill slope was
           never reset at all (frozen at its last pre-tip value, forever).
           Compounded with the hinge's own rotation this is what twisted
           the lid. The sprite-lab reference this was built from has no
           yaw/pitch concept at all, which is why it never showed this -
           zeroing both the instant we tip matches that. */
        this.yaw = 0;
        /* ...but the challenge's FACE PLANT is a deliberate pitch-over,
           so zeroing here would flatten it back out every frame. */
        if(!this.hjFace) this.pitch = 0;
        /* same family as the yaw/pitch zeroing above: mid-turn tips
           freeze whatever non-quarter drawAngle the facing ease was
           blending through, and every tipped-pose face-visibility test
           (n·(1,1,1), mounting-face wheels, lid hinge planes) is only
           verified at quarters — headless renders of the exact draw
           math reproduce the broken panels at 2.0/2.7/3pi/4 rad and
           render clean at all 8 quarter x tip-direction combos. Snap
           to the nearest quarter the instant we go over; the ease is
           gated off while tipped so this holds. The 45-degree-max pop
           reads as impact chaos. */
        this.drawAngle = Math.round(this.drawAngle / (Math.PI/2)) * (Math.PI/2);
        /* the challenge resets the run itself (hjPendingReset); the
           delivery fail overlay would take over the screen and its
           Retry reloads the daily route. */
        const failPool = this.tipCause === "william" ? WILLIAM_FAIL_LINES : null;
        if(this.attractOwnsTip()){ this.attractRecycle(); }
        else if(this.slOwnsTip()){ this._slAPI.crash(this.tipCause); }
        else if(!this.hjOwnsTip()){ reportFail(this, this.tipCause); setTimeout(() => showFail(failPool), 1500); }
      }
      /* CANCELLATION: par + grace expired -> the order dies. A fail
         with the robot upright: the state gate stops the sim, input
         goes dead, fail overlay with the cancel pool. No payout, no
         daily-best entry — a canceled order never happened. */
      if(this.runT > this.route.parMs + CANCEL_GRACE_MS){
        this.state = "canceled";
        this.speed = 0; this.throttle = 0;
        if(this.attractOwnsTip()){ this.attractRecycle(); return; }
        reportFail(this, "canceled");
        setTimeout(() => showFail(CANCEL_LINES), 900);
        return;
      }
      /* win: at the door, slow, upright */
      const remain = this.route.doorS - this.botS;
      if(remain < 34 && remain > -60 && this.speed < 0.02 && Math.abs(this.tilt) < 0.5){
        this.state = "won";
        if(this.attractOwnsTip()) this.attractRecycle(ATTRACT_WIN_MS);
        else showWin(this);
      }
      /* overshot the door: clamp to whichever is closer — the edge of the
         win window itself (doorS+60, matching the "remain > -60" bound
         above) or the true route end. Previously this was anchored to
         totalLen alone, which is fine on the ~90-unit-gap days but on
         routes where doorS lands far short of totalLen (confirmed up to
         54,600 units short on ~47% of tested days — findGoodS() correctly
         finds the nearest buildable straight leg, but the walked route's
         tail can genuinely have none nearby), the player would sail
         through a dead zone with no win trigger and no clamp until
         hitting totalLen-30, sometimes tens of thousands of units later —
         reading as "win doesn't fire" rather than a clear, immediate stop
         at the address. */
      /* With a reroute loop welded in (route.loop, built at spawn) the
         clamp never engages — the street simply continues into the lap.
         The clamp remains ONLY as the no-loop fallback (rare grid-corner
         days with no road ring around the address), and its old
         tilt+=0.5 shove is gone: touching the end of the road stops the
         robot, it doesn't knock him over. */
      if(!this.route.loop){
        const overshootLimit = Math.min(this.route.doorS + 60, this.route.totalLen - 30);
        if(this.botS > overshootLimit){
          this.botS = overshootLimit; this.speed = 0;
        }
      }
      if(this.botS < _botS_frameStart - 0.01){
        console.warn(`[BACKWARD] botS ${_botS_frameStart.toFixed(1)} -> ${this.botS.toFixed(1)} (Δ${(this.botS-_botS_frameStart).toFixed(1)}) botRow=${this.botRow} isBlocked=${this.isBlocked} segType=${this.segAt(this.botS).type}`);
      }
      /* GPS reroute: past the win window and into the lap's entry
         corner means the first pass is MISSED — retarget doorS to its
         next-lap occurrence (the lap is periodic: world(s+len) ===
         world(s), so doorS0+len IS the same physical door). At the
         weld point wrap botS back one period — identical world position
         and heading, invisible to the player, loops forever until the
         par+grace cancel fires. Placed AFTER the backward-warn so the
         wrap's negative Δ never trips it. */
      const lp = this.route.loop;
      if(lp){
        if(!lp.missed && this.botS > lp.sCut - 20){
          lp.missed = true;
          this.route.doorS = lp.doorS0 + lp.len;
        }
        if(this.botS >= lp.sEnd) this.botS -= lp.len;
      }
    }

    /* cosmetic particle sims keep ticking after play ends (reported
       on-device 2026-07-27, "the puddle splash particles didn't
       land"): the whole hazard sim loop above is play-gated, and a
       hydrant's droplet eruption usually coincides with the very tip
       that ENDS play -- bursting requires arriving at/above
       HYD_SLIP.thresh, and that same bonk + hydroplane spin is what
       tips you -- so the freshly-erupted droplets froze mid-air over
       the tipped screen while the world kept drawing. Same class for
       a knocked rover's cargo, bin trash, or planter leaves still
       airborne at the tip/win moment. All four sims are pure item
       integrators (no gameplay writes -- verified before adding
       this), so ticking them outside play is side-effect-free; the
       items-empty early-out makes the extra pass free on routes with
       nothing airborne. */
    if(this.route && this.state !== "play"){
      for(const hz of this.route.hazards){
        if(!hz.items || !hz.items.length) continue;
        if(hz.type === "hydrant") this.simHydrantWater(hz, dt);
        else if(hz.type === "bin") this.simBinTrash(hz, dt);
        else if(hz.type === "planter") this.simPlanterLeaves(hz, dt);
        else if(hz.type === "robot") this.simRobotCargo(hz, dt);
      }
    }

    /* tipped: roll over + spill (the sprite-lab pratfall) */
    if(this.state !== "play") this.yaw = Phaser.Math.Linear(this.yaw, 0, 0.15);
    if(this.state === "tipped"){
      this.tipT = Phaser.Math.Linear(this.tipT, 1, 0.09);
      /* no cargo in the challenge, so nothing to spill */
      if(this.tipT > 0.55 && !this.spilled && !this.hjOwnsTip()) this.spillCargo();
      /* lid behavior genuinely differs by tip direction now that the
         hinge is a fixed edge (not mirrored) — gravity swings it back
         shut on one side, holds it open on the other. This is NOT the
         same animation mirrored, it's two different physical outcomes.
         tipDir<0: pops open to spill, holds ~400ms, flops back closed.
         tipDir>=0: opens and stays open (original behavior). Confirmed
         in-game 2026-07-10 — first guess had this backwards. */
      if(this.tipDir < 0){
        if(this.spilled) this.postSpillMs = (this.postSpillMs || 0) + dt;
        const closing = this.spilled && this.postSpillMs > 400;
        const lidOpenTarget = this.tipT > 0.5 ? 0.9 : 0;
        this.lidAng = closing
          ? Phaser.Math.Linear(this.lidAng, 0, 0.05)
          : Phaser.Math.Linear(this.lidAng, Math.max(this.lidAng, lidOpenTarget), 0.05);
      } else {
        this.lidAng = Phaser.Math.Linear(this.lidAng, Math.max(this.lidAng, this.tipT > 0.5 ? 1.78 : 0), 0.05);
      }
      /* the face plant is a PITCH-over and owns the pose itself; letting
         the sideways roll run as well is why it never showed. */
      if(!this.hjFace)
        this.roll = Phaser.Math.Linear(this.tipStartRoll, this.tipDir * (Math.PI*0.5), this.tipT);
    } else {
      this.roll = Phaser.Math.Clamp(this.tilt, -1, 1) * 0.5 + this.cornerLean + (this.slabRoll || 0) + (this.crossJitter || 0);
    }
    this.simItems(dt);

    /* world pose from the path: position + lane, eased continuous heading */
    const hdg = this.headingAt(this.botS);
    const pp = this.posAt(this.botS);
    const rvx = -Math.sin(hdg), rvy = Math.cos(hdg);       // right of travel
    this.botX = pp.x + rvx*this.laneOff;
    this.botY = pp.y + rvy*this.laneOff;
    const fi = Math.round(hdg / (Math.PI/2));
    this.f = ((fi % 4) + 4) % 4;   // kept for hazard/HUD logic only — not used for drawing anymore
    /* unwrap: headingAt() can report the same physical direction with a
       different numeric value depending which segment it's reading from
       (an exit leg computes its heading as f*90° in canonical [0,2pi),
       while the arc feeding into it may have swept into negative
       numbers) — at certain facing wraps those two representations land
       a full 2pi apart even though they mean the same heading. Bring the
       target to whichever representation is closest to where drawAngle
       already is before easing toward it, instead of chasing a fake
       360° jump. (Full derivation + verification: corner+robot lab.) */
    let _targetAngle = hdg;
    while(_targetAngle - this.drawAngle >  Math.PI) _targetAngle -= Math.PI*2;
    while(_targetAngle - this.drawAngle < -Math.PI) _targetAngle += Math.PI*2;
    if(this.state !== "tipped") this.drawAngle = Phaser.Math.Linear(this.drawAngle, _targetAngle, 0.12);   // tipped: hold the quarter snap (see the tip transition)
    this.yaw = this.hopYaw + (this.slipYaw || 0);

    /* stuck jitter rattles the whole body */
    if(this.stuckAmt > 0.05){
      this.botX += (Math.random()-0.5) * 2.6 * this.stuckAmt;
      this.botY += (Math.random()-0.5) * 1.4 * this.stuckAmt;
    }

    /* the jump is an ADDITIONAL term on the game's own ground stack, not
       a parallel simulation — so slopes, slabs and cross-slope all still
       apply underneath the arc. */
    this.botZ = this.groundZ(this.botS) + (this.slabZ || 0) + (this.crossZ || 0)
              + (this.hjAir ? this.hjAir.z : 0)
              + (this.hjAir ? 0 : this.hjSlabZ(this.botS));   // hjAir.z already carries it
    /* MAX_GRADE: hard ceiling at a real 5% grade (atan(0.05) ≈ 2.86°),
       on top of the HILL_AMP retune above — the retune sets the typical
       feel per neighborhood, this guarantees no unlucky noise seed ever
       exceeds the stated max regardless. */
    const MAX_GRADE = 0.05;
    /* Ground-slope pitch, every frame — but NOT while airborne in the
       challenge, where the nose follows the velocity vector instead.
       This line was silently flattening the whole arc attitude. */
    if(this.state !== "tipped" && !this.hjAir)
      /* SIGN, settled 2026-08-03. Both slope sources are POSITIVE-UPHILL:
         groundSlope() reads elevAt ahead minus behind, and the crossing ramp
         tiles above set slope = drop/T2 with drop negative on the descending
         side. And negative pitch is NOSE-DOWN — the face plant drives pitch
         toward -(PI/2) pivoting on BODY.hx, the front face, and T() maps a nose
         point to z = x*sin(pitch) + z*cos(pitch), which sinks x>0 when pitch<0.
         So the old leading minus pitched the robot nose-UP on a descent and
         nose-DOWN on a climb: exactly backwards, on the hill grade and on every
         curb ramp alike. The ramp drop was small enough to pass as noise; a
         Bluffs downhill is not, and it read as a climb on-device. */
      this.pitch = Math.atan(Phaser.Math.Clamp(this.groundSlope(this.botS) + (this.crossSlope || 0), -MAX_GRADE, MAX_GRADE));

    /* camera reframe: at f=3 the worker/customer's walk-out direction
       pushes them far enough sideways on screen that tracking only the
       robot leaves them off-frame (confirmed: 227px past a 430px-wide
       screen's left edge while the robot sat centered). Widen the
       target to a blend of door + bot + their far position + raised-
       hand reach whenever they're actually visible. */
    let camTargetX = this.botX + Math.cos(hdg)*95;
    let camTargetY = this.botY + Math.sin(hdg)*95;
    let camTargetZ = this.botZ;

    /* doorSwing used to be checked here too, but it never added
       anything on the opening side (the door's target already flips
       open the same instant pickupWalk starts at 1) -- its only real
       effect was keeping this true during the door's own lingering
       close after the worker had already finished walking back,
       which is what held the camera on an empty doorway. The door
       still closes exactly the same as before; the camera just stops
       waiting on it. */
    /* The camera lets go the moment the bag DROPS into the bay
       (pickupLoadFrac reaching dropFrac -- ~490ms in), not a quarter
       into the walk-back like before: the player can gun it the
       instant the order is aboard, and the worker's whole walk plays
       out behind them as scenery. pickupLoadFrac is assigned earlier
       in this same update pass, so it is always this frame's value.
       Challenge mode has no worker and never holds. */
    const pickupWorkerVisible = this.mode !== "challenge" &&
      (this.pickupLoadFrac || 0) < LOAD_ART.dropFrac;
    if(this.state === "play" && this.pickupDoorDV && pickupWorkerVisible){
      const dv3 = this.pickupDoorDV, rv3 = this.pickupDoorRV;
      const doorX3 = this.pickupDoorUX + dv3.x*this.pickupDoorCenterX, doorY3 = this.pickupDoorUY + dv3.y*this.pickupDoorCenterX;
      /* the worker's far spot is the MEET beside the robot now, and his
         facing follows the true door->robot approach — mirrors the won
         branch below. */
      let workerFarX = doorX3 + rv3.x*(T2*2.1-50), workerFarY = doorY3 + rv3.y*(T2*2.1-50);
      let facingRobot = Math.atan2(rv3.y, rv3.x) - Math.PI/2;
      if(this.route.pickupSpot){
        let cvx = this.route.pickupSpot.x - doorX3, cvy = this.route.pickupSpot.y - doorY3;
        const cd = Math.hypot(cvx, cvy) || 1; cvx /= cd; cvy /= cd;
        workerFarX = this.route.pickupSpot.x - cvx*12;
        workerFarY = this.route.pickupSpot.y - cvy*12;
        facingRobot = Math.atan2(cvy, cvx) - Math.PI/2;
      }
      const wBuild2 = PEOPLE_BUILD[mulberry32(this.pickupWorkerSeed)() < 0.5 ? 0 : 1];
      const armReach2 = this.handWorldPos(workerFarX, workerFarY, facingRobot, wBuild2, 1);
      camTargetX = (doorX3 + this.botX + workerFarX + armReach2.x) / 4;
      camTargetY = (doorY3 + this.botY + workerFarY + armReach2.y) / 4;
      camTargetZ = (0 + 0 + 0 + armReach2.z) / 4;
    } else if(this.state === "won" && this.addrDoorDV){
      const dv2 = this.addrDoorDV, rv2 = this.addrDoorRV;
      const doorX = this.addrDoorUX + dv2.x*this.addrDoorCenterX, doorY = this.addrDoorUY + dv2.y*this.addrDoorCenterX;
      /* frame the REAL meet point (the customer walks to the robot
         now), falling back to the old mat-edge spot for the first
         frames before the won timeline has computed it. */
      const custFarX = this.wonMeet ? this.wonMeet.x : doorX + rv2.x*(T2-8);
      const custFarY = this.wonMeet ? this.wonMeet.y : doorY + rv2.y*(T2-8);
      const thW2 = this.wonMeet ? this.wonMeetTh : Math.atan2(rv2.y, rv2.x) - Math.PI/2;
      const cBuild2 = PEOPLE_BUILD[mulberry32(this.addrCustSeed)() < 0.5 ? 0 : 1];
      const armReach = this.handWorldPos(custFarX, custFarY, thW2, cBuild2, 1);
      camTargetX = (doorX + this.botX + custFarX + armReach.x) / 4;
      camTargetY = (doorY + this.botY + custFarY + armReach.y) / 4;
      camTargetZ = (0 + 0 + 0 + armReach.z) / 4;
    } else if(this.state === "tipped"){
      /* the default target above leads the robot by 95 units along
         the route heading -- meant to bias the view toward what's
         coming up next while driving, which is meaningless once
         he's down. Centering directly on him instead, same pattern
         as the pickup/won branches above. */
      camTargetX = this.botX;
      camTargetY = this.botY;
    }

    this.camX = Phaser.Math.Linear(this.camX, camTargetX, 0.08);
    this.camY = Phaser.Math.Linear(this.camY, camTargetY, 0.06);
    this.camZ = Phaser.Math.Linear(this.camZ, camTargetZ, 0.08);

    /* the "?!" of a machine confronting a tree */
    if(this.stuckAmt > 0.5 && this.state === "play"){
      const sp2 = this.W(this.botX, this.botY, this.botZ + 130);
      this.qtext.setVisible(true).setAlpha(this.stuckAmt);
      this.qtext.setPosition(sp2.x + 42 + Math.random()*2,
                             sp2.y + Math.sin(t*0.008)*6);
    } else this.qtext.setVisible(false);

    const driving = this.state === "play" && this.speed > 0.01;
    const bobZ = this.state === "tipped" ? 0 : (driving ? Math.sin(t*0.012)*1.1 : Math.sin(t*0.0022)*1.4);
    const leanTarget = driving ? -0.3*(this.speed/0.15) : Math.sin(t*0.0022)*0.08;
    this.flagLean = Phaser.Math.Linear(this.flagLean, leanTarget, 0.06);

    /* shadow (never pitches or rolls) */
    const sp = this.pitch, srl = this.roll; this.pitch = 0; this.roll = 0;
    const sh = [];
    for(let i=0;i<14;i++){
      const a=(i/14)*Math.PI*2;
      sh.push(this.P(Math.cos(a)*34, -this.tipT*26*(this.tipDir||1) + Math.sin(a)*(30 + this.tipT*26), 0.5));
    }
    this.quadOn(g, sh, SKIN.shadow, 0.16);
    this.pitch = sp; this.roll = srl;

    /* spilled cargo lies in the world, behind the robot */
    this.drawItems();
    if(!this.flagNear()) this.drawFlag(bobZ);

    /* wheels far -> undercarriage -> body -> details -> wheels near -> flag */
    const wheels = [];
    /* near/far by MOUNTING-FACE VISIBILITY — the same projection-exact
       normal test drawBox uses for every hull face: a wheel row draws
       in front of the body iff the body face it's bolted to (local
       (0, side, 0)) faces the camera. The old depth() comparison had
       the z*0.4 pathology lidNear()/flagNear() each already fixed: a
       tipped robot's air row out-depthed its grounded mirror at EVERY
       heading, so the trio painted over the hull wherever the body
       should hide it (reported at f=2 tipped). A planimetric fix is
       degenerate at the 90-degree rest pose (the rows stack vertically,
       identical x/y) — the face-normal test has no such hole: upright
       it reduces exactly to the heading answer, rolled it hands the
       sky-facing row to the near pass, and every angle between is
       continuous, all 4 headings by construction. */
    for(const side of [-1, 1]){
      const wnorm = this.R(0, side, 0);
      const sideNear = (wnorm.x + wnorm.y + wnorm.z) > 0;
      for(const wx of WHEEL.xs){
        const c = {x:wx, y:side*WHEEL.side, z:WHEEL.z};
        wheels.push({ c, side, near: sideNear, d: this.depth(c.x, c.y, c.z) });
      }
    }
    /* the 3 wheels on a given side (front/mid/rear along the body) were
       always drawn in fixed array order (-16, 0, 16) regardless of
       which one the current yaw/facing actually put closer to camera —
       sorting by real depth first keeps that trio in the right
       front-to-back order at every angle instead of just at the ones
       where the fixed order happened to already match. */
    wheels.sort((a,b) => a.d - b.d);
    for(const w of wheels) if(!w.near) this.drawWheel(w.c, w.side);

    /* the open lid can swing to the far side of the body — draw it first there */
    const lidBox = {...LID, z0:LID.z0+bobZ, z1:LID.z1+bobZ};
    const lidIsNear = this.lidNear();
    if(!lidIsNear) this.drawLid(lidBox);

    this.drawBox({hx:24, hy:17, z0:6, z1:BODY.z0+1}, 0x3f434c, 0x3a3d45, 0x2e3138, false);
    this.drawBox({...BODY, z0:BODY.z0+bobZ, z1:BODY.z1+bobZ}, SKIN.bodyTop, SKIN.bodyRight, SKIN.bodyLeft);
    this.drawBox({hx:BODY.hx+0.6, hy:BODY.hy+0.6, z0:STRIPE.z0+bobZ, z1:STRIPE.z1+bobZ},
                 null, SKIN.stripe, SKIN.stripeDk, false, true);
    /* ---- SKIN EXTRAS ----
       The Daredevil is white leather with a BLUE band carrying WHITE
       STARS and a RED band beneath it. The palette ported across but
       these two extra passes did not, so it was arriving as a plain blue
       stripe. Both are gated on the palette, so no other skin grows
       them. */
    if(SKIN.stars || SKIN.emblem) this.drawHullEmblem(bobZ);
    if(SKIN.stripe2){
      this.drawBox({hx:BODY.hx+0.6, hy:BODY.hy+0.6,
                    z0:HJ_STRIPE2.z0+bobZ, z1:HJ_STRIPE2.z1+bobZ},
                   null, SKIN.stripe2, SKIN.stripe2Dk, false, true);
    }
    /* cavity + hinged lid */
    if(this.lidAng > 0.12){
      const wn = this.R(0, 0, 1);
      if(wn.x + wn.y + wn.z > 0){
        const zc = LID.z0 + bobZ + 0.5;
        const ring = (hx, hy) => [
          this.P(hx,-hy,zc), this.P(hx,hy,zc), this.P(-hx,hy,zc), this.P(-hx,-hy,zc)
        ];
        this.quadOn(g, ring(LID.hx-2, LID.hy-2), SKIN.cavityWall);
        this.quadOn(g, ring(LID.hx-6, LID.hy-6), SKIN.cavityFloor);
      }
    }
    if(lidIsNear) this.drawLid(lidBox);

    const fn = this.R(1, 0, 0);
    const F = (y, z) => this.P(BODY.hx + 0.8, y, z + bobZ);
    const ks = this.kScale();
    if(fn.x + fn.y + fn.z > 0){
      this.quadOn(g, [F(-13,40), F(13,40), F(13,50), F(-13,50)], SKIN.visor);
      this.edgeOn(g, [F(-13,40), F(13,40), F(13,50), F(-13,50)], SKIN.outline, this.kw(1.5));
      /* Everything below is drawn in SCREEN pixels, after this.P() has
         already applied the camera scale -- so these constants have to
         be scaled by hand or the eyes stay full size while the robot
         shrinks (very visible at depth 3, K=0.30). ks() is normalised
         against ZOOM_K[0], so depth 1 is byte-identical to before.
         Stroke widths get a 1px floor so they don't vanish. */
      if(this.state === "tipped"){
        g.lineStyle(Math.max(1, 2.5*ks), SKIN.eyeAlert, 1);
        for(const ey of [-7, 7]){
          const c = F(ey, 45), x = 4*ks;
          g.lineBetween(c.x-x, c.y-x, c.x+x, c.y+x);
          g.lineBetween(c.x-x, c.y+x, c.x+x, c.y-x);
        }
      } else {
        this.blinkT -= dt;
        if(this.blinkT < -3200 + Math.random()*80) this.blinkT = 130;
        const open = this.blinkT > 0 ? 0.15 : 1;
        const ec = (Math.abs(this.tilt) > 0.6 || this.stuckAmt > 0.4 || this.slide) ? SKIN.eyeAlert : SKIN.eye;
        for(const ey of [-7, 7]){
          const c = F(ey, 45);
          g.fillStyle(ec, 1);
          g.fillEllipse(c.x, c.y, 7*ks, 7*ks*open);
        }
      }
      this.quadOn(g, [F(-16,18), F(16,18), F(16,22), F(-16,22)], 0xfff3b0);
    }
    if(this.route && this.route.night){
      /* the eyes stay lit after dark. A single flat wash doesn't read
         against the navy night multiply — same finding the lamp lab
         already hit (see the streetlamp's own layered gl.fillStyle
         chain a few hundred lines up: "a single faint wash can't even
         cancel the navy"). Same fix here: soft outer wash, then a
         tighter mid layer, then a small hot white core, instead of one
         flat fill. Sine breathing pulse drives the whole stack together
         rather than a hard strobe — flashing/strobing is a real
         photosensitivity concern, a smooth ~4s cycle reads as "these
         are lights" with no flicker. Both eyes in phase.
         This whole block sits outside the fn-facing gate above on
         purpose now — that hard cutoff is right for the solid visor
         geometry (you can't see a robot's face from directly behind),
         but it's a binary on/off across a full 180° of headings, and
         this is a grid-based map: whole cardinal legs landed on the
         wrong side of that line and went completely dark, eyes and
         headlights both, not dim — actually invisible. faceK below is
         a smooth version of the same fn value instead of a hard cutoff:
         full brightness facing the camera, fading toward the back
         rather than vanishing outright at the halfway point. It
         doesn't solve true occlusion — gGlow still composites as one
         layer above every sprite, no real depth test against the body
         — but it keeps the worst of the through-body look confined to
         the dim end instead of showing at full strength from any angle,
         which was the actual problem with the previous "always
         visible" version. */
      const pulse = 0.5 + 0.5*Math.sin(this.time.now / 650);
      const faceK = Phaser.Math.Clamp((fn.x + fn.y + fn.z + 1.4) / 2.2, 0.4, 1);
      for(const ey of [-7, 7]){
        const c = F(ey, 45);
        this.gGlow.fillStyle(SKIN.eye, (0.14 + 0.12*pulse)*faceK);
        this.gGlow.fillEllipse(c.x, c.y, (15 + 4*pulse)*ks, (13 + 4*pulse)*ks);
        this.gGlow.fillStyle(SKIN.eye, (0.40 + 0.28*pulse)*faceK);
        this.gGlow.fillEllipse(c.x, c.y, (8 + 2.5*pulse)*ks, (7 + 2.5*pulse)*ks);
        this.gGlow.fillStyle(0xffffff, (0.5 + 0.35*pulse)*faceK);
        this.gGlow.fillEllipse(c.x, c.y, (3.5 + 1*pulse)*ks, (3 + 1*pulse)*ks);
      }
      /* headlights: pool + beams, ALL geometry generated in world space
         off botX/botY + drawAngle alone (not a full R() through
         yaw/pitch/roll, so a hop or tip doesn't swing the beam) and
         only then projected through this.W. The previous version mixed
         frames: the two beam triangles shared one far base drawn as a
         horizontal SCREEN segment (gp.x +/- 32px) — perpendicular to
         travel only at the headings where forward projects vertically.
         At the other two headings that base ran parallel to the beam
         and the triangles sheared into slivers; and since both eyes
         fanned to the same base, the pair merged into one blob instead
         of two headlights. Same screen-vs-world frame mistake class as
         the old slalom gate-color bug — the fix is the same: pick one
         frame (world), do all geometry there, project last. A bonus of
         world-space pools: a flat world ellipse projects through the
         iso transform to the correctly foreshortened screen ellipse at
         every heading for free, no hand-rotated canvas needed.
         beamFwd pulled back from 50 to 34 — 50 left ~24 units of dark
         air between the face and the start of the beam (footprint ends
         at 24, eyes at ~26) and the light read as detached from him.
         34 keeps 10 units of clearance past his own silhouette (the
         through-body paint problem started when the beam ORIGIN sat on
         the body at ~27) while the eye halo bridges the remaining gap.
         Sizes chosen to project to the already-approved screen scale:
         at depth 1 W() maps ~1.6px per world unit, so pool half-width
         21 =~ the old 70px ellipse and far beam span +/-21 =~ the old
         +/-32px base. Each eye now owns its own trapezoid (near edge
         under its eye, far edge diverging outward) so two distinct
         beams read at every heading. */
      const hx2 = Math.cos(this.drawAngle), hy2 = Math.sin(this.drawAngle);
      const lx = -Math.sin(this.drawAngle), ly = Math.cos(this.drawAngle);
      const poolDist = 100, beamFwd = 34;
      const WB = (fwd, side, z) => this.W(this.botX + fwd*hx2 + side*lx,
                                          this.botY + fwd*hy2 + side*ly, z);
      const poolK = (0.6 + 0.4*pulse)*faceK;
      /* ground pool: three stacked world-space ellipses, long axis along
         travel, sampled and projected point-by-point */
      const poolLayers = [
        [27, 21, SKIN.eye, 0.30],
        [18, 14, SKIN.eye, 0.52],
        [9.5, 7, 0xffffff, 0.70]
      ];
      for(const L of poolLayers){
        const pp = [];
        for(let i = 0; i < 20; i++){
          const t = i/20 * Math.PI * 2;
          const q = WB(poolDist + Math.cos(t)*L[0], Math.sin(t)*L[1], 0);
          pp.push(new Phaser.Geom.Point(q.x, q.y));
        }
        this.gGlow.fillStyle(L[2], L[3]*poolK);
        this.gGlow.fillPoints(pp, true);
      }
      /* beams: one trapezoid per eye. Near edge sits just under eye
         height 10 units past the footprint; far edge lands inside the
         pool's cross-travel half-width (21) so beam and pool meet. */
      this.gGlow.fillStyle(SKIN.eye, (0.20 + 0.12*pulse)*poolK);
      for(const ey of [-7, 7]){
        const dv = ey > 0 ? 1 : -1;
        const n0 = WB(beamFwd, ey - dv*2.8, this.botZ + 36);
        const n1 = WB(beamFwd, ey + dv*2.8, this.botZ + 36);
        const f0 = WB(poolDist, ey*1.85 - dv*8, 0);
        const f1 = WB(poolDist, ey*1.85 + dv*8, 0);
        this.gGlow.fillPoints([
          new Phaser.Geom.Point(n0.x, n0.y),
          new Phaser.Geom.Point(n1.x, n1.y),
          new Phaser.Geom.Point(f1.x, f1.y),
          new Phaser.Geom.Point(f0.x, f0.y)
        ], true);
      }
    }
    for(const w of wheels) if(w.near) this.drawWheel(w.c, w.side);
    if(this.flagNear()) this.drawFlag(bobZ);
  }

  /* Screen-pixel scale factor, normalised so depth 1 (K = ZOOM_K[0] =
     1.5) returns exactly 1 and nothing about the shipped look changes.
     Use for anything drawn in raw pixels AFTER this.P() -- stroke
     widths, fillCircle/fillEllipse radii, hand-rolled offsets. */
  kScale(){ return this.K / ZOOM_K[0]; }
  /* stroke widths: same normalisation, with a 1px floor so outlines
     don't disappear entirely at depth 3 */
  kw(w){ return Math.max(1, w * this.kScale()); }

  flagNear(){
    /* roll excluded here, same fix lidNear() already needed for the
       same reason: the depth formula's z*0.4 weighting is guaranteed
       to flip this comparison somewhere in the middle of any large
       roll sweep -- not a tunable constant, a consequence of the
       formula itself. Left in, the flag would flicker in front of and
       behind the lid throughout the whole crash instead of holding
       one answer. The flag's actual near/far relationship to the lid
       is fixed by their local positions and doesn't change just
       because the robot's currently rolling over -- roll is how the
       crash looks, not a reason the two should swap places. Verified
       across all 4 headings x both tip directions x the full tipT
       sweep: zero flips with roll excluded, versus flipping multiple
       times per crash with it included. */
    const sr = this.roll; this.roll = 0;
    const result = this.depth(FLAG.base.x, FLAG.base.y, FLAG.z0 + 20) > this.depth(0, 0, 34);
    this.roll = sr;
    return result;
  }

  /* near/far by TOP-FACE VISIBILITY, not a depth comparison. The lid is
     hinged along the body's rear top edge and only ever swings within
     the hemisphere above that face — it can never end up behind the
     body when the top face itself is camera-facing, or in front of it
     when the top face faces away. So the same test the cavity gate
     below already uses for "is the top face visible" (this.R(0,0,1),
     summed) also answers "is the lid near", and the two can never
     disagree with each other since it's the literal same expression
     evaluated in the same frame.
     Replaces a point-depth comparison (this.depth(), which weights z
     by 0.4) that was forced-near below lidAng 0.15 and only ran the
     depth test above that. That combination (a) kept painting the shut
     lid over the body for several frames after the body had already
     rolled past the point it should occlude it, (b) popped visibly at
     the 0.15 threshold mid-roll, and (c) is mathematically guaranteed
     to flip mid-sweep for any large roll — same z*0.4 root cause
     already fixed in flagNear() and the wheel mounting-face test, just
     never carried over here. The normal test is continuous through the
     whole roll sweep instead. lidAng and lidHingeFlip don't factor in
     at all now — which edge is the physical hinge never changes which
     side of the body's own top plane the lid is swinging into. */
  lidNear(){
    const w = this.R(0, 0, 1);
    return (w.x + w.y + w.z) > 0;
  }

  rollPt(x, y, z){                 // roll only — no facing (for world-space spawns)
    if(this.roll === 0) return {x, y, z};
    const PIV = this.roll >= 0 ? 22 : -22;
    const y0 = y + PIV, c = Math.cos(this.roll), s = Math.sin(this.roll);
    return { x, y:-PIV + y0*c - z*s, z:y0*s + z*c };
  }

  /* the lid: a box on a hinge along its rear edge; swings open by this.lidAng */
  drawLid(b){
    const {hx, hy, z0, z1} = b;
    const A = this.lidAng, cA = Math.cos(A);
    /* hinge side: fixed edge (doesn't mirror with tip direction) for
       the tip/spill crash animation — this.lidHingeFlip defaults to
       false everywhere except during pickup loading, so that behavior
       is completely unchanged. Only the pickup sequence sets it true.
       Flipping the hinge point alone isn't a true mirror — the sin
       term (equivalent to using -A) has to flip too, or the lid
       swings the wrong way relative to its new hinge instead of
       mirroring the same upward-opening motion. Verified: with the
       sign flip, both hinge sides lift the same height, just swinging
       toward opposite directions — a proper mirror. */
    const sA = Math.sin(A) * (this.lidHingeFlip ? -1 : 1);
    const yh = (this.lidHingeFlip ? hy : -hy), zh = z0;
    const H = (x, y, z) => {                     // hinge rotation, then normal pipeline
      const dy = y - yh, dz = z - zh;
      return this.P(x, yh + dy*cA - dz*sA, zh + dy*sA + dz*cA);
    };
    const HN = (nx, ny, nz) => {                 // normals: hinge rot then roll+facing
      const ny2 = ny*cA - nz*sA, nz2 = ny*sA + nz*cA;
      return this.R(nx, ny2, nz2);
    };
    const C = (sx, sy, sz) => H(sx*hx, sy*hy, sz === 1 ? z1 : z0);
    const faces = [
      { n:{x:0,y:0,z: 1}, pts:[C( 1,-1,1), C( 1, 1,1), C(-1, 1,1), C(-1,-1,1)] },
      { n:{x:0,y:0,z:-1}, pts:[C( 1,-1,0), C( 1, 1,0), C(-1, 1,0), C(-1,-1,0)] },
      { n:{x: 1,y:0,z:0}, pts:[C( 1,-1,0), C( 1, 1,0), C( 1, 1,1), C( 1,-1,1)] },
      { n:{x:-1,y:0,z:0}, pts:[C(-1,-1,0), C(-1, 1,0), C(-1, 1,1), C(-1,-1,1)] },
      { n:{x:0,y: 1,z:0}, pts:[C( 1, 1,0), C(-1, 1,0), C(-1, 1,1), C( 1, 1,1)] },
      { n:{x:0,y:-1,z:0}, pts:[C( 1,-1,0), C(-1,-1,0), C(-1,-1,1), C( 1,-1,1)] }
    ];
    for(const fc of faces){
      const w = HN(fc.n.x, fc.n.y, fc.n.z);
      if((w.x + w.y + w.z) <= 0) continue;
      const col = w.z > 0.5 ? SKIN.bodyTop
                : w.z < -0.5 ? SKIN.lidInner
                : (w.x >= w.y) ? SKIN.bodyRight : SKIN.bodyLeft;
      this.quad(fc.pts, col);
      this.edge(fc.pts);
    }
  }

  quad(pts, color, alpha=1){
    this.g.fillStyle(color, alpha);
    this.g.fillPoints(pts.map(p => new Phaser.Geom.Point(p.x, p.y)), true, true);
  }
  edge(pts, color=SKIN.outline, w=2){
    this.g.lineStyle(this.kw(w), color, 1);
    this.g.strokePoints(pts.map(p => new Phaser.Geom.Point(p.x, p.y)), true);
  }

  /* ---------- spilled cargo ---------- */
  spillCargo(){
    this.spilled = true;
    /* opening point: the lid's far edge (opposite the fixed hinge),
       rotated by the CURRENT lidAng first — matching drawLid's own
       hinge geometry exactly — before applying the body's roll. The
       old version skipped the hinge rotation entirely and used a
       fixed local point as if the lid were still shut, so once the
       lid had actually swung open the spill came out of the wrong
       spot/direction relative to where the opening really was. */
    const hA = this.lidAng, chA = Math.cos(hA), shA = Math.sin(hA);
    const hyh = -LID.hy, hzh = LID.z0;
    const hdy = LID.hy - hyh, hdz = 0;   // far-bottom edge, opposite the hinge
    const hingedY = hyh + hdy*chA - hdz*shA;
    const hingedZ = hzh + hdy*shA + hdz*chA;
    const mouth = this.rollPt(0, hingedY, hingedZ + 4);   // lid opening, mid-fall — fixed
                                                          // edge (opposite the now-fixed
                                                          // hinge), not mirrored by tip
                                                          // direction; rollPt() still
                                                          // carries the tip-direction-
                                                          // dependent world-space effect
    const outSign = this.tipDir >= 0 ? -1 : 1;   // the two tip types roll opposite
                                                    // ways around the same fixed hinge,
                                                    // so "away from the opening" flips
                                                    // horizontally between them
    const spawn = (kind, size) => this.items.push({
      kind, size,
      x: mouth.x + (Math.random()-0.5)*10,
      y: mouth.y + outSign*(4 + Math.random()*6),
      z: mouth.z + Math.random()*4,
      vx: (Math.random()-0.5)*2.2,
      vy: outSign*(0.8 + Math.random()*1.4),
      vz: 0.5 + Math.random()*0.9,
      spin: (Math.random()-0.5)*0.3, ang: Math.random()*Math.PI,
      rest: false
    });
    /* the takeout BAG itself tumbles out first — it's the thing the
       whole delivery is about, and spilling only its contents read as
       the bag never existing. Gated on loadDone so a tip during the
       loading beat (bag still in the worker's hand / mid-arc) can't
       duplicate it. Slightly heavier throw than the contents: the
       container leads, the burrito chases. */
    if(this.bagOnBoard) this.items.push({
      kind:"bag", size: 12,
      x: mouth.x + (Math.random()-0.5)*8,
      y: mouth.y + outSign*(6 + Math.random()*5),
      z: mouth.z + 3,
      vx: (Math.random()-0.5)*1.8,
      vy: outSign*(1.1 + Math.random()*1.2),
      vz: 0.7 + Math.random()*0.7,
      spin: (Math.random()-0.5)*0.22, ang: Math.random()*Math.PI,
      rest: false
    });
    this.bagOnBoard = false;   // it's on the pavement now
    /* the spill IS the order: every line item's spill kinds hit the
       pavement — books outside the bookstore, apples outside the
       market, a pizza box shedding slices. Capped at 8 pieces (perf +
       readability); a missing order falls back to the classic trio. */
    const SPILL_SIZE = { burrito:9, cup:7, fry:4, taco:7, croissant:6, donut:5.5,
                         loaf:9, sandwich:7, pizzabox:11, slice:7, cone:6, pint:6,
                         apple:5, milk:6.5, eggs:8, parcel:10, book:7, paintcan:6.5 };
    const spillKinds = [];
    if(this.route.order)
      for(const l of this.route.order.lines)
        for(let q = 0; q < l.qty; q++) spillKinds.push(...(l.spill || ["burrito"]));
    while(spillKinds.length > 8) spillKinds.splice(Math.floor(Math.random()*spillKinds.length), 1);
    if(!spillKinds.length) spillKinds.push("burrito", "cup", "fry", "fry", "fry");
    for(const sk of spillKinds) spawn(sk, SPILL_SIZE[sk] || 6);
  }

  simItems(dt){
    const k = dt/16.7;
    for(const it of this.items){
      if(it.rest) continue;
      it.vz -= 0.14*k;
      it.x += it.vx*k; it.y += it.vy*k; it.z += it.vz*k;
      it.ang += it.spin*k;
      if(it.z <= it.size*0.35){
        it.z = it.size*0.35;
        if(Math.abs(it.vz) < 0.25){ it.rest = true; it.vx = it.vy = it.vz = 0; }
        else { it.vz *= -0.38; it.vx *= 0.7; it.vy *= 0.7; it.spin *= 0.6; }
      }
    }
  }

  /* ---------- bin debris (approved bin hit lab, 2026-07-09) ----------
     Same ballistic-arc-then-settle pattern as the robot's own
     spillCargo/simItems, just per-hazard: each knocked bin owns its
     own hz.items array. Coordinates are LOCAL to the hazard's own
     (u,v,h) axes — the same frame binTipPoint/drawProp's W() already
     use — so this needs no knowledge of the route's actual world
     direction; that translation happens later, at render time. */
  spillBinTrash(hz){
    const cth = hz.fallPsi !== undefined ? hz.fallPsi : (hz.thetaF || 0);
    const fc = Math.cos(cth), fsn = Math.sin(cth);
    const tt = binTipPoint(BIN.height, 2, hz.phi);
    const slide = hz.slide || 0;
    const mx = (tt.u + slide)*fc, my = (tt.u + slide)*fsn, mz = tt.z;
    const spawn = (kind, size) => hz.items.push({
      kind, size,
      x: mx + (Math.random()-0.5)*6,
      y: my + (Math.random()-0.5)*6,
      z: mz + Math.random()*4,
      vx: fc*(1.8 + Math.random()*2.4) + (Math.random()-0.5)*2.4,
      vy: fsn*(1.8 + Math.random()*2.4) + (Math.random()-0.5)*2.4,
      vz: 2.4 + Math.random()*2.0,
      spin: (Math.random()-0.5)*0.3, ang: Math.random()*Math.PI,
      rest: false
    });
    spawn("paper", 5);
    spawn("can", 4);
    for(let i=0; i<2; i++) spawn("wrap", 3);
  }
  simBinTrash(hz, dt){
    if(!hz.items || !hz.items.length) return;
    const k = dt/16.7;
    for(const it of hz.items){
      if(it.rest) continue;
      it.vz -= 0.14*k;
      it.x += it.vx*k; it.y += it.vy*k; it.z += it.vz*k;
      it.ang += it.spin*k;
      if(it.z <= it.size*0.35){
        it.z = it.size*0.35;
        if(Math.abs(it.vz) < 0.25){ it.rest = true; it.vx = it.vy = it.vz = 0; }
        else { it.vz *= -0.38; it.vx *= 0.7; it.vy *= 0.7; it.spin *= 0.6; }
      }
    }
  }
  /* spilled plants — same shape as bin's trash spill, colored from
     the planter's own variant so a tropical planter spills tropical
     leaves, not generic green ones. */
  /* hydrant shear burst (requested 2026-07-27, "a little more life"):
     same per-hazard hz.items contract as spillBinTrash/
     spillPlanterLeaves, but water — droplets erupt from the sheared
     front nozzle in an up-and-out cone, splash down, and EVAPORATE
     into the flood (life fade) instead of settling permanently like
     leaves/trash do. One-shot at the burst moment; the standing spray
     arc + growing puddle remain the persistent part. */
  spillHydrantWater(hz){
    const n = 16 + Math.floor(Math.random()*8);
    for(let i=0; i<n; i++){
      hz.items.push({
        col: Math.random() < 0.65 ? HYD.water : HYD.waterDk,
        size: 1 + Math.random()*1.5,
        x: 6 + Math.random()*4, y: (Math.random()-0.5)*6, z: 10 + Math.random()*5,
        vx: (Math.random()-0.2)*2.5, vy: (Math.random()-0.5)*2.2, vz: 0.8 + Math.random()*1.0,
        life: 1, landed: false
      });
    }
  }
  simHydrantWater(hz, dt){
    if(!hz.items || !hz.items.length) return;
    const k = dt/16.7;
    for(const it of hz.items){
      if(!it.landed){
        it.vz -= 0.11*k;
        it.x += it.vx*k; it.y += it.vy*k; it.z += it.vz*k;
        if(it.z <= 0.4){ it.z = 0.4; it.landed = true; it.vx *= 0.3; it.vy *= 0.3; }
      } else {
        it.x += it.vx*k; it.y += it.vy*k;
        it.life -= 0.03*k;
      }
    }
    hz.items = hz.items.filter(it => it.life > 0);
  }
  spillPlanterLeaves(hz){
    const V = PLANTER_VARIANTS[hz.variantIdx || 0];
    const n = 5 + Math.floor(Math.random()*3);
    for(let i=0; i<n; i++){
      hz.items.push({
        col: [V.leafA, V.leafB, V.leafC, V.flower][Math.floor(Math.random()*4)],
        size: (2 + Math.random()*2) * (hz.scale || 1),
        x: (Math.random()-0.5)*10*(hz.scale||1), y: (Math.random()-0.5)*10*(hz.scale||1), z: 6 + Math.random()*6,
        vx: (Math.random()-0.5)*1.6, vy: (Math.random()-0.5)*1.6, vz: 0.6 + Math.random()*0.8,
        spin: (Math.random()-0.5)*0.3, ang: Math.random()*Math.PI,
        rest: false
      });
    }
  }
  simPlanterLeaves(hz, dt){
    if(!hz.items || !hz.items.length) return;
    const k = dt/16.7;
    for(const it of hz.items){
      if(it.rest) continue;
      it.vz -= 0.09*k;
      it.x += it.vx*k; it.y += it.vy*k; it.z += it.vz*k;
      if(it.z <= 0.5){
        it.z = 0.5;
        if(Math.abs(it.vz) < 0.2){ it.rest = true; it.vx = it.vy = it.vz = 0; }
        else { it.vz *= -0.3; it.vx *= 0.6; it.vy *= 0.6; }
      }
    }
  }
  /* other robots' spilled cargo (requested 2026-07-25): same ballistic-
     arc-then-settle pattern as spillBinTrash/spillPlanterLeaves --
     a burrito and fries instead of trash or leaves, but otherwise the
     identical per-hazard hz.items contract. */
  spillRobotCargo(hz){
    const spawn = (kind, size) => hz.items.push({
      kind, size,
      x: (Math.random()-0.5)*10, y: (Math.random()-0.5)*10, z: 20 + Math.random()*8,
      vx: (Math.random()-0.5)*2.4, vy: (Math.random()-0.5)*2.4, vz: 2.0 + Math.random()*1.6,
      spin: (Math.random()-0.5)*0.3, ang: Math.random()*Math.PI, rest: false
    });
    spawn("burrito", 7);
    spawn("fries", 5);
  }
  simRobotCargo(hz, dt){
    if(!hz.items || !hz.items.length) return;
    const k = dt/16.7;
    for(const it of hz.items){
      if(it.rest) continue;
      it.vz -= 0.12*k;
      it.x += it.vx*k; it.y += it.vy*k; it.z += it.vz*k;
      it.ang += it.spin*k;
      if(it.z <= it.size*0.3){
        it.z = it.size*0.3;
        if(Math.abs(it.vz) < 0.25){ it.rest = true; it.vx = it.vy = it.vz = 0; }
        else { it.vz *= -0.35; it.vx *= 0.7; it.vy *= 0.7; it.spin *= 0.6; }
      }
    }
  }

  drawItems(){
    if(!this.items.length) return;
    const sr = this.roll; this.roll = 0;         // items are world objects
    const g = this.g, K = this.K;
    for(const it of this.items){
      // little ground shadow
      const s = this.P(it.x, it.y, 0.4);
      g.fillStyle(SKIN.shadow, 0.15);
      g.fillEllipse(s.x, s.y, it.size*K*0.9, it.size*K*0.4);
      const p = this.P(it.x, it.y, it.z);
      if(it.kind === "burrito"){
        g.fillStyle(0xe8b04b, 1);
        g.fillEllipse(p.x, p.y, 16*K*0.8, 9*K*0.8);
        g.lineStyle(2, 0xb5813a, 1); g.strokeEllipse(p.x, p.y, 16*K*0.8, 9*K*0.8);
        g.fillStyle(0x7fae4e, 1);                       // sad lettuce
        g.fillEllipse(p.x + 5*K*0.8, p.y, 4*K*0.8, 5*K*0.8);
      } else if(it.kind === "cup"){
        g.fillStyle(0xf4f5f7, 1);
        g.fillRect(p.x - 4*K*0.7, p.y - 6*K*0.7, 8*K*0.7, 11*K*0.7);
        g.lineStyle(2, 0xc9ccd2, 1);
        g.strokeRect(p.x - 4*K*0.7, p.y - 6*K*0.7, 8*K*0.7, 11*K*0.7);
        g.fillStyle(0x8b5a3c, 1);                       // the puddle
        if(it.rest) g.fillEllipse(p.x + 7*K, p.y + 5*K*0.6, 14*K*0.8, 5*K*0.8);
      } else if(it.kind === "bag"){
        /* kraft paper bag, drawn as flat primitives in the same this.P
           space as every other spilled item — drawBagTop/drawBagBody
           live in W() space and would place it in the wrong frame
           here. Same BAG_ART palette as the held bag so it reads as
           the same object, tumbling via the shared ang/spin sim. */
        const a2 = it.ang * 0.6, bw = BAG_ART.w*K*0.8, bh = BAG_ART.h*K*0.8;
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(a2);
        g.fillStyle(BAG_ART.paper, 1);
        g.fillRect(-bw/2, -bh/2, bw, bh);
        g.fillStyle(BAG_ART.paperLt, 1);
        g.fillRect(-bw/2, -bh/2, bw, bh*0.3);           // folded/rolled top
        g.lineStyle(2, BAG_ART.foldLine, 1);
        g.strokeRect(-bw/2, -bh/2, bw, bh);
        g.lineBetween(-bw/2, -bh/2 + bh*0.3, bw/2, -bh/2 + bh*0.3);
        g.restore();
      } else if(it.kind === "taco"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.5);
        g.fillStyle(0xe8c07a, 1);                       // shell half-moon
        g.slice(0, 2*K, 8*K*0.8, Math.PI, 0, false); g.fillPath();
        g.lineStyle(2, 0xc09a52, 1);
        g.slice(0, 2*K, 8*K*0.8, Math.PI, 0, false); g.strokePath();
        g.fillStyle(0x7fae4e, 1);                       // filling peeking out
        for(const fx of [-4, 0, 4]) g.fillCircle(fx*K*0.8, 0.5*K, 1.6*K);
        g.fillStyle(0xc2452e, 1); g.fillCircle(-2*K*0.8, 0.2*K, 1.2*K);
        g.restore();
      } else if(it.kind === "croissant"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.5);
        g.fillStyle(0xd9973f, 1);                       // three tapering lobes
        g.fillEllipse(0, 0, 9*K*0.8, 5.5*K*0.8);
        g.fillEllipse(-6*K*0.8, 1.5*K*0.8, 5*K*0.8, 4*K*0.8);
        g.fillEllipse(6*K*0.8, 1.5*K*0.8, 5*K*0.8, 4*K*0.8);
        g.lineStyle(1.6, 0xb0742c, 1);
        g.lineBetween(-3*K*0.8, -2*K*0.8, -2*K*0.8, 2.4*K*0.8);
        g.lineBetween(3*K*0.8, -2*K*0.8, 2*K*0.8, 2.4*K*0.8);
        g.restore();
      } else if(it.kind === "donut"){
        g.fillStyle(0xd97b9c, 1);                       // frosting ring
        g.fillCircle(p.x, p.y, 5.5*K*0.8);
        g.fillStyle(0xc9a06a, 1);                       // the hole (dough shows through)
        g.fillCircle(p.x, p.y, 2*K*0.8);
        g.lineStyle(1.4, 0xf7e8b0, 1);                  // sprinkles
        g.lineBetween(p.x-3*K, p.y-2*K, p.x-1.8*K, p.y-1.4*K);
        g.lineBetween(p.x+2*K, p.y-3*K, p.x+3*K, p.y-2.2*K);
        g.lineBetween(p.x+1*K, p.y+3*K, p.x+2.2*K, p.y+3.6*K);
      } else if(it.kind === "loaf"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.4);
        g.fillStyle(0xc98d4f, 1);
        g.fillRoundedRect(-9*K*0.8, -5*K*0.8, 18*K*0.8, 10*K*0.8, 4*K*0.8);
        g.lineStyle(1.6, 0xa06c34, 1);                  // score marks
        for(const sx of [-4, 0, 4]) g.lineBetween((sx-1.5)*K*0.8, -3*K*0.8, (sx+1.5)*K*0.8, 3*K*0.8);
        g.restore();
      } else if(it.kind === "sandwich"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.5);
        g.fillStyle(0xe8d9b0, 1);                       // triangle half
        g.fillTriangle(-7*K*0.8, 6*K*0.8, 7*K*0.8, 6*K*0.8, 7*K*0.8, -7*K*0.8);
        g.lineStyle(2, 0xc2b183, 1);
        g.strokeTriangle(-7*K*0.8, 6*K*0.8, 7*K*0.8, 6*K*0.8, 7*K*0.8, -7*K*0.8);
        g.lineStyle(2.2, 0x7fae4e, 1);                  // filling along the cut
        g.lineBetween(-5*K*0.8, 4.6*K*0.8, 5.6*K*0.8, -5*K*0.8);
        g.lineStyle(2.2, 0xd98a8a, 1);
        g.lineBetween(-3.4*K*0.8, 5.4*K*0.8, 6.2*K*0.8, -3.2*K*0.8);
        g.restore();
      } else if(it.kind === "pizzabox"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.35);
        g.fillStyle(0xd9c9a8, 1);
        g.fillRect(-11*K*0.8, -11*K*0.8, 22*K*0.8, 22*K*0.8);
        g.lineStyle(2, 0xb5a479, 1);
        g.strokeRect(-11*K*0.8, -11*K*0.8, 22*K*0.8, 22*K*0.8);
        g.lineBetween(-11*K*0.8, -5*K*0.8, 11*K*0.8, -5*K*0.8);   // lid seam
        g.fillStyle(0xc2452e, 1); g.fillCircle(0, 3*K*0.8, 2.4*K*0.8);  // logo
        g.restore();
      } else if(it.kind === "slice"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.6);
        g.fillStyle(0xe8b84f, 1);                       // cheese wedge
        g.fillTriangle(0, -8*K*0.8, -5.5*K*0.8, 6*K*0.8, 5.5*K*0.8, 6*K*0.8);
        g.lineStyle(3, 0xc98d4f, 1);                    // crust
        g.lineBetween(-5.5*K*0.8, 6*K*0.8, 5.5*K*0.8, 6*K*0.8);
        g.fillStyle(0xc2452e, 1);                       // pepperoni
        g.fillCircle(-1.4*K*0.8, 1*K*0.8, 1.5*K*0.8);
        g.fillCircle(2*K*0.8, 3.4*K*0.8, 1.5*K*0.8);
        g.fillCircle(0.4*K*0.8, -3*K*0.8, 1.3*K*0.8);
        g.restore();
      } else if(it.kind === "cone"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.5);
        g.fillStyle(0xd9a45f, 1);                       // wafer
        g.fillTriangle(0, 8*K*0.8, -4*K*0.8, -2*K*0.8, 4*K*0.8, -2*K*0.8);
        g.lineStyle(1.2, 0xb0742c, 1);
        g.lineBetween(-2.6*K*0.8, 1*K*0.8, 2.6*K*0.8, 1*K*0.8);
        g.lineBetween(-1.4*K*0.8, 4.4*K*0.8, 1.4*K*0.8, 4.4*K*0.8);
        g.fillStyle(0xf7dce8, 1);                       // the scoop (splatted once at rest)
        g.fillEllipse(0, -3.4*K*0.8, (it.rest ? 9 : 6.5)*K*0.8, (it.rest ? 5.5 : 6)*K*0.8);
        g.restore();
      } else if(it.kind === "pint"){
        g.fillStyle(0xf4f5f7, 1);
        g.fillRect(p.x - 4.5*K*0.7, p.y - 4*K*0.7, 9*K*0.7, 8*K*0.7);
        g.fillStyle(0xd97b9c, 1);                       // strawberry band
        g.fillRect(p.x - 4.5*K*0.7, p.y - 1*K*0.7, 9*K*0.7, 2.6*K*0.7);
        g.lineStyle(2, 0xc9ccd2, 1);
        g.strokeRect(p.x - 4.5*K*0.7, p.y - 4*K*0.7, 9*K*0.7, 8*K*0.7);
        g.fillStyle(0xf7dce8, 1);                       // melt puddle
        if(it.rest) g.fillEllipse(p.x + 6*K, p.y + 4*K*0.6, 11*K*0.8, 4.5*K*0.8);
      } else if(it.kind === "apple"){
        g.fillStyle(0xc23b2e, 1);
        g.fillCircle(p.x, p.y, 4.5*K*0.8);
        g.lineStyle(1.6, 0x6b4a2c, 1);                  // stem
        g.lineBetween(p.x, p.y - 4*K*0.8, p.x + 1.4*K*0.8, p.y - 6*K*0.8);
        g.fillStyle(0x7fae4e, 1);                       // leaf
        g.fillEllipse(p.x + 2.6*K*0.8, p.y - 5.4*K*0.8, 2.6*K*0.8, 1.4*K*0.8);
      } else if(it.kind === "milk"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.4);
        g.fillStyle(0xf0ece0, 1);                       // carton body
        g.fillRect(-4*K*0.8, -3*K*0.8, 8*K*0.8, 9*K*0.8);
        g.fillTriangle(-4*K*0.8, -3*K*0.8, 4*K*0.8, -3*K*0.8, 0, -7*K*0.8);   // gable top
        g.lineStyle(1.6, 0xc9c2b0, 1);
        g.strokeRect(-4*K*0.8, -3*K*0.8, 8*K*0.8, 9*K*0.8);
        g.fillStyle(0x4f7fb8, 1);                       // label band
        g.fillRect(-4*K*0.8, 0.5*K*0.8, 8*K*0.8, 2.4*K*0.8);
        g.restore();
      } else if(it.kind === "eggs"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.3);
        g.fillStyle(0xd9d2c4, 1);                       // carton
        g.fillRoundedRect(-8*K*0.8, -4*K*0.8, 16*K*0.8, 8*K*0.8, 2*K*0.8);
        g.lineStyle(1.6, 0xb0a993, 1);
        g.strokeRoundedRect(-8*K*0.8, -4*K*0.8, 16*K*0.8, 8*K*0.8, 2*K*0.8);
        g.fillStyle(0xf4f0e4, 1);                       // the dome bumps
        for(const ex of [-5, 0, 5]) g.fillCircle(ex*K*0.8, -1*K*0.8, 2*K*0.8);
        /* one casualty at rest */
        if(it.rest){ g.fillStyle(0xf2c94c, 1); g.fillCircle(9*K*0.8, 3*K*0.8, 1.8*K*0.8);
          g.fillStyle(0xf4f0e4, 0.9); g.fillEllipse(9*K*0.8, 3*K*0.8, 5.5*K*0.8, 3.5*K*0.8); }
        g.restore();
      } else if(it.kind === "parcel"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.4);
        const pw = 16*K*0.8, ph = 12*K*0.8;
        g.fillStyle(0xc9a06a, 1);
        g.fillRect(-pw/2, -ph/2, pw, ph);
        g.lineStyle(2, 0xa8824e, 1);
        g.strokeRect(-pw/2, -ph/2, pw, ph);
        g.lineStyle(2.4, 0xe8dcc4, 1);                  // packing tape cross
        g.lineBetween(0, -ph/2, 0, ph/2);
        g.lineBetween(-pw/2, 0, pw/2, 0);
        g.restore();
      } else if(it.kind === "book"){
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(it.ang*0.5);
        const bw2 = 12*K*0.8, bh2 = 9*K*0.8;
        g.fillStyle(0x3f6e8f, 1);                       // cover
        g.fillRect(-bw2/2, -bh2/2, bw2, bh2);
        g.fillStyle(0xf0ece0, 1);                       // page edge
        g.fillRect(bw2/2 - 1.6*K*0.8, -bh2/2 + 1*K*0.8, 1.6*K*0.8, bh2 - 2*K*0.8);
        g.lineStyle(2, 0x2c4d63, 1);                    // spine
        g.lineBetween(-bw2/2 + 1.4*K*0.8, -bh2/2, -bw2/2 + 1.4*K*0.8, bh2/2);
        g.restore();
      } else if(it.kind === "paintcan"){
        g.fillStyle(0x9aa0aa, 1);                       // tin body
        g.fillRect(p.x - 4.5*K*0.7, p.y - 4*K*0.7, 9*K*0.7, 8.5*K*0.7);
        g.fillStyle(0xb8bdc6, 1);
        g.fillEllipse(p.x, p.y - 4*K*0.7, 9*K*0.7, 3*K*0.7);       // lid
        g.lineStyle(1.6, 0x6c727d, 1);
        g.strokeRect(p.x - 4.5*K*0.7, p.y - 4*K*0.7, 9*K*0.7, 8.5*K*0.7);
        g.fillStyle(0x3f8f7a, 1);                       // the spill at rest
        if(it.rest) g.fillEllipse(p.x + 7*K, p.y + 5*K*0.6, 13*K*0.8, 5*K*0.8);
      } else {                                          // fry
        g.fillStyle(0xf2c94c, 1);
        const a = it.ang, L = 7*K*0.7, W2 = 2.2*K*0.7;
        g.save(); g.translateCanvas(p.x, p.y); g.rotateCanvas(a);
        g.fillRect(-L/2, -W2/2, L, W2);
        g.restore();
      }
    }
    this.roll = sr;
  }

  drawBox(b, cTop, cRight, cLeft, outline=true, decal=false, cBottom=SKIN.belly){
    const {hx, hy, z0, z1} = b, ox = b.ox || 0, oy = b.oy || 0;
    const C = (sx, sy, sz) => this.P(ox + sx*hx, oy + sy*hy, sz === 1 ? z1 : z0);
    const faces = [
      { n:{x:0,y:0,z: 1}, pts:[C( 1,-1,1), C( 1, 1,1), C(-1, 1,1), C(-1,-1,1)] },
      { n:{x:0,y:0,z:-1}, pts:[C( 1,-1,0), C( 1, 1,0), C(-1, 1,0), C(-1,-1,0)] },
      { n:{x: 1,y:0,z:0}, pts:[C( 1,-1,0), C( 1, 1,0), C( 1, 1,1), C( 1,-1,1)] },
      { n:{x:-1,y:0,z:0}, pts:[C(-1,-1,0), C(-1, 1,0), C(-1, 1,1), C(-1,-1,1)] },
      { n:{x:0,y: 1,z:0}, pts:[C( 1, 1,0), C(-1, 1,0), C(-1, 1,1), C( 1, 1,1)] },
      { n:{x:0,y:-1,z:0}, pts:[C( 1,-1,0), C(-1,-1,0), C(-1,-1,1), C( 1,-1,1)] }
    ];
    for(const fc of faces){
      /* decals have no geometric top/bottom — but their SIDE faces always draw,
         even when a roll points them skyward (fixes the vanishing stripe) */
      if(decal && fc.n.z !== 0) continue;
      const w = this.R(fc.n.x, fc.n.y, fc.n.z);
      if((w.x + w.y + w.z) <= 0) continue;
      let col;
      if(w.z > 0.5)       col = decal ? cRight : cTop;
      else if(w.z < -0.5) col = decal ? null : cBottom;
      else                col = (w.x >= w.y) ? cRight : cLeft;
      if(col == null) continue;
      this.quadOn(this.g, fc.pts, col);
      if(outline) this.edgeOn(this.g, fc.pts, SKIN.outline, this.kw(2));
    }
  }

  disc(center, r, color, outlineC){
    const pts = [];
    for(let i=0; i<14; i++){
      const a = (i/14)*Math.PI*2;
      pts.push(this.P(center.x + Math.cos(a)*r, center.y, center.z + Math.sin(a)*r));
    }
    this.quadOn(this.g, pts, color);
    if(outlineC !== undefined) this.edgeOn(this.g, pts, outlineC, this.kw(2));
  }

  drawWheel(c, sideSign){
    /* was: 6 depth-sorted flat discs stacked along the wheel's width.
       Each disc alone degenerates to a hairline exactly when residual
       yaw hits +/-45 deg (screen width is proportional to cos(yaw)-sin(yaw),
       which is zero right there) - and every turn's facing-snap sweeps
       through exactly that angle, so every corner clipped the wheels to
       slices. The scooter and traffic props (drawProp's swheel/wheel)
       never had this problem because they build the tread as a single
       convexHull spanning TWO rings offset along the width axis, instead
       of one ring's own outline - the guaranteed gap between the two
       rings contributes width independent of the collapsing term, so it
       can't go to zero. Porting that same construction here. */
    const W2 = 7.5;
    const ring = (oy, r) => {
      const pts = [];
      for(let i=0; i<14; i++){
        const a = (i/14)*Math.PI*2;
        pts.push(this.P(c.x + Math.cos(a)*r, oy, c.z + Math.sin(a)*r));
      }
      return pts;
    };
    const b0 = c.y - W2/2, b1 = c.y + W2/2;
    this.quadOn(this.g, convexHull(ring(b0, WHEEL.r).concat(ring(b1, WHEEL.r))), SKIN.wheelDark);
    const face = this.depth(c.x, b1, c.z) > this.depth(c.x, b0, c.z) ? b1 : b0;
    const faceRing = ring(face, WHEEL.r);
    this.quadOn(this.g, faceRing, SKIN.wheel);
    this.edgeOn(this.g, faceRing, SKIN.outline, this.kw(2));
    this.disc({x:c.x, y:face, z:c.z}, WHEEL.r*0.55, SKIN.wheelHubFace);
    const a = this.wheelPhase + c.x*0.2;
    this.disc({ x:c.x + Math.cos(a)*WHEEL.r*0.34, y:face,
                z:c.z + Math.sin(a)*WHEEL.r*0.34 }, 2.4, SKIN.wheelHub);
  }


  /* JOLLY ROGER -- Porch Pirate's flag, gated on SKIN.jolly.
     Carries a bone X, NOT a skull. The stock pennant is a ~11x20 SCREEN-pixel
     triangle that kScale() shrinks further with depth; a skull drawn there is
     three pixels of mush, and an X still reads. The skull lives on the hull,
     where there is room for it.

     This also changes the flag's geometry for this skin: the stock pennant
     extends ABOVE the pole tip, which is why it reads as a streamer. A real
     flag hangs off the pole, so this one runs outward along the perpendicular
     and downward along the pole. Pole, bend and kScale are identical to
     drawFlag's, so it leans and whips through a tip-over the same way. */
  drawJollyRoger(bobZ){
    const g = this.g;
    const L = FLAG.z1 - FLAG.z0;
    const bend = this.flagLean*0.5 + this.tipT*0.7*(this.tipDir || 1);
    const seg = 6, pts = [];
    for(let i=0;i<=seg;i++){
      const s = i/seg, a = bend*s;
      pts.push(this.P(FLAG.base.x,
                      FLAG.base.y - Math.sin(a)*L*s,
                      FLAG.z0 + Math.cos(a)*L*s + bobZ));
    }
    const ks = this.kScale();
    g.lineStyle(Math.max(1, 3*ks), SKIN.flagPole, 1);
    g.beginPath();
    g.moveTo(pts[0].x, pts[0].y);
    for(let i=1;i<=seg;i++) g.lineTo(pts[i].x, pts[i].y);
    g.strokePath();

    const p = pts[seg], q = pts[seg-1];
    let dx = p.x - q.x, dy = p.y - q.y;
    const dl = Math.hypot(dx, dy) || 1; dx /= dl; dy /= dl;   // up the pole
    const ux = -dy, uy = dx;                                   // out from it
    const Wf = 21*ks, Hf = 14*ks;
    const c = (a,b) => ({ x: p.x + ux*a + dx*b, y: p.y + uy*a + dy*b });
    const A = c(0,0), B = c(Wf,0), C = c(Wf,-Hf), D = c(0,-Hf);
    g.fillStyle(SKIN.flag, 1);
    g.fillTriangle(A.x,A.y,B.x,B.y,C.x,C.y);
    g.fillTriangle(A.x,A.y,C.x,C.y,D.x,D.y);

    /* the bone X, two thin quads corner to corner. Width has a 1px floor for
       the same reason kw() does -- without it the X vanishes at depth 3. */
    const bone = SKIN.emblemColor || 0xe8e2d0;
    const bw = Math.max(1, 1.5*ks);
    const bar = (P0,P1) => {
      let vx = P1.x-P0.x, vy = P1.y-P0.y;
      const vl = Math.hypot(vx,vy) || 1; vx/=vl; vy/=vl;
      const nx = -vy*bw, ny = vx*bw;
      g.fillStyle(bone, 1);
      g.fillTriangle(P0.x+nx,P0.y+ny, P1.x+nx,P1.y+ny, P1.x-nx,P1.y-ny);
      g.fillTriangle(P0.x+nx,P0.y+ny, P1.x-nx,P1.y-ny, P0.x-nx,P0.y-ny);
    };
    bar(c(2*ks,-2*ks), c(Wf-2*ks,-Hf+2*ks));
    bar(c(2*ks,-Hf+2*ks), c(Wf-2*ks,-2*ks));
  }

  drawFlag(bobZ){
    if(SKIN.jolly) return this.drawJollyRoger(bobZ);
    const g = this.g;
    const L = FLAG.z1 - FLAG.z0;
    const bend = this.flagLean*0.5 + this.tipT*0.7*(this.tipDir||1);
    const seg = 6, pts = [];
    for(let i=0; i<=seg; i++){
      const s = i/seg, a = bend*s;
      pts.push(this.P(FLAG.base.x,
                      FLAG.base.y - Math.sin(a)*L*s,
                      FLAG.z0 + Math.cos(a)*L*s + bobZ));
    }
    /* pole width and pennant size are SCREEN pixels -- this.P() has
       already scaled the point positions, so without kScale() the
       pennant keeps its full size on a robot a fifth as big. */
    const ks = this.kScale();
    g.lineStyle(Math.max(1, 3*ks), SKIN.flagPole, 1);
    g.beginPath();
    g.moveTo(pts[0].x, pts[0].y);
    for(let i=1; i<=seg; i++) g.lineTo(pts[i].x, pts[i].y);
    g.strokePath();
    const p = pts[seg], q = pts[seg-1];
    let dx = p.x - q.x, dy = p.y - q.y;
    const dl = Math.hypot(dx, dy) || 1; dx /= dl; dy /= dl;
    g.fillStyle(SKIN.flag, 1);
    g.fillTriangle(p.x, p.y,
                   p.x - dy*11*ks, p.y + dx*11*ks,
                   p.x + dx*20*ks, p.y + dy*20*ks + 4*ks);
  }

  /* ---------- THE WILLIAM: TAIL OF THE TIMELINE ----------
     gloat -> return -> patrol. None of it reads the robot, which is the
     point: the in-play hazard pass and the post-tip pass below both
     call this rather than each keeping their own copy. */
  williamSettleStep(hz, t){
    const KA = WILLIAM_ACT, kel = t - hz.kt0;
    if(hz.kst === "gloat"){
      if(kel >= KA.gloat){ hz.kst = "return"; hz.kt0 = t; hz.retA = hz.ka; hz.retB = hz.kb; }
    } else if(hz.kst === "whiff"){
      if(kel >= KA.whiffBeat){ hz.kst = "return"; hz.kt0 = t; hz.retA = hz.ka; hz.retB = hz.kb; }
    } else if(hz.kst === "return"){
      const ku = Math.min(1, kel/KA.retMs), ke = ku*ku*(3-2*ku);
      const ksp = peopleSpotAt(t, hz);
      hz.ka = hz.retA + (ksp.a - hz.retA)*ke;
      hz.kb = hz.retB + ((ksp.b || 0) - hz.retB)*ke;
      hz.kth = Math.atan2(-(ksp.a - hz.retA), ((ksp.b || 0) - hz.retB) || 1);
      if(ku >= 1){ hz.kst = "patrol"; hz.kt0 = t; }
    }
  }

  /* ---------- THE WILLIAM AFTER THE RUN ENDS ----------
     His whole state machine lives inside the hazard loop, which lives
     inside `if(this.state === "play")`. So the instant his own boot
     tipped the robot, the sim that owns him stopped running and he
     stood there frozen mid-kick, leg still extended, until the fail
     overlay took the screen. He finishes the swing, gloats, walks back
     to his patrol and keeps strolling -- the point of the character is
     that he does not care, and standing petrified in a kick pose reads
     as a bug rather than contempt.

     Only the states that do not need the robot run here. Anything he
     was mid-approach on (intercept/block/windup) is abandoned straight
     into return: there is nothing left to chase. */
  updateWilliamIdle(t){
    if(this.state === "play") return;      // the hazard pass owns him while playing
    const hazards = this.route && this.route.hazards;
    if(!hazards) return;
    const KA = WILLIAM_ACT;
    for(const hz of hazards){
      if(hz.type !== "william" || hz.kst === undefined) continue;
      const kel = t - hz.kt0;
      if(hz.kst === "patrol"){
        const ksp = peopleSpotAt(t, hz);
        hz.ka = ksp.a; hz.kb = ksp.b || 0;
      } else if(hz.kst === "kick"){
        /* let the swing play out to its natural end, then branch on
           whether it connected -- the same exit the in-play pass uses,
           minus the contact test, which already ran. */
        if(kel >= KA.swing){
          hz.spent = true;
          hz.kst = hz.klanded ? "gloat" : "whiff"; hz.kt0 = t;
        }
      } else if(hz.kst === "intercept" || hz.kst === "block" || hz.kst === "windup"){
        hz.kst = "return"; hz.kt0 = t; hz.retA = hz.ka; hz.retB = hz.kb;
      } else {
        this.williamSettleStep(hz, t);
      }
    }
  }

  /* ---------- TRAFFIC OBEYS THE LIGHT ----------
     Same `hold` field trafficWorldAt already subtracts -- the mechanism curb
     queues and the crime scene share -- stepped by real elapsed t via
     _trafHoldStep and holdFrame-guarded, so no car takes two steps in one
     frame and drives backward.

     A car only holds inside a short band just before the stop line, so it
     rolls up to the line instead of freezing wherever it happened to be when
     the light changed. Past the line it is committed and clears the box
     rather than parking in the middle of the intersection. Cars mid-corner
     are skipped: they are not approaching any line. */
  updateSignalHolds(t){
    if(!SIGNAL.aware) return;
    const traffic = this.route && this.route.traffic;
    if(!traffic) return;
    const hDt = this._trafHoldDt !== undefined ? this._trafHoldDt : 0;
    for(const tr of traffic){
      const { wp, fc } = trafficWorldAt(tr, t);
      if(Math.abs(fc - Math.round(fc)) > 0.1) continue;
      const f = ((Math.round(fc) % 4) + 4) % 4, d = DIRV[f];
      const onX = d.x !== 0;
      const pos = onX ? wp.x : wp.y, dir = onX ? d.x : d.y;
      const nodeCoord = dir > 0 ? Math.ceil(pos/BLOCK)*BLOCK : Math.floor(pos/BLOCK)*BLOCK;
      const dist = Math.abs(nodeCoord - pos);
      if(dist < ROAD_HALF || dist > ROAD_HALF + SIGNAL.stopBand) continue;
      const node = onX ? { i: Math.round(nodeCoord/BLOCK), j: Math.round(wp.y/BLOCK) }
                       : { i: Math.round(wp.x/BLOCK),      j: Math.round(nodeCoord/BLOCK) };
      if(signalAxisGo(node, t, onX ? 0 : 1)) continue;
      if(tr.holdFrame !== t){ tr.hold = (tr.hold || 0) + hDt; tr.holdFrame = t; }
    }
  }

  /* ---------- CAR FOLLOWING / SPACING ----------
     Independent traffic loops share streets with zero mutual awareness,
     and the three cars on any one loop run at different speeds, so they
     genuinely converge -- the old draw-time cull was hiding that rather
     than solving it. This yields instead: a car whose forward cone
     contains another car within GAP accumulates `hold`, and
     trafficWorldAt subtracts hold from its own clock, so the car really
     stops. Because the freeze happens inside the one pure function both
     the renderer and the hitbox call, a stopped car's art and its
     collision box stay together -- the same invariant the phase
     machine's hold already depends on.

     Cone, not radius: a car yields to what is IN FRONT of it and never
     to what it has already passed. A plain radius check makes two cars
     that meet freeze each other permanently.

     Opposing lanes are 4*T2 = 368 apart and GAP is ~259, so normal
     two-way traffic can never trigger this at all; only same-lane
     convergence does. MAX_YIELD is the escape hatch for the rare
     cross-route case where two loops put opposing cars in one lane --
     the car waits, then goes, instead of parking forever. */
  /* hold is subtracted from `t` inside trafficWorldAt, so a frame's
     worth of hold must equal a frame's worth of t -- NOT dt. Phaser
     smooths and clamps delta (~50ms ceiling) while time.now is real
     wall clock, so on any dropped frame dt is far smaller than the t
     the car's position is computed from, and a "stopped" car quietly
     keeps rolling by the difference. Measured in the headless bench at
     2fps: cars held every frame still closed on each other. Deriving
     the step from t itself makes a held car exactly stationary at any
     frame rate. Capped so a tab-resume jump parks nobody for minutes. */
  _trafHoldStep(t){
    const prev = this._trafHoldPrev;
    this._trafHoldPrev = t;
    this._trafHoldDt = prev === undefined ? 0 : Math.max(0, Math.min(250, t - prev));
    return this._trafHoldDt;
  }

  updateTrafficSpacing(t, dt){
    const hDt = this._trafHoldStep(t);
    const traffic = this.route && this.route.traffic;
    if(!traffic || traffic.length < 2) return;
    const GAP = CARC.len * 1.15, GAP_SQ = GAP*GAP, MAX_YIELD = 6000;
    const pos = [];
    for(const tr of traffic){
      const { wp, fc } = trafficWorldAt(tr, t);
      const th = fc * (Math.PI/2);
      pos.push({ tr, x: wp.x, y: wp.y, dx: Math.cos(th), dy: Math.sin(th) });
    }
    for(let i = 0; i < pos.length; i++){
      const a = pos[i];
      let blocked = false;
      for(let j = 0; j < pos.length && !blocked; j++){
        if(j === i) continue;
        const b = pos[j];
        const rx = b.x - a.x, ry = b.y - a.y, dSq = rx*rx + ry*ry;
        if(dSq > GAP_SQ || dSq < 1e-6) continue;
        const d = Math.sqrt(dSq);
        const ahead = (rx*a.dx + ry*a.dy) / d;        // -1 behind .. +1 dead ahead
        if(ahead < -0.5) continue;                     // safely behind me: not my problem
        /* Two distinct conflicts, one rule each.

           FOLLOWING (ahead >= 0.7 -- the other car is in my lane, in
           front): I always yield. No tie-break needed, because the car
           in front is by definition not yielding to me.

           EVERYTHING ELSE inside GAP -- crossing at an intersection
           (~90 deg, so neither car is in the other's following cone),
           or two routes merging onto the same lane side by side (same
           heading, purely LATERAL closing, which is what the bench
           actually caught) -- needs a right-of-way rule or both cars
           sail straight through each other. Priority goes to the lower
           array index: arbitrary, but stable and deterministic, which
           is all a right-of-way rule has to be. Deterministic also
           means no deadlock: exactly one car of any pair ever waits. */
        if(ahead >= 0.7 || j < i) blocked = true;
      }
      if(blocked && (a.tr.yieldMs || 0) < MAX_YIELD){
        a.tr.yieldMs = (a.tr.yieldMs || 0) + hDt;
        /* holdFrame guards against the phase machine adding a step to
           the same car in the same frame: two increments in one frame
           makes hold outrun t and the car drives BACKWARD. */
        if(a.tr.holdFrame !== t){ a.tr.hold = (a.tr.hold || 0) + hDt; a.tr.holdFrame = t; }
      } else if(!blocked){
        a.tr.yieldMs = 0;
      }
    }
  }

  /* ---------- PHASED TRAFFIC CONTROL ----------
     Lives in the SIM, driven by dt from update() — not in a draw hook.
     A phase advanced during rendering runs at frame rate and freezes
     whenever the world is not being drawn. */
  updateCrimeTraffic(t, dt){
    const cr = this.route && this.route.crime;
    if(!cr) return;
    const P = cr.pinch;
    const ph = this.crimePhase || (this.crimePhase =
      { green: 0, allStop: false, tLeft: CRIME_PHASE_MS });

    /* classify every car against the pinch, and answer the two
       questions with their own tolerances */
    let occupied = false, straddling = false;
    const holding = [];
    for(const tr of this.route.traffic){
      const { wp, f, straddle } = trafficWorldAt(tr, t);
      const dx = wp.x - P.x, dy = wp.y - P.y;
      const along = dx*P.ax + dy*P.ay;
      const lat   = dx*P.lx + dy*P.ly;
      if(Math.abs(lat) > CRIME_ONROAD_TOL) continue;      // not on this road
      const dv = DIRV[f];
      const face = dv.x*P.ax + dv.y*P.ay;                 // +1 / -1 along the road
      if(Math.abs(face) < 0.5) continue;                  // crossing, not travelling it
      if(Math.abs(along) < CRIME_CLEAR_TOL) occupied = true;   // still inside the pinch
      const group = face > 0 ? 0 : 1;
      const progress = along * face;   // negative = approaching the cruiser
      const stopped = (ph.allStop || group !== ph.green)
                   && progress > -CRIME_STOP_R && progress < -CRIME_STOP_LINE;
      if(stopped) holding.push(tr);
      /* Straddling is asked only of cars that are MOVING and belong to
         the outgoing green group — the bench's `if(!c.held)`, restated.
         A held car is frozen wherever it stopped and the stop line (210)
         sits inside the straddle radius (460), so counting held cars
         deadlocks the junction: 9 phase flips a minute became 1. And it
         has to be evaluated during allStop too, not just before it —
         gating it on !allStop made the interlock dead code, because the
         swap itself only ever happens while allStop is true. */
      if(!stopped && group === ph.green && straddle > CRIME_CLEARED_BY) straddling = true;
    }
    /* see updateTrafficSpacing: whichever of the two passes gets to a
       car first owns its hold for this frame. Both adding dt would push
       hold past t and reverse the car. */
    const hDt = this._trafHoldDt !== undefined ? this._trafHoldDt : dt;
    for(const tr of holding){
      if(tr.holdFrame === t) continue;
      tr.hold = (tr.hold || 0) + hDt; tr.holdFrame = t;
    }

    ph.tLeft -= dt;
    if(ph.tLeft <= 0){
      if(!ph.allStop){ ph.allStop = true; ph.tLeft = CRIME_ALLSTOP_MS; ph.heldMs = 0; }
      else {
        /* Swap only when the junction is genuinely empty AND nobody is
           still straddling. A timer-only flip let oncoming traffic go
           while a car was mid-detour — the head-on the bench chased for
           four rounds. maxHold breaks the tie if someone is stuck. */
        const clear = !occupied && !straddling;
        if(clear || (ph.heldMs || 0) >= CRIME_MAX_HOLD){
          ph.green ^= 1; ph.allStop = false; ph.tLeft = CRIME_PHASE_MS; ph.heldMs = 0;
        } else {
          ph.heldMs = (ph.heldMs || 0) + dt;
          ph.tLeft = 120;                    // re-ask shortly
        }
      }
    }

    /* the officer faces whichever direction is currently HELD, palm out,
       with a small wave. liftT rides in through drawOfficer's opts. */
    const heldDir = ph.green === 0 ? -1 : 1;
    this.crimeArm = {
      liftT: 0.78 + 0.14*Math.sin(t*0.004),
      thW: crimeFacing({ x: P.ax*heldDir, y: P.ay*heldDir })
    };
  }

  /* ---------- CORDON BREAK ----------
     In the SIM, like the phase machine. Purely cosmetic: this sets a
     flag and nothing else — it never touches velocity, tilt, cargo or
     the hazard list, and the tape is not in hazVQ at all. Each span is
     tested INDEPENDENTLY, so walking in through one and out through
     another leaves two torn spans rather than one. */
  updateCrimeTape(t){
    const cr = this.route && this.route.crime;
    if(!cr || !cr.tape) return;
    const cur = { x: this.botX, y: this.botY };
    const prev = this.__tapePrev || cur;
    this.__tapePrev = cur;
    for(let i = 0; i < cr.tape.length; i++){
      if(cr.tapeBroken[i]) continue;                 // stays broken for the run
      if(segCross(prev, cur, cr.tape[i].a, cr.tape[i].b)){
        cr.tapeBroken[i] = true;
        cr.tapeBrokeAt[i] = t;
      }
    }
  }

  /* One span. Drawn per-span so each queues at its own depth — the long
     kerb run and the two cross-walk spans have to sort against the cars
     and officers individually, not all at one averaged depth. */
  drawTapeSpan(g, i, t){
    const cr = this.route.crime;
    const sp = cr.tape && cr.tape[i];
    if(!sp) return;
    const A = sp.a, B = sp.b;

    const post = (P) => {
      const c = [];
      for(const dx of [-TAPE.stakeR, TAPE.stakeR])
        for(const dy of [-TAPE.stakeR, TAPE.stakeR])
          for(const h of [0, TAPE.stakeH]) c.push(this.W(P.x+dx, P.y+dy, h));
      const hull = convexHull(c);
      this.quadOn(g, hull, TAPE.stake);
      this.edgeOn(g, hull, TAPE.stakeDk, 1);
    };
    if(sp.post[0]) post(A);
    if(sp.post[1]) post(B);

    const ribbon = (pts) => {
      for(let k = 0; k < pts.length-1; k++){
        const p = pts[k], q = pts[k+1];
        this.quadOn(g, [ this.W(p.x,p.y,p.z-TAPE.half), this.W(q.x,q.y,q.z-TAPE.half),
                         this.W(q.x,q.y,q.z+TAPE.half), this.W(p.x,p.y,p.z+TAPE.half) ],
                    (k % 3 === 2) ? TAPE.band : TAPE.yellow);
      }
    };

    const len = Math.hypot(B.x-A.x, B.y-A.y);
    const nSeg = Math.max(6, Math.round(TAPE.segs * Math.min(2.4, len/260)));

    if(!cr.tapeBroken[i]){
      const pts = [];
      for(let k = 0; k <= nSeg; k++){
        const u = k/nSeg;
        pts.push({ x: A.x + (B.x-A.x)*u, y: A.y + (B.y-A.y)*u,
                   z: TAPE.z - TAPE.sag*Math.sin(Math.PI*u) });
      }
      ribbon(pts);
      return;
    }
    /* BROKEN: each half snaps back to its OWN end post and dangles. The
       anchored end never moves — that is what reads as tape that tore
       rather than tape that vanished. */
    const k0 = Math.min(1, (t - cr.tapeBrokeAt[i]) / TAPE.snapMs);
    const e = 1 - Math.pow(1-k0, 3);
    const mid = { x:(A.x+B.x)/2, y:(A.y+B.y)/2 };
    for(const S of [A, B]){
      const pts = [];
      for(let k = 0; k <= nSeg; k++){
        const u = k/nSeg;
        const tx = S.x + (mid.x-S.x)*u, ty = S.y + (mid.y-S.y)*u;
        const tz = TAPE.z - TAPE.sag*Math.sin(Math.PI*(u*0.5));
        const hx = S.x + (mid.x-S.x)*u*TAPE.hang;
        const hy = S.y + (mid.y-S.y)*u*TAPE.hang;
        const hz = TAPE.z - (TAPE.z - 5)*(u*u);
        pts.push({ x: tx+(hx-tx)*e, y: ty+(hy-ty)*e, z: tz+(hz-tz)*e });
      }
      ribbon(pts);
    }
  }

  update(t, dt){
    /* desktop throttle */
    /* Attract holds its own gas. This has to come BEFORE the desktop
       keys block, not after: that block's final branch zeroes throttle
       whenever no key and no pointer is down, which is every frame of
       an attract run -- the robot would accelerate for one frame and
       coast to a stop forever after. */
    if(this.attract){ this.attractDrive(); }
    else if(this.keys){
      if(this.keys.right.isDown || this.keys.d.isDown) this.throttle = 1;
      else if(this.keys.left.isDown || this.keys.a.isDown) this.throttle = -1;
      else if(!this.input.activePointer.isDown) this.throttle = 0;
    }
    if(this.mode === "challenge" && this.hjFace && this.state === "tipped"){
      /* FACE PLANT — short and ease-OUT (fast off the impact,
         decelerating in) with a slight overshoot past vertical, so it
         reads as a hit rather than a topple. Pivoted at the body's front
         face: rotating 90deg about the origin drives the body through
         the floor. */
      this.hjTipT = Math.min(1, (this.hjTipT || 0) + dt/HJ_CRASH.faceMs);
      const t = this.hjTipT;
      const e = (1 - Math.pow(1-t,3)) * (1 + (HJ_CRASH.faceKick-1)*Math.sin(Math.PI*t));
      this.pitch = this.hjTipPitch0 + (-(Math.PI*0.5) - this.hjTipPitch0)*e;
      this.pitchPivot = BODY.hx * e;
      this.roll = 0;
      /* carry the momentum: friction rises as he goes flat */
    }
    /* SKID — runs for BOTH crash poses, and outside the hjFace branch,
       because the game stops advancing botS the moment it goes tipped
       and that is what killed the slide entirely. */
    if(this.mode === "challenge" && this.state === "tipped"){
      if(!this.hjFace) this.hjTipT = Math.min(1, (this.hjTipT||0) + dt/HJ_CRASH.sideMs);
    }
    if(this.mode === "challenge" && this.state === "tipped" && this.hjSkidV > 0){
      const tt = Math.min(1, (this.hjTipT || 0));
      const grip = HJ_SKID.base + HJ_SKID.bite*tt;
      this.hjSkidV = Math.max(0, this.hjSkidV - grip*this.hjSkidV*dt);
      if(this.hjSkidV < 0.0008) this.hjSkidV = 0;
      this.botS += this.hjSkidV*dt;
      const sp = this.posAt(this.botS), hdg = this.headingAt(this.botS);
      this.botX = sp.x + (-Math.sin(hdg))*this.laneOff;
      this.botY = sp.y + Math.cos(hdg)*this.laneOff;
    }
    if(this.mode === "challenge"){
      if(this.hjPendingReset > 0){
        this.hjPendingReset -= dt;
        if(this.hjPendingReset <= 0){ this.hjPendingReset = 0; this.hjResetRun(); }
      }
      this.hjSim(dt, this.route && this.route.challenge);
    }
    this.updateTrafficSpacing(t, dt);   // sets _trafHoldDt, which the signals reuse
    this.updateSignalHolds(t);
    this.updateWilliamIdle(t);
    this.updateCrimeTraffic(t, dt);
    this.updateCrimeTape(t);
    this.drawWorld(t);
    this.drawRobot(t, dt);
    this.drawHUD();
    if(this.mode === "challenge") hjUpdateMeter(this);
  }

  /* next upcoming turn ahead of the robot's current position, for the
     turn-by-turn HUD. sign>0 is a CCW (angle-increasing, atan2 sense)
     rotation — in any right-handed 2D frame that's a turn toward the
     traveler's own left, independent of how the axes get projected to
     screen, so sign>0 = Left, sign<0 = Right. Small back-tolerance (20
     units) so the indicator doesn't blink away right as the robot
     enters the arc. */
  /* The GPS's LIVE target, which is not always route.doorS. doorS is
     retargeted (+= loop.len) when the first pass is missed, but between
     sailing past the door and that retarget the door sits BEHIND the
     robot and the next pass is a whole lap away. The distance readout
     and the turn strip have to agree on which door they mean, or they
     contradict each other on the same line. */
  targetDoorS(){
    const r = this.route;
    if(r.loop && r.loop.missed && r.doorS - this.botS < -60) return r.doorS + r.loop.len;
    return r.doorS;
  }
  findNextTurn(){
    /* Turns BEYOND the drop-off are not the driver's problem -- they
       arrive first. Without this cutoff the strip advertised a corner
       the player never reaches, and worse, the checkered final-approach
       cue almost never fired: the route does not end at the door, and
       the reroute lap welds four more arcs on behind it, so there was
       essentially ALWAYS an arc somewhere ahead and the "no turns left"
       branch was close to dead code. */
    const doorS = this.targetDoorS();
    for(const sg of this.route.segs){
      if(sg.type === "arc" && sg.s0 > this.botS - 20)
        return sg.s0 >= doorS ? null : sg;
    }
    return null;
  }
  drawHUD(){
    /* The gauges are painted on the Phaser canvas, not in the DOM, so
       body.attractBare's display:none never reached them -- the tilt arc
       and cargo bar were still drawing across the top of the splash. A
       decorative background has no cargo to spill and nobody steering
       it, so there is nothing for a gauge to report.

       Gated on this.attract rather than ATTRACT_BARE: the question is
       "is anyone driving", not "which embedder launched us". Keyed to
       the launch flag it still drew the tilt arc across the standalone
       title screen, which is a gauge reporting on a robot the player is
       not controlling. */
    if(this.attract) return;
    const g = this.hud; g.clear();
    /* Camera depth is the ONE instrument both modes share, so its
       visibility is settled here BEFORE the challenge early-return
       below — and #zoomBtn is deliberately absent from hjChrome()'s
       hide list for the same reason. Visible whenever driving. */
    const zb = document.getElementById("zoomBtn");
    if(zb) zb.classList.toggle("hidden", this.state !== "play");
    /* The tilt gauge, the cargo-condition bar and the GPS turn strip are
       all DELIVERY instruments — they are drawn onto the HUD canvas, not
       into DOM, which is why hiding the panels never got rid of them.
       There is no cargo and no tip in the Hydrant Challenge, so none of
       it applies. */
    if(this.mode === "challenge"){
      const gpsEl0 = document.getElementById("gpsHud");
      if(gpsEl0) gpsEl0.classList.add("hidden");
      return;
    }
    const w = this.scale.gameSize.width, h = this.scale.gameSize.height;

    /* delivery-app style HUD: distance/ETA/turn-by-turn, replacing the
       old progress bar + live timer/cargo%. Quality (cargo%) and
       elapsed time are reported once, at the end, in showWin — not
       shown live during the trip anymore. */
    /* mid-lap on the reroute loop (door already passed this lap) this
       counts to the NEXT pass, GPS-style, instead of 0 ft -- see
       targetDoorS(), which findNextTurn() shares so the distance and the
       turn strip can never disagree about which door is being counted. */
    const remainDist = Math.max(0, this.targetDoorS() - this.botS);
    const FT_PER_UNIT = 0.6; // flavor conversion, not a real-world claim
    const distFt = remainDist * FT_PER_UNIT;
    const distText = distFt > 1000 ? (distFt/5280).toFixed(1)+" mi" : Math.round(distFt/10)*10 + " ft";

    /* delivery TIMER (replaces the ETA estimate): counts down the
       route's par time; past zero it shows the overage with a minus —
       the tip is decaying (1%/5s, see showWin) and the driver should
       feel it. */
    const remainMs = this.route.parMs - this.runT;
    const fmtMs = v => Math.floor(v/60000) + ":" + String(Math.floor((v%60000)/1000)).padStart(2,"0");
    /* two clocks in one: par countdown while there's time, then the
       CANCEL countdown through the grace window — a second, scarier
       timer instead of a mysterious negative number. */
    const timerText = remainMs >= 0
      ? fmtMs(remainMs)
      : "⚠ cancels " + fmtMs(Math.max(0, this.route.parMs + CANCEL_GRACE_MS - this.runT));

    /* mid-turn HOLD: while the robot is actually ON an arc, show just
       the current turn's arrow — no distance. findNextTurn() looks
       AHEAD, so without this the readout jumped to the next corner's
       countdown the instant the current turn began, mid-steer. The
       countdown resumes only once the robot exits onto the straight. */
    const curSeg = this.segAt(this.botS);
    let turnText;
    if(curSeg.type === "arc"){
      /* sign>0 means the heading steps f -> f+1, which under this iso
         projection reads on screen as a RIGHT turn — the old mapping
         had it backwards (on-device: "says right, robot goes left"). */
      const dir = curSeg.sign > 0 ? "Right" : "Left";
      const arrow = curSeg.sign > 0 ? "→" : "←";
      turnText = `${arrow} Turn ${dir}`;
    } else {
      const nextTurn = this.findNextTurn();
      if(nextTurn){
        const distToTurn = Math.max(0, nextTurn.s0 - this.botS);
        const dir = nextTurn.sign > 0 ? "Right" : "Left";   // same screen-handedness fix as the hold branch
        const arrow = nextTurn.sign > 0 ? "→" : "←";
        turnText = distToTurn < 20
          ? `${arrow} Turn ${dir}`
          : `${arrow} Turn ${dir} in ${Math.round(distToTurn*FT_PER_UNIT/10)*10} ft`;
      } else {
        /* Final approach: name the ADDRESS. "Straight ahead to drop-off"
           told the driver nothing they could act on, and this is the one
           moment the destination itself is the useful thing to read.
           Also SHORTER than the old string, which matters -- #gpsHud is
           white-space:nowrap and centre-anchored, so a longer readout
           overflows both edges on a narrow phone. */
        turnText = `🏁 ${this.route.address}`;
      }
    }

    /* tilt meter */
    const cx = w/2, cy = 56, r = 24;
    const danger = Math.min(Math.abs(this.tilt), 1);
    g.lineStyle(5, 0xffffff, 0.55);
    g.beginPath(); g.arc(cx, cy, r, Math.PI, 0); g.strokePath();
    g.lineStyle(5, danger > 0.75 ? 0xc2452e : danger > 0.45 ? 0xff7a1a : 0x3f7d43, 1);
    g.beginPath();
    g.arc(cx, cy, r, -Math.PI/2, -Math.PI/2 + Phaser.Math.Clamp(this.tilt, -1, 1)*1.35, this.tilt < 0);
    g.strokePath();
    g.lineStyle(3, 0x2e3138, 1);
    g.lineBetween(cx, cy, cx + Math.sin(this.tilt*1.2)*r, cy - Math.cos(this.tilt*1.2)*r);

    /* cargo condition meter — separate bar under the tilt gauge (spec:
       tied to the red zone, own widget rather than fused into tilt's).
       Starts full green (pristine cargo) and DRAINS toward empty as
       damage/95 climbs -- reads as "quality remaining," not "damage
       taken," so a fresh run is visibly full rather than visibly
       blank. Cap of 95 matches the tip-deduction math (dmgPen =
       damage*0.2 in showWin), so what the player watches drain IS the
       real payout hit. No refill: unlike tilt, cargo damage is
       permanent for the run. Color keys off raw damage fraction, width
       off its inverse. Thresholds (0.25/0.5) are intentionally earlier
       than the tilt gauge's own 0.45/0.75 -- cargo condition is meant
       to read as compromised well before a tip-over is imminent, not
       in lockstep with it. A crash snaps damage to 95, which drains
       this to fully empty: nothing left, goods ruined. */
    const dmgFrac = Phaser.Math.Clamp(this.damage / 95, 0, 1);
    const qualityFrac = 1 - dmgFrac;
    const barW = 70, barH = 6, barX = cx - barW/2, barY = cy + r + 14;
    g.fillStyle(0x000000, 0.35);
    g.fillRoundedRect(barX, barY, barW, barH, barH/2);
    if(qualityFrac > 0){
      g.fillStyle(dmgFrac > 0.5 ? 0xc2452e : dmgFrac > 0.25 ? 0xff7a1a : 0x3f7d43, 1);
      g.fillRoundedRect(barX, barY, barW*qualityFrac, barH, barH/2);
    }

    /* DOM readout (see #gpsHud CSS): textContent update is cheap, the
       browser centers it, font-size:min() shrinks it on narrow screens,
       and native-DPR rendering keeps it as crisp as the overlay
       headlines it's styled after. Visible only while driving. */
    const gpsEl = document.getElementById("gpsHud");
    gpsEl.textContent = `${timerText} · ${distText} · ${turnText}`;
    gpsEl.classList.toggle("hidden", this.state !== "play");
  }
}

/* ---------- boot + panel ---------- */

/* ============================================================
   HYDRANT CHALLENGE — side mission, ported verbatim from
   labs/hydrant-challenge-lab.html.
   Everything is HJ_-prefixed; it reuses the game's TILE, T2,
   DIRV, SKIN, BODY, LID, STRIPE, WHEEL, HYD, mulberry32 and
   convexHull, which are byte-identical to the lab's copies.
   NOTE: the hostile pedestrian is WILLIAM (formerly 'kicker');
   in THIS course feature 'kicker' always means the RAMP (hjRole,
   kickerS, the lab's kicker ramp -> HJ_RAMP on the way in).
   ============================================================ */
"use strict";

/* ============================================================
   TIPSEY — Hydrant Jump Lab v1
   First bench for the launch/arc/landing system from
   docs/ramp-jump-spec.md, built as the FIRE HJ_CHIEF unlock stunt:

     KICKER SLAB  — one sidewalk tile heaved along the TRAVEL axis
                    (flush at the near edge, lifted HJ_RAMP.lift at the
                    far edge). Same art vocabulary as ramp-lab's
                    cross-slope heave, rotated 90° so it kicks
                    instead of tipping. Clears the lip at speed and
                    the wheels leave the ground.
     ARC          — parabolic, tuned for feel not physics:
                    vz0 = speed * Pow, then vz -= Grav*dt.
                    Horizontal speed is UNCHANGED in air (no air
                    control, per spec §1).
     HYDRANT      — the game's approved prop.hydrant, one tile past
                    the kicker, sitting inside the arc. Clearance is
                    checked exactly as the robot crosses its along
                    position: arc height must beat HYD.height + Clear.
     LANDING SLAB — a second heaved tile, mirrored (lifted at the
                    NEAR edge, flush at the far edge) so it's a
                    down-ramp. Landing on it absorbs most of the slam;
                    landing on flat sidewalk does not.
     UNLOCK       — hydrant cleared + clean landing on the slab
                    grants the fire chief entitlement. HJ_CHIEF SKIN
                    previews the reward palette.

   Robot, tiles, hydrant, T()/R()/W()/P()/depth(), drawBox/drawWheel/
   drawLid/lidNear and the |tilt| >= 1 tip threshold are all verbatim
   from game/index.html via hydrant-hit-lab / ramp-lab.

   HEADING GATE (the pass/fail item in spec §2): everything is built
   in (along, cross) run space and mapped through AC()/Wp(), so the
   f0/f1/f2/f3 button rotates the whole scene — run direction, tiles,
   both slabs, the hydrant and the robot's facing together. The
   airborne depth bias MUST read correctly at all four before this
   gets ported into game/index.html.
   ============================================================ */

/* ---------- ported verbatim from game/index.html ---------- */
