function showWin(s){
  document.getElementById("winSub").textContent =
    WIN_LINES[Math.floor(Math.random()*WIN_LINES.length)];
  const cargo = Math.round(100 - s.damage);
  const secs = s.runT/1000;
  /* walk penalty: the customer walks all the way to the robot now, and
     the tip drops the further he has to come. Distance measured
     door -> robot at the moment of the win (the robot is already
     frozen); the first ~120 units are free — that's roughly a stop
     flush with the mat — then 3 cents a unit, so the worst legal stops
     (far lane, edge of the win window, ~400+ units) cost real money.
     Shown in the panel so parking tight reads as strategy. */
  /* ---------- the TIP ENGINE ----------
     A percentage of the ORDER VALUE, not a multiplier: 20% baseline.
     Deductions: cargo damage (0.2%/pt — trash the burrito, lose the
     tip), lateness past par (1% per 5s, casual for now), and the walk
     the customer makes to a badly parked robot (per unit past the
     free 120). Bonuses: flawless cargo +1%, beating par with 20% to
     spare +1% — the 22% ceiling for a perfect run. Floor 0%: mess it
     up completely and you deliver for free. */
  let walkExtra = 0;
  if(s.addrDoorDV){
    const doorX = s.addrDoorUX + s.addrDoorDV.x*s.addrDoorCenterX;
    const doorY = s.addrDoorUY + s.addrDoorDV.y*s.addrDoorCenterX;
    walkExtra = Math.max(0, Math.hypot(s.botX - doorX, s.botY - doorY) - 120);
  }
  const order = s.route.order;
  const dmgPen  = s.damage * 0.2;
  const latePen = Math.max(0, s.runT - s.route.parMs) / 5000;
  const walkPen = walkExtra * 0.008;
  let pct = 20 - dmgPen - latePen - walkPen;
  if(s.damage === 0) pct += 1;
  if(s.runT < s.route.parMs * 0.8) pct += 1;
  pct = Math.max(0, Math.min(22, pct));
  const payout = Math.round(order.value * pct) / 100;
  const pctShow = Math.round(pct);
  const cuts = [];
  if(dmgPen  >= 0.5) cuts.push(`dmg −${Math.round(dmgPen)}%`);
  if(latePen >= 0.5) cuts.push(`late −${Math.round(latePen)}%`);
  if(walkPen >= 0.5) cuts.push(`walk −${Math.round(walkPen)}%`);
  /* daily best — tip dollars ranked, time the tiebreak. Shared across
     everyone on the subreddit when running in the Devvit webview
     (tipsyBridge.active — see the bridge shim near the top of the
     script); falls back to a local-only best via localStorage in the
     standalone GitHub Pages build, exactly as before this bridge
     existed.

     isReplay is decided purely off the loaded route's own date: on
     Devvit the ONLY way s.route.dateStr is ever not today is via the
     Past Routes picker (the old reroll panel is hidden there), so
     there's no separate "replay mode" flag to keep in sync — the date
     already says everything. This also guarantees api/tipsy/best/submit
     (today-only on the server; see db.ts todayUTC()) never receives a
     replay's date by accident. */
  const isReplay = IS_DEVVIT_BUILD && s.route.dateStr !== clientTodayUTC();
  let bestRow = "", allTimeRow = "";
  if(isReplay){
    try {
      /* tipsyBridge.historyBest was populated when Past Routes was
         opened to reach this route in the first place, so it's already
         warm — same optimistic-then-server-confirms pattern as the
         today branch below, just against the history cache instead of
         tipsyBridge.best. */
      const prev = tipsyBridge.historyBest[s.route.dateStr];
      const better = !prev || payout > prev.tip || (payout === prev.tip && s.runT < prev.ms);
      const delta = Math.max(0, payout - (prev ? prev.tip : 0));
      if(better){
        tipsyBridge.historyBest[s.route.dateStr] = { tip: payout, ms: s.runT };
        if(tipsyBridge.allTimeTotal != null) tipsyBridge.allTimeTotal += delta;
      }
      submitReplay(s.route.dateStr, payout, s.runT);
      bestRow = better
        ? `<div class="sheetRow" style="color:#3f7d43;font-size:13px">★ NEW BEST FOR THIS DAY</div>`
        : `<div class="sheetRow" style="color:#8f95a1;font-size:13px">best for this day $${prev.tip.toFixed(2)} · ${(prev.ms/1000).toFixed(1)}s</div>`;
      allTimeRow = (better && delta > 0)
        ? `<div class="sheetRow" style="color:#ff9c4d;font-size:13px;font-weight:700">+$${delta.toFixed(2)} added to all-time</div>`
        : "";
    } catch(e){}
  } else {
    try {
      const key = "tipsy-best-" + s.route.dateStr;
      const prev = tipsyBridge.active
        ? tipsyBridge.best[s.route.dateStr]
        : JSON.parse(localStorage.getItem(key) || "null");
      /* `prev` (tipsyBridge.best) is today's #1 score overall, not the
         player's OWN prior run — it's only correct for the "did I just
         take the top spot" banner below. Submission must NOT be gated
         on it: a run that beats your own last score but isn't yet #1
         overall would never reach the server at all. The server already
         compares against your own prior score correctly (dbSubmitScore),
         so every completed delivery submits unconditionally and lets
         the server decide whether it's actually an improvement — cheap
         no-op there when it isn't. */
      const better = !prev || payout > prev.tip || (payout === prev.tip && s.runT < prev.ms);
      if(tipsyBridge.active){
        if(better) tipsyBridge.best[s.route.dateStr] = { tip: payout, ms: s.runT };   // optimistic — server is source of truth next load
        fetch("api/tipsy/best/submit", {
          method: "POST",
          headers: { "Content-Type": "application/json", Accept: "application/json" },
          body: JSON.stringify({ tip: payout, ms: s.runT })
        }).catch(()=>{});
      } else if(better){
        localStorage.setItem(key, JSON.stringify({ tip: payout, ms: s.runT }));
      }
      bestRow = better
        ? `<div class="sheetRow" style="color:#3f7d43;font-size:13px">★ NEW DAILY BEST</div>`
        : `<div class="sheetRow" style="color:#8f95a1;font-size:13px">daily best $${prev.tip.toFixed(2)} · ${(prev.ms/1000).toFixed(1)}s</div>`;
    } catch(e){}
  }
  document.getElementById("winCard").innerHTML =
    `<div class="sheetRow"><b>${s.route.address}</b>&nbsp;·&nbsp;${s.route.hood.n}</div>` +
    `<div class="sheetRow" style="color:#8f95a1;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;text-align:center">${order.text} · $${order.value.toFixed(2)}</div>` +
    `<div class="sheetRow">time <b>${secs.toFixed(1)}s</b>&nbsp;·&nbsp;cargo <b>${cargo}%</b>&nbsp;·&nbsp;tip <b>${pctShow}% · $${payout.toFixed(2)}</b>${cuts.length ? `&nbsp;<span style="color:#8f95a1">(${cuts.join(", ")})</span>` : ""}</div>` +
    bestRow + allTimeRow;
  tipsyProfileOnDelivery(s.route.dateStr, payout, s.runT, isReplay);
  reportWin(s, payout, pctShow);
  /* The whole win-screen stack anchors to the MEASURED panel, not a CSS
     constant: the receipt's height varies (order length, deduction
     notes, the daily-best row), and a fixed bottom was budgeted for the
     original two-row card — every growth spurt parked Again on top of
     the text (on-device, twice now, back when Again was the only thing
     here). Same fix, now applied to three stacked elements instead of
     one: FOLLOW sits in the old Again slot (cardH+16), COMMENT stacks
     above it, and the explore icon row (glass+robot, tdStackIcons) sits
     above that — the row's own top:calc(46%+140px) class rule is
     cleared to "auto" here since bottom is what actually places it now.
     ORDER MATTERS: show() first. Measuring while the overlay is still
     display:none reads offsetHeight = 0, which parked Again at
     bottom:16px — on top of the stats (on-device, the bug's third
     costume) — same trap for any of these three if measured too early. */
  show("winOverlay");
  const cardEl = document.getElementById("winCard");
  const stackBase = cardEl.offsetHeight + 16;
  twFxSyncFollowBtn();
  twFxSyncCommentBtn();
  tdStackIcons("winOverlay");
  const followBtn = document.getElementById("twFxFollowBtn");
  if(followBtn) followBtn.style.bottom = stackBase + "px";
  const commentBtn = document.getElementById("twFxCommentBtn");
  if(commentBtn) commentBtn.style.bottom = (stackBase + 60) + "px";
  const iconRow = document.getElementById("tdStackIcons_winOverlay");
  if(iconRow){ iconRow.style.top = "auto"; iconRow.style.bottom = (stackBase + 120) + "px"; }
}

window.addEventListener("resize", () => {
  const s = scn();
  if(s && s.route) { resizeRouteMap(); drawRouteMap(s.route); }
});

/* ---------- RESUME RE-SYNC (iPad, 2026-07-31) ----------
   Phaser.Scale.RESIZE only reacts to window `resize`. Backgrounding the
   app on iPadOS and coming back frequently fires NO resize event, and
   Phaser's own scale poll is halted while the page is hidden, so a size
   change that happened while we were away is dropped on the floor: the
   canvas keeps its stale width and you get a black band down the side
   with the HUD laid out to the old dimensions.

   scale.refresh() re-measures the parent and re-emits RESIZE, which the
   scene's own listener (this.scale.on("resize", ...) => layout()) picks
   up. Called twice: iPadOS reports stale innerWidth/innerHeight on the
   first frame after resume, so the rAF pass is the one that usually
   lands. Cheap enough to do both. */
function tpResyncViewport(){
  if(!game || !game.scale) return;
  game.scale.refresh();
  const s = scn();
  if(s && s.route) { resizeRouteMap(); drawRouteMap(s.route); }
}
function tpResumeResync(){
  tpResyncViewport();
  requestAnimationFrame(tpResyncViewport);
}
document.addEventListener("visibilitychange", () => {
  if(!document.hidden) tpResumeResync();
});
window.addEventListener("pageshow", tpResumeResync);
window.addEventListener("focus", tpResumeResync);
window.addEventListener("orientationchange", tpResumeResync);
document.getElementById("startBtn").addEventListener("click", () => {
  hide("titleOverlay");
  const s = scn();
  if(s.mode === "challenge"){ hjBegin(); return; }
  if(s.mode === "slalom-pending"){ tpSlalomStart(); return; }
  /* Leave attract BEFORE anything else -- attractStop clears the pending
     recycle timer, and a recycle that fires after GO reloads the route
     out from under a live run. */
  const wasAttract = s.attract;
  s.attractStop();
  countPlay();
  /* The attract robot has been driving for a while: he is somewhere down
     the block, part-damaged, maybe mid-topple. The player starts at the
     shop with a clean load, so the route is rebuilt rather than
     inherited. Same day -- attract only ever loops today's route, so
     this is the route the order card has been advertising. */
  if(wasAttract) s.loadRoute(s.route ? s.route.dateStr : clientTodayUTC());
  s.state = "play";
});
document.getElementById("retryBtn").addEventListener("click", () => {
  hide("failOverlay");
  const s = scn();
  /* In the challenge, Retry means RETRY THE JUMP. Loading the daily
     route dumped the player out of the mission entirely. */
  if(s.mode === "challenge"){ s.hjResetRun(); return; }
  document.getElementById("retryBtn").textContent = "Retry";
  countPlay();
  s.loadRoute(s.route.dateStr); s.state = "play";
});
